--
-- Name: _admin_require_ctx(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._admin_require_ctx() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid   text;
  v_ctx   text;
  v_reqs  text[];
  v_admin boolean;
  v_super boolean;
  v_perms text[];
BEGIN
  v_uid := auth.uid()::text;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'forbidden: admin required' USING ERRCODE = '42501';
  END IF;

  SELECT (u.user_type = 'admin'), u.is_super_admin, u.admin_permissions
    INTO v_admin, v_super, v_perms
    FROM public.users u WHERE u.id = v_uid;

  IF NOT COALESCE(v_admin, false) THEN
    RAISE EXCEPTION 'forbidden: admin required' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(v_super, false) THEN
    RETURN;                       -- المدير الأعلى: بلا قيود، كما كان دائماً
  END IF;

  GET DIAGNOSTICS v_ctx = PG_CONTEXT;

  SELECT array_agg(DISTINCT r.required_perm) INTO v_reqs
    FROM public.admin_rpc_permissions r
   WHERE v_ctx ~ ('function ' || r.rpc_name || '\(');

  IF v_reqs IS NULL THEN
    RETURN;                       -- غير مُخرَّطة: أي أدمن — لا يُقفل أحد أبداً
  END IF;

  IF NOT (COALESCE(v_perms, '{}'::text[]) && v_reqs) THEN
    RAISE EXCEPTION 'forbidden: this account does not have any of the % permissions', v_reqs
      USING ERRCODE = '42501';
  END IF;
END;
$$;


--
-- Name: _apply_merchant_payment(text, text, text, numeric, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._apply_merchant_payment(p_provider text, p_merchant_id text, p_payment_ref text, p_amount numeric, p_barcode text, p_status text DEFAULT 'paid'::text, p_vat numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_b public.bookings%ROWTYPE; v_rows integer; v_amt text;
BEGIN
  SELECT * INTO v_b FROM public.bookings WHERE barcode = p_barcode;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'BOOKING_NOT_FOUND'); END IF;

  INSERT INTO public.platform_payment_log
    (booking_barcode, merchant_id, buyer_id, amount, vat_amount, provider, payment_ref, status)
  VALUES (p_barcode, p_merchant_id, v_b.user_id, p_amount, COALESCE(p_vat, 0), p_provider, p_payment_ref, p_status)
  ON CONFLICT (provider, payment_ref) DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN RETURN jsonb_build_object('ok', true, 'duplicate', true); END IF;

  IF p_status = 'paid' THEN
    UPDATE public.bookings
    SET paid_at = now(), payment_provider = p_provider, payment_ref = p_payment_ref, paid_amount = p_amount
    WHERE barcode = p_barcode AND paid_at IS NULL;
    UPDATE public.merchant_gateways SET fail_count = 0, updated_at = now() WHERE merchant_id = p_merchant_id;

    v_amt := trim(to_char(p_amount, 'FM999999990.09'));
    IF p_provider = 'sim' THEN
      INSERT INTO public.notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      VALUES
        ('ntf_pay_b_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
         v_b.user_id,
         '🧪 (تجريبي) تمت محاكاة دفعتك', '(Test) Simulated payment recorded',
         'وضع تجريبي: سُجّلت محاكاة دفع ' || v_amt || ' ر.س للحجز ' || p_barcode || ' — لم يُخصم أي مبلغ حقيقي.',
         'Test mode: a simulated payment of ' || v_amt || ' SAR was recorded for booking ' || p_barcode || ' — no real money was charged.',
         'booking', jsonb_build_object('audience', 'buyer', 'barcode', p_barcode)),
        ('ntf_pay_s_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
         p_merchant_id,
         '🧪 (تجريبي) محاكاة دفعة على حجز', '(Test) Simulated payment on a booking',
         'وضع تجريبي: سُجّلت محاكاة دفع ' || v_amt || ' ر.س على الحجز ' || p_barcode || ' — تنبيه: لا يوجد أي مبلغ حقيقي، هذه تجربة للنظام فقط.',
         'Test mode: a simulated payment of ' || v_amt || ' SAR was recorded on booking ' || p_barcode || ' — note: NO real money was received.',
         'booking', jsonb_build_object('audience', 'seller', 'barcode', p_barcode));
    ELSE
      INSERT INTO public.notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      VALUES
        ('ntf_pay_b_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
         v_b.user_id,
         '💳 تم استلام دفعتك بنجاح', 'Payment received',
         'تم دفع ' || v_amt || ' ر.س إلكترونياً لحساب التاجر مباشرة. حجزك: ' || p_barcode,
         'Paid ' || v_amt || ' SAR directly to the merchant. Booking: ' || p_barcode,
         'booking', jsonb_build_object('audience', 'buyer', 'barcode', p_barcode)),
        ('ntf_pay_s_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
         p_merchant_id,
         '💰 دفعة جديدة وصلت حسابك', 'New payment received',
         'استلمت ' || v_amt || ' ر.س في حساب بوابتك عن الحجز ' || p_barcode || ' — المبلغ في حسابك مباشرة دون أي عمولة.',
         'You received ' || v_amt || ' SAR in your gateway account for booking ' || p_barcode || '.',
         'booking', jsonb_build_object('audience', 'seller', 'barcode', p_barcode));
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true);
END $$;


--
-- Name: _booking_amount_due(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._booking_amount_due(p_barcode text) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT round(COALESCE(
           b.total_amount,
           (public.taki_booking_amount(b.deal_id, b.booked_quantity, b.selected_options, b.delivery_fee)->>'total')::numeric,
           0), 2)
    FROM public.bookings b
   WHERE b.barcode = upper(btrim(p_barcode));
$$;


--
-- Name: _booking_card(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._booking_card(p_barcode text, p_role text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'barcode', b.barcode, 'backup_code', b.backup_code,
    'user_name', COALESCE(b.user_name,'—'), 'user_phone', COALESCE(b.user_phone,'—'),
    'shop_name', COALESCE(NULLIF(u.shop,''), NULLIF(u.name,''), '—'),
    'deal_name', COALESCE(d.item_name,'العرض'), 'deal_id', b.deal_id,
    'quantity', b.booked_quantity, 'status', b.status,
    'notes', COALESCE(b.notes,''), 'merchant_note', COALESCE(b.merchant_note,''),
    'prep_time', b.prep_time, 'sort_at', b.booked_at, 'booked_at', b.booked_at,
    'expiry_time', b.expiry_time,
    'unread', (SELECT count(*) FROM booking_messages m
               WHERE m.barcode = b.barcode
                 AND m.sender_role <> p_role AND m.read_at IS NULL),
    'fulfillment', COALESCE(b.fulfillment,'pickup'),
    'delivery_fee', b.delivery_fee,
    'delivery_label',   b.delivery_address->>'label',
    'delivery_details', b.delivery_address->>'details',
    'delivery_phone',   b.delivery_address->>'phone',
    'delivery_lat',     b.delivery_address->>'lat',
    'delivery_lng',     b.delivery_address->>'lng',
    'payment_method', b.payment_method,
    'paid', b.paid_at IS NOT NULL,
    'paid_amount', b.paid_amount,
    'total_amount', b.total_amount,
    'role', p_role
  )
  FROM public.bookings b
  LEFT JOIN public.deals d ON d.id = b.deal_id
  LEFT JOIN public.users u ON u.id = b.store_id
  WHERE b.barcode = p_barcode;
$$;


--
-- Name: _bot_gate_ok(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bot_gate_ok() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    COALESCE((SELECT value FROM public.app_secrets WHERE key = 'bot_gate_enforced'), '0') <> '1'
    -- لا ترويسات = نداءٌ من داخل القاعدة (مشغّل/كرون/خدمي) لا من متصفّح.
    -- PostgREST يضع الترويسات دائماً، فهذا الفرع غير قابل للوصول من الشبكة.
    OR current_setting('request.headers', true) IS NULL
    OR current_setting('request.headers', true) = ''
    OR EXISTS (
      SELECT 1 FROM public.app_secrets
      WHERE key IN ('bot_gateway_secret', 'bot_gateway_secret_next')
        AND value IS NOT NULL AND value <> ''
        AND value = (current_setting('request.headers', true)::json ->> 'x-bot-secret')
    );
$$;


--
-- Name: _bot_gen_barcode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bot_gen_barcode() RETURNS text
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', (floor(random()*32)+1)::int, 1), '')
  FROM generate_series(1,8);
$$;


