    booking_ban_reason text,
    delivery_address jsonb,
    is_anonymized boolean DEFAULT false NOT NULL,
    anonymized_at timestamp with time zone,
    gateway_agreement_version text,
    gateway_agreement_at timestamp with time zone,
    consent_age_confirmed boolean DEFAULT false NOT NULL,
    consent_min_age integer,
    CONSTRAINT users_bot_lang_chk CHECK ((bot_lang = ANY (ARRAY['ar'::text, 'en'::text]))),
    CONSTRAINT users_delivery_address_chk CHECK (((delivery_address IS NULL) OR ((jsonb_typeof(delivery_address) = 'object'::text) AND (length((delivery_address)::text) <= 2000) AND ((delivery_address ->> 'lat'::text) ~ '^-?[0-9]+(\.[0-9]+)?$'::text) AND ((delivery_address ->> 'lng'::text) ~ '^-?[0-9]+(\.[0-9]+)?$'::text)))),
    CONSTRAINT users_preferred_lang_check CHECK ((preferred_lang = ANY (ARRAY['ar'::text, 'en'::text]))),
    CONSTRAINT users_user_type_check CHECK ((user_type = ANY (ARRAY['buyer'::text, 'seller'::text, 'admin'::text])))
);

