--
-- Name: _bot_profile(public.users); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bot_profile(v_user public.users) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sp store_profiles%ROWTYPE;
BEGIN
  IF v_user.user_type = 'seller' THEN
    SELECT * INTO v_sp FROM store_profiles WHERE store_id = v_user.id LIMIT 1;
  END IF;
  RETURN jsonb_build_object(
    'id', v_user.id, 'name', v_user.name, 'phone', v_user.phone,
    'user_type', v_user.user_type, 'shop', v_user.shop,
    'is_suspended', COALESCE(v_user.is_suspended, false),
    'is_super_admin', COALESCE(v_user.is_super_admin, false),
    'admin_permissions', COALESCE(v_user.admin_permissions, ARRAY[]::text[]),
    'subscription_plan', v_sp.subscription_plan,
    'subscription_expires_at', v_sp.subscription_expires_at,
    'lat', v_user.lat,
    'lng', v_user.lng,
    'bot_lang', COALESCE(v_user.bot_lang, 'ar')
  );
END;
$$;


--
-- Name: _bot_uid(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bot_uid(p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT id FROM public.users
   WHERE deleted_at IS NULL
     AND public._bot_gate_ok()
     AND ( (p_telegram_id IS NOT NULL AND telegram_id     = p_telegram_id)
        OR (p_whatsapp_id IS NOT NULL AND whatsapp_chat_id = p_whatsapp_id) )
   LIMIT 1;
$$;


--
-- Name: _broadcast_campaign_core(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._broadcast_campaign_core(p_campaign_id text, p_force boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE camp RECORD; affected INTEGER := 0;
BEGIN
  SELECT * INTO camp FROM public.promotional_campaigns WHERE id = p_campaign_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Campaign % not found', p_campaign_id; END IF;

  IF p_force THEN
    DELETE FROM public.promo_impressions WHERE campaign_id = camp.id;
  END IF;

  INSERT INTO public.notifications (
    user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
  SELECT u.id, camp.title_ar, camp.title_en, camp.body_ar, camp.body_en, 'marketing',
    jsonb_build_object(
      'campaignId',    camp.id,
      'imageUrl',      camp.image_url,
      'actionUrl',     camp.action_url,
      'actionLabelAr', camp.action_label_ar,
      'actionLabelEn', camp.action_label_en,
      -- 🪤 البوتان يقرآن الشرطة السفلية. مفتاحٌ واحد بالسنام كان يعني أن زرّ
      -- الحملة لا يظهر في تيليجرام ولا واتساب أبداً، وناصر يملأ «رابط عند
      -- الضغط» ولا يجد أحدٌ ما يضغطه.
      'action_url',    camp.action_url,
      'image_url',     camp.image_url,
      'action_label_ar', camp.action_label_ar,
      'action_label_en', camp.action_label_en),
    NOW()
  FROM public.users u
  WHERE (camp.target_audience = 'all' OR u.user_type = camp.target_audience)
    AND u.deleted_at IS NULL
    AND COALESCE(u.is_suspended, false) = false
    AND public.taki_user_in_campaign(u.id, camp.target_city, camp.target_region)
    AND NOT EXISTS (SELECT 1 FROM public.promo_impressions p
                    WHERE p.campaign_id = camp.id AND p.user_id = u.id);

  GET DIAGNOSTICS affected = ROW_COUNT;

  INSERT INTO public.promo_impressions (campaign_id, user_id, seen_at, clicked)
  SELECT camp.id, u.id, NOW(), FALSE
  FROM public.users u
  WHERE (camp.target_audience = 'all' OR u.user_type = camp.target_audience)
    AND u.deleted_at IS NULL
    AND COALESCE(u.is_suspended, false) = false
    AND public.taki_user_in_campaign(u.id, camp.target_city, camp.target_region)
  ON CONFLICT (campaign_id, user_id) DO NOTHING;

  UPDATE public.promotional_campaigns
     SET current_impressions = COALESCE(current_impressions, 0) + affected,
         last_broadcast_at = NOW()
   WHERE id = camp.id;

  RETURN affected;
END $$;


--
-- Name: _bump_gateway_fail(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bump_gateway_fail(p_merchant_id text) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE public.merchant_gateways
  SET fail_count = fail_count + 1, updated_at = now()
  WHERE merchant_id = p_merchant_id
  RETURNING fail_count;
$$;


--
-- Name: _gateway_masked(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._gateway_masked(p_merchant_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN p_merchant_id IS NULL THEN NULL ELSE
    COALESCE(
      CASE WHEN g.merchant_id IS NULL THEN NULL ELSE jsonb_build_object(
        'provider',              g.provider,
        'publishable_key',       g.publishable_key,
        'extra_config',          g.extra_config,
        'key_last4',             g.key_last4,
        'has_secret',            g.secret_key_id IS NOT NULL,
        'has_webhook_secret',    g.webhook_secret_id IS NOT NULL,
        'payment_modes',         g.payment_modes,
        'is_enabled',            g.is_enabled,
        'disabled_by_admin',     g.disabled_by_admin,
        'fail_count',            g.fail_count,
        'verified_at',           g.verified_at,
        'agreement_accepted_at', g.agreement_accepted_at,
        'provider_enabled',      public.pay_provider_on(g.provider)
      ) END,
      '{}'::jsonb
    )
    || jsonb_build_object(
        'direct_pay_enabled', public.direct_pay_on(),
        'enabled_providers',
          COALESCE((SELECT jsonb_agg(k.key) FROM (
            SELECT e.key FROM public.platform_settings ps,
                 LATERAL jsonb_each(ps.value) e
            WHERE ps.key = 'enabled_pay_providers' AND e.value = 'true'::jsonb
          ) k), '[]'::jsonb)
      )
  END
  FROM (SELECT 1) x
  LEFT JOIN public.merchant_gateways g ON g.merchant_id = p_merchant_id;
$$;


--
-- Name: _gateway_secrets(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._gateway_secrets(p_merchant_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE g public.merchant_gateways%ROWTYPE; v_sk text; v_ws text;
BEGIN
  SELECT * INTO g FROM public.merchant_gateways WHERE merchant_id = p_merchant_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF g.secret_key_id IS NOT NULL THEN
    SELECT ds.decrypted_secret INTO v_sk FROM vault.decrypted_secrets ds WHERE ds.id = g.secret_key_id;
  END IF;
  IF g.webhook_secret_id IS NOT NULL THEN
    SELECT ds.decrypted_secret INTO v_ws FROM vault.decrypted_secrets ds WHERE ds.id = g.webhook_secret_id;
  END IF;
  RETURN jsonb_build_object(
    'provider', g.provider, 'publishable_key', g.publishable_key, 'extra_config', g.extra_config,
    'secret_key', v_sk, 'webhook_secret', v_ws,
    'is_enabled', g.is_enabled, 'disabled_by_admin', g.disabled_by_admin,
    'verified_at', g.verified_at, 'payment_modes', g.payment_modes, 'fail_count', g.fail_count,
    'provider_enabled', public.pay_provider_on(g.provider));
END $$;


--
-- Name: _gateway_write(text, text, text, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._gateway_write(p_merchant_id text, p_provider text, p_publishable_key text, p_secret_key text, p_webhook_secret text, p_extra jsonb, p_actor_id text, p_actor_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.merchant_gateways%ROWTYPE;
  v_sk  text := NULLIF(btrim(COALESCE(p_secret_key, '')), '');
  v_ws  text := NULLIF(btrim(COALESCE(p_webhook_secret, '')), '');
  v_provider_changed boolean := false;
  v_by_admin boolean := (p_actor_id IS DISTINCT FROM p_merchant_id);
BEGIN
  IF p_provider IS NULL OR p_provider NOT IN ('sim','moyasar','tap','paytabs','payfort','hyperpay','checkout') THEN
    RAISE EXCEPTION 'BAD_PROVIDER';
  END IF;

  SELECT * INTO v_row FROM public.merchant_gateways WHERE merchant_id = p_merchant_id;
  IF NOT FOUND THEN
    INSERT INTO public.merchant_gateways (merchant_id, provider)
    VALUES (p_merchant_id, p_provider) RETURNING * INTO v_row;
  END IF;
  v_provider_changed := (v_row.provider IS DISTINCT FROM p_provider);

  -- الوضع التجريبي لا يطلب مفاتيح — سر داخلي عشوائي يُولَّد له
  IF p_provider = 'sim' AND v_sk IS NULL AND (v_provider_changed OR v_row.secret_key_id IS NULL) THEN
    v_sk := md5(random()::text || clock_timestamp()::text) || md5(random()::text || p_merchant_id);
  END IF;

  UPDATE public.merchant_gateways SET
    provider        = p_provider,
    publishable_key = COALESCE(NULLIF(btrim(COALESCE(p_publishable_key,'')), ''), publishable_key),
    extra_config    = COALESCE(p_extra, extra_config),
    verified_at     = CASE WHEN v_provider_changed OR v_sk IS NOT NULL OR v_ws IS NOT NULL THEN NULL ELSE verified_at END,
    is_enabled      = CASE WHEN v_provider_changed THEN false ELSE is_enabled END,
    fail_count      = 0,
    updated_at      = now()
  WHERE merchant_id = p_merchant_id;

  IF v_sk IS NOT NULL THEN
    IF v_row.secret_key_id IS NULL THEN
      UPDATE public.merchant_gateways
      SET secret_key_id = vault.create_secret(v_sk, 'mg_' || p_merchant_id || '_sk', 'TAKI merchant gateway secret key'),
          key_last4     = right(v_sk, 4)
      WHERE merchant_id = p_merchant_id;
    ELSE
      PERFORM vault.update_secret(v_row.secret_key_id, v_sk);
      UPDATE public.merchant_gateways SET key_last4 = right(v_sk, 4) WHERE merchant_id = p_merchant_id;
    END IF;
  END IF;

  IF v_ws IS NOT NULL THEN
    IF v_row.webhook_secret_id IS NULL THEN
      UPDATE public.merchant_gateways
      SET webhook_secret_id = vault.create_secret(v_ws, 'mg_' || p_merchant_id || '_whs', 'TAKI merchant gateway webhook secret')
      WHERE merchant_id = p_merchant_id;
    ELSE
      PERFORM vault.update_secret(v_row.webhook_secret_id, v_ws);
    END IF;
  END IF;

  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (p_actor_id, p_actor_type, 'gateway_keys_updated', 'merchant_gateway', p_merchant_id,
          jsonb_build_object('provider', p_provider, 'by_admin', v_by_admin,
                             'secret_changed', v_sk IS NOT NULL, 'webhook_changed', v_ws IS NOT NULL));
  INSERT INTO public.notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES ('ntf_gw_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
          p_merchant_id,
          '🔐 تحديث بيانات بوابة الدفع', 'Payment gateway credentials updated',
          CASE WHEN v_by_admin
            THEN 'قامت الإدارة بإعداد/تحديث بوابة الدفع لمتجرك. تجدها في لوحتك ← بطاقة «💳 بوابة الدفع».'
            ELSE 'تم تحديث بيانات بوابة الدفع لمتجرك. إن لم تكن أنت من قام بذلك فأوقف البوابة فوراً وتواصل مع الإدارة.' END,
          CASE WHEN v_by_admin
            THEN 'The platform admin configured/updated your store''s payment gateway.'
            ELSE 'Your store''s payment gateway credentials were updated. If this was not you, disable the gateway immediately and contact support.' END,
          'system', jsonb_build_object('audience', 'seller'));

  RETURN public._gateway_masked(p_merchant_id);
END $$;


