--

CREATE FUNCTION public._taki_client_ip() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT nullif(
           split_part(
             coalesce(
               nullif(current_setting('request.headers', true), '')::json ->> 'x-forwarded-for',
               ''),
             ',', 1),
           '');
$$;


--
-- Name: _taki_deal_branches_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._taki_deal_branches_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM public.deal_branches WHERE deal_id = OLD.id;
    RETURN NULL;
  END IF;
  PERFORM public._taki_rebuild_deal_branches(NEW.id);
  RETURN NULL;
END
$$;


--
-- Name: _taki_deal_loc_keys(text, double precision, double precision, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._taki_deal_loc_keys(p_location_id text, p_lat double precision, p_lng double precision, p_locations jsonb) RETURNS SETOF text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_location_id IS NOT NULL AND p_location_id <> 'other'
         AND p_location_id NOT LIKE 'custom\_%' ESCAPE '\'
    THEN 'loc:' || p_location_id
    ELSE 'geo:' || ROUND(COALESCE(p_lat,0)::numeric,3)::text || ',' || ROUND(COALESCE(p_lng,0)::numeric,3)::text
  END
  UNION
  SELECT CASE
    WHEN NULLIF(e->>'locationId','') IS NOT NULL AND e->>'locationId' <> 'other'
         AND e->>'locationId' NOT LIKE 'custom\_%' ESCAPE '\'
    THEN 'loc:' || (e->>'locationId')
    ELSE 'geo:' || ROUND(COALESCE(NULLIF(e->>'lat','')::numeric,0),3)::text || ',' || ROUND(COALESCE(NULLIF(e->>'lng','')::numeric,0),3)::text
  END
  FROM jsonb_array_elements(
         CASE WHEN p_locations IS NOT NULL AND jsonb_typeof(p_locations) = 'array'
              THEN p_locations ELSE '[]'::jsonb END) e
  WHERE COALESCE(e->>'id','') <> 'primary';
$$;


--
-- Name: _taki_km(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._taki_km(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT 2 * 6371 * asin(least(1.0, sqrt(
      power(sin(radians(lat2 - lat1) / 2), 2)
    + cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2))));
$$;


--
-- Name: _taki_point_in_polygon(jsonb, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._taki_point_in_polygon(p_pts jsonb, p_lat double precision, p_lng double precision) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$
DECLARE n int; i int; j int; xi float8; yi float8; xj float8; yj float8; inside boolean := false;
BEGIN
  IF p_pts IS NULL OR jsonb_typeof(p_pts) <> 'array' THEN RETURN false; END IF;
  n := jsonb_array_length(p_pts);
  IF n < 3 THEN RETURN false; END IF;
  j := n - 1;
  FOR i IN 0 .. n - 1 LOOP
    yi := (p_pts->i->>0)::float8; xi := (p_pts->i->>1)::float8;
    yj := (p_pts->j->>0)::float8; xj := (p_pts->j->>1)::float8;
    IF ((yi > p_lat) <> (yj > p_lat))
       AND (p_lng < (xj - xi) * (p_lat - yi) / (yj - yi) + xi) THEN
      inside := NOT inside;
    END IF;
    j := i;
  END LOOP;
  RETURN inside;
END
$$;


--
-- Name: _taki_rebuild_deal_branches(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._taki_rebuild_deal_branches(p_deal_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE d public.deals%ROWTYPE;
BEGIN
  DELETE FROM public.deal_branches WHERE deal_id = p_deal_id;
  SELECT * INTO d FROM public.deals WHERE id = p_deal_id;
  IF NOT FOUND OR d.status = 'deleted' THEN RETURN; END IF;

  IF jsonb_typeof(d.locations) = 'array' AND jsonb_array_length(d.locations) > 1 THEN
    INSERT INTO public.deal_branches (deal_id, branch_id, lat, lng, location_id, branch_name, region, city, quantity)
    SELECT d.id,
           COALESCE(NULLIF(e->>'id',''), 'b' || ord::text),
           COALESCE(kn.lat, NULLIF(e->>'lat','')::double precision),
           COALESCE(kn.lng, NULLIF(e->>'lng','')::double precision),
           NULLIF(e->>'locationId',''),
           COALESCE(NULLIF(e->>'name',''), kn.name, ''),
           COALESCE(NULLIF(e->>'region',''), c.region_id, d.region),
           COALESCE(NULLIF(e->>'city',''),   kn.city_id,  d.city),
           CASE WHEN d.loc_qty_mode = 'per_location'
                THEN NULLIF(e->>'quantity','')::integer ELSE NULL END
    FROM jsonb_array_elements(d.locations) WITH ORDINALITY AS t(e, ord)
    LEFT JOIN public.locations kn ON kn.id = NULLIF(e->>'locationId','')
    LEFT JOIN public.cities    c  ON c.id  = kn.city_id
    ON CONFLICT (deal_id, branch_id) DO NOTHING;
  ELSE
    INSERT INTO public.deal_branches (deal_id, branch_id, lat, lng, location_id, branch_name, region, city, quantity)
    SELECT d.id, 'primary',
           COALESCE(kn.lat, d.map_lat),
           COALESCE(kn.lng, d.map_lng),
           d.location_id,
           COALESCE(kn.name, d.custom_location_name, ''),
           d.region, d.city, NULL
    FROM (SELECT 1) z
    LEFT JOIN public.locations kn ON kn.id = d.location_id;
  END IF;
END
$$;


--
-- Name: _taki_sync_deal_auth_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._taki_sync_deal_auth_counts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_deal text := COALESCE(NEW.deal_id, OLD.deal_id);
BEGIN
  -- تحديث جزئي لا يمسّ status، فلا يستفزّ tr_guard_deal_publish.
  UPDATE public.deals d
     SET auth_real_count = (SELECT count(*) FROM public.deal_authenticity_votes v
                             WHERE v.deal_id = v_deal AND v.is_real),
         auth_fake_count = (SELECT count(*) FROM public.deal_authenticity_votes v
                             WHERE v.deal_id = v_deal AND NOT v.is_real)
   WHERE d.id = v_deal;
  RETURN NULL;
END
$$;


--
-- Name: _taki_sync_deal_bookings_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._taki_sync_deal_bookings_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_deal text := COALESCE(NEW.deal_id, OLD.deal_id);
BEGIN
  IF v_deal IS NULL THEN RETURN NULL; END IF;
  -- تحديث جزئي لا يمسّ status فلا يستفزّ tr_guard_deal_publish
  UPDATE public.deals d
     SET bookings_count = (SELECT count(*) FROM public.bookings b
                            WHERE b.deal_id = v_deal AND b.status <> 'cancelled')
   WHERE d.id = v_deal;
  RETURN NULL;
END
$$;


--
-- Name: _taki_sync_deal_rating_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._taki_sync_deal_rating_stats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_deal text := COALESCE(NEW.deal_id, OLD.deal_id);
BEGIN
  UPDATE public.deals d
     SET rating_avg   = COALESCE(s.avg_score, 0),
         rating_count = COALESCE(s.n, 0)
    FROM (SELECT round(avg(r.score)::numeric, 2) AS avg_score, count(*) AS n
            FROM public.ratings r
           WHERE r.deal_id = v_deal AND r.deleted_at IS NULL) s
   WHERE d.id = v_deal;
  RETURN NULL;
END
$$;


