-- Name: _taki_user_is_admin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._taki_user_is_admin(p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS (SELECT 1 FROM users WHERE id = p_user_id AND user_type = 'admin'); $$;


--
-- Name: store_delivery_zones; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.store_delivery_zones (
    id text DEFAULT ('dz_'::text || replace((gen_random_uuid())::text, '-'::text, ''::text)) NOT NULL,
    store_id text NOT NULL,
    name text,
    kind text NOT NULL,
    center_lat double precision,
    center_lng double precision,
    radius_km numeric,
    points jsonb,
    fee numeric,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    branch_id text,
    CONSTRAINT store_delivery_zones_kind_check CHECK ((kind = ANY (ARRAY['circle'::text, 'rect'::text, 'polygon'::text])))
);


--
-- Name: _taki_zone_contains(public.store_delivery_zones, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._taki_zone_contains(z public.store_delivery_zones, p_lat double precision, p_lng double precision) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$
DECLARE a_lat float8; a_lng float8; b_lat float8; b_lng float8;
BEGIN
  IF p_lat IS NULL OR p_lng IS NULL THEN RETURN false; END IF;
  IF z.kind = 'circle' THEN
    RETURN public._taki_km(z.center_lat, z.center_lng, p_lat, p_lng) <= z.radius_km;
  ELSIF z.kind = 'rect' THEN
    a_lat := (z.points->0->>0)::float8; a_lng := (z.points->0->>1)::float8;
    b_lat := (z.points->1->>0)::float8; b_lng := (z.points->1->>1)::float8;
    RETURN p_lat BETWEEN least(a_lat, b_lat) AND greatest(a_lat, b_lat)
       AND p_lng BETWEEN least(a_lng, b_lng) AND greatest(a_lng, b_lng);
  ELSE
    RETURN public._taki_point_in_polygon(z.points, p_lat, p_lng);
  END IF;
END
$$;


--
-- Name: account_exists(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_exists(p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_email_taken boolean := false;
  v_phone_taken boolean := false;
  v_ip          text;
BEGIN
  v_ip := public._taki_client_ip();
  IF v_ip IS NOT NULL THEN
    PERFORM public.taki_rate_check('acex1m:' || v_ip, 20, 60,
      '⏳ محاولات كثيرة خلال وقت قصير — انتظر دقيقة ثم أعد المحاولة.');
    PERFORM public.taki_rate_check('acex1h:' || v_ip, 200, 3600,
      '⏳ محاولات كثيرة — أعد المحاولة بعد قليل.');
  END IF;

  IF p_email IS NOT NULL AND length(btrim(p_email)) > 0 THEN
    SELECT EXISTS(SELECT 1 FROM public.users WHERE email ILIKE p_email AND deleted_at IS NULL) INTO v_email_taken;
  END IF;
  IF p_phone IS NOT NULL AND length(btrim(p_phone)) > 0 THEN
    SELECT EXISTS(SELECT 1 FROM public.users WHERE phone = p_phone AND deleted_at IS NULL) INTO v_phone_taken;
  END IF;
  RETURN jsonb_build_object('email_taken', v_email_taken, 'phone_taken', v_phone_taken);
END;
$$;


--
-- Name: taki_norm(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_norm(txt text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT NULLIF(btrim(
    regexp_replace(
      translate(
        translate(
          lower(
            -- ١) حذف التشكيل والتطويل: U+0610..061A, U+064B..065F, U+0640, U+0670, U+06D6..06ED
            regexp_replace(
              COALESCE(txt, ''),
              '[' || chr(1552) || '-' || chr(1562)
                  || chr(1611) || '-' || chr(1631)
                  || chr(1600) || chr(1648)
                  || chr(1750) || '-' || chr(1773) || ']',
              '', 'g'
            )
          ),
          -- ٢) توحيد الحروف: أ إ آ ٱ → ا | ى ئ → ي | ؤ → و | ة → ه
          chr(1571)||chr(1573)||chr(1570)||chr(1649)||chr(1609)||chr(1574)||chr(1572)||chr(1577),
          chr(1575)||chr(1575)||chr(1575)||chr(1575)||chr(1610)||chr(1610)||chr(1608)||chr(1607)
        ),
        -- ٣) الأرقام العربية والفارسية → لاتينية
        chr(1632)||chr(1633)||chr(1634)||chr(1635)||chr(1636)||chr(1637)||chr(1638)||chr(1639)||chr(1640)||chr(1641)||
        chr(1776)||chr(1777)||chr(1778)||chr(1779)||chr(1780)||chr(1781)||chr(1782)||chr(1783)||chr(1784)||chr(1785),
        '01234567890123456789'
      ),
      -- ٤) كل ما عدا الحروف/الأرقام يصير مسافة واحدة (يوحّد الترقيم والرموز)
      '[^0-9a-z' || chr(224) || '-' || chr(255) || chr(1569) || '-' || chr(1610) || ']+',
      ' ', 'g'
    )
  ), '');
$$;


--
-- Name: FUNCTION taki_norm(txt text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.taki_norm(txt text) IS 'v13.24 — تطبيع عربي موحّد للبحث: حذف التشكيل/التطويل، توحيد الألف والياء والتاء المربوطة والهمزات، تحويل الأرقام العربية، وتوحيد الترقيم إلى مسافات.';


--
-- Name: bookings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bookings (
    barcode text NOT NULL,
    backup_code text NOT NULL,
    deal_id text NOT NULL,
    user_id text NOT NULL,
    store_id text NOT NULL,
    booked_quantity integer DEFAULT 1,
    prep_time text,
    notes text,
    status text DEFAULT 'pending'::text,
    booked_at bigint NOT NULL,
    expiry_time bigint NOT NULL,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    merchant_note text,
    user_name text,
    user_phone text,
    expiry_warned boolean DEFAULT false,
    closing_warned boolean DEFAULT false,
    source text DEFAULT 'web'::text NOT NULL,
    cancelled_by text,
    selected_options jsonb,
    paid_at timestamp with time zone,
    payment_provider text,
    payment_ref text,
    paid_amount numeric,
    payment_expected numeric,
    location_id text,
    payment_method text,
    search_norm text GENERATED ALWAYS AS (public.taki_norm(((((((((COALESCE(user_name, ''::text) || ' '::text) || COALESCE(notes, ''::text)) || ' '::text) || COALESCE(barcode, ''::text)) || ' '::text) || COALESCE(backup_code, ''::text)) || ' '::text) || COALESCE(user_phone, ''::text)))) STORED,
    fulfillment text DEFAULT 'pickup'::text NOT NULL,
    delivery_address jsonb,
    delivery_fee numeric,
    completed_by text,
    total_amount numeric,
    CONSTRAINT bookings_fulfillment_chk CHECK ((fulfillment = ANY (ARRAY['pickup'::text, 'delivery'::text]))),
    CONSTRAINT bookings_source_chk CHECK ((source = ANY (ARRAY['web'::text, 'telegram'::text, 'whatsapp'::text]))),
    CONSTRAINT bookings_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'acknowledged'::text, 'completed'::text, 'cancelled'::text]))),
    CONSTRAINT bookings_total_amount_sane CHECK (((total_amount IS NULL) OR ((total_amount >= (0)::numeric) AND (total_amount <= (1000000)::numeric))))
);

ALTER TABLE ONLY public.bookings REPLICA IDENTITY FULL;


--
-- Name: COLUMN bookings.merchant_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bookings.merchant_note IS 'Note left by the merchant when acknowledging an order — separate from buyer notes column.';


--
-- Name: COLUMN bookings.location_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bookings.location_id IS 'v12.91 chosen deal_locations.id for this booking (per-location stock decrement)';


--
-- Name: COLUMN bookings.payment_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bookings.payment_method IS 'v13.11 نية الدفع وقت الحجز: cod (عند الاستلام) | online (إلكتروني) | NULL (قديم). يخفي زر «ادفع الآن» عن حجوزات COD.';


--
-- Name: COLUMN bookings.completed_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bookings.completed_by IS 'seller | buyer | system — من أغلق الطلب. يُكتب من الخادم وحده (أثر تدقيق للنزاعات).';


--
-- Name: COLUMN bookings.total_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bookings.total_amount IS 'إجمالي الفاتورة بالريال وقت الحجز (بضاعة + إضافات + توصيل) — يكتبه tr_ae_set_booking_total ولا يلمسه العميل';


--
-- Name: acknowledge_booking(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_booking(p_barcode text, p_merchant_note text DEFAULT NULL::text) RETURNS public.bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    caller text := auth.uid()::text;
    updated public.bookings;
BEGIN
    IF caller IS NULL THEN
        RAISE EXCEPTION 'يجب تسجيل الدخول' USING ERRCODE = '28000';
    END IF;

    UPDATE public.bookings
    SET status = 'acknowledged',
        merchant_note = COALESCE(p_merchant_note, merchant_note)
    WHERE barcode = p_barcode
      AND status = 'pending'
      AND caller = store_id
    RETURNING * INTO updated;

    IF updated.barcode IS NULL THEN
        IF EXISTS (
            SELECT 1 FROM public.bookings
            WHERE barcode = p_barcode AND caller = store_id
        ) THEN
            RAISE EXCEPTION 'الحجز ليس في حالة انتظار' USING ERRCODE = 'P0001';
        ELSE
            RAISE EXCEPTION 'لم يتم العثور على الحجز أو ليست لديك صلاحية' USING ERRCODE = 'P0002';
        END IF;
    END IF;

    RETURN updated;
END;
$$;


--
-- Name: adjust_deal_quantity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adjust_deal_quantity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sel    jsonb;
  v_dir    int;
  v_need   int;
  v_rows   int;
  v_capped boolean;
BEGIN
    v_need := GREATEST(COALESCE(NEW.booked_quantity, 1), 1);

    IF TG_OP = 'INSERT' THEN
        v_dir := -1;
    ELSIF TG_OP = 'UPDATE' AND NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM 'cancelled' THEN
        v_dir := 1;
    ELSE
        RETURN NEW;
    END IF;

    SELECT NOT COALESCE(d.is_unlimited, false) AND COALESCE(d.initial_quantity, 0) > 0
      INTO v_capped FROM deals d WHERE d.id = NEW.deal_id;

    IF v_dir = -1 THEN
        IF COALESCE(v_capped, false) THEN
            UPDATE deals SET quantity = quantity - v_need
             WHERE id = NEW.deal_id AND quantity >= v_need;
            GET DIAGNOSTICS v_rows = ROW_COUNT;
            IF v_rows = 0 THEN
                RAISE EXCEPTION 'نفدت الكمية — سبقك مشترون آخرون إليها'
                    USING ERRCODE = 'P0010';
            END IF;
        ELSE
            UPDATE deals SET quantity = GREATEST(0, COALESCE(quantity, 0) - v_need)
             WHERE id = NEW.deal_id AND COALESCE(is_unlimited, false) = FALSE;
        END IF;
    ELSE
        UPDATE deals SET quantity = COALESCE(quantity, 0) + v_need
         WHERE id = NEW.deal_id AND COALESCE(is_unlimited, false) = FALSE;
    END IF;

    IF NEW.selected_options IS NOT NULL AND jsonb_typeof(NEW.selected_options) = 'array' THEN
      FOR v_sel IN SELECT * FROM jsonb_array_elements(NEW.selected_options) LOOP
        CONTINUE WHEN v_sel->>'g' IS DISTINCT FROM '__variant__';
        UPDATE deals d SET variants = (
          SELECT jsonb_agg(
            CASE WHEN e->>'id' = v_sel->>'c' AND (e ? 'qty') AND NULLIF(e->>'qty','') IS NOT NULL
                 THEN jsonb_set(e, '{qty}', to_jsonb(GREATEST(0,
                        (e->>'qty')::int + v_dir * GREATEST(COALESCE((v_sel->>'qty')::int,1),1))))
                 ELSE e END)
          FROM jsonb_array_elements(d.variants) e)
        WHERE d.id = NEW.deal_id
          AND d.variants IS NOT NULL AND jsonb_typeof(d.variants) = 'array'
          AND (v_dir = 1 OR COALESCE((
                SELECT NULLIF(e2->>'qty','')::int FROM jsonb_array_elements(d.variants) e2
                 WHERE e2->>'id' = v_sel->>'c' LIMIT 1), 2147483647)
              >= GREATEST(COALESCE((v_sel->>'qty')::int,1),1));
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_dir = -1 AND v_rows = 0
           AND EXISTS (SELECT 1 FROM deals d2
                        WHERE d2.id = NEW.deal_id
                          AND d2.variants IS NOT NULL
                          AND jsonb_typeof(d2.variants) = 'array') THEN
            RAISE EXCEPTION 'نفدت كمية النوع المختار — سبقك مشترون آخرون إليه'
                USING ERRCODE = 'P0010';
        END IF;
      END LOOP;
    END IF;

    IF NEW.location_id IS NOT NULL THEN
      UPDATE deals d SET locations = (
        SELECT jsonb_agg(
          CASE WHEN e->>'id' = NEW.location_id AND (e ? 'quantity') AND NULLIF(e->>'quantity','') IS NOT NULL
               THEN jsonb_set(e, '{quantity}', to_jsonb(GREATEST(0,
                      (e->>'quantity')::int + v_dir * v_need)))
               ELSE e END)
        FROM jsonb_array_elements(d.locations) e)
      WHERE d.id = NEW.deal_id
        AND d.loc_qty_mode = 'per_location'
        AND d.locations IS NOT NULL AND jsonb_typeof(d.locations) = 'array'
        AND (v_dir = 1 OR COALESCE((
              SELECT NULLIF(e2->>'quantity','')::int FROM jsonb_array_elements(d.locations) e2
               WHERE e2->>'id' = NEW.location_id LIMIT 1), 2147483647) >= v_need);
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_dir = -1 AND v_rows = 0
         AND EXISTS (SELECT 1 FROM deals d2
                      WHERE d2.id = NEW.deal_id AND d2.loc_qty_mode = 'per_location'
                        AND d2.locations IS NOT NULL AND jsonb_typeof(d2.locations) = 'array') THEN
          RAISE EXCEPTION 'نفدت كمية هذا الفرع — سبقك مشترون آخرون إليها'
              USING ERRCODE = 'P0010';
      END IF;
    END IF;

    IF NEW.location_id IS NOT NULL
       AND NEW.selected_options IS NOT NULL AND jsonb_typeof(NEW.selected_options) = 'array' THEN
      FOR v_sel IN SELECT * FROM jsonb_array_elements(NEW.selected_options) LOOP
        CONTINUE WHEN v_sel->>'g' IS DISTINCT FROM '__variant__';
        UPDATE deals d SET locations = (
          SELECT jsonb_agg(
            CASE WHEN e->>'id' = NEW.location_id
                  AND (e ? 'variantQtys')
                  AND ((e->'variantQtys') ? (v_sel->>'c'))
                  AND NULLIF(e->'variantQtys'->>(v_sel->>'c'),'') IS NOT NULL
                 THEN jsonb_set(e, ARRAY['variantQtys', v_sel->>'c'], to_jsonb(GREATEST(0,
                        (e->'variantQtys'->>(v_sel->>'c'))::int + v_dir * GREATEST(COALESCE((v_sel->>'qty')::int,1),1))))
                 ELSE e END)
          FROM jsonb_array_elements(d.locations) e)
        WHERE d.id = NEW.deal_id
          AND d.loc_qty_mode = 'per_location'
          AND d.locations IS NOT NULL AND jsonb_typeof(d.locations) = 'array'
          AND (v_dir = 1 OR COALESCE((
                SELECT NULLIF(e2->'variantQtys'->>(v_sel->>'c'),'')::int
                  FROM jsonb_array_elements(d.locations) e2
                 WHERE e2->>'id' = NEW.location_id AND (e2 ? 'variantQtys') LIMIT 1), 2147483647)
              >= GREATEST(COALESCE((v_sel->>'qty')::int,1),1));
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_dir = -1 AND v_rows = 0
           AND EXISTS (SELECT 1 FROM deals d2
                        WHERE d2.id = NEW.deal_id AND d2.loc_qty_mode = 'per_location'
                          AND d2.locations IS NOT NULL AND jsonb_typeof(d2.locations) = 'array') THEN
            RAISE EXCEPTION 'نفد هذا النوع في الفرع المختار — سبقك مشترون آخرون إليه'
                USING ERRCODE = 'P0010';
        END IF;
      END LOOP;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: admin_activity_heatmap(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_activity_heatmap(p_days integer DEFAULT 30) RETURNS TABLE(dow integer, hour integer, cnt integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT EXTRACT(DOW   FROM created_at AT TIME ZONE 'Asia/Riyadh')::INT,
           EXTRACT(HOUR  FROM created_at AT TIME ZONE 'Asia/Riyadh')::INT,
           COUNT(*)::INT
    FROM activity_log
    WHERE created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
    GROUP BY 1, 2
    ORDER BY 1, 2;
END;
$$;


--
-- Name: admin_ai_analyst(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_ai_analyst(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    d int := GREATEST(7, LEAST(365, COALESCE(p_days, 30)));
    since timestamptz := now() - (GREATEST(7, LEAST(365, COALESCE(p_days, 30)))::text || ' days')::interval;
    res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;

    SELECT jsonb_build_object(
      'generated_at', now(),
      'days', d,

      'peak_hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb)
        FROM (SELECT extract(hour FROM created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
              FROM bookings WHERE created_at >= since GROUP BY 1) t),
      'peak_days', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('dow', dow, 'n', n) ORDER BY dow), '[]'::jsonb)
        FROM (SELECT extract(dow FROM created_at AT TIME ZONE 'Asia/Riyadh')::int dow, count(*) n
              FROM bookings WHERE created_at >= since GROUP BY 1) t),

      'funnel', (
        SELECT jsonb_build_object(
          'deal_views',  (SELECT count(*) FROM analytics_events WHERE kind='deal_view'  AND created_at >= since),
          'store_views', (SELECT count(*) FROM analytics_events WHERE kind='store_view' AND created_at >= since),
          'bookings',    (SELECT count(*) FROM bookings WHERE created_at >= since),
          'completed',   (SELECT count(*) FROM bookings WHERE created_at >= since AND status='completed'),
          'cancelled',   (SELECT count(*) FROM bookings WHERE created_at >= since AND status IN ('cancelled','canceled','expired'))
        )),

      'monthly', (
        SELECT COALESCE(jsonb_agg(row_to_json(m)::jsonb ORDER BY m.mon), '[]'::jsonb) FROM (
          SELECT to_char(gs, 'YYYY-MM') mon,
            (SELECT count(*) FROM users u WHERE u.user_type='seller' AND u.deleted_at IS NULL AND date_trunc('month', u.created_at AT TIME ZONE 'Asia/Riyadh') = gs) new_sellers,
            (SELECT count(*) FROM users u WHERE u.user_type='buyer'  AND u.deleted_at IS NULL AND date_trunc('month', u.created_at AT TIME ZONE 'Asia/Riyadh') = gs) new_buyers,
            (SELECT count(*) FROM bookings b WHERE date_trunc('month', b.created_at AT TIME ZONE 'Asia/Riyadh') = gs) bookings,
            (SELECT COALESCE(sum(p.amount),0) FROM subscription_payments p WHERE p.status='paid' AND date_trunc('month', p.paid_at AT TIME ZONE 'Asia/Riyadh') = gs) revenue
          FROM generate_series(date_trunc('month', (now() AT TIME ZONE 'Asia/Riyadh') - interval '5 months'),
                               date_trunc('month', now() AT TIME ZONE 'Asia/Riyadh'), interval '1 month') gs
        ) m),

      'seasonal', (
        SELECT COALESCE(jsonb_agg(row_to_json(m)::jsonb ORDER BY m.mon), '[]'::jsonb) FROM (
          SELECT to_char(date_trunc('month', b.created_at AT TIME ZONE 'Asia/Riyadh'), 'YYYY-MM') mon, count(*) bookings
          FROM bookings b WHERE b.created_at >= now() - interval '12 months' GROUP BY 1
        ) m),

      'renewals', (
        SELECT COALESCE(jsonb_agg(row_to_json(r)::jsonb ORDER BY r.mon), '[]'::jsonb) FROM (
          SELECT to_char(date_trunc('month', p.period_end AT TIME ZONE 'Asia/Riyadh'), 'YYYY-MM') mon,
                 count(*) expired,
                 count(*) FILTER (WHERE EXISTS (
                   SELECT 1 FROM subscription_payments p2
                   WHERE p2.merchant_id = p.merchant_id AND p2.status='paid'
                     AND p2.period_start > p.period_start
                     AND p2.period_start <= p.period_end + interval '21 days'
                 )) renewed
          FROM subscription_payments p
          WHERE p.status='paid' AND p.period_end >= now() - interval '6 months' AND p.period_end <= now()
          GROUP BY 1
        ) r),

      'sellers', (
        SELECT COALESCE(jsonb_agg(row_to_json(s)::jsonb), '[]'::jsonb) FROM (
          SELECT u.id, COALESCE(NULLIF(btrim(u.shop),''), u.name) shop,
                 -- مدينة التاجر = المدينة الأكثر تكراراً في عروضه
                 (SELECT dl.city FROM deals dl WHERE dl.store_id=u.id AND COALESCE(btrim(dl.city),'') <> ''
                   GROUP BY dl.city ORDER BY count(*) DESC LIMIT 1) city,
                 u.created_at, u.last_active_at,
                 sp.subscription_plan plan, sp.subscription_expires_at expires_at,
                 (SELECT count(*) FROM deals dl WHERE dl.store_id=u.id AND dl.status='active') active_deals,
                 (SELECT count(*) FROM deals dl WHERE dl.store_id=u.id AND dl.status<>'active') inactive_deals,
                 (SELECT count(*) FROM bookings b WHERE b.store_id=u.id AND b.created_at >= now() - interval '30 days') bookings_30,
                 (SELECT count(*) FROM bookings b WHERE b.store_id=u.id AND b.created_at >= now() - interval '60 days' AND b.created_at < now() - interval '30 days') bookings_prev30,
                 (SELECT count(*) FROM analytics_events e WHERE e.store_id=u.id AND e.kind='deal_view'  AND e.created_at >= now() - interval '30 days') deal_views_30,
                 (SELECT count(*) FROM analytics_events e WHERE e.store_id=u.id AND e.kind='store_view' AND e.created_at >= now() - interval '30 days') store_views_30,
                 (SELECT round(avg(r.score)::numeric, 1) FROM ratings r WHERE r.store_id=u.id AND r.deleted_at IS NULL) rating_avg,
                 (SELECT count(*) FROM ratings r WHERE r.store_id=u.id AND r.deleted_at IS NULL) rating_count,
                 (SELECT dl.category FROM deals dl LEFT JOIN bookings b2 ON b2.deal_id=dl.id
                   WHERE dl.store_id=u.id GROUP BY dl.category
                   ORDER BY count(b2.barcode) DESC NULLS LAST LIMIT 1) top_category,
                 (SELECT round(avg(COALESCE(array_length(dl.images,1),0))::numeric,1)
                   FROM deals dl WHERE dl.store_id=u.id AND dl.status='active') avg_images,
                 (SELECT count(*) FROM deals dl WHERE dl.store_id=u.id AND dl.status='active'
                   AND COALESCE(array_length(dl.images,1),0) <= 1) weak_image_deals,
                 (SELECT count(*) FROM deals dl WHERE dl.store_id=u.id AND dl.status='active'
                   AND length(COALESCE(dl.description,'')) < 20) weak_desc_deals,
                 COALESCE((u.working_hours->>'enabled')::boolean, false) has_hours
          FROM users u
          LEFT JOIN store_profiles sp ON sp.store_id = u.id
          WHERE u.user_type IN ('seller','admin') AND u.deleted_at IS NULL AND u.is_suspended IS NOT TRUE
            AND (u.user_type='seller' OR COALESCE(NULLIF(btrim(u.shop),''),'') <> '')
        ) s),

      'cities', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.city),''),'غير محدد') city,
                 count(DISTINCT dl.id) FILTER (WHERE dl.status='active') deals,
                 count(b.barcode) bookings
          FROM deals dl LEFT JOIN bookings b ON b.deal_id = dl.id AND b.created_at >= since
          GROUP BY 1 ORDER BY count(b.barcode) DESC LIMIT 15
        ) c),
      'regions', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.region),''),'غير محدد') region,
                 count(DISTINCT dl.id) FILTER (WHERE dl.status='active') deals,
                 count(b.barcode) bookings
          FROM deals dl LEFT JOIN bookings b ON b.deal_id = dl.id AND b.created_at >= since
          GROUP BY 1 ORDER BY count(b.barcode) DESC LIMIT 13
        ) c),
      'categories', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.category),''),'other') category,
                 count(DISTINCT dl.id) FILTER (WHERE dl.status='active') deals,
                 count(b.barcode) bookings
          FROM deals dl LEFT JOIN bookings b ON b.deal_id = dl.id AND b.created_at >= since
          GROUP BY 1 ORDER BY count(b.barcode) DESC LIMIT 20
        ) c),
      'malls', (
        SELECT COALESCE(jsonb_agg(row_to_json(m)::jsonb ORDER BY m.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(l.name, dl.custom_location_name, 'غير محدد') mall,
                 count(DISTINCT dl.id) FILTER (WHERE dl.status='active') deals,
                 count(b.barcode) bookings
          FROM deals dl
          LEFT JOIN locations l ON l.id = dl.location_id
          LEFT JOIN bookings b ON b.deal_id = dl.id AND b.created_at >= since
          GROUP BY 1 ORDER BY count(b.barcode) DESC LIMIT 12
        ) m),

      -- مدن نشاط المشترين = أين يحجزون فعلاً
      'buyers_by_city', (
        SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.buyers DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.city),''),'غير محدد') city,
                 count(DISTINCT b.user_id) buyers, count(*) bookings
          FROM bookings b JOIN deals dl ON dl.id = b.deal_id
          WHERE b.created_at >= now() - interval '90 days'
          GROUP BY 1 ORDER BY 2 DESC LIMIT 15
        ) t),

      'content', (
        SELECT jsonb_build_object(
          'active_deals', count(*),
          'no_image',  count(*) FILTER (WHERE COALESCE(array_length(images,1),0) = 0),
          'one_image', count(*) FILTER (WHERE COALESCE(array_length(images,1),0) = 1),
          'no_desc',   count(*) FILTER (WHERE length(COALESCE(description,'')) < 20)
        ) FROM deals WHERE status='active'),

      'buyers', (
        SELECT jsonb_build_object(
          'total',      (SELECT count(*) FROM users WHERE user_type='buyer' AND deleted_at IS NULL),
          'active_30',  (SELECT count(DISTINCT b.user_id) FROM bookings b WHERE b.created_at >= now() - interval '30 days'),
          'with_booking', (SELECT count(DISTINCT b.user_id) FROM bookings b),
          'repeaters',  (SELECT count(*) FROM (SELECT b.user_id FROM bookings b GROUP BY b.user_id HAVING count(*) >= 2) t),
          'dormant_30', (SELECT count(*) FROM users u WHERE u.user_type='buyer' AND u.deleted_at IS NULL
                           AND COALESCE(u.last_active_at, u.created_at) < now() - interval '30 days')
        ))
    ) INTO res;
    RETURN res;
END $$;


--
-- Name: admin_ai_custom(text, text, integer, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_ai_custom(p_start text, p_end text, p_hour_from integer DEFAULT 0, p_hour_to integer DEFAULT 23, p_dow integer DEFAULT NULL::integer, p_city text DEFAULT NULL::text, p_category text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    d1 date := COALESCE(NULLIF(btrim(p_start),'')::date, (now() AT TIME ZONE 'Asia/Riyadh')::date - 30);
    d2 date := COALESCE(NULLIF(btrim(p_end),'')::date,   (now() AT TIME ZONE 'Asia/Riyadh')::date);
    f int := LEAST(23, GREATEST(0, COALESCE(p_hour_from, 0)));
    t int := LEAST(23, GREATEST(0, COALESCE(p_hour_to, 23)));
    res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    IF d2 < d1 THEN RAISE EXCEPTION 'نهاية الفترة قبل بدايتها'; END IF;
    IF d2 - d1 > 400 THEN d1 := d2 - 400; END IF;

    SELECT jsonb_build_object(
      'start', d1, 'end', d2, 'from', f, 'to', t, 'dow', p_dow, 'city', p_city, 'category', p_category,
      'totals', (
        WITH bw AS (
          SELECT b.*, dl.city dcity, dl.category dcat FROM bookings b
          JOIN deals dl ON dl.id = b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
        ), ew AS (
          SELECT e.* FROM analytics_events e
          LEFT JOIN deals dl ON dl.id = e.deal_id
          WHERE (e.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND CASE WHEN f <= t
                  THEN extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND (p_city IS NULL OR e.kind='search' OR dl.city = p_city)
            AND (p_category IS NULL OR e.kind='search' OR dl.category = p_category)
        ), dw AS (
          SELECT d.id FROM deals d
          WHERE (to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND CASE WHEN f <= t
                  THEN extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND (p_city IS NULL OR d.city = p_city)
            AND (p_category IS NULL OR d.category = p_category)
        )
        SELECT jsonb_build_object(
          'bookings',  (SELECT count(*) FROM bw),
          'completed', (SELECT count(*) FROM bw WHERE status='completed'),
          'cancelled', (SELECT count(*) FROM bw WHERE status='cancelled'),
          'cancel_buyer',  (SELECT count(*) FROM bw WHERE status='cancelled' AND cancelled_by='buyer'),
          'cancel_seller', (SELECT count(*) FROM bw WHERE status='cancelled' AND cancelled_by='seller'),
          'cancel_system', (SELECT count(*) FROM bw WHERE status='cancelled' AND cancelled_by='system'),
          'buyers',    (SELECT count(DISTINCT user_id) FROM bw),
          'sellers',   (SELECT count(DISTINCT store_id) FROM bw),
          'qty',       (SELECT COALESCE(sum(booked_quantity),0) FROM bw),
          'views',     (SELECT count(*) FROM ew WHERE kind IN ('deal_view','store_view')),
          'clicks',    (SELECT count(*) FROM ew WHERE kind='deal_click'),
          'searches',  (SELECT count(*) FROM ew WHERE kind='search'),
          'deals_published', (SELECT count(*) FROM dw)
        )),
      -- منحنى يومي عبر الفترة (لرسم الاتجاه)
      'daily', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('d', d0, 'n', n) ORDER BY d0), '[]'::jsonb) FROM (
          SELECT (b.created_at AT TIME ZONE 'Asia/Riyadh')::date d0, count(*) n
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY 1) x),
      -- توزيع الساعات داخل الشريحة
      'hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb) FROM (
          SELECT extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
          GROUP BY 1) x),
      'top_cities', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.city),''),'غير محدد') name, count(*) n,
                 count(*) FILTER (WHERE b.status='completed') ok, count(*) FILTER (WHERE b.status='cancelled') bad
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY 1 ORDER BY 2 DESC LIMIT 6) x),
      'top_categories', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.category),''),'other') name, count(*) n,
                 count(*) FILTER (WHERE b.status='completed') ok, count(*) FILTER (WHERE b.status='cancelled') bad
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY 1 ORDER BY 2 DESC LIMIT 6) x),
      'top_malls', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(l.name, dl.custom_location_name, 'غير محدد') name, count(*) n,
                 count(*) FILTER (WHERE b.status='completed') ok, count(*) FILTER (WHERE b.status='cancelled') bad
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id LEFT JOIN locations l ON l.id=dl.location_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY 1 ORDER BY 2 DESC LIMIT 6) x),
      'top_stores', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(u.shop),''), u.name) name, count(*) n,
                 count(*) FILTER (WHERE b.status='completed') ok, count(*) FILTER (WHERE b.status='cancelled') bad
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id JOIN users u ON u.id=b.store_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY 1 ORDER BY 2 DESC LIMIT 6) x),
      'top_deals', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT dl.item_name name, dl.shop_name shop, count(*) n
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY dl.id, dl.item_name, dl.shop_name ORDER BY count(*) DESC LIMIT 5) x)
    ) INTO res;
    RETURN res;
END $$;


--
-- Name: admin_ai_funnel(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_ai_funnel(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    since timestamptz := now() - (GREATEST(7, LEAST(365, COALESCE(p_days, 30)))::text || ' days')::interval;
    res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    SELECT jsonb_build_object(
      'funnel', (SELECT jsonb_build_object(
        'store_views', (SELECT count(*) FROM analytics_events WHERE kind='store_view' AND created_at >= since),
        'deal_views',  (SELECT count(*) FROM analytics_events WHERE kind='deal_view'  AND created_at >= since),
        'clicks',      (SELECT count(*) FROM analytics_events WHERE kind='deal_click' AND created_at >= since),
        'bookings',    (SELECT count(*) FROM bookings WHERE created_at >= since),
        'completed',   (SELECT count(*) FROM bookings WHERE created_at >= since AND status='completed'),
        'cancelled',   (SELECT count(*) FROM bookings WHERE created_at >= since AND status='cancelled'),
        'cancel_buyer',  (SELECT count(*) FROM bookings WHERE created_at >= since AND status='cancelled' AND cancelled_by='buyer'),
        'cancel_seller', (SELECT count(*) FROM bookings WHERE created_at >= since AND status='cancelled' AND cancelled_by='seller'),
        'cancel_system', (SELECT count(*) FROM bookings WHERE created_at >= since AND status='cancelled' AND cancelled_by='system'),
        'cancel_legacy', (SELECT count(*) FROM bookings WHERE created_at >= since AND status='cancelled' AND cancelled_by IS NULL)
      )),
      'by_city', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.city),''),'غير محدد') city,
                 count(*) bookings,
                 count(*) FILTER (WHERE b.status='completed') completed,
                 count(*) FILTER (WHERE b.status='cancelled') cancelled,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='buyer') c_buyer,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='seller') c_seller,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='system') c_system
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE b.created_at >= since GROUP BY 1
        ) c),
      'by_category', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.category),''),'other') category,
                 count(*) bookings,
                 count(*) FILTER (WHERE b.status='completed') completed,
                 count(*) FILTER (WHERE b.status='cancelled') cancelled,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='buyer') c_buyer,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='seller') c_seller,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='system') c_system
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE b.created_at >= since GROUP BY 1
        ) c),
      'by_store', (
        SELECT COALESCE(jsonb_agg(row_to_json(s)::jsonb ORDER BY s.cancelled DESC), '[]'::jsonb) FROM (
          SELECT b.store_id, COALESCE(NULLIF(btrim(u.shop),''), u.name) shop,
                 (SELECT dl2.city FROM deals dl2 WHERE dl2.store_id=b.store_id AND COALESCE(btrim(dl2.city),'')<>'' GROUP BY dl2.city ORDER BY count(*) DESC LIMIT 1) city,
                 count(*) bookings,
                 count(*) FILTER (WHERE b.status='completed') completed,
                 count(*) FILTER (WHERE b.status='cancelled') cancelled,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='seller') c_seller
          FROM bookings b JOIN users u ON u.id=b.store_id
          WHERE b.created_at >= since GROUP BY b.store_id, u.shop, u.name
        ) s),
      -- الاحتفاظ: أفواج المشترين شهرياً — كم عاد وحجز مرة ثانية؟
      'retention', (
        SELECT COALESCE(jsonb_agg(row_to_json(r)::jsonb ORDER BY r.cohort), '[]'::jsonb) FROM (
          SELECT to_char(date_trunc('month', f.first_at AT TIME ZONE 'Asia/Riyadh'), 'YYYY-MM') cohort,
                 count(*) buyers,
                 count(*) FILTER (WHERE f.total >= 2) returned
          FROM (SELECT b.user_id, min(b.created_at) first_at, count(*) total
                FROM bookings b GROUP BY b.user_id) f
          GROUP BY 1
        ) r)
    ) INTO res;
    RETURN res;
END $$;


--
-- Name: admin_ai_hours(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_ai_hours(p_from integer DEFAULT 0, p_to integer DEFAULT 23, p_dow integer DEFAULT NULL::integer, p_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    since timestamptz := now() - (GREATEST(7, LEAST(365, COALESCE(p_days, 90)))::text || ' days')::interval;
    f int := LEAST(23, GREATEST(0, COALESCE(p_from, 0)));
    t int := LEAST(23, GREATEST(0, COALESCE(p_to, 23)));
    res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;

    SELECT jsonb_build_object(
      'from', f, 'to', t, 'dow', p_dow, 'days', GREATEST(7, LEAST(365, COALESCE(p_days, 90))),
      'totals', (
        WITH bw AS (
          SELECT b.* FROM bookings b
          WHERE b.created_at >= since
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
        ), ew AS (
          SELECT e.* FROM analytics_events e
          WHERE e.created_at >= since
            AND CASE WHEN f <= t
                  THEN extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
        ), dw AS (
          SELECT d.id FROM deals d
          WHERE to_timestamp(d.created_at / 1000.0) >= since
            AND CASE WHEN f <= t
                  THEN extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
        )
        SELECT jsonb_build_object(
          'bookings',  (SELECT count(*) FROM bw),
          'completed', (SELECT count(*) FROM bw WHERE status='completed'),
          'cancelled', (SELECT count(*) FROM bw WHERE status='cancelled'),
          'buyers',    (SELECT count(DISTINCT user_id) FROM bw),
          'sellers',   (SELECT count(DISTINCT store_id) FROM bw),
          'views',     (SELECT count(*) FROM ew WHERE kind IN ('deal_view','store_view')),
          'clicks',    (SELECT count(*) FROM ew WHERE kind='deal_click'),
          'searches',  (SELECT count(*) FROM ew WHERE kind='search'),
          'deals_published', (SELECT count(*) FROM dw)
        )),
      'top_categories', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.category),''),'other') category, count(*) n
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE b.created_at >= since
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
          GROUP BY 1 ORDER BY 2 DESC LIMIT 3) x),
      'top_cities', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.city),''),'غير محدد') city, count(*) n
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE b.created_at >= since
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
          GROUP BY 1 ORDER BY 2 DESC LIMIT 3) x),
      'heatmap', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('dow', dow, 'h', h, 'n', n)), '[]'::jsonb) FROM (
          SELECT extract(dow  FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int dow,
                 extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int h,
                 count(*) n
          FROM bookings b WHERE b.created_at >= since GROUP BY 1, 2) x)
    ) INTO res;
    RETURN res;
END $$;


--
-- Name: admin_ai_hours(integer, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_ai_hours(p_days integer DEFAULT 30, p_city text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_dow integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    since timestamptz := now() - (GREATEST(7, LEAST(365, COALESCE(p_days, 30)))::text || ' days')::interval;
    res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    SELECT jsonb_build_object(
      'hours', (
        SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.h), '[]'::jsonb) FROM (
          SELECT gs.h,
            COALESCE(b.bookings, 0) bookings,
            COALESCE(b.completed, 0) completed,
            COALESCE(b.cancelled, 0) cancelled,
            COALESCE(b.buyers, 0) buyers,
            COALESCE(b.sellers, 0) sellers,
            COALESCE(e.views, 0) views,
            COALESCE(e.clicks, 0) clicks
          FROM generate_series(0, 23) gs(h)
          LEFT JOIN (
            SELECT extract(hour FROM bk.created_at AT TIME ZONE 'Asia/Riyadh')::int h,
                   count(*) bookings,
                   count(*) FILTER (WHERE bk.status='completed') completed,
                   count(*) FILTER (WHERE bk.status='cancelled') cancelled,
                   count(DISTINCT bk.user_id) buyers,
                   count(DISTINCT bk.store_id) sellers
            FROM bookings bk JOIN deals dl ON dl.id = bk.deal_id
            WHERE bk.created_at >= since
              AND (p_city IS NULL OR dl.city = p_city)
              AND (p_category IS NULL OR dl.category = p_category)
              AND (p_dow IS NULL OR extract(dow FROM bk.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            GROUP BY 1
          ) b ON b.h = gs.h
          LEFT JOIN (
            SELECT extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int h,
                   count(*) FILTER (WHERE e.kind='deal_view') views,
                   count(*) FILTER (WHERE e.kind='deal_click') clicks
            FROM analytics_events e LEFT JOIN deals dl ON dl.id = e.deal_id
            WHERE e.created_at >= since AND e.kind IN ('deal_view','deal_click')
              AND (p_city IS NULL OR dl.city = p_city)
              AND (p_category IS NULL OR dl.category = p_category)
              AND (p_dow IS NULL OR extract(dow FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            GROUP BY 1
          ) e ON e.h = gs.h
        ) t),
      -- إجماليات الفلتر الحالي (كل الساعات) — المشترون/التجار مميزون فعلياً
      'totals', (
        SELECT jsonb_build_object(
          'bookings', count(*),
          'completed', count(*) FILTER (WHERE bk.status='completed'),
          'cancelled', count(*) FILTER (WHERE bk.status='cancelled'),
          'buyers', count(DISTINCT bk.user_id),
          'sellers', count(DISTINCT bk.store_id)
        )
        FROM bookings bk JOIN deals dl ON dl.id = bk.deal_id
        WHERE bk.created_at >= since
          AND (p_city IS NULL OR dl.city = p_city)
          AND (p_category IS NULL OR dl.category = p_category)
          AND (p_dow IS NULL OR extract(dow FROM bk.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow))
    ) INTO res;
    RETURN res;
END $$;


--
-- Name: admin_ai_matrix(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_ai_matrix(p_city text DEFAULT NULL::text, p_category text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    SELECT jsonb_build_object(
      'city', p_city, 'category', p_category,
      -- حجوزات ٩٠ يوماً حسب الساعة (تاريخ غني منذ انطلاق المنصة)
      'hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb)
        FROM (SELECT extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
              FROM bookings b JOIN deals dl ON dl.id = b.deal_id
              WHERE b.created_at >= now() - interval '90 days'
                AND (p_city IS NULL OR dl.city = p_city)
                AND (p_category IS NULL OR dl.category = p_category)
              GROUP BY 1) t),
      -- مشاهدات/نقرات حسب الساعة (منذ بدء تسجيل الأحداث v12.38)
      'view_hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb)
        FROM (SELECT extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
              FROM analytics_events e JOIN deals dl ON dl.id = e.deal_id
              WHERE e.kind IN ('deal_view','deal_click')
                AND (p_city IS NULL OR dl.city = p_city)
                AND (p_category IS NULL OR dl.category = p_category)
              GROUP BY 1) t),
      'totals', (
        SELECT jsonb_build_object(
          'bookings_30', (SELECT count(*) FROM bookings b JOIN deals dl ON dl.id=b.deal_id
                          WHERE b.created_at >= now() - interval '30 days'
                            AND (p_city IS NULL OR dl.city = p_city)
                            AND (p_category IS NULL OR dl.category = p_category)),
          'views_30', (SELECT count(*) FROM analytics_events e JOIN deals dl ON dl.id=e.deal_id
                       WHERE e.kind='deal_view' AND e.created_at >= now() - interval '30 days'
                         AND (p_city IS NULL OR dl.city = p_city)
                         AND (p_category IS NULL OR dl.category = p_category)),
          'clicks_30', (SELECT count(*) FROM analytics_events e JOIN deals dl ON dl.id=e.deal_id
                        WHERE e.kind='deal_click' AND e.created_at >= now() - interval '30 days'
                          AND (p_city IS NULL OR dl.city = p_city)
                          AND (p_category IS NULL OR dl.category = p_category)),
          'active_deals', (SELECT count(*) FROM deals dl WHERE dl.status='active'
                             AND (p_city IS NULL OR dl.city = p_city)
                             AND (p_category IS NULL OR dl.category = p_category)),
          'stores', (SELECT count(DISTINCT dl.store_id) FROM deals dl WHERE dl.status='active'
                       AND (p_city IS NULL OR dl.city = p_city)
                       AND (p_category IS NULL OR dl.category = p_category))
        )),
      'top_deals', (
        SELECT COALESCE(jsonb_agg(row_to_json(td)::jsonb ORDER BY td.bookings DESC), '[]'::jsonb) FROM (
          SELECT dl.item_name, dl.shop_name, count(b.barcode) bookings, COALESCE(dl.views,0) views
          FROM deals dl LEFT JOIN bookings b ON b.deal_id = dl.id AND b.created_at >= now() - interval '90 days'
          WHERE (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
          GROUP BY dl.id, dl.item_name, dl.shop_name, dl.views
          ORDER BY count(b.barcode) DESC LIMIT 5) td)
    ) INTO res;
    RETURN res;
END $$;


--
-- Name: admin_ai_pulse2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_ai_pulse2() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    SELECT jsonb_build_object(
      -- تفاعل كل قسم: مشاهدات/نقرات/حجوزات ٣٠ يوماً → من يحتاج تخفيضات
      'cat_engagement', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY (c.views_30 + c.clicks_30) DESC), '[]'::jsonb) FROM (
          SELECT dl.category,
                 count(DISTINCT dl.id) FILTER (WHERE dl.status='active') active_deals,
                 (SELECT count(*) FROM analytics_events e WHERE e.kind='deal_view'
                    AND e.created_at >= now() - interval '30 days'
                    AND e.deal_id IN (SELECT id FROM deals dx WHERE dx.category = dl.category)) views_30,
                 (SELECT count(*) FROM analytics_events e WHERE e.kind='deal_click'
                    AND e.created_at >= now() - interval '30 days'
                    AND e.deal_id IN (SELECT id FROM deals dx WHERE dx.category = dl.category)) clicks_30,
                 (SELECT count(*) FROM bookings b JOIN deals dx ON dx.id=b.deal_id
                    WHERE dx.category = dl.category AND b.created_at >= now() - interval '30 days') bookings_30
          FROM deals dl GROUP BY dl.category
        ) c),
      -- أعلى كلمات البحث ٣٠ يوماً + نطاقها
      'searches', (
        SELECT COALESCE(jsonb_agg(row_to_json(s)::jsonb ORDER BY s.n DESC), '[]'::jsonb) FROM (
          SELECT query q, count(*) n, count(DISTINCT COALESCE(user_id, id::text)) searchers,
                 mode() WITHIN GROUP (ORDER BY source) top_scope
          FROM analytics_events WHERE kind='search' AND created_at >= now() - interval '30 days'
          GROUP BY query ORDER BY count(*) DESC LIMIT 15
        ) s),
      'search_total_30', (SELECT count(*) FROM analytics_events WHERE kind='search' AND created_at >= now() - interval '30 days')
    ) INTO res;
    RETURN res;
END $$;


--
-- Name: admin_ai_seller_competitors(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_ai_seller_competitors(p_store_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_city text; v_cat text; res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    SELECT dl.city INTO v_city FROM deals dl
     WHERE dl.store_id = p_store_id AND COALESCE(btrim(dl.city),'') <> ''
     GROUP BY dl.city ORDER BY count(*) DESC LIMIT 1;
    SELECT dl.category INTO v_cat FROM deals dl
      LEFT JOIN bookings b ON b.deal_id = dl.id
     WHERE dl.store_id = p_store_id
     GROUP BY dl.category ORDER BY count(b.barcode) DESC NULLS LAST LIMIT 1;

    SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings_30 DESC), '[]'::jsonb) INTO res FROM (
      SELECT u.id, COALESCE(NULLIF(btrim(u.shop),''), u.name) shop,
             (SELECT count(*) FROM bookings b WHERE b.store_id=u.id AND b.created_at >= now() - interval '30 days') bookings_30,
             (SELECT count(*) FROM deals dl WHERE dl.store_id=u.id AND dl.status='active') active_deals,
             (SELECT round(avg(r.score)::numeric,1) FROM ratings r WHERE r.store_id=u.id AND r.deleted_at IS NULL) rating_avg,
             (SELECT count(*) FROM analytics_events e WHERE e.store_id=u.id AND e.kind IN ('deal_view','store_view')
                AND e.created_at >= now() - interval '30 days') views_30
      FROM users u
      WHERE u.user_type IN ('seller','admin') AND u.deleted_at IS NULL AND u.id <> p_store_id
        AND EXISTS (SELECT 1 FROM deals dx WHERE dx.store_id=u.id
                      AND dx.category IS NOT DISTINCT FROM v_cat
                      AND (v_city IS NULL OR dx.city = v_city))
      ORDER BY 3 DESC LIMIT 3
    ) c;
    RETURN jsonb_build_object('city', v_city, 'category', v_cat, 'competitors', COALESCE(res, '[]'::jsonb));
END $$;


--
-- Name: admin_ai_seller_report(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_ai_seller_report(p_store_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    res jsonb; v_city text; v_cat text;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;

    SELECT dl.city INTO v_city FROM deals dl
     WHERE dl.store_id = p_store_id AND COALESCE(btrim(dl.city),'') <> ''
     GROUP BY dl.city ORDER BY count(*) DESC LIMIT 1;
    SELECT dl.category INTO v_cat FROM deals dl
      LEFT JOIN bookings b ON b.deal_id = dl.id
     WHERE dl.store_id = p_store_id
     GROUP BY dl.category ORDER BY count(b.barcode) DESC NULLS LAST LIMIT 1;

    SELECT jsonb_build_object(
      'store_id', p_store_id,
      'city', v_city,
      'top_category', v_cat,
      'hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb)
        FROM (SELECT extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
              FROM bookings b WHERE b.store_id=p_store_id AND b.created_at >= now() - interval '90 days' GROUP BY 1) t),
      'days', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('dow', dow, 'n', n) ORDER BY dow), '[]'::jsonb)
        FROM (SELECT extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int dow, count(*) n
              FROM bookings b WHERE b.store_id=p_store_id AND b.created_at >= now() - interval '90 days' GROUP BY 1) t),
      'weekly', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('w', w, 'n', n) ORDER BY wk), '[]'::jsonb)
        FROM (SELECT date_trunc('week', b.created_at AT TIME ZONE 'Asia/Riyadh') wk,
                     to_char(date_trunc('week', b.created_at AT TIME ZONE 'Asia/Riyadh'), 'MM-DD') w,
                     count(*) n
              FROM bookings b WHERE b.store_id=p_store_id AND b.created_at >= now() - interval '8 weeks'
              GROUP BY 1, 2) t),
      'cat_city_hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb)
        FROM (SELECT extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
              FROM bookings b JOIN deals dl ON dl.id = b.deal_id
              WHERE dl.category IS NOT DISTINCT FROM v_cat
                AND (v_city IS NULL OR dl.city = v_city)
                AND b.created_at >= now() - interval '90 days' GROUP BY 1) t),
      'cat_city_avg_bookings_30', (
        SELECT round(avg(cnt)::numeric, 1) FROM (
          SELECT count(b.barcode) cnt
          FROM users u2
          LEFT JOIN bookings b ON b.store_id = u2.id AND b.created_at >= now() - interval '30 days'
          WHERE u2.user_type IN ('seller','admin') AND u2.deleted_at IS NULL AND u2.id <> p_store_id
            AND EXISTS (SELECT 1 FROM deals dx WHERE dx.store_id=u2.id
                          AND dx.category IS NOT DISTINCT FROM v_cat
                          AND (v_city IS NULL OR dx.city = v_city))
          GROUP BY u2.id
        ) t),
      'top_deal', (
        SELECT to_jsonb(td) FROM (
          SELECT dl.item_name, count(b.barcode) bookings, COALESCE(dl.views,0) views
          FROM deals dl LEFT JOIN bookings b ON b.deal_id = dl.id
          WHERE dl.store_id = p_store_id
          GROUP BY dl.id, dl.item_name, dl.views ORDER BY count(b.barcode) DESC LIMIT 1
        ) td),
      'last_booking_at', (SELECT max(b.created_at) FROM bookings b WHERE b.store_id = p_store_id)
    ) INTO res;
    RETURN res;
END $$;


--
-- Name: admin_apply_subscription(text, text, timestamp with time zone, timestamp with time zone, numeric, numeric, text, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_apply_subscription(p_store_id text, p_plan text, p_started_at timestamp with time zone DEFAULT now(), p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_discount numeric DEFAULT 0, p_amount numeric DEFAULT 199, p_notes text DEFAULT NULL::text, p_send_notification boolean DEFAULT true, p_max_branches integer DEFAULT NULL::integer, p_package_id integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_role TEXT; v_caller_id TEXT; v_user_name TEXT; v_pkg_id INT; v_max INT;
BEGIN
  PERFORM public._admin_require_ctx();
    v_caller_id := auth.uid()::text;
    SELECT user_type INTO v_caller_role FROM users WHERE id = v_caller_id;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Admin only'; END IF;
    IF p_plan NOT IN ('free','trial','premium') THEN RAISE EXCEPTION 'Invalid plan: %', p_plan; END IF;
    IF p_max_branches IS NOT NULL AND p_max_branches < 1 THEN
        RAISE EXCEPTION 'Invalid package size: %', p_max_branches;
    END IF;

    SELECT name INTO v_user_name FROM users WHERE id = p_store_id;
    IF v_user_name IS NULL THEN RAISE EXCEPTION 'Store not found: %', p_store_id; END IF;

    -- v13.16: معرّف الباقة — إن لم يُمرَّر، استنتجه من عدد المواقع المطلوب
    v_pkg_id := p_package_id;
    IF v_pkg_id IS NULL AND p_max_branches IS NOT NULL THEN
      SELECT (e->>'id')::int INTO v_pkg_id
        FROM jsonb_array_elements(
               (SELECT value FROM platform_settings WHERE key='location_packages')) e
       WHERE (e->>'max')::int = p_max_branches
       ORDER BY (e->>'id')::int LIMIT 1;
    END IF;

    INSERT INTO store_profiles (
        store_id, subscription_plan, subscription_started_at,
        subscription_expires_at, discount_percentage, subscription_amount,
        admin_notes, max_branches, subscription_package_id, updated_at
    ) VALUES (
        p_store_id, p_plan, p_started_at, p_expires_at,
        COALESCE(p_discount, 0), COALESCE(p_amount, 199),
        p_notes, COALESCE(p_max_branches, 3), v_pkg_id, NOW()
    )
    ON CONFLICT (store_id) DO UPDATE SET
        subscription_plan = EXCLUDED.subscription_plan,
        subscription_started_at = EXCLUDED.subscription_started_at,
        subscription_expires_at = EXCLUDED.subscription_expires_at,
        discount_percentage = EXCLUDED.discount_percentage,
        subscription_amount = EXCLUDED.subscription_amount,
        admin_notes = EXCLUDED.admin_notes,
        max_branches = COALESCE(p_max_branches, store_profiles.max_branches, 3),
        subscription_package_id = COALESCE(v_pkg_id, store_profiles.subscription_package_id),
        updated_at = NOW();

    IF p_plan <> 'free' THEN
        UPDATE store_profiles SET subscription_canceled_at = NULL WHERE store_id = p_store_id;
    END IF;

    IF p_send_notification THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type)
        VALUES (
            p_store_id,
            CASE p_plan WHEN 'premium' THEN '🌟 تم تفعيل اشتراكك المميز'
                        WHEN 'trial'   THEN '🎁 لديك فترة تجريبية جديدة'
                        ELSE '✅ تم تحديث اشتراكك' END,
            CASE p_plan WHEN 'premium' THEN '🌟 Premium subscription activated'
                        WHEN 'trial'   THEN '🎁 New trial period granted'
                        ELSE '✅ Subscription updated' END,
            CASE WHEN p_discount > 0
                 THEN 'تم تطبيق خصم ' || p_discount || '٪ على اشتراكك. صالح حتى ' || COALESCE(to_char(p_expires_at, 'YYYY-MM-DD'), 'بدون انتهاء') || '.'
                 ELSE 'اشتراكك ' || p_plan || ' فعّال حتى ' || COALESCE(to_char(p_expires_at, 'YYYY-MM-DD'), 'إشعار آخر') || '.' END,
            'Your ' || p_plan || ' subscription is active until ' || COALESCE(to_char(p_expires_at, 'YYYY-MM-DD'), 'further notice') || '.',
            'system'
        );
    END IF;

    INSERT INTO activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
    VALUES (v_caller_id, 'admin', 'admin_apply_subscription', 'store', p_store_id,
        jsonb_build_object('plan', p_plan, 'discount', p_discount, 'amount', p_amount,
                           'expires_at', p_expires_at, 'max_branches', p_max_branches,
                           'package_id', v_pkg_id));

    SELECT max_branches INTO v_max FROM store_profiles WHERE store_id = p_store_id;
    RETURN jsonb_build_object('success', true, 'store_id', p_store_id,
        'store_name', v_user_name, 'plan', p_plan,
        'max_branches', v_max, 'package_id', v_pkg_id);
END $$;


--
-- Name: admin_authenticity_stats(timestamp with time zone, timestamp with time zone, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_authenticity_stats(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 20, p_sort text DEFAULT 'fake'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from timestamptz := coalesce(p_from, 'epoch'::timestamptz);
  v_to   timestamptz := coalesce(p_to, now() + interval '1 day');
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 2000));
  v_sort text := CASE WHEN p_sort IN ('fake','real','fake_pct','real_pct') THEN p_sort ELSE 'fake' END;
  v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  WITH votes AS (
    SELECT * FROM deal_authenticity_votes WHERE created_at >= v_from AND created_at < v_to
  ),
  tot AS (
    SELECT count(*) AS n,
           count(*) FILTER (WHERE is_real) AS r,
           count(*) FILTER (WHERE NOT is_real) AS f
    FROM votes
  ),
  by_deal AS (
    SELECT v2.deal_id, max(v2.store_id) AS store_id, count(*) AS n,
           count(*) FILTER (WHERE v2.is_real) AS r,
           count(*) FILTER (WHERE NOT v2.is_real) AS f
    FROM votes v2 GROUP BY v2.deal_id
  ),
  deal_rows AS (
    SELECT bd.*, d.item_name, d.status AS deal_status, coalesce(u.shop, u.name) AS shop
    FROM by_deal bd
    LEFT JOIN deals d ON d.id = bd.deal_id
    LEFT JOIN users u ON u.id = bd.store_id
    ORDER BY
      CASE v_sort
        WHEN 'real'     THEN bd.r::numeric
        WHEN 'fake'     THEN bd.f::numeric
        WHEN 'real_pct' THEN bd.r::numeric / bd.n
        ELSE                 bd.f::numeric / bd.n
      END DESC,
      bd.n DESC
    LIMIT v_limit
  ),
  by_store AS (
    SELECT v3.store_id, count(*) AS n,
           count(*) FILTER (WHERE v3.is_real) AS r,
           count(*) FILTER (WHERE NOT v3.is_real) AS f
    FROM votes v3 GROUP BY v3.store_id
  ),
  store_rows AS (
    SELECT bs.*, coalesce(u.shop, u.name) AS shop
    FROM by_store bs LEFT JOIN users u ON u.id = bs.store_id
    ORDER BY
      CASE v_sort
        WHEN 'real'     THEN bs.r::numeric
        WHEN 'fake'     THEN bs.f::numeric
        WHEN 'real_pct' THEN bs.r::numeric / bs.n
        ELSE                 bs.f::numeric / bs.n
      END DESC,
      bs.n DESC
    LIMIT v_limit
  )
  SELECT jsonb_build_object(
    'total', (SELECT n FROM tot),
    'real',  (SELECT r FROM tot),
    'fake',  (SELECT f FROM tot),
    'deals', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'deal_id', dr.deal_id, 'item_name', dr.item_name, 'deal_status', dr.deal_status,
        'store_id', dr.store_id, 'shop', dr.shop, 'votes', dr.n, 'real', dr.r, 'fake', dr.f)) FROM deal_rows dr), '[]'::jsonb),
    'stores', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'store_id', sr.store_id, 'shop', sr.shop, 'votes', sr.n, 'real', sr.r, 'fake', sr.f)) FROM store_rows sr), '[]'::jsonb)
  ) INTO v;
  RETURN v;
END $$;


--
-- Name: admin_booking_funnel(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_booking_funnel(p_days integer DEFAULT 30) RETURNS TABLE(total_views integer, unique_viewers integer, total_bookings integer, unique_bookers integer, conversion_pct numeric, avg_views_per_booker numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_total_views INT;
    v_unique_viewers INT;
    v_total_bookings INT;
    v_unique_bookers INT;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;

    SELECT COUNT(*), COUNT(DISTINCT user_id)
      INTO v_total_views, v_unique_viewers
    FROM activity_log
    WHERE action = 'view_deal'
      AND created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL;

    SELECT COUNT(*), COUNT(DISTINCT user_id)
      INTO v_total_bookings, v_unique_bookers
    FROM activity_log
    WHERE action = 'book'
      AND created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL;

    RETURN QUERY SELECT
        COALESCE(v_total_views, 0)::INT,
        COALESCE(v_unique_viewers, 0)::INT,
        COALESCE(v_total_bookings, 0)::INT,
        COALESCE(v_unique_bookers, 0)::INT,
        CASE WHEN COALESCE(v_unique_viewers, 0) = 0 THEN 0
             ELSE ROUND(100.0 * v_unique_bookers / v_unique_viewers, 1) END,
        CASE WHEN COALESCE(v_unique_bookers, 0) = 0 THEN 0
             ELSE ROUND(v_total_views::NUMERIC / v_unique_bookers, 1) END;
END;
$$;


--
-- Name: admin_bot_analytics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_bot_analytics() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v jsonb; v_cut bigint;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
  v_cut := (EXTRACT(EPOCH FROM NOW())*1000)::bigint - 30*86400000;
  SELECT jsonb_build_object(
    'tg_linked',   (SELECT count(*) FROM users WHERE telegram_id IS NOT NULL AND deleted_at IS NULL),
    'wa_linked',   (SELECT count(*) FROM users WHERE whatsapp_chat_id IS NOT NULL AND deleted_at IS NULL),
    'both_linked', (SELECT count(*) FROM users WHERE telegram_id IS NOT NULL AND whatsapp_chat_id IS NOT NULL AND deleted_at IS NULL),
    'total_users', (SELECT count(*) FROM users WHERE deleted_at IS NULL),
    'lang_ar',     (SELECT count(*) FROM users WHERE (bot_lang='ar' OR bot_lang IS NULL) AND (telegram_id IS NOT NULL OR whatsapp_chat_id IS NOT NULL) AND deleted_at IS NULL),
    'lang_en',     (SELECT count(*) FROM users WHERE bot_lang='en' AND (telegram_id IS NOT NULL OR whatsapp_chat_id IS NOT NULL) AND deleted_at IS NULL),
    'bookings_total', jsonb_build_object(
       'web',      (SELECT count(*) FROM bookings WHERE source='web'),
       'telegram', (SELECT count(*) FROM bookings WHERE source='telegram'),
       'whatsapp', (SELECT count(*) FROM bookings WHERE source='whatsapp')),
    'bookings_30d', jsonb_build_object(
       'web',      (SELECT count(*) FROM bookings WHERE source='web'      AND booked_at >= v_cut),
       'telegram', (SELECT count(*) FROM bookings WHERE source='telegram' AND booked_at >= v_cut),
       'whatsapp', (SELECT count(*) FROM bookings WHERE source='whatsapp' AND booked_at >= v_cut)),
    'deals_total', jsonb_build_object(
       'web',      (SELECT count(*) FROM deals WHERE source='web'),
       'telegram', (SELECT count(*) FROM deals WHERE source='telegram'),
       'whatsapp', (SELECT count(*) FROM deals WHERE source='whatsapp'))
  ) INTO v;
  RETURN v;
END; $$;


--
-- Name: admin_broadcast_notification(text, text, text, text, jsonb, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_broadcast_notification(p_title_ar text, p_body_ar text DEFAULT ''::text, p_audience text DEFAULT 'all'::text, p_type text DEFAULT 'system'::text, p_meta jsonb DEFAULT '{}'::jsonb, p_inapp boolean DEFAULT true, p_email boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_notified int := 0;
    v_emailed  int := 0;
    v_html     text;
    r RECORD;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'forbidden: admin only';
    END IF;
    IF COALESCE(btrim(p_title_ar), '') = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'empty_title');
    END IF;
    IF NOT p_inapp AND NOT p_email THEN
        RETURN jsonb_build_object('success', true, 'notified', 0, 'emailed', 0);
    END IF;

    IF p_inapp THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        SELECT u.id,
               p_title_ar, p_title_ar,
               COALESCE(p_body_ar, ''), COALESCE(p_body_ar, ''),
               COALESCE(NULLIF(btrim(p_type), ''), 'system'),
               COALESCE(p_meta, '{}'::jsonb) || jsonb_build_object('broadcast', true),
               NOW()
        FROM users u
        WHERE u.deleted_at IS NULL
          AND CASE
                -- «التجار» يشمل حسابات الأدمن المالكة لمتاجر (قاعدة v11.79)
                WHEN p_audience = 'sellers' THEN u.user_type IN ('seller', 'admin')
                WHEN p_audience = 'buyers'  THEN u.user_type IN ('buyer', 'admin')
                ELSE TRUE
              END;
        GET DIAGNOSTICS v_notified = ROW_COUNT;
    END IF;

    IF p_email THEN
        -- Minimal HTML-escape so a title with < or & can't break the email.
        v_html := '<p style="font-size:15px;line-height:1.9;margin:0">'
                  || replace(replace(replace(replace(COALESCE(p_body_ar, ''),
                       '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), E'\n', '<br>')
                  || '</p>';
        FOR r IN
            SELECT u.id FROM users u
            WHERE u.deleted_at IS NULL
              AND CASE
                    WHEN p_audience = 'sellers' THEN u.user_type IN ('seller', 'admin')
                    WHEN p_audience = 'buyers'  THEN u.user_type IN ('buyer', 'admin')
                    ELSE TRUE
                  END
        LOOP
            -- taki_queue_email validates the address and skips bot placeholders.
            IF public.taki_queue_email(r.id, 'admin_broadcast', p_title_ar,
                                       public.taki_email_wrap(p_title_ar, v_html)) THEN
                v_emailed := v_emailed + 1;
            END IF;
        END LOOP;
    END IF;

    RETURN jsonb_build_object('success', true, 'notified', v_notified, 'emailed', v_emailed);
END $$;


--
-- Name: admin_browse_no_book(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_browse_no_book(p_days integer DEFAULT 14, p_limit integer DEFAULT 50) RETURNS TABLE(user_id text, name text, phone text, views_count integer, last_viewed_at timestamp with time zone, deals_seen integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH window_views AS (
        SELECT al.user_id,
               COUNT(*) AS views,
               MAX(al.created_at) AS last_at,
               COUNT(DISTINCT al.entity_id) AS distinct_deals
        FROM activity_log al
        WHERE al.action = 'view_deal'
          AND al.created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
          AND al.user_id IS NOT NULL
        GROUP BY al.user_id
    ),
    window_books AS (
        SELECT DISTINCT al.user_id
        FROM activity_log al
        WHERE al.action = 'book'
          AND al.created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
          AND al.user_id IS NOT NULL
    )
    SELECT u.id::TEXT,
           u.name::TEXT,
           u.phone::TEXT,
           wv.views::INT,
           wv.last_at,
           wv.distinct_deals::INT
    FROM window_views wv
    JOIN users u ON u.id = wv.user_id
    WHERE wv.user_id NOT IN (SELECT user_id FROM window_books WHERE user_id IS NOT NULL)
      AND u.user_type = 'buyer'
      AND COALESCE(u.is_suspended, FALSE) = FALSE
    ORDER BY wv.views DESC, wv.last_at DESC
    LIMIT GREATEST(p_limit, 1);
END;
$$;


--
-- Name: admin_campaign_audience(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_campaign_audience(p_campaign_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE camp RECORD; v_all int; v_hit int; v_new int;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT * INTO camp FROM public.promotional_campaigns WHERE id = p_campaign_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;

  SELECT count(*) INTO v_all FROM public.users u
  WHERE (camp.target_audience = 'all' OR u.user_type = camp.target_audience)
    AND u.deleted_at IS NULL AND COALESCE(u.is_suspended,false) = false;

  SELECT count(*) INTO v_hit FROM public.users u
  WHERE (camp.target_audience = 'all' OR u.user_type = camp.target_audience)
    AND u.deleted_at IS NULL AND COALESCE(u.is_suspended,false) = false
    AND public.taki_user_in_campaign(u.id, camp.target_city, camp.target_region);

  SELECT count(*) INTO v_new FROM public.users u
  WHERE (camp.target_audience = 'all' OR u.user_type = camp.target_audience)
    AND u.deleted_at IS NULL AND COALESCE(u.is_suspended,false) = false
    AND public.taki_user_in_campaign(u.id, camp.target_city, camp.target_region)
    AND NOT EXISTS (SELECT 1 FROM public.promo_impressions p
                    WHERE p.campaign_id = camp.id AND p.user_id = u.id);

  RETURN jsonb_build_object('ok', true, 'eligible', v_all, 'targeted', v_hit,
                            'will_receive', v_new,
                            'targeted_city', camp.target_city, 'targeted_region', camp.target_region);
END $$;


--
-- Name: admin_category_funnel(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_category_funnel(p_days integer DEFAULT 30, p_limit integer DEFAULT 12) RETURNS TABLE(category text, views integer, bookings integer, conversion_pct numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH win AS (
        SELECT al.action, al.entity_id, al.created_at
        FROM activity_log al
        WHERE al.action IN ('view_deal', 'book')
          AND al.entity_id IS NOT NULL
          AND al.created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
    ),
    joined AS (
        SELECT COALESCE(d.category, 'غير مصنّف') AS cat,
               COUNT(*) FILTER (WHERE win.action = 'view_deal') AS views,
               COUNT(*) FILTER (WHERE win.action = 'book') AS books
        FROM win
        LEFT JOIN deals d ON d.id = win.entity_id
        GROUP BY 1
    )
    SELECT joined.cat::TEXT,
           joined.views::INT,
           joined.books::INT,
           CASE WHEN joined.views = 0 THEN 0
                ELSE ROUND(100.0 * joined.books / joined.views, 1) END
    FROM joined
    WHERE joined.views > 0
    ORDER BY joined.views DESC
    LIMIT GREATEST(p_limit, 1);
END;
$$;


--
-- Name: admin_churned_subscribers(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_churned_subscribers(p_days integer DEFAULT 90, p_limit integer DEFAULT 100) RETURNS TABLE(store_id text, name text, shop text, phone text, plan text, ended_at timestamp with time zone, days_since_churn integer, last_amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT u.id::TEXT,
           u.name::TEXT,
           u.shop::TEXT,
           u.phone::TEXT,
           sp.subscription_plan::TEXT,
           sp.subscription_expires_at,
           GREATEST(0, EXTRACT(DAY FROM (now() - sp.subscription_expires_at))::INT) AS days_since,
           sp.subscription_amount
    FROM store_profiles sp
    JOIN users u ON u.id = sp.store_id
    WHERE u.user_type = 'seller'
      AND COALESCE(u.is_suspended, FALSE) = FALSE
      AND sp.subscription_expires_at IS NOT NULL
      AND sp.subscription_expires_at < now()
      AND sp.subscription_expires_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
      AND (sp.subscription_plan IS NULL OR sp.subscription_plan IN ('free', 'expired'))
    ORDER BY sp.subscription_expires_at DESC
    LIMIT GREATEST(p_limit, 1);
END;
$$;


--
-- Name: admin_custom_draw(text, text, timestamp with time zone, timestamp with time zone, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_custom_draw(p_source text, p_role text DEFAULT 'all'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_count integer DEFAULT 1, p_title text DEFAULT ''::text, p_preview boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_from timestamptz := coalesce(p_from, 'epoch'::timestamptz);
  v_to   timestamptz := coalesce(p_to, now() + interval '1 day');
  v_count integer := greatest(1, least(coalesce(p_count, 1), 500));
  v_pick integer;
  v_role text := CASE WHEN p_role IN ('all','buyers','sellers') THEN p_role ELSE 'all' END;
  v_pool integer := 0;
  v_win jsonb;
  v_id uuid;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_source NOT IN ('buyers_booked','stores_booked','registered') THEN
    RAISE EXCEPTION 'bad source';
  END IF;
  -- preview = عينة عشوائية للعجلة الدوّارة فقط (لا سحب ولا حفظ)
  v_pick := CASE WHEN p_preview THEN 40 ELSE v_count END;

  IF p_source = 'buyers_booked' THEN
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND EXISTS (SELECT 1 FROM bookings b
                    WHERE b.user_id = u.id AND b.status <> 'cancelled'
                      AND b.created_at >= v_from AND b.created_at < v_to);
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone, 'shop', NULL)) INTO v_win
      FROM (SELECT u.id, u.name, u.phone FROM users u
             WHERE u.deleted_at IS NULL
               AND EXISTS (SELECT 1 FROM bookings b
                            WHERE b.user_id = u.id AND b.status <> 'cancelled'
                              AND b.created_at >= v_from AND b.created_at < v_to)
             ORDER BY random() LIMIT v_pick) t;

  ELSIF p_source = 'stores_booked' THEN
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND EXISTS (SELECT 1 FROM bookings b
                    WHERE b.store_id = u.id AND b.status <> 'cancelled'
                      AND b.created_at >= v_from AND b.created_at < v_to);
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone, 'shop', t.shop)) INTO v_win
      FROM (SELECT u.id, u.name, u.phone, coalesce(u.shop, u.name) AS shop FROM users u
             WHERE u.deleted_at IS NULL
               AND EXISTS (SELECT 1 FROM bookings b
                            WHERE b.store_id = u.id AND b.status <> 'cancelled'
                              AND b.created_at >= v_from AND b.created_at < v_to)
             ORDER BY random() LIMIT v_pick) t;

  ELSE -- registered
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND u.created_at >= v_from AND u.created_at < v_to
       AND (v_role = 'all'
            OR (v_role = 'buyers'  AND u.user_type = 'buyer')
            OR (v_role = 'sellers' AND u.user_type = 'seller'));
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone, 'shop', t.shop)) INTO v_win
      FROM (SELECT u.id, u.name, u.phone, u.shop FROM users u
             WHERE u.deleted_at IS NULL
               AND u.created_at >= v_from AND u.created_at < v_to
               AND (v_role = 'all'
                    OR (v_role = 'buyers'  AND u.user_type = 'buyer')
                    OR (v_role = 'sellers' AND u.user_type = 'seller'))
             ORDER BY random() LIMIT v_pick) t;
  END IF;

  IF v_pool = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'empty_pool');
  END IF;

  IF p_preview THEN
    RETURN jsonb_build_object('success', true, 'preview', true, 'pool', v_pool, 'sample', coalesce(v_win, '[]'::jsonb));
  END IF;

  INSERT INTO admin_draws (title, source, role_filter, from_ts, to_ts, winners_count, pool_size, winners, created_by)
  VALUES (coalesce(btrim(p_title), ''), p_source, v_role, p_from, p_to, v_count, v_pool, coalesce(v_win, '[]'::jsonb), auth.uid()::text)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('success', true, 'id', v_id, 'pool', v_pool, 'winners', coalesce(v_win, '[]'::jsonb));
END $$;


--
-- Name: admin_custom_draw_preview(text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_custom_draw_preview(p_source text, p_role text DEFAULT 'all'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from timestamptz := coalesce(p_from, 'epoch'::timestamptz);
  v_to   timestamptz := coalesce(p_to, now() + interval '1 day');
  v_role text := CASE WHEN p_role IN ('all','buyers','sellers') THEN p_role ELSE 'all' END;
  v_pool integer := 0;
  v_sample jsonb;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_source NOT IN ('buyers_booked','stores_booked','registered') THEN
    RAISE EXCEPTION 'bad source';
  END IF;

  IF p_source = 'buyers_booked' THEN
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND EXISTS (SELECT 1 FROM bookings b
                    WHERE b.user_id = u.id AND b.status <> 'cancelled'
                      AND b.created_at >= v_from AND b.created_at < v_to);
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone)) INTO v_sample
      FROM (SELECT u.id, coalesce(u.name,'مشارك') AS name, coalesce(u.phone,'') AS phone FROM users u
             WHERE u.deleted_at IS NULL
               AND EXISTS (SELECT 1 FROM bookings b
                            WHERE b.user_id = u.id AND b.status <> 'cancelled'
                              AND b.created_at >= v_from AND b.created_at < v_to)
             ORDER BY random() LIMIT 40) t;

  ELSIF p_source = 'stores_booked' THEN
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND EXISTS (SELECT 1 FROM bookings b
                    WHERE b.store_id = u.id AND b.status <> 'cancelled'
                      AND b.created_at >= v_from AND b.created_at < v_to);
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone)) INTO v_sample
      FROM (SELECT u.id, coalesce(u.shop, u.name, 'متجر') AS name, coalesce(u.phone,'') AS phone FROM users u
             WHERE u.deleted_at IS NULL
               AND EXISTS (SELECT 1 FROM bookings b
                            WHERE b.store_id = u.id AND b.status <> 'cancelled'
                              AND b.created_at >= v_from AND b.created_at < v_to)
             ORDER BY random() LIMIT 40) t;

  ELSE
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND u.created_at >= v_from AND u.created_at < v_to
       AND (v_role = 'all'
            OR (v_role = 'buyers'  AND u.user_type = 'buyer')
            OR (v_role = 'sellers' AND u.user_type = 'seller'));
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone)) INTO v_sample
      FROM (SELECT u.id, coalesce(u.shop, u.name, 'مشارك') AS name, coalesce(u.phone,'') AS phone FROM users u
             WHERE u.deleted_at IS NULL
               AND u.created_at >= v_from AND u.created_at < v_to
               AND (v_role = 'all'
                    OR (v_role = 'buyers'  AND u.user_type = 'buyer')
                    OR (v_role = 'sellers' AND u.user_type = 'seller'))
             ORDER BY random() LIMIT 40) t;
  END IF;

  RETURN jsonb_build_object('pool', v_pool, 'sample', coalesce(v_sample, '[]'::jsonb));
END $$;


--
-- Name: admin_daily_metrics(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_daily_metrics(p_days integer DEFAULT 30) RETURNS TABLE(day_key text, day_label text, events integer, bookings integer, new_users integer, completed_bookings integer, cancelled_bookings integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH days AS (
        SELECT date_trunc('day', now() AT TIME ZONE 'Asia/Riyadh')::DATE - n AS d
        FROM generate_series(0, GREATEST(p_days, 1) - 1) AS n
    ),
    events_per_day AS (
        SELECT (created_at AT TIME ZONE 'Asia/Riyadh')::DATE AS d, COUNT(*) AS c
        FROM activity_log
        WHERE created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
        GROUP BY 1
    ),
    bookings_per_day AS (
        SELECT (created_at AT TIME ZONE 'Asia/Riyadh')::DATE AS d,
               COUNT(*) AS c,
               COUNT(*) FILTER (WHERE status = 'completed') AS done,
               COUNT(*) FILTER (WHERE status = 'cancelled') AS cancelled
        FROM bookings
        WHERE created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
        GROUP BY 1
    ),
    new_per_day AS (
        SELECT (created_at AT TIME ZONE 'Asia/Riyadh')::DATE AS d, COUNT(*) AS c
        FROM users
        WHERE created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
          AND user_type = 'buyer'
        GROUP BY 1
    )
    SELECT to_char(days.d, 'YYYY-MM-DD')::TEXT,
           to_char(days.d, 'DD/MM')::TEXT,
           COALESCE(e.c, 0)::INT,
           COALESCE(b.c, 0)::INT,
           COALESCE(n.c, 0)::INT,
           COALESCE(b.done, 0)::INT,
           COALESCE(b.cancelled, 0)::INT
    FROM days
    LEFT JOIN events_per_day e ON e.d = days.d
    LEFT JOIN bookings_per_day b ON b.d = days.d
    LEFT JOIN new_per_day n ON n.d = days.d
    ORDER BY days.d ASC;
END;
$$;


