--
-- Name: admin_delete_message(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_delete_message(p_message_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_caller TEXT;
BEGIN
    v_caller := auth.uid()::text;
    IF NOT public.is_admin(v_caller) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;
    DELETE FROM public.booking_messages WHERE id = p_message_id;
    INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
    VALUES (v_caller, 'admin', 'admin_delete_message', 'booking_message', p_message_id, '{}'::jsonb);
    RETURN jsonb_build_object('success', TRUE);
END $$;


--
-- Name: admin_delete_warning(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_delete_warning(p_warning_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  DELETE FROM public.pending_warnings WHERE warning_id = p_warning_id AND sent_at IS NULL;
  DELETE FROM public.user_warnings WHERE id = p_warning_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  RETURN jsonb_build_object('success', true);
END $$;


--
-- Name: admin_demote_user(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_demote_user(target_id text, target_role text DEFAULT 'buyer'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'forbidden: super admin required';
  END IF;
  IF target_role NOT IN ('buyer','seller') THEN
    RAISE EXCEPTION 'target_role must be buyer or seller';
  END IF;
  IF EXISTS (SELECT 1 FROM public.users u WHERE u.id = target_id AND u.is_super_admin = TRUE) THEN
    RAISE EXCEPTION 'cannot demote super admin';
  END IF;
  UPDATE public.users u
  SET user_type = target_role,
      admin_permissions = '{}'::TEXT[]
  WHERE u.id = target_id AND u.user_type = 'admin';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target is not a staff admin';
  END IF;
END;
$$;


--
-- Name: admin_first_members(text, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_first_members(p_kind text DEFAULT 'all'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from timestamptz := coalesce(p_from, 'epoch'::timestamptz);
  v_to   timestamptz := coalesce(p_to, now() + interval '1 day');
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 20000));
  v_kind text := CASE WHEN p_kind IN ('all','buyers','sellers') THEN p_kind ELSE 'all' END;
  v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'name', t.name, 'shop', t.shop, 'phone', t.phone,
           'user_type', t.user_type, 'created_at', t.created_at) ORDER BY t.created_at ASC), '[]'::jsonb)
    INTO v
    FROM (
      SELECT u.id, u.name, u.shop, u.phone, u.user_type, u.created_at
        FROM users u
       WHERE u.deleted_at IS NULL
         AND u.created_at >= v_from AND u.created_at < v_to
         AND (v_kind = 'all'
              OR (v_kind = 'buyers'  AND u.user_type = 'buyer')
              OR (v_kind = 'sellers' AND u.user_type = 'seller'))
       ORDER BY u.created_at ASC
       LIMIT v_limit
    ) t;
  RETURN coalesce(v, '[]'::jsonb);
END $$;


--
-- Name: admin_geo_insights(integer, text, text, double precision, double precision, double precision, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_geo_insights(p_days integer DEFAULT 7, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_radius_km double precision DEFAULT NULL::double precision, p_date text DEFAULT NULL::text, p_hour_from integer DEFAULT NULL::integer, p_hour_to integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_days int := least(greatest(coalesce(p_days,7),1),90);
  v_today date := (now() AT TIME ZONE 'Asia/Riyadh')::date;
  v_day_from date;
  v_day_to   date;
  v_from timestamptz;
  v_to   timestamptz;
  v_hf int := coalesce(p_hour_from, 0);
  v_ht int := coalesce(p_hour_to, 23);
  v_has_hours boolean := (p_hour_from IS NOT NULL OR p_hour_to IS NOT NULL);
  v_has_area boolean := (p_region IS NOT NULL) OR (p_city IS NOT NULL)
                        OR (p_lat IS NOT NULL AND p_lng IS NOT NULL AND p_radius_km IS NOT NULL AND p_radius_km > 0);
  v_out jsonb;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden'; END IF;

  IF p_date IS NOT NULL AND p_date <> '' THEN
    v_day_from := p_date::date; v_day_to := p_date::date;
  ELSE
    v_day_from := v_today - (v_days-1); v_day_to := v_today;
  END IF;
  v_from := (v_day_from::timestamp) AT TIME ZONE 'Asia/Riyadh';
  v_to   := ((v_day_to + 1)::timestamp) AT TIME ZONE 'Asia/Riyadh';
  v_hf := least(greatest(v_hf,0),23); v_ht := least(greatest(v_ht,0),23);

  WITH ulocs AS (
    SELECT u.id, u.user_type, u.lat, u.lng, u.created_at AS joined_at, c.city_id, c.region_id
    FROM users u
    LEFT JOIN LATERAL (
      SELECT g.city_id, g.region_id FROM sa_cities_geo g
      WHERE u.lat IS NOT NULL AND u.lng IS NOT NULL
      ORDER BY (g.lat-u.lat)*(g.lat-u.lat) + (g.lng-u.lng)*(g.lng-u.lng) ASC
      LIMIT 1
    ) c ON true
    WHERE u.deleted_at IS NULL
  ),
  area_users AS (
    SELECT id FROM ulocs
    WHERE (p_region IS NULL OR region_id = p_region)
      AND (p_city IS NULL OR city_id = p_city)
      AND (p_lat IS NULL OR p_lng IS NULL OR p_radius_km IS NULL OR p_radius_km <= 0
           OR (lat IS NOT NULL AND
               6371*acos(least(1, greatest(-1,
                 sin(radians(p_lat))*sin(radians(lat)) +
                 cos(radians(p_lat))*cos(radians(lat))*cos(radians(lng - p_lng))))) <= p_radius_km))
  ),
  ev AS (
    SELECT e.*, (e.created_at AT TIME ZONE 'Asia/Riyadh')::date AS d,
           extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int AS hr
    FROM analytics_events e
    WHERE e.created_at >= v_from AND e.created_at < v_to
      AND (NOT v_has_hours OR extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN v_hf AND v_ht)
      AND (NOT v_has_area OR (e.user_id IS NOT NULL AND e.user_id IN (SELECT id FROM area_users)))
  ),
  bk_all AS (
    SELECT b.*, (b.created_at AT TIME ZONE 'Asia/Riyadh')::date AS d
    FROM bookings b
    WHERE b.created_at >= v_from AND b.created_at < v_to
      AND (NOT v_has_hours OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN v_hf AND v_ht)
      AND (NOT v_has_area OR b.user_id IN (SELECT id FROM area_users))
  ),
  bk AS (SELECT * FROM bk_all WHERE status <> 'cancelled'),
  days AS (
    SELECT generate_series(v_day_from, v_day_to, interval '1 day')::date AS d
  ),
  daily AS (
    SELECT dd.d,
      coalesce(e.actives,0) AS actives, coalesce(e.opens,0) AS opens,
      coalesce(b.bookers,0) AS bookers, coalesce(b.bookings,0) AS bookings
    FROM days dd
    LEFT JOIN (
      SELECT d, count(DISTINCT user_id) AS actives,
             count(*) FILTER (WHERE kind='app_open') AS opens
      FROM ev GROUP BY d
    ) e ON e.d = dd.d
    LEFT JOIN (
      SELECT d, count(DISTINCT user_id) AS bookers, count(*) AS bookings
      FROM bk GROUP BY d
    ) b ON b.d = dd.d
    ORDER BY dd.d
  ),
  hours AS (
    SELECT h AS hr,
      coalesce((SELECT count(*) FROM ev WHERE ev.hr = h AND ev.kind='app_open'),0) AS opens,
      coalesce((SELECT count(DISTINCT ev.user_id) FROM ev WHERE ev.hr = h),0) AS actives
    FROM generate_series(0,23) h
  ),
  srcs AS (
    SELECT coalesce(source,'web') AS source,
           count(DISTINCT user_id) AS users,
           count(*) FILTER (WHERE kind='app_open') AS opens
    FROM ev WHERE source IN ('web','telegram','whatsapp') GROUP BY 1
  ),
  bksrc AS (
    SELECT coalesce(source,'web') AS source, count(*) AS bookings FROM bk GROUP BY 1
  ),
  cats AS (
    SELECT d2.category, count(*) AS views,
           count(DISTINCT e.user_id) AS viewers
    FROM ev e JOIN deals d2 ON d2.id = e.deal_id
    WHERE e.kind = 'deal_view'
    GROUP BY 1 ORDER BY views DESC LIMIT 20
  ),
  regions AS (
    SELECT ul.region_id,
      count(*)::int AS registered,
      count(*) FILTER (WHERE ul.user_type = 'buyer')::int AS buyers,
      count(*) FILTER (WHERE ul.user_type IN ('seller','admin'))::int AS sellers,
      (SELECT count(DISTINCT e.user_id) FROM ev e JOIN ulocs u2 ON u2.id = e.user_id WHERE u2.region_id = ul.region_id) AS actives
    FROM ulocs ul
    WHERE ul.region_id IS NOT NULL
    GROUP BY ul.region_id
  ),
  city_daily AS (
    SELECT ul.city_id, ul.region_id, e.d, count(DISTINCT e.user_id) AS n
    FROM ev e JOIN ulocs ul ON ul.id = e.user_id
    WHERE e.user_id IS NOT NULL AND ul.city_id IS NOT NULL
    GROUP BY 1,2,3
  ),
  city_reg AS (
    SELECT city_id, count(*)::int AS registered FROM ulocs WHERE city_id IS NOT NULL GROUP BY city_id
  ),
  cities AS (
    SELECT cd.city_id, cd.region_id,
      coalesce(cr.registered,0) AS registered,
      (SELECT count(DISTINCT e2.user_id) FROM ev e2 JOIN ulocs u2 ON u2.id=e2.user_id WHERE u2.city_id = cd.city_id) AS actives,
      coalesce(sum(cd.n) FILTER (WHERE cd.d = v_today),0)::int AS today,
      coalesce(sum(cd.n) FILTER (WHERE cd.d = v_today - 1),0)::int AS yesterday
    FROM city_daily cd
    LEFT JOIN city_reg cr ON cr.city_id = cd.city_id
    GROUP BY cd.city_id, cd.region_id, cr.registered
    ORDER BY actives DESC
    LIMIT 60
  )
  SELECT jsonb_build_object(
    'daily',   (SELECT coalesce(jsonb_agg(jsonb_build_object('d',d,'actives',actives,'opens',opens,'bookers',bookers,'bookings',bookings) ORDER BY d),'[]'::jsonb) FROM daily),
    'hours',   (SELECT coalesce(jsonb_agg(jsonb_build_object('hr',hr,'opens',opens,'actives',actives) ORDER BY hr),'[]'::jsonb) FROM hours),
    'regions', (SELECT coalesce(jsonb_agg(jsonb_build_object('region',region_id,'registered',registered,'buyers',buyers,'sellers',sellers,'actives',actives) ORDER BY registered DESC),'[]'::jsonb) FROM regions),
    'sources', (SELECT coalesce(jsonb_agg(jsonb_build_object('source',s.source,'users',s.users,'opens',s.opens,'bookings',coalesce(bs.bookings,0))),'[]'::jsonb)
                FROM srcs s LEFT JOIN bksrc bs ON bs.source = s.source),
    'cats',    (SELECT coalesce(jsonb_agg(jsonb_build_object('category',category,'views',views,'viewers',viewers) ORDER BY views DESC),'[]'::jsonb) FROM cats),
    'cities',  (SELECT coalesce(jsonb_agg(jsonb_build_object('city',city_id,'region',region_id,'registered',registered,'actives',actives,'today',today,'yesterday',yesterday) ORDER BY actives DESC),'[]'::jsonb) FROM cities),
    'totals',  jsonb_build_object(
        'actives',       (SELECT count(DISTINCT user_id) FROM ev),
        'opens',         (SELECT count(*) FROM ev WHERE kind='app_open'),
        'bookers',       (SELECT count(DISTINCT user_id) FROM bk),
        'bookings',      (SELECT count(*) FROM bk_all),
        'bk_completed',  (SELECT count(*) FROM bk_all WHERE status = 'completed'),
        'bk_active',     (SELECT count(*) FROM bk_all WHERE status NOT IN ('completed','cancelled')),
        'bk_cancelled',  (SELECT count(*) FROM bk_all WHERE status = 'cancelled'),
        'bk_c_buyer',    (SELECT count(*) FROM bk_all WHERE status = 'cancelled' AND cancelled_by = 'buyer'),
        'bk_c_seller',   (SELECT count(*) FROM bk_all WHERE status = 'cancelled' AND cancelled_by = 'seller'),
        'bk_c_system',   (SELECT count(*) FROM bk_all WHERE status = 'cancelled' AND cancelled_by = 'system'),
        'actives_today', (SELECT count(DISTINCT user_id) FROM ev WHERE d = v_today),
        'actives_yday',  (SELECT count(DISTINCT user_id) FROM ev WHERE d = v_today - 1),
        'located_users', (SELECT count(*) FROM ulocs WHERE lat IS NOT NULL),
        'total_users',   (SELECT count(*) FROM ulocs),
        'new_users',     (SELECT count(*) FROM ulocs WHERE joined_at >= v_from AND joined_at < v_to
                            AND (NOT v_has_area OR id IN (SELECT id FROM area_users)))
    )
  ) INTO v_out;

  RETURN v_out;
END;
$$;


--
-- Name: admin_geographic_breakdown(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_geographic_breakdown(p_days integer DEFAULT 30, p_limit integer DEFAULT 20) RETURNS TABLE(city text, region text, bookings_count integer, completed_bookings integer, gmv numeric, unique_buyers integer, active_stores integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT
        COALESCE(d.city, 'غير محدّد')::TEXT,
        COALESCE(d.region, 'غير محدّد')::TEXT,
        COUNT(*)::INT,
        COUNT(*) FILTER (WHERE b.status = 'completed')::INT,
        COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)) FILTER (WHERE b.status IN ('completed', 'acknowledged')), 0)::NUMERIC,
        COUNT(DISTINCT b.user_id)::INT,
        COUNT(DISTINCT b.store_id)::INT
    FROM bookings b
    LEFT JOIN deals d ON d.id = b.deal_id
    WHERE b.created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
    GROUP BY 1, 2
    HAVING COUNT(*) > 0
    ORDER BY 5 DESC, 3 DESC
    LIMIT GREATEST(p_limit, 1);
END;
$$;


--
-- Name: admin_get_thread_messages(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_thread_messages(p_barcode text) RETURNS TABLE(id text, barcode text, sender_id text, sender_role text, sender_name text, body text, created_at timestamp with time zone, read_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT public.is_admin(auth.uid()::text) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    RETURN QUERY
    SELECT bm.id, bm.barcode, bm.sender_id, bm.sender_role,
           u.name, bm.body, bm.created_at, bm.read_at
    FROM public.booking_messages bm
    LEFT JOIN public.users u ON u.id = bm.sender_id
    WHERE bm.barcode = p_barcode
    ORDER BY bm.created_at ASC;
END $$;


--
-- Name: admin_gmv_monthly(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_gmv_monthly(p_months integer DEFAULT 12) RETURNS TABLE(month_key text, month_label text, gmv numeric, completed_gmv numeric, bookings_count integer, completed_count integer, avg_order_value numeric, savings_delivered numeric, unique_buyers integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH months AS (
        SELECT date_trunc('month', now()) - (n || ' months')::INTERVAL AS m
        FROM generate_series(0, GREATEST(p_months, 1) - 1) AS n
    ),
    bk AS (
        SELECT date_trunc('month', b.created_at) AS m,
               COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)), 0) AS gmv,
               COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)) FILTER (WHERE b.status = 'completed'), 0) AS done_gmv,
               COUNT(*) AS cnt,
               COUNT(*) FILTER (WHERE b.status = 'completed') AS done,
               COALESCE(SUM(b.booked_quantity * GREATEST(COALESCE(d.original_price, 0) - COALESCE(d.discounted_price, 0), 0)) FILTER (WHERE b.status = 'completed'), 0) AS save,
               COUNT(DISTINCT b.user_id) AS unique_b
        FROM bookings b
        LEFT JOIN deals d ON d.id = b.deal_id
        WHERE b.created_at >= date_trunc('month', now()) - ((p_months - 1) || ' months')::INTERVAL
        GROUP BY 1
    )
    SELECT to_char(months.m, 'YYYY-MM')::TEXT,
           to_char(months.m, 'Mon YY')::TEXT,
           COALESCE(bk.gmv, 0)::NUMERIC,
           COALESCE(bk.done_gmv, 0)::NUMERIC,
           COALESCE(bk.cnt, 0)::INT,
           COALESCE(bk.done, 0)::INT,
           CASE WHEN COALESCE(bk.done, 0) = 0 THEN 0 ELSE ROUND(bk.done_gmv / bk.done, 2) END,
           COALESCE(bk.save, 0)::NUMERIC,
           COALESCE(bk.unique_b, 0)::INT
    FROM months
    LEFT JOIN bk ON bk.m = months.m
    ORDER BY months.m ASC;
END;
$$;


--
-- Name: admin_health_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_health_check() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result JSONB;
    v_table_counts JSONB;
    v_critical_triggers JSONB;
    v_indexes_present JSONB;
    v_rls_status JSONB;
    v_recent_errors INT;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;

    -- Row counts for core tables — quick sanity check
    SELECT jsonb_build_object(
        'users',                  (SELECT COUNT(*) FROM users),
        'sellers',                (SELECT COUNT(*) FROM users WHERE user_type='seller'),
        'buyers',                 (SELECT COUNT(*) FROM users WHERE user_type='buyer'),
        'admins',                 (SELECT COUNT(*) FROM users WHERE user_type='admin'),
        'deals',                  (SELECT COUNT(*) FROM deals),
        'deals_active',           (SELECT COUNT(*) FROM deals WHERE status='active'),
        'bookings',               (SELECT COUNT(*) FROM bookings),
        'bookings_today',         (SELECT COUNT(*) FROM bookings WHERE created_at >= now() - INTERVAL '1 day'),
        'activity_log',           (SELECT COUNT(*) FROM activity_log),
        'activity_today',         (SELECT COUNT(*) FROM activity_log WHERE created_at >= now() - INTERVAL '1 day'),
        'user_sessions',          (SELECT COUNT(*) FROM user_sessions),
        'sessions_recent',        (SELECT COUNT(*) FROM user_sessions WHERE last_seen_at >= now() - INTERVAL '5 minutes'),
        'merchant_subscriptions', (SELECT COUNT(*) FROM merchant_subscriptions),
        'subscription_payments',  (SELECT COUNT(*) FROM subscription_payments),
        'store_profiles',         (SELECT COUNT(*) FROM store_profiles),
        'store_analytics_events', (SELECT COUNT(*) FROM store_analytics_events),
        'notifications',          (SELECT COUNT(*) FROM notifications),
        'ratings',                (SELECT COUNT(*) FROM ratings)
    ) INTO v_table_counts;

    -- Critical triggers — confirm the safety-net triggers exist
    SELECT jsonb_object_agg(tgname, true)
      INTO v_critical_triggers
    FROM pg_trigger
    WHERE NOT tgisinternal
      AND tgname IN (
        'tr_guard_deal_publish',
        'tr_guard_report_insert',
        'tr_guard_complaint_insert',
        'tr_new_seller_trial'
      );

    -- Critical indexes — query plan health
    SELECT jsonb_object_agg(indexname, true)
      INTO v_indexes_present
    FROM pg_indexes
    WHERE schemaname='public'
      AND indexname IN (
        'bookings_user_id_idx',
        'bookings_store_id_idx',
        'deals_store_id_idx',
        'deals_status_idx',
        'activity_log_created_at_idx',
        'user_sessions_last_seen_idx'
      );

    -- RLS status on critical tables
    SELECT jsonb_object_agg(c.relname, c.relrowsecurity)
      INTO v_rls_status
    FROM pg_class c
    JOIN pg_namespace n ON c.relnamespace = n.oid
    WHERE n.nspname = 'public'
      AND c.relname IN ('users','deals','bookings','merchant_subscriptions','subscription_payments','store_profiles','notifications','activity_log');

    v_result := jsonb_build_object(
        'as_of',              now(),
        'admin_user_id',      auth.uid()::TEXT,
        'table_counts',       v_table_counts,
        'critical_triggers',  COALESCE(v_critical_triggers, '{}'::JSONB),
        'critical_indexes',   COALESCE(v_indexes_present, '{}'::JSONB),
        'rls_enabled',        COALESCE(v_rls_status, '{}'::JSONB),
        'db_size_bytes',      (SELECT pg_database_size(current_database()))
    );
    RETURN v_result;
END;
$$;


--
-- Name: admin_investor_kpis(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_investor_kpis(p_days integer DEFAULT 30) RETURNS TABLE(period_days integer, gmv numeric, gmv_completed numeric, savings_delivered numeric, total_bookings integer, completed_bookings integer, cancelled_bookings integer, avg_order_value numeric, dau integer, wau integer, mau integer, stickiness_pct numeric, total_views integer, unique_viewers integer, conversion_pct numeric, repeat_customer_rate_pct numeric, mom_gmv_growth_pct numeric, mom_bookings_growth_pct numeric, mom_new_users_growth_pct numeric, new_buyers integer, new_sellers integer, net_active_merchants integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_end TIMESTAMPTZ := now();
    v_start TIMESTAMPTZ := now() - (GREATEST(p_days, 1) || ' days')::INTERVAL;
    v_prev_start TIMESTAMPTZ := v_start - (GREATEST(p_days, 1) || ' days')::INTERVAL;
    v_gmv NUMERIC; v_gmv_done NUMERIC; v_save NUMERIC;
    v_total_bk INT; v_done_bk INT; v_canc_bk INT;
    v_dau INT; v_wau INT; v_mau INT;
    v_views INT; v_viewers INT;
    v_buyers INT; v_sellers INT;
    v_repeat_bk INT; v_single_bk INT;
    v_prev_gmv NUMERIC; v_prev_total_bk INT; v_prev_new_users INT;
    v_active_merchants INT;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;

    -- Volume (current period)
    SELECT
        COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)), 0),
        COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)) FILTER (WHERE b.status = 'completed'), 0),
        COALESCE(SUM(b.booked_quantity * GREATEST(COALESCE(d.original_price, 0) - COALESCE(d.discounted_price, 0), 0)) FILTER (WHERE b.status = 'completed'), 0),
        COUNT(*),
        COUNT(*) FILTER (WHERE b.status = 'completed'),
        COUNT(*) FILTER (WHERE b.status = 'cancelled')
      INTO v_gmv, v_gmv_done, v_save, v_total_bk, v_done_bk, v_canc_bk
    FROM bookings b
    LEFT JOIN deals d ON d.id = b.deal_id
    WHERE b.created_at >= v_start AND b.created_at <= v_end;

    -- Active users — DAU last 1d, WAU last 7d, MAU last 30d (from activity_log)
    SELECT COUNT(DISTINCT user_id) INTO v_dau
    FROM activity_log
    WHERE created_at >= v_end - INTERVAL '1 day' AND user_id IS NOT NULL;

    SELECT COUNT(DISTINCT user_id) INTO v_wau
    FROM activity_log
    WHERE created_at >= v_end - INTERVAL '7 days' AND user_id IS NOT NULL;

    SELECT COUNT(DISTINCT user_id) INTO v_mau
    FROM activity_log
    WHERE created_at >= v_end - INTERVAL '30 days' AND user_id IS NOT NULL;

    -- Funnel
    SELECT COUNT(*), COUNT(DISTINCT user_id)
      INTO v_views, v_viewers
    FROM activity_log
    WHERE action = 'view_deal' AND created_at >= v_start AND created_at <= v_end;

    -- New buyers / sellers in current period
    SELECT COUNT(*) FILTER (WHERE user_type = 'buyer'),
           COUNT(*) FILTER (WHERE user_type = 'seller')
      INTO v_buyers, v_sellers
    FROM users
    WHERE created_at >= v_start AND created_at <= v_end;

    -- Repeat customer rate: bookers with 2+ bookings / bookers with any booking
    WITH bookers AS (
        SELECT user_id, COUNT(*) AS n
        FROM bookings
        WHERE created_at >= v_start AND created_at <= v_end
          AND status IN ('completed', 'acknowledged')
          AND user_id IS NOT NULL
        GROUP BY user_id
    )
    SELECT COUNT(*) FILTER (WHERE n >= 2), COUNT(*)
      INTO v_repeat_bk, v_single_bk
    FROM bookers;

    -- Previous period for MoM growth
    SELECT COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)), 0),
           COUNT(*)
      INTO v_prev_gmv, v_prev_total_bk
    FROM bookings b
    LEFT JOIN deals d ON d.id = b.deal_id
    WHERE b.created_at >= v_prev_start AND b.created_at < v_start;

    SELECT COUNT(*) INTO v_prev_new_users
    FROM users
    WHERE created_at >= v_prev_start AND created_at < v_start AND user_type = 'buyer';

    -- Net active merchants — sellers who actually had bookings in the window
    SELECT COUNT(DISTINCT b.store_id) INTO v_active_merchants
    FROM bookings b
    WHERE b.created_at >= v_start AND b.created_at <= v_end;

    RETURN QUERY SELECT
        p_days,
        v_gmv, v_gmv_done, v_save,
        v_total_bk, v_done_bk, v_canc_bk,
        CASE WHEN v_done_bk = 0 THEN 0 ELSE ROUND(v_gmv_done / v_done_bk, 2) END,
        v_dau, v_wau, v_mau,
        CASE WHEN v_mau = 0 THEN 0 ELSE ROUND(100.0 * v_dau / v_mau, 1) END,
        v_views, v_viewers,
        CASE WHEN v_viewers = 0 THEN 0 ELSE ROUND(100.0 * v_single_bk / v_viewers, 1) END,
        CASE WHEN v_single_bk = 0 THEN 0 ELSE ROUND(100.0 * v_repeat_bk / v_single_bk, 1) END,
        CASE WHEN v_prev_gmv = 0 THEN
             CASE WHEN v_gmv = 0 THEN 0 ELSE 100 END
             ELSE ROUND(100.0 * (v_gmv - v_prev_gmv) / v_prev_gmv, 1) END,
        CASE WHEN v_prev_total_bk = 0 THEN
             CASE WHEN v_total_bk = 0 THEN 0 ELSE 100 END
             ELSE ROUND(100.0 * (v_total_bk - v_prev_total_bk) / v_prev_total_bk, 1) END,
        CASE WHEN v_prev_new_users = 0 THEN
             CASE WHEN v_buyers = 0 THEN 0 ELSE 100 END
             ELSE ROUND(100.0 * (v_buyers - v_prev_new_users) / v_prev_new_users, 1) END,
        v_buyers, v_sellers, v_active_merchants;
END;
$$;


--
-- Name: admin_list_complaints(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_complaints(p_query text DEFAULT ''::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, created_at timestamp with time zone, category text, subject text, message text, status text, admin_note text, user_id text, user_name text, user_phone text, user_type text, target_id text, target_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_role TEXT;
    v_q TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
    SELECT u.user_type INTO v_role FROM public.users u WHERE u.id = auth.uid()::text;
    IF v_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;
    v_q := '%' || COALESCE(p_query, '') || '%';

    RETURN QUERY
    SELECT
        c.id, c.created_at, c.category, c.subject, c.message, c.status, c.admin_note,
        c.user_id,
        COALESCE(NULLIF(cu.name,''), cu.shop, '—'),
        cu.phone,
        COALESCE(cu.user_type, c.user_role),
        c.target_id,
        COALESCE(NULLIF(tu.name,''), tu.shop, NULL)
    FROM public.complaints c
    LEFT JOIN public.users cu ON cu.id = c.user_id
    LEFT JOIN public.users tu ON tu.id = c.target_id
    WHERE (p_status IS NULL OR c.status = p_status)
      AND (
          p_query = '' OR
          c.user_id ILIKE v_q OR cu.name ILIKE v_q OR cu.phone ILIKE v_q OR
          c.message ILIKE v_q OR COALESCE(c.subject,'') ILIKE v_q
      )
    ORDER BY c.created_at DESC
    LIMIT GREATEST(p_limit, 1) OFFSET GREATEST(p_offset, 0);
END $$;


--
-- Name: admin_list_gateways(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_gateways() RETURNS TABLE(merchant_id text, store_name text, provider text, payment_modes text, is_enabled boolean, disabled_by_admin boolean, verified_at timestamp with time zone, fail_count integer, key_last4 text, agreement_accepted_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF;
  RETURN QUERY
  SELECT g.merchant_id, COALESCE(NULLIF(u.shop, ''), u.name) AS store_name, g.provider, g.payment_modes,
         g.is_enabled, g.disabled_by_admin, g.verified_at,
         g.fail_count, g.key_last4, g.agreement_accepted_at, g.created_at
  FROM public.merchant_gateways g
  LEFT JOIN public.users u ON u.id = g.merchant_id
  ORDER BY g.created_at DESC;
END $$;


--
-- Name: admin_list_message_threads(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_message_threads(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(barcode text, deal_id text, buyer_id text, buyer_name text, buyer_phone text, seller_id text, seller_name text, seller_shop text, booking_status text, message_count bigint, last_body text, last_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT public.is_admin(auth.uid()::text) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    RETURN QUERY
    WITH agg AS (
        SELECT bm.barcode,
               COUNT(*) AS message_count,
               MAX(bm.created_at) AS last_at,
               (ARRAY_AGG(bm.body ORDER BY bm.created_at DESC))[1] AS last_body
        FROM public.booking_messages bm
        GROUP BY bm.barcode
    )
    SELECT a.barcode, b.deal_id,
           b.user_id, COALESCE(bu.name, b.user_name), COALESCE(bu.phone, b.user_phone),
           b.store_id, su.name, su.shop,
           b.status, a.message_count, a.last_body, a.last_at
    FROM agg a
    JOIN public.bookings b ON b.barcode = a.barcode
    LEFT JOIN public.users bu ON bu.id = b.user_id
    LEFT JOIN public.users su ON su.id = b.store_id
    WHERE p_search IS NULL OR p_search = '' OR (
        a.barcode ILIKE '%'||p_search||'%'
        OR COALESCE(bu.name,'')  ILIKE '%'||p_search||'%'
        OR COALESCE(su.name,'')  ILIKE '%'||p_search||'%'
        OR COALESCE(su.shop,'')  ILIKE '%'||p_search||'%'
        OR COALESCE(bu.phone,'') ILIKE '%'||p_search||'%'
    )
    ORDER BY a.last_at DESC
    LIMIT GREATEST(1, LEAST(p_limit, 500));
END $$;


--
-- Name: admin_list_payment_attempts(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_payment_attempts(p_days integer DEFAULT 30, p_limit integer DEFAULT 100) RETURNS TABLE(id text, merchant_id text, merchant_name text, merchant_shop text, gateway text, amount numeric, currency text, status text, gateway_reference text, error_message text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT pa.id::TEXT, pa.merchant_id::TEXT,
           u.name::TEXT, u.shop::TEXT,
           pa.gateway::TEXT, pa.amount, pa.currency::TEXT, pa.status::TEXT,
           pa.gateway_reference::TEXT, pa.error_message::TEXT, pa.created_at
    FROM payment_attempts pa
    LEFT JOIN users u ON u.id = pa.merchant_id
    WHERE pa.created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
    ORDER BY pa.created_at DESC
    LIMIT GREATEST(p_limit, 1);
END;
$$;


--
-- Name: admin_list_platform_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_platform_settings() RETURNS TABLE(key text, value jsonb, description text, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT ps.key::TEXT, ps.value, ps.description::TEXT, ps.updated_at
    FROM platform_settings ps
    ORDER BY ps.key ASC;
END;
