--
-- Name: admin_list_reports(text, text, text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_reports(p_query text DEFAULT ''::text, p_reported_role text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_days integer DEFAULT 0, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, created_at timestamp with time zone, report_type text, reason text, status text, admin_note text, reporter_id text, reporter_name text, reporter_phone text, reporter_role text, reporter_filed_count bigint, reported_id text, reported_name text, reported_phone text, reported_role text, reported_under_review boolean, reported_received_count bigint, reported_distinct_reporters bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_role TEXT;
    v_q TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
    SELECT u.user_type INTO v_role FROM public.users u WHERE u.id = auth.uid()::text;
    IF v_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;
    v_q := '%' || COALESCE(p_query, '') || '%';

    RETURN QUERY
    SELECT
        r.id, r.created_at, r.report_type, r.reason, r.status, r.admin_note,
        r.reporter_id,
        COALESCE(NULLIF(ru.name,''), ru.shop, '—'),
        ru.phone, r.reporter_role,
        (SELECT COUNT(*) FROM public.reports rf WHERE rf.reporter_id = r.reporter_id),
        r.reported_id,
        COALESCE(NULLIF(du.name,''), du.shop, '—'),
        du.phone, r.reported_role,
        COALESCE(du.under_review, FALSE),
        (SELECT COUNT(*) FROM public.reports rc
            WHERE rc.reported_id = r.reported_id AND rc.status <> 'dismissed'),
        (SELECT COUNT(DISTINCT rd.reporter_id) FROM public.reports rd
            WHERE rd.reported_id = r.reported_id AND rd.status <> 'dismissed'
              AND rd.created_at > NOW() - INTERVAL '14 days')
    FROM public.reports r
    LEFT JOIN public.users ru ON ru.id = r.reporter_id
    LEFT JOIN public.users du ON du.id = r.reported_id
    WHERE (p_reported_role IS NULL OR r.reported_role = p_reported_role)
      AND (p_type   IS NULL OR r.report_type = p_type)
      AND (p_status IS NULL OR r.status = p_status)
      AND (p_days  <= 0 OR r.created_at > NOW() - (p_days || ' days')::INTERVAL)
      AND (
          p_query = '' OR
          r.reporter_id ILIKE v_q OR r.reported_id ILIKE v_q OR
          ru.name ILIKE v_q OR du.name ILIKE v_q OR
          ru.shop ILIKE v_q OR du.shop ILIKE v_q OR
          ru.phone ILIKE v_q OR du.phone ILIKE v_q OR
          r.reason ILIKE v_q
      )
    ORDER BY r.created_at DESC
    LIMIT GREATEST(p_limit, 1) OFFSET GREATEST(p_offset, 0);
END $$;


--
-- Name: admin_list_sponsors(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_sponsors() RETURNS TABLE(store_id text, store_name text, shop text, is_active boolean, target_category text, target_city text, target_region text, target_radius_km double precision, priority integer, starts_at timestamp with time zone, expires_at timestamp with time zone, notes text, label_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT public.is_admin(auth.uid()::text) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;
    RETURN QUERY
    SELECT s.store_id, u.name, u.shop, s.is_active, s.target_category,
           s.target_city, s.target_region, s.target_radius_km, s.priority,
           s.starts_at, s.expires_at, s.notes, s.label_type
    FROM public.sponsors s JOIN public.users u ON u.id = s.store_id
    ORDER BY s.priority DESC, s.created_at DESC;
END $$;


--
-- Name: admin_list_staff(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_staff() RETURNS TABLE(id text, name text, email text, phone text, user_type text, is_super_admin boolean, admin_permissions text[], created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'forbidden: super admin required';
  END IF;
  RETURN QUERY
    SELECT u.id, u.name, u.email, u.phone, u.user_type,
           u.is_super_admin, u.admin_permissions, u.created_at
    FROM public.users u
    WHERE u.user_type = 'admin'
    ORDER BY u.is_super_admin DESC, u.created_at NULLS LAST;
END;
$$;


--
-- Name: admin_list_store_name_requests(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_store_name_requests(p_status text DEFAULT 'requested'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.requested_at DESC), '[]'::jsonb) INTO v
  FROM (SELECT r.*, u.name AS owner_name, u.phone AS owner_phone
        FROM public.store_name_requests r JOIN public.users u ON u.id = r.store_id
        WHERE p_status IS NULL OR r.status = p_status) t;
  RETURN jsonb_build_object('ok', true, 'rows', v);
END $$;


--
-- Name: admin_list_warned_users(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_warned_users(p_role text DEFAULT NULL::text, p_min_count integer DEFAULT 1, p_search text DEFAULT ''::text) RETURNS TABLE(user_id text, name text, phone text, user_type text, is_suspended boolean, warn_count integer, last_warned_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  RETURN QUERY
    SELECT t.user_id, t.name, t.phone, t.user_type, t.is_suspended, t.warn_count, t.last_warned_at
    FROM (
      SELECT w.user_id,
        u.name, u.phone, u.user_type, COALESCE(u.is_suspended, false) AS is_suspended,
        count(*)::int AS warn_count,
        max(w.created_at) AS last_warned_at
      FROM user_warnings w
      LEFT JOIN users u ON u.id = w.user_id
      WHERE (p_role IS NULL OR u.user_type = p_role)
        AND (COALESCE(TRIM(p_search), '') = ''
             OR u.name ILIKE '%' || p_search || '%'
             OR u.phone ILIKE '%' || p_search || '%'
             OR w.user_id ILIKE '%' || p_search || '%')
      GROUP BY w.user_id, u.name, u.phone, u.user_type, u.is_suspended
    ) t
    WHERE t.warn_count >= GREATEST(1, COALESCE(p_min_count, 1))
    ORDER BY t.warn_count DESC, t.last_warned_at DESC;
END $$;


--
-- Name: admin_lookup_by_date(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_lookup_by_date(p_date date) RETURNS TABLE(target_date date, views_count integer, unique_viewers integer, bookings_count integer, unique_bookers integer, completed_bookings integer, cancelled_bookings integer, gmv numeric, savings_delivered numeric, new_buyers integer, new_sellers integer, active_users integer, total_events integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_start TIMESTAMPTZ;
    v_end TIMESTAMPTZ;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    v_start := p_date::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';
    v_end := (p_date + 1)::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';

    RETURN QUERY
    WITH al AS (
        SELECT * FROM activity_log
        WHERE created_at >= v_start AND created_at < v_end
    ),
    bk AS (
        SELECT b.*, d.discounted_price, d.original_price
        FROM bookings b
        LEFT JOIN deals d ON d.id = b.deal_id
        WHERE b.created_at >= v_start AND b.created_at < v_end
    )
    SELECT p_date,
        (SELECT COUNT(*) FROM al WHERE action = 'view_deal')::INT,
        (SELECT COUNT(DISTINCT user_id) FROM al WHERE action = 'view_deal' AND user_id IS NOT NULL)::INT,
        (SELECT COUNT(*) FROM bk)::INT,
        (SELECT COUNT(DISTINCT user_id) FROM bk WHERE user_id IS NOT NULL)::INT,
        (SELECT COUNT(*) FROM bk WHERE status = 'completed')::INT,
        (SELECT COUNT(*) FROM bk WHERE status = 'cancelled')::INT,
        (SELECT COALESCE(SUM(booked_quantity * COALESCE(discounted_price, 0)), 0) FROM bk WHERE status IN ('completed', 'acknowledged'))::NUMERIC,
        (SELECT COALESCE(SUM(booked_quantity * GREATEST(COALESCE(original_price, 0) - COALESCE(discounted_price, 0), 0)), 0) FROM bk WHERE status = 'completed')::NUMERIC,
        (SELECT COUNT(*) FROM users WHERE created_at >= v_start AND created_at < v_end AND user_type = 'buyer')::INT,
        (SELECT COUNT(*) FROM users WHERE created_at >= v_start AND created_at < v_end AND user_type = 'seller')::INT,
        (SELECT COUNT(DISTINCT user_id) FROM al WHERE user_id IS NOT NULL)::INT,
        (SELECT COUNT(*) FROM al)::INT;
END;
$$;


--
-- Name: admin_lookup_by_month(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_lookup_by_month(p_year integer, p_month integer) RETURNS TABLE(label text, views_count integer, bookings_count integer, completed_bookings integer, gmv numeric, savings_delivered numeric, new_buyers integer, active_users integer, daily_breakdown jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_start TIMESTAMPTZ;
    v_end TIMESTAMPTZ;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    v_start := make_date(p_year, p_month, 1)::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';
    v_end := (make_date(p_year, p_month, 1) + INTERVAL '1 month')::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';

    RETURN QUERY
    WITH al AS (
        SELECT * FROM activity_log
        WHERE created_at >= v_start AND created_at < v_end
    ),
    bk AS (
        SELECT b.*, d.discounted_price, d.original_price
        FROM bookings b
        LEFT JOIN deals d ON d.id = b.deal_id
        WHERE b.created_at >= v_start AND b.created_at < v_end
    ),
    daily AS (
        SELECT (al.created_at AT TIME ZONE 'Asia/Riyadh')::DATE AS d,
               COUNT(*) FILTER (WHERE al.action = 'view_deal') AS views,
               COUNT(*) FILTER (WHERE al.action = 'book') AS books
        FROM al
        GROUP BY 1
        ORDER BY 1
    )
    SELECT to_char(v_start, 'Mon YYYY')::TEXT,
        (SELECT COUNT(*) FROM al WHERE action = 'view_deal')::INT,
        (SELECT COUNT(*) FROM bk)::INT,
        (SELECT COUNT(*) FROM bk WHERE status = 'completed')::INT,
        (SELECT COALESCE(SUM(booked_quantity * COALESCE(discounted_price, 0)), 0) FROM bk WHERE status IN ('completed', 'acknowledged'))::NUMERIC,
        (SELECT COALESCE(SUM(booked_quantity * GREATEST(COALESCE(original_price, 0) - COALESCE(discounted_price, 0), 0)), 0) FROM bk WHERE status = 'completed')::NUMERIC,
        (SELECT COUNT(*) FROM users WHERE created_at >= v_start AND created_at < v_end AND user_type = 'buyer')::INT,
        (SELECT COUNT(DISTINCT user_id) FROM al WHERE user_id IS NOT NULL)::INT,
        COALESCE((SELECT jsonb_agg(jsonb_build_object('day', to_char(d, 'YYYY-MM-DD'), 'views', views, 'books', books) ORDER BY d) FROM daily), '[]'::jsonb);
END;
$$;


--
-- Name: admin_lookup_by_year(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_lookup_by_year(p_year integer) RETURNS TABLE(label text, views_count integer, bookings_count integer, completed_bookings integer, gmv numeric, savings_delivered numeric, new_buyers integer, new_sellers integer, monthly_breakdown jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_start TIMESTAMPTZ;
    v_end TIMESTAMPTZ;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    v_start := make_date(p_year, 1, 1)::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';
    v_end := make_date(p_year + 1, 1, 1)::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';

    RETURN QUERY
    WITH al AS (
        SELECT * FROM activity_log
        WHERE created_at >= v_start AND created_at < v_end
    ),
    bk AS (
        SELECT b.*, d.discounted_price, d.original_price
        FROM bookings b
        LEFT JOIN deals d ON d.id = b.deal_id
        WHERE b.created_at >= v_start AND b.created_at < v_end
    ),
    monthly AS (
        SELECT date_trunc('month', al.created_at AT TIME ZONE 'Asia/Riyadh') AS m,
               COUNT(*) FILTER (WHERE al.action = 'view_deal') AS views,
               COUNT(*) FILTER (WHERE al.action = 'book') AS books
        FROM al
        GROUP BY 1
    ),
    monthly_bk AS (
        SELECT date_trunc('month', bk.created_at AT TIME ZONE 'Asia/Riyadh') AS m,
               COALESCE(SUM(bk.booked_quantity * COALESCE(bk.discounted_price, 0)) FILTER (WHERE bk.status IN ('completed','acknowledged')), 0) AS gmv
        FROM bk
        GROUP BY 1
    )
    SELECT p_year::TEXT,
        (SELECT COUNT(*) FROM al WHERE action = 'view_deal')::INT,
        (SELECT COUNT(*) FROM bk)::INT,
        (SELECT COUNT(*) FROM bk WHERE status = 'completed')::INT,
        (SELECT COALESCE(SUM(booked_quantity * COALESCE(discounted_price, 0)), 0) FROM bk WHERE status IN ('completed', 'acknowledged'))::NUMERIC,
        (SELECT COALESCE(SUM(booked_quantity * GREATEST(COALESCE(original_price, 0) - COALESCE(discounted_price, 0), 0)), 0) FROM bk WHERE status = 'completed')::NUMERIC,
        (SELECT COUNT(*) FROM users WHERE created_at >= v_start AND created_at < v_end AND user_type = 'buyer')::INT,
        (SELECT COUNT(*) FROM users WHERE created_at >= v_start AND created_at < v_end AND user_type = 'seller')::INT,
        COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'month', to_char(m, 'Mon YYYY'),
            'month_key', to_char(m, 'YYYY-MM'),
            'views', COALESCE(monthly.views, 0),
            'books', COALESCE(monthly.books, 0),
            'gmv', COALESCE(monthly_bk.gmv, 0)
        ) ORDER BY m)
        FROM (SELECT DISTINCT m FROM monthly UNION SELECT DISTINCT m FROM monthly_bk) all_months
        LEFT JOIN monthly USING (m)
        LEFT JOIN monthly_bk USING (m)
        ), '[]'::jsonb);
END;
$$;


--
-- Name: admin_moderation_flags(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_moderation_flags(p_store text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id', t.id, 'kind', t.kind, 'source', t.source,
      'store_id', t.store_id, 'offender_id', t.offender_id, 'offender_name', t.offender_name,
      'content', t.content, 'matched', t.matched, 'status', t.status,
      'created_at', t.created_at) ORDER BY t.created_at DESC), '[]'::jsonb)
    INTO v
    FROM (
      SELECT mf.* FROM moderation_flags mf
       WHERE (p_store IS NULL OR mf.store_id = p_store OR mf.offender_id = p_store)
         AND (p_status IS NULL OR mf.status = p_status)
       ORDER BY mf.created_at DESC
       LIMIT greatest(1, least(coalesce(p_limit, 200), 2000))
    ) t;
  RETURN coalesce(v, '[]'::jsonb);
END $$;


--
-- Name: admin_moderation_overview(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_moderation_overview(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT jsonb_build_object(
    'total_open', (SELECT count(*) FROM moderation_flags mf2 WHERE mf2.status = 'open'),
    'stores', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'store_id', t.store_id, 'shop', t.shop,
        'flags', t.flags, 'open', t.open_flags,
        'chat', t.chat, 'rating', t.rating, 'deal', t.deal, 'upload', t.upload,
        'last_at', t.last_at) ORDER BY t.open_flags DESC, t.flags DESC)
      FROM (
        SELECT mf.store_id,
               coalesce(max(mf.offender_name), mf.store_id) AS shop,
               count(*) AS flags,
               count(*) FILTER (WHERE mf.status = 'open') AS open_flags,
               count(*) FILTER (WHERE mf.source = 'chat') AS chat,
               count(*) FILTER (WHERE mf.source = 'rating') AS rating,
               count(*) FILTER (WHERE mf.source = 'deal') AS deal,
               count(*) FILTER (WHERE mf.source = 'upload') AS upload,
               max(mf.created_at) AS last_at
          FROM moderation_flags mf
         WHERE mf.store_id IS NOT NULL
         GROUP BY mf.store_id
         ORDER BY count(*) FILTER (WHERE mf.status = 'open') DESC, count(*) DESC
         LIMIT greatest(1, least(coalesce(p_limit, 100), 1000))
      ) t), '[]'::jsonb)
  ) INTO v;
  RETURN v;
END $$;


--
-- Name: admin_mrr_monthly(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_mrr_monthly(p_months integer DEFAULT 12) RETURNS TABLE(month_key text, month_label text, paid_amount numeric, paid_count integer, refunded_amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH months AS (
        SELECT date_trunc('month', now()) - (n || ' months')::INTERVAL AS m
        FROM generate_series(0, GREATEST(p_months, 1) - 1) AS n
    ),
    paid AS (
        SELECT date_trunc('month', paid_at) AS m,
               SUM(amount) FILTER (WHERE status = 'paid') AS amt,
               COUNT(*) FILTER (WHERE status = 'paid') AS cnt,
               SUM(amount) FILTER (WHERE status = 'refunded') AS refunded
        FROM subscription_payments
        WHERE paid_at IS NOT NULL
          AND paid_at >= date_trunc('month', now()) - ((p_months - 1) || ' months')::INTERVAL
        GROUP BY 1
    )
    SELECT to_char(months.m, 'YYYY-MM')::TEXT,
           to_char(months.m, 'Mon YY')::TEXT,
           COALESCE(paid.amt, 0)::NUMERIC,
           COALESCE(paid.cnt, 0)::INT,
           COALESCE(paid.refunded, 0)::NUMERIC
    FROM months
    LEFT JOIN paid ON paid.m = months.m
    ORDER BY months.m ASC;
END;
$$;


--
-- Name: admin_my_permissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_my_permissions() RETURNS TABLE(is_super_admin boolean, admin_permissions text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'forbidden: admin required';
  END IF;
  RETURN QUERY
    SELECT u.is_super_admin, u.admin_permissions
    FROM public.users u
    WHERE u.id = auth.uid()::text;
END;
$$;


--
-- Name: admin_notify_user(text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_notify_user(p_user_id text, p_title_ar text, p_body_ar text, p_email boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_emailed boolean := false;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    IF COALESCE(btrim(p_title_ar),'') = '' OR p_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_fields');
    END IF;
    INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
    VALUES (p_user_id, p_title_ar, p_title_ar, COALESCE(p_body_ar,''), COALESCE(p_body_ar,''),
            'system', jsonb_build_object('from_analyst', true), NOW());
    IF p_email THEN
        v_emailed := public.taki_queue_email(
          p_user_id, 'analyst_tip', p_title_ar,
          public.taki_email_wrap(p_title_ar,
            '<p style="font-size:15px;line-height:1.9;margin:0">'
            || replace(replace(replace(replace(COALESCE(p_body_ar,''),'&','&amp;'),'<','&lt;'),'>','&gt;'), E'\n', '<br>')
            || '</p>'));
    END IF;
    RETURN jsonb_build_object('success', true, 'emailed', v_emailed);
END $$;


--
-- Name: admin_payment_gateway_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_payment_gateway_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_enabled BOOLEAN;
    v_provider TEXT;
    v_pub_key TEXT;
    v_webhook_url TEXT;
    v_has_secret BOOLEAN := FALSE; -- secret key is server-side only; we don't read it client-facing
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    SELECT (value)::BOOLEAN INTO v_enabled FROM platform_settings WHERE key='payment_gateway_enabled';
    SELECT (value #>> '{}')::TEXT INTO v_provider FROM platform_settings WHERE key='payment_gateway_provider';
    SELECT (value #>> '{}')::TEXT INTO v_pub_key FROM platform_settings WHERE key='payment_gateway_publishable_key';
    SELECT (value #>> '{}')::TEXT INTO v_webhook_url FROM platform_settings WHERE key='payment_gateway_webhook_url';

    RETURN jsonb_build_object(
        'enabled',              COALESCE(v_enabled, FALSE),
        'provider',             COALESCE(v_provider, ''),
        'has_publishable_key',  v_pub_key IS NOT NULL AND length(v_pub_key) > 8,
        'publishable_key_hint', CASE
                                  WHEN v_pub_key IS NULL OR length(v_pub_key) < 8 THEN NULL
                                  ELSE substring(v_pub_key from 1 for 8) || '…'
                                END,
        'webhook_url',          COALESCE(v_webhook_url, ''),
        'has_secret_configured', v_has_secret,
        'attempts_total',       (SELECT COUNT(*) FROM payment_attempts),
        'attempts_paid',        (SELECT COUNT(*) FROM payment_attempts WHERE status='paid'),
        'attempts_failed',      (SELECT COUNT(*) FROM payment_attempts WHERE status='failed')
    );
END;
$$;


--
-- Name: admin_payment_log(timestamp with time zone, timestamp with time zone, text, text, text, bigint, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_payment_log(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_merchant text DEFAULT NULL::text, p_provider text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_before_id bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50, p_search text DEFAULT NULL::text) RETURNS TABLE(id bigint, booking_barcode text, merchant_id text, merchant_name text, buyer_id text, buyer_name text, amount numeric, vat_amount numeric, provider text, payment_ref text, status text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_q text := NULLIF(btrim(COALESCE(p_search, '')), '');
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF;
  RETURN QUERY
  SELECT l.id, l.booking_barcode, l.merchant_id,
         COALESCE(NULLIF(um.shop, ''), um.name) AS merchant_name,
         l.buyer_id, ub.name AS buyer_name,
         l.amount, l.vat_amount, l.provider, l.payment_ref, l.status, l.created_at
  FROM public.platform_payment_log l
  LEFT JOIN public.users um ON um.id = l.merchant_id
  LEFT JOIN public.users ub ON ub.id = l.buyer_id
  WHERE (p_from IS NULL OR l.created_at >= p_from)
    AND (p_to   IS NULL OR l.created_at <  p_to)
    AND (p_merchant IS NULL OR l.merchant_id = p_merchant)
    AND (p_provider IS NULL OR l.provider = p_provider)
    AND (p_status   IS NULL OR l.status = p_status)
    AND (p_before_id IS NULL OR l.id < p_before_id)
    AND (v_q IS NULL
         OR l.booking_barcode LIKE upper(v_q) || '%'
         OR l.payment_ref LIKE v_q || '%'
         OR (v_q ~ '^[0-9]+$' AND l.id = v_q::bigint))
  ORDER BY l.id DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
END $_$;


--
-- Name: admin_payment_log_export(timestamp with time zone, timestamp with time zone, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_payment_log_export(p_from timestamp with time zone, p_to timestamp with time zone, p_merchant text DEFAULT NULL::text, p_provider text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_before_id bigint DEFAULT NULL::bigint) RETURNS TABLE(id bigint, booking_barcode text, merchant_id text, merchant_name text, buyer_id text, amount numeric, vat_amount numeric, provider text, payment_ref text, status text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF;
  IF p_from IS NULL OR p_to IS NULL THEN RAISE EXCEPTION 'RANGE_REQUIRED'; END IF;
  IF p_to - p_from > interval '32 days' THEN RAISE EXCEPTION 'RANGE_TOO_WIDE'; END IF;
  RETURN QUERY
  SELECT l.id, l.booking_barcode, l.merchant_id,
         COALESCE(NULLIF(um.shop, ''), um.name) AS merchant_name,
         l.buyer_id, l.amount, l.vat_amount, l.provider, l.payment_ref, l.status, l.created_at
  FROM public.platform_payment_log l
  LEFT JOIN public.users um ON um.id = l.merchant_id
  WHERE l.created_at >= p_from AND l.created_at < p_to
    AND (p_merchant IS NULL OR l.merchant_id = p_merchant)
    AND (p_provider IS NULL OR l.provider = p_provider)
    AND (p_status   IS NULL OR l.status = p_status)
    AND (p_before_id IS NULL OR l.id < p_before_id)
  ORDER BY l.id DESC
  LIMIT 10000;
END $$;


--
-- Name: admin_payment_log_stats(timestamp with time zone, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_payment_log_stats(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_merchant text DEFAULT NULL::text, p_provider text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_out jsonb;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF;
  SELECT jsonb_build_object(
    'count',     COUNT(*),
    'total',     COALESCE(SUM(l.amount), 0),
    'vat_total', COALESCE(SUM(l.vat_amount), 0)
  ) INTO v_out
  FROM public.platform_payment_log l
  WHERE (p_from IS NULL OR l.created_at >= p_from)
    AND (p_to   IS NULL OR l.created_at <  p_to)
    AND (p_merchant IS NULL OR l.merchant_id = p_merchant)
    AND (p_provider IS NULL OR l.provider = p_provider)
    AND (p_status   IS NULL OR l.status = p_status);
  RETURN v_out;
END $$;


--
-- Name: admin_promote_user(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_promote_user(target_id text, perms text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  current_role TEXT;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'forbidden: super admin required';
  END IF;
  IF target_id IS NULL OR target_id = '' THEN
    RAISE EXCEPTION 'target_id required';
  END IF;
  SELECT u.user_type INTO current_role FROM public.users u WHERE u.id = target_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'user not found';
  END IF;
  -- Refuse if already a super admin (would be a privilege downgrade attempt).
  IF EXISTS (SELECT 1 FROM public.users u WHERE u.id = target_id AND u.is_super_admin = TRUE) THEN
    RAISE EXCEPTION 'cannot modify super admin permissions via this RPC';
  END IF;
  UPDATE public.users u
  SET user_type = 'admin',
      is_super_admin = FALSE,
      admin_permissions = COALESCE(perms, '{}'::TEXT[])
  WHERE u.id = target_id;
END;
$$;


--
-- Name: admin_range_summary(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_range_summary(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(new_buyers integer, new_sellers integer, new_users integer, bookings integer, completed_bookings integer, cancelled_bookings integer, gmv numeric, new_subscriptions integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
  RETURN QUERY
    SELECT
      (SELECT count(*) FROM users u    WHERE u.user_type = 'buyer'  AND u.created_at >= p_from AND u.created_at < p_to)::int,
      (SELECT count(*) FROM users u    WHERE u.user_type = 'seller' AND u.created_at >= p_from AND u.created_at < p_to)::int,
      (SELECT count(*) FROM users u    WHERE u.created_at >= p_from AND u.created_at < p_to)::int,
      (SELECT count(*) FROM bookings b WHERE b.created_at >= p_from AND b.created_at < p_to)::int,
      (SELECT count(*) FROM bookings b WHERE b.status = 'completed' AND b.created_at >= p_from AND b.created_at < p_to)::int,
      (SELECT count(*) FROM bookings b WHERE b.status = 'cancelled' AND b.created_at >= p_from AND b.created_at < p_to)::int,
      COALESCE((SELECT sum(d.discounted_price * b.booked_quantity) FROM bookings b JOIN deals d ON d.id = b.deal_id WHERE b.created_at >= p_from AND b.created_at < p_to), 0),
      (SELECT count(*) FROM merchant_subscriptions ms WHERE ms.created_at >= p_from AND ms.created_at < p_to)::int;
END $$;


--
-- Name: admin_referral_stats(timestamp with time zone, timestamp with time zone, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_referral_stats(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 10, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_location text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from timestamptz := coalesce(p_from, 'epoch'::timestamptz);
  v_to   timestamptz := coalesce(p_to, now() + interval '1 day');
  v_limit integer := greatest(1, least(coalesce(p_limit, 10), 2000));
  v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  WITH ref_users AS (
    SELECT u.* FROM users u
     WHERE u.deleted_at IS NULL
       AND u.created_at >= v_from AND u.created_at < v_to
  ),
  src AS (
    SELECT coalesce(ru.referral_source, 'unknown') AS source, count(*) AS n
      FROM ref_users ru
     WHERE ru.referral_source IS NOT NULL OR ru.referred_by_store IS NOT NULL
     GROUP BY coalesce(ru.referral_source, 'unknown')
  ),
  store_geo_ok AS (
    SELECT s.id
      FROM users s
     WHERE s.deleted_at IS NULL
       AND (
            (p_region IS NULL AND p_city IS NULL AND p_location IS NULL)
         OR EXISTS (SELECT 1 FROM store_branches sb
                     WHERE sb.merchant_id = s.id AND sb.is_active IS NOT FALSE
                       AND (p_region   IS NULL OR sb.region_id   = p_region)
                       AND (p_city     IS NULL OR sb.city_id     = p_city)
                       AND (p_location IS NULL OR sb.location_id = p_location))
         OR EXISTS (SELECT 1 FROM deals d
                     WHERE d.store_id = s.id
                       AND (p_region   IS NULL OR d.region      = p_region)
                       AND (p_city     IS NULL OR d.city        = p_city)
                       AND (p_location IS NULL OR d.location_id = p_location))
       )
  ),
  board AS (
    SELECT s.id AS store_id,
           coalesce(s.shop, s.name) AS shop,
           s.referral_code,
           count(ru.id) AS refs,
           count(ru.id) FILTER (WHERE ru.user_type = 'seller') AS seller_refs
      FROM users s
      JOIN ref_users ru ON ru.referred_by_store = s.id
     WHERE s.id IN (SELECT sg.id FROM store_geo_ok sg)
     GROUP BY s.id, coalesce(s.shop, s.name), s.referral_code
     ORDER BY count(ru.id) DESC
     LIMIT v_limit
  )
  SELECT jsonb_build_object(
    'total_referred', (SELECT count(*) FROM ref_users ru2 WHERE ru2.referred_by_store IS NOT NULL),
    'sources', coalesce((SELECT jsonb_agg(jsonb_build_object('source', sr.source, 'count', sr.n) ORDER BY sr.n DESC) FROM src sr), '[]'::jsonb),
    'stores', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'store_id', b.store_id, 'shop', b.shop, 'code', b.referral_code,
        'refs', b.refs, 'seller_refs', b.seller_refs) ORDER BY b.refs DESC) FROM board b), '[]'::jsonb)
  ) INTO v;
  RETURN v;
END $$;


--
-- Name: admin_remove_sponsor(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_remove_sponsor(p_store_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_id TEXT;
BEGIN
    v_caller_id := auth.uid()::text;
    IF NOT public.is_admin(v_caller_id) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    DELETE FROM public.sponsors WHERE store_id = p_store_id;
    UPDATE public.store_profiles sp SET is_pinned = FALSE, updated_at = NOW()
     WHERE sp.store_id = p_store_id;

    RETURN jsonb_build_object('success', TRUE, 'store_id', p_store_id);
END $$;


--
-- Name: admin_reports_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reports_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT jsonb_build_object(
    'reports', jsonb_build_object(
      'open',     (SELECT count(*) FROM public.reports WHERE status = 'open'),
      'review',   (SELECT count(*) FROM public.reports WHERE status = 'under_review'),
      'resolved', (SELECT count(*) FROM public.reports WHERE status = 'resolved'),
      'total',    (SELECT count(*) FROM public.reports)),
    'complaints', jsonb_build_object(
      'open',     (SELECT count(*) FROM public.complaints WHERE status = 'open'),
      'review',   (SELECT count(*) FROM public.complaints WHERE status = 'reviewing'),
      'resolved', (SELECT count(*) FROM public.complaints WHERE status = 'resolved'),
      'total',    (SELECT count(*) FROM public.complaints))
  ) INTO v;
  RETURN v;
END $$;


--
-- Name: admin_reset_contest_winners(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reset_contest_winners(p_contest_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.is_admin() then raise exception 'forbidden: admin only'; end if;
  update contest_entries set is_winner = false where contest_id = p_contest_id;
  update contests set status = 'closed', updated_at = now()
    where id = p_contest_id and status = 'drawn';
  return jsonb_build_object('success', true);
end; $$;


--
-- Name: admin_resolve_store_name(text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_resolve_store_name(p_id text, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r public.store_name_requests%ROWTYPE; v_msg text;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT * INTO r FROM public.store_name_requests WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;
  IF r.status <> 'requested' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ALREADY_DECIDED', 'status', r.status);
  END IF;

  IF p_approve THEN
    -- المشغّل على `users.shop` ينشر الاسم على كل عروض المتجر تلقائياً.
    UPDATE public.users SET shop = r.wanted_name WHERE id = r.store_id;
    v_msg := '✅ اعتُمد اسم متجرك الجديد: ' || r.wanted_name;
  ELSE
    v_msg := '❌ لم يُعتمد تغيير اسم متجرك إلى «' || r.wanted_name || '»'
             || CASE WHEN COALESCE(btrim(p_note),'') <> '' THEN ' — ' || btrim(p_note) ELSE '' END || '.';
  END IF;

  UPDATE public.store_name_requests
     SET status = CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,
         admin_note = NULLIF(btrim(COALESCE(p_note,'')), ''),
         admin_id = auth.uid()::text, decided_at = now()
   WHERE id = p_id;

  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (r.store_id, CASE WHEN p_approve THEN '✅ اسم المتجر' ELSE '❌ اسم المتجر' END,
          CASE WHEN p_approve THEN '✅ Store name' ELSE '❌ Store name' END,
          v_msg, v_msg, 'system', jsonb_build_object('audience','seller'));

  RETURN jsonb_build_object('ok', true, 'approved', p_approve);
END $$;


--
-- Name: admin_retention_curve(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_retention_curve(p_months_back integer DEFAULT 6) RETURNS TABLE(cohort_month text, cohort_label text, cohort_size integer, d1_pct numeric, d7_pct numeric, d30_pct numeric, d60_pct numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH cohorts AS (
        SELECT u.id AS user_id,
               date_trunc('month', u.created_at) AS cohort_m,
               u.created_at
        FROM users u
        WHERE u.user_type = 'buyer'
          AND u.created_at >= date_trunc('month', now()) - ((p_months_back - 1) || ' months')::INTERVAL
          AND COALESCE(u.is_suspended, FALSE) = FALSE
          AND u.deleted_at IS NULL
    ),
    activity_after AS (
        SELECT c.user_id, c.cohort_m, c.created_at,
               BOOL_OR(al.created_at BETWEEN c.created_at + INTERVAL '1 day'  AND c.created_at + INTERVAL '2 days')  AS d1,
               BOOL_OR(al.created_at BETWEEN c.created_at + INTERVAL '7 days' AND c.created_at + INTERVAL '8 days')  AS d7,
               BOOL_OR(al.created_at BETWEEN c.created_at + INTERVAL '30 days' AND c.created_at + INTERVAL '31 days') AS d30,
               BOOL_OR(al.created_at BETWEEN c.created_at + INTERVAL '60 days' AND c.created_at + INTERVAL '61 days') AS d60
        FROM cohorts c
        LEFT JOIN activity_log al ON al.user_id = c.user_id
        GROUP BY c.user_id, c.cohort_m, c.created_at
    )
    SELECT to_char(cohort_m, 'YYYY-MM')::TEXT,
           to_char(cohort_m, 'Mon YY')::TEXT,
           COUNT(*)::INT,
           CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE d1) / COUNT(*), 1) END,
           CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE d7) / COUNT(*), 1) END,
           CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE d30) / COUNT(*), 1) END,
           CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE d60) / COUNT(*), 1) END
    FROM activity_after
    GROUP BY cohort_m
    ORDER BY cohort_m ASC;
END;
$$;


--
-- Name: admin_revenue_forecast(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_revenue_forecast() RETURNS TABLE(monthly_expected numeric, paying_sellers integer, free_sellers integer, trial_sellers integer, expires_7d integer, expires_30d integer, avg_arpu numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_monthly NUMERIC;
    v_paying INT;
    v_free INT;
    v_trial INT;
    v_exp7 INT;
    v_exp30 INT;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;

    SELECT COALESCE(SUM(sp.subscription_amount * (1 - COALESCE(sp.discount_percentage, 0) / 100.0)), 0),
           COUNT(*)
      INTO v_monthly, v_paying
    FROM store_profiles sp
    JOIN users u ON u.id = sp.store_id
    WHERE sp.subscription_plan = 'premium'
      AND COALESCE(sp.is_suspended, FALSE) = FALSE
      AND COALESCE(u.is_suspended, FALSE) = FALSE
      AND u.user_type = 'seller';

    SELECT COUNT(*) INTO v_free
    FROM store_profiles sp
    JOIN users u ON u.id = sp.store_id
    WHERE u.user_type = 'seller'
      AND COALESCE(u.is_suspended, FALSE) = FALSE
      AND (sp.subscription_plan IS NULL OR sp.subscription_plan = 'free');

    SELECT COUNT(*) INTO v_trial
    FROM store_profiles sp
    JOIN users u ON u.id = sp.store_id
    WHERE u.user_type = 'seller'
      AND COALESCE(u.is_suspended, FALSE) = FALSE
      AND sp.subscription_plan = 'trial';

    SELECT COUNT(*) INTO v_exp7
    FROM store_profiles
    WHERE subscription_plan = 'premium'
      AND subscription_expires_at IS NOT NULL
      AND subscription_expires_at BETWEEN now() AND now() + INTERVAL '7 days';

    SELECT COUNT(*) INTO v_exp30
    FROM store_profiles
    WHERE subscription_plan = 'premium'
      AND subscription_expires_at IS NOT NULL
      AND subscription_expires_at BETWEEN now() AND now() + INTERVAL '30 days';

    RETURN QUERY SELECT
        v_monthly,
        v_paying,
        v_free,
        v_trial,
        v_exp7,
        v_exp30,
        CASE WHEN v_paying = 0 THEN 0 ELSE ROUND(v_monthly / v_paying, 2) END;
END;
$$;


--
-- Name: admin_search_users(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_search_users(p_query text DEFAULT ''::text, p_user_type text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id text, name text, phone text, email text, user_type text, shop text, address text, is_suspended boolean, total_bookings integer, total_spent numeric, last_active_at timestamp with time zone, created_at timestamp with time zone, subscription_plan text, subscription_expires_at timestamp with time zone, subscription_amount numeric, discount_percentage numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_role TEXT;
    v_q TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
    SELECT u.user_type INTO v_caller_role FROM users u WHERE u.id = auth.uid()::text;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    v_q := '%' || COALESCE(p_query, '') || '%';

    RETURN QUERY
    SELECT u.id, u.name, u.phone, u.email, u.user_type, u.shop, u.address,
           COALESCE(u.is_suspended, FALSE),
           (SELECT COUNT(*)::int FROM bookings b WHERE b.user_id = u.id),
           -- v14.33 — `u.total_spent` عمودٌ ميّت: DEFAULT 0 ولا يكتبه أحد في
           -- المنصّة كلها (قِيس: صفر لكل الحسابات). فبطاقة المشتري كانت تقول
           -- «٠ ر.س مصروفة» مهما أنفق، ومرشّح «الأكثر إنفاقاً» يرتّب بقيمة
           -- ثابتة فلا يرتّب. المصدر الصحيح هو الإجمالي المُجمَّد على الحجز.
           public.taki_user_spend(u.id),
           u.last_active_at, u.created_at,
           sp.subscription_plan,
           sp.subscription_expires_at,
           sp.subscription_amount,
           sp.discount_percentage::numeric
    FROM users u
    LEFT JOIN store_profiles sp ON sp.store_id = u.id
    WHERE (u.deleted_at IS NULL)
      AND (
        p_user_type IS NULL
        OR u.user_type = p_user_type
        OR (p_user_type = 'buyer' AND u.user_type <> 'seller'
            AND EXISTS (SELECT 1 FROM bookings b WHERE b.user_id = u.id))
      )
      AND (
        p_query = '' OR
        u.name  ILIKE v_q OR
        u.phone ILIKE v_q OR
        u.email ILIKE v_q OR
        u.shop  ILIKE v_q OR
        u.address ILIKE v_q
      )
    ORDER BY u.created_at DESC
    LIMIT p_limit OFFSET p_offset;
END $$;


--
-- Name: admin_set_booking_ban(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_booking_ban(p_user_id text, p_days integer, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_msg text;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  IF p_days IS NULL OR p_days <= 0 THEN
    UPDATE users SET booking_banned_until = NULL, booking_ban_reason = NULL WHERE id = p_user_id;
    INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (p_user_id, '✅ رفع تعليق الحجز', '✅ Booking ban lifted',
            'تم رفع تعليق الحجز عن حسابك — يمكنك الحجز الآن.', 'Your booking ban was lifted.', 'system',
            jsonb_build_object('audience', 'user'));
    RETURN jsonb_build_object('success', true, 'cleared', true);
  END IF;
  v_msg := format('⏸️ تم تعليق الحجز على حسابك لمدة %s أيام%s.', p_days,
                  CASE WHEN COALESCE(TRIM(p_reason), '') <> '' THEN ' — السبب: ' || TRIM(p_reason) ELSE '' END);
  UPDATE users SET booking_banned_until = now() + make_interval(days => p_days),
                   booking_ban_reason = COALESCE(NULLIF(TRIM(p_reason), ''), 'قرار إداري')
   WHERE id = p_user_id;
  INSERT INTO user_warnings (user_id, user_role, reason, admin_id)
  VALUES (p_user_id, (SELECT user_type FROM users WHERE id = p_user_id), v_msg, auth.uid()::text);
  INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (p_user_id, '⏸️ تعليق الحجز', '⏸️ Booking suspended', v_msg, v_msg, 'system',
          jsonb_build_object('audience', 'user', 'admin_warning', TRUE));
  RETURN jsonb_build_object('success', true, 'until', now() + make_interval(days => p_days));
END $$;


--
-- Name: admin_set_complaint_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_complaint_status(p_id uuid, p_status text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_role TEXT;
    v_caller TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
    v_caller := auth.uid()::text;
    SELECT u.user_type INTO v_role FROM public.users u WHERE u.id = v_caller;
    IF v_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;
    IF p_status NOT IN ('open','reviewing','resolved','dismissed') THEN
        RAISE EXCEPTION 'Bad status';
    END IF;
    UPDATE public.complaints
       SET status = p_status,
           admin_note = COALESCE(p_note, admin_note),
           resolved_by = CASE WHEN p_status IN ('resolved','dismissed') THEN v_caller ELSE resolved_by END,
           resolved_at = CASE WHEN p_status IN ('resolved','dismissed') THEN NOW() ELSE resolved_at END
     WHERE id = p_id;
    RETURN jsonb_build_object('success', TRUE);
END $$;


--
-- Name: admin_set_flag_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_flag_status(p_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_status NOT IN ('open','reviewed') THEN RAISE EXCEPTION 'bad status'; END IF;
  UPDATE moderation_flags SET status = p_status WHERE id = p_id;
END $$;


--
-- Name: admin_set_gateway_blocked(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_gateway_blocked(p_merchant_id text, p_blocked boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF;
  UPDATE public.merchant_gateways
  SET disabled_by_admin = p_blocked, updated_at = now()
  WHERE merchant_id = p_merchant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NO_GATEWAY'; END IF;
  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (auth.uid()::text, 'admin',
          CASE WHEN p_blocked THEN 'gateway_admin_blocked' ELSE 'gateway_admin_unblocked' END,
          'merchant_gateway', p_merchant_id, '{}'::jsonb);
  INSERT INTO public.notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES ('ntf_gwadm_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
          p_merchant_id,
          CASE WHEN p_blocked THEN '⛔️ تم إيقاف بوابة الدفع لمتجرك' ELSE '✅ أُعيد تفعيل بوابة الدفع لمتجرك' END,
          CASE WHEN p_blocked THEN 'Your payment gateway was suspended' ELSE 'Your payment gateway was re-enabled' END,
          CASE WHEN p_blocked THEN 'أوقفت الإدارة خاصية الدفع الإلكتروني لمتجرك مؤقتاً — منتجاتك تعود تلقائياً للدفع عند الاستلام. تواصل مع الإدارة للتفاصيل.'
               ELSE 'أعادت الإدارة تفعيل الدفع الإلكتروني لمتجرك.' END,
          CASE WHEN p_blocked THEN 'The platform temporarily suspended online payment for your store — your products fall back to pay-on-pickup automatically.'
               ELSE 'Online payment for your store has been re-enabled.' END,
          'system', jsonb_build_object('audience', 'seller'));
END $$;


--
-- Name: admin_set_permissions(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_permissions(target_id text, perms text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'forbidden: super admin required';
  END IF;
  IF target_id IS NULL OR target_id = '' THEN
    RAISE EXCEPTION 'target_id required';
  END IF;
  IF EXISTS (SELECT 1 FROM public.users u WHERE u.id = target_id AND u.is_super_admin = TRUE) THEN
    RAISE EXCEPTION 'cannot modify super admin permissions';
  END IF;
  UPDATE public.users u
  SET admin_permissions = COALESCE(perms, '{}'::TEXT[])
  WHERE u.id = target_id AND u.user_type = 'admin';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target is not a staff admin';
  END IF;
END;
$$;


