--
-- Name: admin_set_sponsor(text, boolean, text, text, text, double precision, double precision, double precision, integer, timestamp with time zone, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_sponsor(p_store_id text, p_is_active boolean DEFAULT true, p_target_category text DEFAULT NULL::text, p_target_city text DEFAULT NULL::text, p_target_region text DEFAULT NULL::text, p_target_lat double precision DEFAULT NULL::double precision, p_target_lng double precision DEFAULT NULL::double precision, p_target_radius_km double precision DEFAULT NULL::double precision, p_priority integer DEFAULT 0, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text, p_label_type text DEFAULT 'ad'::text, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_id TEXT;
    v_store_name TEXT;
    v_was_active BOOLEAN;
    v_label TEXT;
    v_start TIMESTAMPTZ;
BEGIN
    v_caller_id := auth.uid()::text;
    IF NOT public.is_admin(v_caller_id) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    v_label := lower(COALESCE(NULLIF(TRIM(p_label_type), ''), 'ad'));
    IF v_label NOT IN ('ad','sponsor','none','star') THEN v_label := 'ad'; END IF;
    v_start := COALESCE(p_starts_at, NOW());

    -- Validate the window: start must be before expiry (if expiry given).
    IF p_expires_at IS NOT NULL AND v_start >= p_expires_at THEN
        RAISE EXCEPTION 'Start date must be before expiry date';
    END IF;

    SELECT u.name INTO v_store_name FROM public.users u WHERE u.id = p_store_id;
    IF v_store_name IS NULL THEN
        RAISE EXCEPTION 'Store not found: %', p_store_id;
    END IF;

    SELECT s.is_active INTO v_was_active FROM public.sponsors s WHERE s.store_id = p_store_id;

    INSERT INTO public.sponsors (
        store_id, is_active, target_category, target_city, target_region,
        target_lat, target_lng, target_radius_km, priority, starts_at, expires_at,
        notes, label_type, created_by, updated_at
    ) VALUES (
        p_store_id, COALESCE(p_is_active, TRUE),
        NULLIF(TRIM(COALESCE(p_target_category, '')), ''),
        NULLIF(TRIM(COALESCE(p_target_city, '')), ''),
        NULLIF(TRIM(COALESCE(p_target_region, '')), ''),
        p_target_lat, p_target_lng, p_target_radius_km,
        COALESCE(p_priority, 0), v_start, p_expires_at, p_notes, v_label, v_caller_id, NOW()
    )
    ON CONFLICT (store_id) DO UPDATE SET
        is_active        = COALESCE(p_is_active, TRUE),
        target_category  = NULLIF(TRIM(COALESCE(p_target_category, '')), ''),
        target_city      = NULLIF(TRIM(COALESCE(p_target_city, '')), ''),
        target_region    = NULLIF(TRIM(COALESCE(p_target_region, '')), ''),
        target_lat       = p_target_lat,
        target_lng       = p_target_lng,
        target_radius_km = p_target_radius_km,
        priority         = COALESCE(p_priority, 0),
        starts_at        = v_start,
        expires_at       = p_expires_at,
        notes            = p_notes,
        label_type       = v_label,
        updated_at       = NOW();

    UPDATE public.store_profiles sp
       SET is_pinned = COALESCE(p_is_active, TRUE), updated_at = NOW()
     WHERE sp.store_id = p_store_id;
    IF NOT FOUND THEN
        INSERT INTO public.store_profiles (store_id, is_pinned, updated_at)
        VALUES (p_store_id, COALESCE(p_is_active, TRUE), NOW())
        ON CONFLICT (store_id) DO UPDATE SET is_pinned = EXCLUDED.is_pinned, updated_at = NOW();
    END IF;

    IF COALESCE(p_is_active, TRUE) AND COALESCE(v_was_active, FALSE) IS DISTINCT FROM TRUE THEN
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
        VALUES (
            p_store_id,
            '🌟 أصبحت راعياً رسمياً في تاكي',
            '🌟 You are now an Official Sponsor on TAKI',
            'تهانينا! متجرك الآن راعٍ رسمي — تظهر منتجاتك كإعلانات مميزة بإطار ذهبي ضمن العروض' ||
                COALESCE(' حتى ' || to_char(p_expires_at, 'YYYY-MM-DD'), '') || '.',
            'Congratulations! Your store is now an official sponsor — your deals appear as featured gold ads' ||
                COALESCE(' until ' || to_char(p_expires_at, 'YYYY-MM-DD'), '') || '.',
            'system',
            jsonb_build_object('audience', 'user', 'sponsor', TRUE)
        );
    END IF;

    RETURN jsonb_build_object('success', TRUE, 'store_id', p_store_id, 'store_name', v_store_name, 'label_type', v_label);
END $$;


--
-- Name: admin_soft_delete_user(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_soft_delete_user(p_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_role TEXT;
    v_caller_id TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
    v_caller_id := auth.uid()::text;
    SELECT user_type INTO v_caller_role FROM users WHERE id = v_caller_id;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    UPDATE users SET is_suspended = TRUE, updated_at = NOW() WHERE id = p_user_id;
    UPDATE deals SET status = 'deleted' WHERE store_id = p_user_id;

    INSERT INTO activity_log (user_id, user_type, action, entity_type, entity_id)
    VALUES (v_caller_id, 'admin', 'admin_soft_delete_user', 'user', p_user_id);

    RETURN jsonb_build_object('success', true);
END $$;


--
-- Name: admin_subscription_growth(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_subscription_growth(p_months integer DEFAULT 12) RETURNS TABLE(month_key text, month_label text, new_subs integer, churned_subs integer, net_change integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH months AS (
        SELECT date_trunc('month', now()) - (n || ' months')::INTERVAL AS m
        FROM generate_series(0, GREATEST(p_months, 1) - 1) AS n
    ),
    news AS (
        SELECT date_trunc('month', created_at) AS m, COUNT(*) AS cnt
        FROM merchant_subscriptions
        WHERE created_at >= date_trunc('month', now()) - ((p_months - 1) || ' months')::INTERVAL
        GROUP BY 1
    ),
    churns AS (
        SELECT date_trunc('month', updated_at) AS m, COUNT(*) AS cnt
        FROM merchant_subscriptions
        WHERE status = 'cancelled'
          AND updated_at >= date_trunc('month', now()) - ((p_months - 1) || ' months')::INTERVAL
        GROUP BY 1
    )
    SELECT to_char(months.m, 'YYYY-MM')::TEXT,
           to_char(months.m, 'Mon YY')::TEXT,
           COALESCE(news.cnt, 0)::INT,
           COALESCE(churns.cnt, 0)::INT,
           (COALESCE(news.cnt, 0) - COALESCE(churns.cnt, 0))::INT
    FROM months
    LEFT JOIN news   ON news.m   = months.m
    LEFT JOIN churns ON churns.m = months.m
    ORDER BY months.m ASC;
END;
$$;


--
-- Name: admin_subscription_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_subscription_lifecycle() RETURNS TABLE(status text, cnt integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
