$$;


--
-- Name: bot_pull_email_outbox(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_pull_email_outbox(p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN '[]'::jsonb; END IF;
  -- a crashed sender must not strand rows in 'sending'
  UPDATE email_outbox SET status = 'pending'
   WHERE status = 'sending' AND picked_at < now() - interval '10 minutes';
  -- a backlog older than 48h is stale news — never flood on late SMTP setup
  UPDATE email_outbox SET status = 'expired'
   WHERE status = 'pending' AND created_at < now() - interval '48 hours';
  WITH picked AS (
    SELECT id FROM email_outbox
    WHERE status = 'pending' AND attempts < 5
    ORDER BY created_at ASC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit,10), 25))
    FOR UPDATE SKIP LOCKED
  ),
  upd AS (
    UPDATE email_outbox e
       SET status = 'sending', picked_at = now(), attempts = e.attempts + 1
      FROM picked WHERE e.id = picked.id
    RETURNING e.id, e.to_email, e.subject, e.html, e.event, e.created_at
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', id, 'to_email', to_email, 'subject', subject, 'html', html, 'event', event
  ) ORDER BY created_at ASC) INTO v FROM upd;
  RETURN COALESCE(v, '[]'::jsonb);
END $$;


--
-- Name: bot_pull_outbox(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_pull_outbox(p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN '[]'::jsonb; END IF;
  WITH picked AS (
    SELECT n.id FROM public.notifications n
    WHERE n.bot_pushed_at IS NULL AND n.created_at > now() - interval '2 days'
    ORDER BY n.created_at ASC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit,25), 50))
    FOR UPDATE SKIP LOCKED
  ),
  upd AS (
    UPDATE public.notifications n SET bot_pushed_at = now()
    FROM picked WHERE n.id = picked.id
    RETURNING n.id, n.user_id, n.type, n.title_ar, n.title_en, n.body_ar, n.body_en, n.meta_data, n.created_at
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', upd.id, 'user_id', upd.user_id, 'type', upd.type,
    'title_ar', upd.title_ar, 'title_en', upd.title_en,
    'body_ar', upd.body_ar, 'body_en', upd.body_en, 'meta_data', upd.meta_data,
    'telegram_chat_id', u.telegram_chat_id, 'notify_via_telegram', COALESCE(u.notify_via_telegram, true),
    'whatsapp_chat_id', u.whatsapp_chat_id, 'notify_via_whatsapp', COALESCE(u.notify_via_whatsapp, false),
    'preferred_lang', u.preferred_lang
  ) ORDER BY upd.created_at ASC)
  INTO v FROM upd JOIN public.users u ON u.id = upd.user_id;
  RETURN COALESCE(v, '[]'::jsonb);
END; $$;


--
-- Name: bot_rate_store(bigint, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_rate_store(p_telegram_id bigint, p_barcode text, p_score integer, p_comment text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text; v_name text; v_b bookings%ROWTYPE; v_store text;
BEGIN
  SELECT id, COALESCE(name,'مشتري') INTO v_uid, v_name FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF p_score < 1 OR p_score > 5 THEN RETURN jsonb_build_object('success',false,'error','bad_score'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode=UPPER(p_barcode) AND user_id=v_uid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  IF v_b.status <> 'completed' THEN RETURN jsonb_build_object('success',false,'error','not_completed'); END IF;
  SELECT store_id INTO v_store FROM deals WHERE id = v_b.deal_id;

  IF EXISTS (SELECT 1 FROM ratings WHERE store_id=v_store AND user_id=v_uid AND deleted_at IS NULL) THEN
    UPDATE ratings SET score=p_score, comment=NULLIF(btrim(COALESCE(p_comment,'')),''), updated_at=NOW()
      WHERE store_id=v_store AND user_id=v_uid AND deleted_at IS NULL;
  ELSE
    INSERT INTO ratings (id, deal_id, user_id, user_name, score, comment)
      VALUES (gen_random_uuid()::text, v_b.deal_id, v_uid, v_name, p_score, NULLIF(btrim(COALESCE(p_comment,'')),''));
  END IF;
  RETURN jsonb_build_object('success',true,'score',p_score);
END; $$;


--
-- Name: bot_rating_status(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_rating_status(p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text, p_barcode text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text; v_b bookings%ROWTYPE; v_store text; v_shop text; v_rev ratings%ROWTYPE; v_voted boolean; v_my_vote boolean;
BEGIN
  v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok',false,'error','not_linked'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode=UPPER(p_barcode) AND user_id=v_uid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','not_found'); END IF;
  SELECT store_id, shop_name INTO v_store, v_shop FROM deals WHERE id = v_b.deal_id;
  SELECT * INTO v_rev FROM ratings WHERE store_id=v_store AND user_id=v_uid AND deleted_at IS NULL LIMIT 1;
  SELECT is_real INTO v_my_vote FROM deal_authenticity_votes WHERE deal_id=v_b.deal_id AND user_id=v_uid;
  v_voted := FOUND;
  RETURN jsonb_build_object(
    'ok', true,
    'completed', v_b.status='completed',
    'shop_name', v_shop,
    'deal_id', v_b.deal_id,
    'voted_auth', v_voted,
    'my_vote', v_my_vote,
    'prev_score', v_rev.score,
    'prev_comment', v_rev.comment
  );
END; $$;


--
-- Name: bot_remove_branch(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_remove_branch(p_telegram_id bigint, p_branch_id text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sid text; v_b store_branches%ROWTYPE; v_locked boolean;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  SELECT * INTO v_b FROM store_branches WHERE id=p_branch_id AND merchant_id=v_sid;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  SELECT EXISTS(SELECT 1 FROM deals d WHERE d.store_id=v_sid AND d.status='active' AND (
     CASE WHEN d.location_id IS NOT NULL AND d.location_id<>'other' AND d.location_id NOT LIKE 'custom~_%' ESCAPE '~'
          THEN 'loc:'||d.location_id ELSE 'geo:'||ROUND(COALESCE(d.map_lat,0)::numeric,3)::text||','||ROUND(COALESCE(d.map_lng,0)::numeric,3)::text END
     = CASE WHEN v_b.location_id IS NOT NULL AND v_b.location_id<>'other' AND v_b.location_id NOT LIKE 'custom~_%' ESCAPE '~'
          THEN 'loc:'||v_b.location_id ELSE 'geo:'||ROUND(COALESCE(v_b.map_lat,0)::numeric,3)::text||','||ROUND(COALESCE(v_b.map_lng,0)::numeric,3)::text END
  )) INTO v_locked;
  IF v_locked THEN RETURN jsonb_build_object('success',false,'error','locked'); END IF;
  UPDATE store_branches SET is_active=false, updated_at=now() WHERE id=p_branch_id AND merchant_id=v_sid;
  RETURN jsonb_build_object('success',true);
END; $$;


--
-- Name: bot_remove_notif_keyword(bigint, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_remove_notif_keyword(p_telegram_id bigint, p_index integer, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text; v_list text[];
BEGIN
  SELECT id, COALESCE(notif_keywords, ARRAY[]::text[]) INTO v_uid, v_list
    FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  IF p_index < 0 OR p_index >= COALESCE(array_length(v_list, 1), 0) THEN
    RETURN jsonb_build_object('success', false, 'error', 'bad_index', 'keywords', to_jsonb(v_list));
  END IF;
  v_list := v_list[1:p_index] || v_list[p_index+2:COALESCE(array_length(v_list,1),0)];
  UPDATE users SET notif_keywords = v_list WHERE id = v_uid;
  RETURN jsonb_build_object('success', true, 'keywords', to_jsonb(COALESCE(v_list, ARRAY[]::text[])));
END; $$;


--
-- Name: bot_remove_smart_alert(bigint, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_remove_smart_alert(p_telegram_id bigint, p_index integer, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text; v_arr jsonb;
BEGIN
  SELECT id, smart_alerts INTO v_uid, v_arr FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF v_arr IS NULL OR jsonb_typeof(v_arr) <> 'array' THEN v_arr := '[]'::jsonb; END IF;
  IF p_index < 0 OR p_index >= jsonb_array_length(v_arr) THEN RETURN jsonb_build_object('success',false,'error','bad_index'); END IF;
  v_arr := v_arr - p_index;
  UPDATE users SET smart_alerts=v_arr, updated_at=NOW() WHERE id=v_uid;
  RETURN jsonb_build_object('success',true,'count',jsonb_array_length(v_arr));
END; $$;


--
-- Name: bot_report(bigint, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_report(p_telegram_id bigint, p_store_id text, p_type text, p_reason text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text; v_reason text;
BEGIN
  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  v_reason := btrim(coalesce(p_reason,''));
  IF length(v_reason) < 5 THEN RETURN jsonb_build_object('success',false,'error','short_reason'); END IF;
  IF p_store_id IS NULL OR NOT EXISTS(SELECT 1 FROM users WHERE id=p_store_id) THEN
    RETURN jsonb_build_object('success',false,'error','bad_target'); END IF;
  BEGIN
    INSERT INTO reports (reporter_id, reported_id, report_type, reason)
    VALUES (v_uid, p_store_id,
            COALESCE(NULLIF(btrim(p_type),''),'other'),
            left(v_reason,1000));
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM LIKE '%SELF_REPORT%'  THEN RETURN jsonb_build_object('success',false,'error','self');
    ELSIF SQLERRM LIKE '%SAME_ROLE%' THEN RETURN jsonb_build_object('success',false,'error','same_role');
    ELSE RETURN jsonb_build_object('success',false,'error','blocked','detail',SQLERRM); END IF;
  END;
  RETURN jsonb_build_object('success',true);
END; $$;


--
-- Name: bot_report_email_status(boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_report_email_status(p_configured boolean, p_from text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN; END IF;
  INSERT INTO platform_settings (key, value, description)
  VALUES ('email_sender_status',
          jsonb_build_object('configured', COALESCE(p_configured,false), 'from', COALESCE(p_from,''), 'updated_at', now()),
          'حالة مرسل الإيميل — يكتبها سيرفر البوت تلقائياً (v12.27)')
  ON CONFLICT (key) DO UPDATE
    SET value = EXCLUDED.value, updated_at = now();
END $$;


--
-- Name: bot_report_gate(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_report_gate(p_version text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_hdr text; v_which text;
BEGIN
  IF NOT public._bot_gate_ok() THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;
  v_hdr := current_setting('request.headers', true)::json ->> 'x-bot-secret';
  SELECT CASE key WHEN 'bot_gateway_secret_next' THEN 'next' ELSE 'current' END
    INTO v_which
  FROM public.app_secrets
  WHERE key IN ('bot_gateway_secret', 'bot_gateway_secret_next') AND value = v_hdr
  LIMIT 1;

  INSERT INTO public.bot_gate_usage (id, which, seen_at, bot_version)
  VALUES (1, COALESCE(v_which, 'unknown'), now(), p_version)
  ON CONFLICT (id) DO UPDATE
    SET which = EXCLUDED.which, seen_at = EXCLUDED.seen_at, bot_version = EXCLUDED.bot_version;

  RETURN jsonb_build_object('success', true, 'using', COALESCE(v_which, 'unknown'));
END $$;


--
-- Name: bot_request_booking_refund(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_request_booking_refund(p_telegram_id bigint, p_barcode text, p_reason text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid text; v_b public.bookings%ROWTYPE; v_amt numeric; v_shop text; v_cur public.booking_refunds%ROWTYPE;
BEGIN
  SELECT id INTO v_uid FROM public.users
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND OR v_b.user_id <> v_uid THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  IF v_b.paid_at IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_paid'); END IF;

  SELECT * INTO v_cur FROM public.booking_refunds WHERE barcode = v_b.barcode;
  IF FOUND AND v_cur.status IN ('requested','approved','refunded') THEN
    RETURN jsonb_build_object('success', true, 'already', true, 'status', v_cur.status);
  END IF;

  v_amt := round(COALESCE(NULLIF(v_b.paid_amount, 0), v_b.total_amount, 0), 2);
  INSERT INTO public.booking_refunds (barcode, store_id, buyer_id, status, opened_by, amount, reason)
  VALUES (v_b.barcode, v_b.store_id, v_b.user_id, 'requested', 'buyer', v_amt,
          NULLIF(left(btrim(COALESCE(p_reason,'')), 600), ''))
  ON CONFLICT (barcode) DO UPDATE
    SET status='requested', opened_by='buyer', amount=EXCLUDED.amount, reason=EXCLUDED.reason,
        requested_at=now(), decided_at=NULL, decided_by=NULL, merchant_note=NULL, updated_at=now();

  SELECT COALESCE(NULLIF(u.shop,''), u.name) INTO v_shop FROM public.users u WHERE u.id = v_b.store_id;
  PERFORM public._refund_notify(v_b.store_id,
    '↩️ طلب إلغاء واسترداد', 'Refund request',
    'طلب المشتري إلغاء الطلب ' || v_b.barcode || ' واسترداد ' || trim(to_char(v_amt,'FM999999990.09')) || ' ر.س. القرار لك وفق سياستك المعلنة.',
    'The buyer asked to cancel order ' || v_b.barcode || ' and be refunded ' || trim(to_char(v_amt,'FM999999990.09')) || ' SAR.',
    v_b.barcode, 'seller', 'refund_requested');
  PERFORM public._refund_notify(v_b.user_id,
    '↩️ وصل طلبك للتاجر', 'Your request was sent',
    'أرسلنا طلبك للطلب ' || v_b.barcode || ' إلى «' || COALESCE(v_shop,'المتجر') || '». القرار والتنفيذ عليه — تاكي وسيط لا تحتفظ بالمال ولا تبتّ فيه.',
    'Your request for order ' || v_b.barcode || ' was sent to "' || COALESCE(v_shop,'the store') || '".',
    v_b.barcode, 'buyer', 'refund_requested');

  RETURN jsonb_build_object('success', true, 'status', 'requested', 'amount', v_amt);
END
$$;


--
-- Name: bot_save_branch(bigint, text, text, text, text, text, double precision, double precision, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_save_branch(p_telegram_id bigint, p_branch_id text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_location_id text DEFAULT NULL::text, p_map_lat double precision DEFAULT NULL::double precision, p_map_lng double precision DEFAULT NULL::double precision, p_google_maps_link text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sid text; v_id text; v_name text; v_clean text;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  v_clean := NULLIF(btrim(COALESCE(p_name,'')),'');
  BEGIN
    IF p_branch_id IS NOT NULL THEN
      UPDATE store_branches SET
        name_ar=COALESCE(v_clean, name_ar),
        region_id=COALESCE(p_region,region_id), city_id=COALESCE(p_city,city_id),
        location_id=COALESCE(p_location_id,location_id), map_lat=COALESCE(p_map_lat,map_lat),
        map_lng=COALESCE(p_map_lng,map_lng), google_maps_link=COALESCE(p_google_maps_link,google_maps_link),
        is_active=true, updated_at=now()
      WHERE id=p_branch_id AND merchant_id=v_sid
      RETURNING name_ar INTO v_name;
      IF v_name IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
      v_id := p_branch_id;
    ELSE
      v_name := COALESCE(v_clean, 'موقع');
      INSERT INTO store_branches (merchant_id, name_ar, region_id, city_id, location_id, map_lat, map_lng, google_maps_link, is_active)
      VALUES (v_sid, v_name, p_region, p_city, p_location_id, p_map_lat, p_map_lng, p_google_maps_link, true)
      RETURNING id INTO v_id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM LIKE '%LOCATION_LIMIT_EXCEEDED%' THEN
      RETURN jsonb_build_object('success', false, 'error', 'location_limit');
    END IF;
    RAISE;
  END;
  RETURN jsonb_build_object('success',true,'id',v_id,'name',v_name);
END; $$;


--
-- Name: bot_search(text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_search(p_query text, p_limit integer DEFAULT 8, p_categories text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_q     text    := btrim(coalesce(p_query,''));
  v_norm  text;
  v_now   bigint  := (extract(epoch from now())*1000)::bigint;
  v_lim   integer := least(greatest(coalesce(p_limit,8),1),12);
  v_pat   text;
  v_ts    tsquery;
  v_deals jsonb;
  v_stores jsonb;
BEGIN
  IF length(v_q) < 2 THEN
    RETURN jsonb_build_object('deals','[]'::jsonb,'stores','[]'::jsonb,'q',v_q);
  END IF;

  v_norm := public.taki_norm(v_q);
  IF v_norm IS NULL THEN
    RETURN jsonb_build_object('deals','[]'::jsonb,'stores','[]'::jsonb,'q',v_q);
  END IF;
  v_pat := '%'||v_norm||'%';
  SELECT to_tsquery('simple', string_agg(quote_literal(t)||':*',' & ')) INTO v_ts
    FROM unnest(string_to_array(v_norm,' ')) AS t WHERE t <> '';

  WITH geo_ids AS (
    SELECT id FROM regions   WHERE public.taki_norm(name) LIKE v_pat
    UNION SELECT id FROM cities    WHERE public.taki_norm(name) LIKE v_pat
    UNION SELECT id FROM locations WHERE public.taki_norm(name) LIKE v_pat
  ),
  cat_keys AS (
    SELECT key FROM (VALUES
      ('فساتين','Fashion_Women'),('نساء','Fashion_Women'),('رجالية','Fashion_Men'),('ملابس رجال','Fashion_Men'),
      ('رضع','Kids_Infants'),('حمل','Kids_Infants'),('اطفال','Kids_Girls'),
      ('الكترونيات','Electronics'),('جوال','Electronics'),('مطاعم','Food'),('مطعم','Food'),
      ('عطور','Beauty'),('تجميل','Beauty'),('صالون رجالي','MensSalon'),('صالون نسائي','WomensSalon'),
      ('رياضة','Sports'),('سوبرماركت','Supermarket'),('بقالة','Supermarket'),('ملحمة','Butcher'),('لحم','Butcher'),
      ('صحية','Sanitary'),('مقاهي','Cafe'),('مقهى','Cafe'),('كافيه','Cafe'),('قهوة','Cafe'),
      ('منزل','Home'),('ديكور','Home'),('فنادق','Hotels'),('فندق','Hotels'),('تأجير سيارات','CarRentals'),('سيارات','CarRentals'),
      ('مغسلة','Laundry'),('خياطة','MensTailor'),('مشغل','WomensTailor'),('غسيل','CarWash'),
      ('ورش','CarWorkshop'),('ملاهي','Amusements'),('نادي','Gym'),('جيم','Gym'),('مكتبة','Library'),
      ('مشاتل','Nursery'),('صيدلية','Pharmacy'),('عيادات','Clinics'),('عيادة','Clinics'),('اونلاين','Online')
    ) AS c(label,key)
    -- التطبيع أغنى عن ازدواج «اطفال/أطفال» و«الكترونيات/إلكترونيات» يدوياً
    WHERE v_norm LIKE '%'||public.taki_norm(label)||'%'
       OR public.taki_norm(label) LIKE v_pat
  ),
  m AS (
    SELECT d.*,
      coalesce(d.discount_percentage,
        round(((d.original_price-d.discounted_price)/nullif(d.original_price,0))*100)::int) AS disc_pct
    FROM deals d
    WHERE d.status='active' AND (d.starts_at IS NULL OR d.starts_at <= v_now)
      AND ( d.name_norm LIKE v_pat                     -- مطابقة داخلية («راشد» في «الراشد»)
            OR d.search_vec @@ v_ts                    -- نصّ كامل موزون (يشمل الوصف)
            OR v_norm <% d.name_norm                   -- تسامح مع الأخطاء الإملائية
            OR (p_categories IS NOT NULL AND d.category = ANY(p_categories))
            OR d.region      IN (SELECT id FROM geo_ids)
            OR d.city        IN (SELECT id FROM geo_ids)
            OR d.location_id IN (SELECT id FROM geo_ids)
            OR d.category    IN (SELECT key FROM cat_keys) )
    ORDER BY bookings_count DESC, d.created_at DESC
    LIMIT v_lim
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id',id,'item_name',item_name,'shop_name',shop_name,'category',category,
    'original_price',original_price,'discounted_price',discounted_price,'discount_percentage',disc_pct,
    'quantity',quantity,'is_unlimited',is_unlimited,'prep_time',prep_time,'expiry_type',expiry_type,
    'expiry_date',expiry_date,'expires_in_minutes',expires_in_minutes,'starts_at',starts_at,'created_at',created_at,
    'map_lat',map_lat,'map_lng',map_lng,'google_maps_link',google_maps_link,'city',city,'region',region,
    'image',(images)[1],'images_count',coalesce(array_length(images,1),0),
    'working_hours',(SELECT working_hours FROM users u WHERE u.id=m.store_id),
    'open_status',public.store_is_open((SELECT working_hours FROM users u WHERE u.id=m.store_id)),
    'bookings_count',bookings_count,'is_sponsored',false)) INTO v_deals FROM m;

  WITH geo_ids AS (
    SELECT id FROM regions   WHERE public.taki_norm(name) LIKE v_pat
    UNION SELECT id FROM cities    WHERE public.taki_norm(name) LIKE v_pat
    UNION SELECT id FROM locations WHERE public.taki_norm(name) LIKE v_pat
  ),
  s AS (
    SELECT d.store_id, max(d.shop_name) AS shop_name, max(d.city) AS city,
           max(d.region) AS region, count(*) AS deals_n
    FROM deals d
    WHERE d.status='active' AND (d.starts_at IS NULL OR d.starts_at <= v_now)
      AND ( d.name_norm LIKE v_pat
            OR d.region      IN (SELECT id FROM geo_ids)
            OR d.city        IN (SELECT id FROM geo_ids)
            OR d.location_id IN (SELECT id FROM geo_ids) )
    GROUP BY d.store_id
    ORDER BY deals_n DESC
    LIMIT 6
  )
  SELECT jsonb_agg(jsonb_build_object('store_id',store_id,'shop_name',shop_name,
    'city',city,'region',region,'deals_n',deals_n)) INTO v_stores FROM s;

  RETURN jsonb_build_object('deals',coalesce(v_deals,'[]'::jsonb),
                            'stores',coalesce(v_stores,'[]'::jsonb),'q',v_q);
END
$$;


--
-- Name: bot_season_campaign(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_season_campaign() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
