  SELECT COALESCE((SELECT value FROM platform_settings WHERE key = 'season_campaign'), 'null'::jsonb);
$$;


--
-- Name: bot_send_booking_message(bigint, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_send_booking_message(p_telegram_id bigint, p_barcode text, p_body text, p_whatsapp_id text DEFAULT NULL::text, p_attachment_path text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid text; v_b bookings%ROWTYPE; v_role text; v_cnt int;
  v_body text := btrim(COALESCE(p_body, ''));
  v_att  text := NULLIF(btrim(COALESCE(p_attachment_path, '')), '');
BEGIN
  IF NOT public._bot_gate_ok() THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;

  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;

  -- صورةٌ بلا نصّ رسالةٌ كاملة، لكن الجدول يمنع النصّ الفارغ.
  IF v_body = '' AND v_att IS NOT NULL THEN v_body := '📎'; END IF;
  IF v_body = '' OR length(v_body) > 500 THEN
    RETURN jsonb_build_object('success', false, 'error', 'bad_body');
  END IF;

  SELECT * INTO v_b FROM bookings WHERE barcode = UPPER(p_barcode) LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  IF v_uid = v_b.user_id THEN v_role := 'buyer';
  ELSIF v_uid = v_b.store_id THEN v_role := 'seller';
  ELSE RETURN jsonb_build_object('success', false, 'error', 'not_authorized'); END IF;

  IF v_b.status IN ('cancelled','completed','expired') THEN
    RETURN jsonb_build_object('success', false, 'error', 'chat_closed');
  END IF;

  -- المرفق تحت مجلّد هذا الحجز، وموجودٌ فعلاً. (المِلكية تحقّقت منها الدالة
  -- الطرفية قبل الرفع — البوت لا يحمل هوية قاعدة بيانات ليُقارَن بها.)
  IF v_att IS NOT NULL THEN
    IF split_part(v_att, '/', 1) <> v_b.barcode THEN
      RETURN jsonb_build_object('success', false, 'error', 'attachment_outside_booking');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'chat' AND o.name = v_att) THEN
      RETURN jsonb_build_object('success', false, 'error', 'attachment_missing');
    END IF;
  END IF;

  SELECT count(*) INTO v_cnt FROM booking_messages WHERE barcode = v_b.barcode AND sender_role = v_role;
  IF v_cnt >= 3 THEN RETURN jsonb_build_object('success', false, 'error', 'limit_reached'); END IF;

  INSERT INTO booking_messages (barcode, sender_id, sender_role, body, attachment_path)
  VALUES (v_b.barcode, v_uid, v_role, v_body, v_att);

  RETURN jsonb_build_object('success', true, 'my_count', v_cnt + 1);
END $$;


--
-- Name: bot_set_deal_location(bigint, text, text, text, double precision, double precision, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_set_deal_location(p_telegram_id bigint, p_deal_id text, p_location_id text DEFAULT NULL::text, p_custom_location_name text DEFAULT NULL::text, p_map_lat double precision DEFAULT NULL::double precision, p_map_lng double precision DEFAULT NULL::double precision, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_google_maps_link text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sid text;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  IF NOT EXISTS(SELECT 1 FROM deals WHERE id=p_deal_id AND store_id=v_sid) THEN
    RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  BEGIN
    UPDATE deals SET
      location_id=p_location_id, custom_location_name=p_custom_location_name,
      map_lat=p_map_lat, map_lng=p_map_lng, region=COALESCE(p_region,region), city=COALESCE(p_city,city),
      google_maps_link=p_google_maps_link
    WHERE id=p_deal_id AND store_id=v_sid;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success',false,'error','blocked','detail',SQLERRM);
  END;
  RETURN jsonb_build_object('success',true);
END; $$;


--
-- Name: bot_set_deal_season(text, boolean, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_set_deal_season(p_deal_id text, p_on boolean DEFAULT true, p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_uid    text;
    v_camp   jsonb;
    v_season text;
BEGIN
    IF NOT public._bot_gate_ok() THEN
        RETURN jsonb_build_object('success', false, 'error', 'forbidden');
    END IF;
    v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
    IF v_uid IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_linked');
    END IF;

    IF p_on THEN
        SELECT value INTO v_camp FROM platform_settings WHERE key = 'season_campaign';
        v_season := v_camp->>'season_id';
        IF v_season IS NULL OR v_season = '' THEN
            RETURN jsonb_build_object('success', false, 'error', 'no_campaign');
        END IF;
    END IF;

    BEGIN
        UPDATE deals SET season_id = CASE WHEN p_on THEN v_season ELSE NULL END
         WHERE id = p_deal_id AND store_id = v_uid;
    EXCEPTION WHEN OTHERS THEN
        -- الحارس tr_deal_season رفض (نافذة مغلقة…) — نعيد رسالته العربية كما هي
        RETURN jsonb_build_object('success', false, 'error', 'window_closed', 'detail', SQLERRM);
    END;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_found');
    END IF;
    RETURN jsonb_build_object('success', true, 'season_id', CASE WHEN p_on THEN v_season ELSE NULL END);
END; $$;


--
-- Name: bot_set_lang(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_set_lang(p_telegram_id bigint, p_lang text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_lang text := lower(COALESCE(p_lang,'ar'));
BEGIN
  IF v_lang NOT IN ('ar','en') THEN v_lang := 'ar'; END IF;
  UPDATE public.users SET bot_lang = v_lang
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  RETURN jsonb_build_object('success', true, 'lang', v_lang);
END;
$$;


--
-- Name: bot_set_location(bigint, double precision, double precision, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_set_location(p_telegram_id bigint, p_lat double precision, p_lng double precision, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text;
BEGIN
  IF p_lat IS NULL OR p_lng IS NULL OR p_lat < -90 OR p_lat > 90 OR p_lng < -180 OR p_lng > 180 THEN
    RETURN jsonb_build_object('success', false, 'error', 'bad_coords');
  END IF;
  UPDATE users SET lat = p_lat, lng = p_lng
    WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL
    RETURNING id INTO v_uid;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  RETURN jsonb_build_object('success', true);
END; $$;


--
-- Name: bot_set_store_hours(bigint, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_set_store_hours(p_telegram_id bigint, p_hours jsonb, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user users%ROWTYPE;
BEGIN
  SELECT * INTO v_user FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  IF v_user.user_type NOT IN ('seller','admin') THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  UPDATE users SET working_hours = p_hours WHERE id = v_user.id;
  RETURN jsonb_build_object('success', true, 'working_hours', p_hours);
END; $$;


--
-- Name: bot_set_telegram_notif(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_set_telegram_notif(p_telegram_id bigint, p_enabled boolean, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text;
BEGIN
  v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  IF p_whatsapp_id IS NOT NULL THEN
    UPDATE users SET notify_via_whatsapp = COALESCE(p_enabled, true) WHERE id = v_uid AND deleted_at IS NULL;
  ELSE
    UPDATE users SET notify_via_telegram = COALESCE(p_enabled, true) WHERE id = v_uid AND deleted_at IS NULL;
  END IF;
  RETURN jsonb_build_object('success', true, 'enabled', COALESCE(p_enabled, true));
END; $$;


--
-- Name: bot_store_contact(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_store_contact(p_telegram_id bigint, p_store_id text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text; v_phone text; v_name text;
BEGIN
  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  SELECT COALESCE(NULLIF(btrim(sp.phone),''), NULLIF(btrim(u.contact_phone),''), NULLIF(btrim(u.phone),'')),
         COALESCE(NULLIF(btrim(u.shop),''), NULLIF(btrim(u.name),''),'المتجر')
    INTO v_phone, v_name
    FROM users u LEFT JOIN store_profiles sp ON sp.store_id=u.id
    WHERE u.id=p_store_id AND u.user_type='seller' LIMIT 1;
  IF v_name IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  RETURN jsonb_build_object('success',true,'phone',v_phone,'name',v_name);
END; $$;


--
-- Name: bot_submit_contest_entry(bigint, uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_submit_contest_entry(p_telegram_id bigint, p_contest_id uuid, p_answers jsonb, p_social jsonb DEFAULT '{}'::jsonb, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c record; q jsonb; v_score int := 0; v_max int := 0; v_qual boolean;
  ans text; pts int;
  correct_set jsonb; n_correct int;
  v_uid text; v_name text; v_phone text; v_role text;
BEGIN
  SELECT id, coalesce(nullif(btrim(name),''),'مشارك'), nullif(btrim(phone),''), user_type
    INTO v_uid, v_name, v_phone, v_role
  FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL  THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF v_phone IS NULL THEN RETURN jsonb_build_object('success',false,'error','no_phone'); END IF;

  SELECT * INTO c FROM contests WHERE id=p_contest_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  IF c.status<>'active' THEN RETURN jsonb_build_object('success',false,'error','not_active'); END IF;
  IF c.starts_at IS NOT NULL AND now()<c.starts_at THEN RETURN jsonb_build_object('success',false,'error','not_started'); END IF;
  IF c.ends_at   IS NOT NULL AND now()>c.ends_at   THEN RETURN jsonb_build_object('success',false,'error','ended'); END IF;

  IF v_role IS DISTINCT FROM 'admin' THEN
    IF c.audience='sellers' AND v_role IS DISTINCT FROM 'seller' THEN
      RETURN jsonb_build_object('success',false,'error','sellers_only'); END IF;
    IF c.audience='buyers'  AND v_role='seller' THEN
      RETURN jsonb_build_object('success',false,'error','buyers_only'); END IF;
  END IF;

  IF EXISTS(SELECT 1 FROM contest_entries e WHERE e.contest_id=p_contest_id AND e.phone=v_phone) THEN
    RETURN jsonb_build_object('success',false,'error','already_entered');
  END IF;

  FOR q IN SELECT * FROM jsonb_array_elements(coalesce(c.questions,'[]'::jsonb)) LOOP
    -- v12.37: multi-correct — correctAnswers[] first, legacy correctAnswer fallback
    correct_set := q->'correctAnswers';
    IF correct_set IS NULL OR jsonb_typeof(correct_set) <> 'array' THEN
      correct_set := '[]'::jsonb;
    END IF;
    IF jsonb_array_length(correct_set) = 0
       AND coalesce(btrim(q->>'correctAnswer'), '') <> '' THEN
      correct_set := jsonb_build_array(q->>'correctAnswer');
    END IF;
    SELECT count(*) INTO n_correct
      FROM jsonb_array_elements_text(correct_set) v WHERE btrim(v) <> '';
    IF n_correct > 0 THEN
      pts := coalesce(nullif(q->>'points','')::int,1);
      v_max := v_max + pts;
      ans := p_answers->>(q->>'id');
      IF ans IS NOT NULL AND EXISTS (
        SELECT 1 FROM jsonb_array_elements_text(correct_set) ca
        WHERE btrim(ca) <> '' AND lower(btrim(ca)) = lower(btrim(ans))
      ) THEN v_score := v_score + pts; END IF;
    END IF;
  END LOOP;

  v_qual := CASE c.pass_mode
    WHEN 'collect' THEN true
    WHEN 'any'     THEN (v_score>0 OR v_max=0)
    ELSE (v_score>=v_max) END;

  INSERT INTO contest_entries(contest_id,name,phone,answers,social_answers,score,max_score,qualified)
  VALUES (p_contest_id,v_name,v_phone,coalesce(p_answers,'{}'::jsonb),coalesce(p_social,'{}'::jsonb),v_score,v_max,v_qual);

  RETURN jsonb_build_object('success',true,'qualified',v_qual,'score',v_score,'max_score',v_max,'name',v_name);
END; $$;


--
-- Name: bot_subscribe_plan(bigint, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_subscribe_plan(p_telegram_id bigint, p_package_id integer, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sid text; v_pkgs jsonb; v_pkg jsonb; v_max int; v_price numeric; v_days int; v_exp timestamptz;
BEGIN
  IF NOT public.bot_payments_enabled() THEN RETURN jsonb_build_object('success',false,'error','free_mode'); END IF;
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  SELECT value INTO v_pkgs FROM platform_settings WHERE key='location_packages' LIMIT 1;
  IF v_pkgs IS NULL THEN RETURN jsonb_build_object('success',false,'error','no_packages'); END IF;
  SELECT p INTO v_pkg FROM jsonb_array_elements(v_pkgs) p
    WHERE (p->>'id')::int = p_package_id AND COALESCE((p->>'active')::boolean,true) LIMIT 1;
  IF v_pkg IS NULL THEN RETURN jsonb_build_object('success',false,'error','bad_package'); END IF;

  v_max   := COALESCE((v_pkg->>'max')::int, 1);
  v_days  := COALESCE((v_pkg->>'durationDays')::int, 30);
  v_price := round( COALESCE((v_pkg->>'price')::numeric,0) * (1 - COALESCE((v_pkg->>'discount')::numeric,0)/100), 2 );
  v_exp   := NOW() + (v_days::text || ' days')::interval;

  IF EXISTS (SELECT 1 FROM store_profiles WHERE store_id=v_sid) THEN
    UPDATE store_profiles SET
      subscription_plan='premium', subscription_started_at=NOW(), subscription_expires_at=v_exp,
      auto_renew=true, subscription_canceled_at=NULL, subscription_amount=v_price,
      max_branches=v_max, updated_at=NOW()
    WHERE store_id=v_sid;
  ELSE
    INSERT INTO store_profiles (store_id, subscription_plan, subscription_started_at, subscription_expires_at,
      auto_renew, subscription_canceled_at, subscription_amount, max_branches, updated_at)
    VALUES (v_sid, 'premium', NOW(), v_exp, true, NULL, v_price, v_max, NOW());
  END IF;

  -- سجل الدفعة → الفاتورة والإشعار عبر التريغر. v12.32: plan_id يبقى NULL —
  -- كان يُكتب فيه رقم باقة المواقع (1..8) وهو FK لجدول subscription_plans
  -- القديم الذي لا يحويها، فكان الاشتراك كاملاً يفشل بـ«تعذّر الاشتراك».
  INSERT INTO subscription_payments (merchant_id, plan_id, amount, currency, status, payment_method, gateway_provider, branches_count, period_start, period_end, paid_at, metadata)
  VALUES (v_sid, NULL, v_price, 'SAR', 'paid', 'bot', 'simulated', v_max, NOW(), v_exp, NOW(),
          jsonb_build_object(
            'source', CASE WHEN p_telegram_id IS NOT NULL THEN 'telegram' ELSE 'whatsapp' END,
            'package_id', p_package_id,
            'package_ar', v_pkg->>'ar'));

  RETURN (SELECT jsonb_build_object('success',true,'plan_ar',v_pkg->>'ar','max_branches',v_max,
        'price',v_price,'expires_at',v_exp,'days',v_days,
        /* v13.36 */
        'vat', t.vat_due, 'total', round(v_price + t.vat_due, 2))
      FROM (SELECT CASE WHEN COALESCE((s.value->>'vat_enabled')::boolean,false)
                         AND COALESCE((s.value->>'prices_include_vat')::boolean,true) = false
                   THEN round(v_price * COALESCE(NULLIF(s.value->>'vat_rate','')::numeric,15) / 100, 2)
                   ELSE 0 END AS vat_due
            FROM (SELECT value FROM platform_settings WHERE key='tax_settings'
                  UNION ALL SELECT '{}'::jsonb LIMIT 1) s) t);
END $$;


--
-- Name: bot_toggle_block(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_toggle_block(p_telegram_id bigint, p_store_id text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text; v_arr text[]; v_blocked boolean;
BEGIN
  SELECT id, COALESCE(blocked_merchants,'{}') INTO v_uid, v_arr FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF p_store_id = ANY(v_arr) THEN
    UPDATE users SET blocked_merchants = array_remove(v_arr, p_store_id) WHERE id=v_uid; v_blocked := false;
  ELSE
    UPDATE users SET blocked_merchants = array_append(v_arr, p_store_id) WHERE id=v_uid; v_blocked := true;
  END IF;
  RETURN jsonb_build_object('success',true,'blocked',v_blocked);
END; $$;


--
-- Name: bot_toggle_deal(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_toggle_deal(p_telegram_id bigint, p_deal_id text, p_status text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sid text; v_max int;
BEGIN
  IF p_status NOT IN ('active','paused') THEN RETURN jsonb_build_object('success', false, 'error', 'invalid'); END IF;
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  IF NOT EXISTS (SELECT 1 FROM deals WHERE id = p_deal_id AND store_id = v_sid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;
  IF p_status = 'active' AND NOT public.ensure_active_subscription(v_sid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'no_subscription');
  END IF;
  BEGIN
    UPDATE deals SET status = p_status WHERE id = p_deal_id AND store_id = v_sid;
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM LIKE 'LOCATION_LIMIT_EXCEEDED%' THEN
      SELECT max_branches INTO v_max FROM store_profiles WHERE store_id = v_sid;
      RETURN jsonb_build_object('success', false, 'error', 'location_cap', 'max', COALESCE(v_max, 3));
    END IF;
    RETURN jsonb_build_object('success', false, 'error', 'blocked', 'detail', SQLERRM);
  END;
  RETURN jsonb_build_object('success', true);
END $$;


--
-- Name: bot_toggle_follow(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_toggle_follow(p_telegram_id bigint, p_store_id text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text; v_arr text[]; v_following boolean;
BEGIN
  SELECT id, COALESCE(followed_merchants,'{}') INTO v_uid, v_arr FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF p_store_id = ANY(v_arr) THEN
    UPDATE users SET followed_merchants = array_remove(v_arr, p_store_id) WHERE id=v_uid; v_following := false;
  ELSE
    UPDATE users SET followed_merchants = array_append(v_arr, p_store_id) WHERE id=v_uid; v_following := true;
  END IF;
  RETURN jsonb_build_object('success',true,'following',v_following);
END; $$;


--
-- Name: bot_touch_chat(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_touch_chat(p_telegram_id bigint, p_chat_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public._bot_gate_ok() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  UPDATE users SET telegram_chat_id = p_chat_id, notify_via_telegram = true
    WHERE telegram_id = p_telegram_id AND telegram_chat_id IS DISTINCT FROM p_chat_id;
END;
$$;


--
-- Name: bot_track_open(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_track_open(p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text := public._bot_uid(p_telegram_id, p_whatsapp_id);
        v_src text := CASE WHEN p_telegram_id IS NOT NULL THEN 'telegram' ELSE 'whatsapp' END;
        v_lat double precision; v_lng double precision;
BEGIN
    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM analytics_events
        WHERE kind='app_open' AND user_id=v_uid AND source=v_src
          AND created_at > now() - interval '30 minutes'
    ) THEN RETURN; END IF;
    -- آخر موقع معروف للمستخدم المربوط (المشترك يشارك موقعه في التطبيق).
    IF v_uid IS NOT NULL THEN
        SELECT u.lat, u.lng INTO v_lat, v_lng FROM users u WHERE u.id = v_uid;
    END IF;
    INSERT INTO analytics_events (kind, user_id, source, lat, lng)
    VALUES ('app_open', v_uid, v_src, v_lat, v_lng);
END;
$$;


--
-- Name: bot_unlink(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_unlink(p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_name text;
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  IF p_whatsapp_id IS NOT NULL THEN
    UPDATE users SET whatsapp_chat_id = NULL, notify_via_whatsapp = false
      WHERE whatsapp_chat_id = p_whatsapp_id RETURNING name INTO v_name;
  ELSE
    UPDATE users SET telegram_id = NULL, telegram_chat_id = NULL, notify_via_telegram = false
      WHERE telegram_id = p_telegram_id RETURNING name INTO v_name;
  END IF;
  IF v_name IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  RETURN jsonb_build_object('success', true, 'name', v_name);
END; $$;


--
-- Name: bot_update_booking(bigint, text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_update_booking(p_telegram_id bigint, p_barcode text, p_quantity integer DEFAULT NULL::integer, p_prep_time text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text; v_b bookings%ROWTYPE; v_deal deals%ROWTYPE; v_newqty int; v_delta int;
BEGIN
  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode = UPPER(p_barcode) AND user_id = v_uid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  IF v_b.status <> 'pending' THEN RETURN jsonb_build_object('success', false, 'error', 'not_editable', 'status', v_b.status); END IF;
  SELECT * INTO v_deal FROM deals WHERE id = v_b.deal_id LIMIT 1;

  v_newqty := COALESCE(p_quantity, v_b.booked_quantity);
  IF v_newqty < 1 THEN v_newqty := 1; END IF;
  -- v12.28: respect the merchant's per-booking cap on edits as well
  IF COALESCE(v_deal.max_per_booking, 0) > 0 AND v_newqty > v_deal.max_per_booking THEN
    RETURN jsonb_build_object('success', false, 'error', 'max_qty', 'limit', v_deal.max_per_booking);
  END IF;
  v_delta := v_newqty - v_b.booked_quantity;
  IF NOT COALESCE(v_deal.is_unlimited,false) AND v_delta > 0 AND COALESCE(v_deal.quantity,0) < v_delta THEN
    RETURN jsonb_build_object('success', false, 'error', 'no_quantity', 'available', v_b.booked_quantity + COALESCE(v_deal.quantity,0));
  END IF;
  IF NOT COALESCE(v_deal.is_unlimited,false) AND v_delta <> 0 THEN
    UPDATE deals SET quantity = GREATEST(0, quantity - v_delta) WHERE id = v_b.deal_id;
  END IF;

  UPDATE bookings SET
    booked_quantity = v_newqty,
    prep_time = COALESCE(NULLIF(btrim(COALESCE(p_prep_time,'')),''), prep_time),
    notes = CASE WHEN p_notes IS NULL THEN notes ELSE NULLIF(btrim(p_notes),'') END
  WHERE barcode = v_b.barcode AND user_id = v_uid;

  RETURN jsonb_build_object('success', true, 'quantity', v_newqty);
END; $$;


--
-- Name: bot_update_deal(bigint, text, text, numeric, numeric, integer, text, text, text, text, text, text, integer, bigint, boolean, boolean, text[], text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_update_deal(p_telegram_id bigint, p_deal_id text, p_item_name text DEFAULT NULL::text, p_original_price numeric DEFAULT NULL::numeric, p_discounted_price numeric DEFAULT NULL::numeric, p_quantity integer DEFAULT NULL::integer, p_description text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_size text DEFAULT NULL::text, p_gender text DEFAULT NULL::text, p_expiry_type text DEFAULT NULL::text, p_expiry_date text DEFAULT NULL::text, p_expires_in_minutes integer DEFAULT NULL::integer, p_starts_at bigint DEFAULT NULL::bigint, p_clear_schedule boolean DEFAULT false, p_is_unlimited boolean DEFAULT NULL::boolean, p_images text[] DEFAULT NULL::text[], p_status text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text, p_max_per_booking integer DEFAULT NULL::integer, p_max_bookings_per_buyer integer DEFAULT NULL::integer, p_rebook_cooldown_minutes integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sid text; v_d deals%ROWTYPE; v_orig numeric; v_disc numeric; v_pct int; v_now bigint;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  SELECT * INTO v_d FROM deals WHERE id=p_deal_id AND store_id=v_sid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;

  v_orig := COALESCE(p_original_price, v_d.original_price);
  v_disc := COALESCE(p_discounted_price, v_d.discounted_price);
  IF v_disc >= v_orig THEN RETURN jsonb_build_object('success',false,'error','invalid_price'); END IF;
  v_pct := CASE WHEN v_orig > 0 THEN round(((v_orig - v_disc)/v_orig)*100) ELSE 0 END;

  UPDATE deals SET
    item_name           = COALESCE(NULLIF(btrim(COALESCE(p_item_name,'')),''), item_name),
    original_price      = v_orig,
    discounted_price    = v_disc,
    discount_percentage = v_pct,
    quantity            = CASE WHEN p_is_unlimited IS TRUE THEN NULL
                               WHEN p_quantity IS NOT NULL THEN GREATEST(0,p_quantity)
                               ELSE quantity END,
    is_unlimited        = CASE WHEN p_is_unlimited IS NOT NULL THEN p_is_unlimited
                               WHEN p_quantity IS NOT NULL THEN (p_quantity = 0)
                               ELSE is_unlimited END,
    description         = CASE WHEN p_description IS NULL THEN description ELSE NULLIF(btrim(p_description),'') END,
    category            = COALESCE(NULLIF(btrim(COALESCE(p_category,'')),''), category),
    size                = CASE WHEN p_size IS NULL THEN size ELSE NULLIF(btrim(p_size),'') END,
    gender              = COALESCE(NULLIF(btrim(COALESCE(p_gender,'')),''), gender),
    expiry_type         = COALESCE(NULLIF(btrim(COALESCE(p_expiry_type,'')),''), expiry_type),
    expiry_date         = CASE WHEN p_expiry_type IS NOT NULL THEN NULLIF(btrim(COALESCE(p_expiry_date,'')),'') ELSE expiry_date END,
    expires_in_minutes  = COALESCE(p_expires_in_minutes, expires_in_minutes),
    starts_at           = CASE WHEN p_clear_schedule IS TRUE THEN NULL
                               WHEN p_starts_at IS NOT NULL THEN p_starts_at
                               ELSE starts_at END,
    images              = CASE WHEN p_images IS NULL THEN images ELSE p_images END,
    -- v12.29: booking limits (NULL=keep, 0=clear, >0=set)
    max_per_booking         = CASE WHEN p_max_per_booking IS NULL THEN max_per_booking ELSE NULLIF(p_max_per_booking, 0) END,
    max_bookings_per_buyer  = CASE WHEN p_max_bookings_per_buyer IS NULL THEN max_bookings_per_buyer ELSE NULLIF(p_max_bookings_per_buyer, 0) END,
    rebook_cooldown_minutes = CASE WHEN p_rebook_cooldown_minutes IS NULL THEN rebook_cooldown_minutes ELSE NULLIF(p_rebook_cooldown_minutes, 0) END
  WHERE id=p_deal_id AND store_id=v_sid;

  IF p_status IS NOT NULL AND p_status <> v_d.status THEN
    IF p_status = 'active' AND NOT public.ensure_active_subscription(v_sid) THEN
      RETURN jsonb_build_object('success', false, 'error', 'no_subscription');
    END IF;
    v_now := (EXTRACT(EPOCH FROM NOW())*1000)::bigint;
    BEGIN
      IF p_status = 'active' THEN
        UPDATE deals SET
          status     = 'active',
          created_at = v_now,
          quantity   = CASE WHEN is_unlimited THEN NULL ELSE COALESCE(initial_quantity, quantity) END
        WHERE id=p_deal_id AND store_id=v_sid;
      ELSE
        UPDATE deals SET status = p_status WHERE id=p_deal_id AND store_id=v_sid;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object('success',false,'error','blocked','detail',SQLERRM);
    END;
  END IF;

  RETURN jsonb_build_object('success',true,'discount',v_pct,
    'reactivated', (p_status='active' AND v_d.status<>'active'));
END; $$;


--
-- Name: bot_update_store_bio(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_update_store_bio(p_telegram_id bigint, p_bio text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sid text; v_bio text;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  v_bio := NULLIF(btrim(coalesce(p_bio,'')),'');
  IF v_bio IS NOT NULL THEN v_bio := left(v_bio,500); END IF;
  IF EXISTS(SELECT 1 FROM store_profiles WHERE store_id=v_sid) THEN
    UPDATE store_profiles SET bio=v_bio, updated_at=NOW() WHERE store_id=v_sid;
  ELSE
    INSERT INTO store_profiles (store_id, bio, updated_at) VALUES (v_sid, v_bio, NOW());
  END IF;
  UPDATE users SET bio=v_bio, updated_at=NOW() WHERE id=v_sid;
  RETURN jsonb_build_object('success',true,'bio',v_bio);
END; $$;


--
-- Name: bot_vat_mode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_vat_mode() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case when public._bot_gate_ok() then
    (select jsonb_build_object(
       'enabled', coalesce((value->>'vat_enabled')::boolean, false),
       'add_on_top', coalesce((value->>'prices_include_vat')::boolean, true) = false,
       'rate', coalesce(nullif(value->>'vat_rate','')::numeric, 15))
     from platform_settings where key = 'tax_settings')
  else null end;
$$;


--
-- Name: bot_verify_booking(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_verify_booking(p_telegram_id bigint, p_barcode text, p_whatsapp_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sid text; v_b bookings%ROWTYPE; v_d deals%ROWTYPE;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  SELECT * INTO v_b FROM bookings WHERE (barcode = UPPER(p_barcode) OR backup_code = UPPER(p_barcode)) AND store_id = v_sid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  SELECT * INTO v_d FROM deals WHERE id = v_b.deal_id LIMIT 1;
  RETURN jsonb_build_object('success', true, 'barcode', v_b.barcode, 'user_name', COALESCE(v_b.user_name,'—'),
    'user_phone', COALESCE(v_b.user_phone,'—'), 'deal_name', v_d.item_name, 'quantity', v_b.booked_quantity,
    'status', v_b.status, 'notes', COALESCE(v_b.notes,''), 'booked_at', to_timestamp(v_b.booked_at::double precision / 1000));
END; $$;


--
-- Name: bot_verify_link_code(text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_verify_link_code(p_code text, p_chat_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user users%ROWTYPE;
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_or_expired'); END IF;
  SELECT * INTO v_user FROM users
  WHERE upper(telegram_link_otp) = upper(trim(p_code))
    AND telegram_link_otp_expires_at > NOW() AND deleted_at IS NULL LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_or_expired'); END IF;
  IF COALESCE(v_user.is_suspended, false) THEN RETURN jsonb_build_object('success', false, 'error', 'suspended'); END IF;
  UPDATE users SET telegram_chat_id = p_chat_id, notify_via_telegram = true,
    telegram_link_otp = NULL, telegram_link_otp_expires_at = NULL WHERE id = v_user.id;
  RETURN jsonb_build_object('success', true, 'id', v_user.id, 'name', v_user.name,
    'user_type', v_user.user_type, 'shop', v_user.shop,
    'is_super_admin', COALESCE(v_user.is_super_admin, false),
    'admin_permissions', COALESCE(v_user.admin_permissions, ARRAY[]::text[]));
END; $$;


