--
-- Name: browse_bookings(text, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browse_bookings(p_scope text DEFAULT 'buyer'::text, p_state text DEFAULT 'all'::text, p_query text DEFAULT NULL::text, p_cursor_ts text DEFAULT NULL::text, p_cursor_id text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_me    text    := auth.uid()::text;
  v_lim   integer := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 50);
  v_q     text    := public.taki_norm(p_query);
  v_where text;
  v_page  text;
  v_out   jsonb;
  v_total bigint;
  c_cap   constant integer := 5000;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('rows','[]'::jsonb,'has_more',false,'total',0,'total_capped',false);
  END IF;

  -- RLS على bookings يحصر الرؤية أصلاً؛ هذا يفصل دور المشتري عن دور التاجر.
  IF lower(COALESCE(p_scope,'buyer')) = 'seller' THEN
    v_where := format('b.store_id = %L', v_me);
  ELSE
    v_where := format('b.user_id = %L', v_me);
  END IF;

  IF lower(COALESCE(p_state,'all')) = 'active' THEN
    v_where := v_where || ' AND b.status NOT IN (''completed'',''cancelled'')';
  ELSIF lower(COALESCE(p_state,'all')) = 'past' THEN
    v_where := v_where || ' AND b.status IN (''completed'',''cancelled'')';
  END IF;

  -- بحث مُطبَّع عربياً (نفس محرك v13.24): الباركود/اسم المنتج/المتجر/المشتري
  IF v_q IS NOT NULL THEN
    v_where := v_where || format(
      ' AND (b.search_norm LIKE %1$L'
      '      OR EXISTS (SELECT 1 FROM public.deals dd WHERE dd.id = b.deal_id'
      '                 AND dd.store_id = b.store_id AND dd.name_norm LIKE %1$L))' /* v13.31 */,
      '%' || v_q || '%');
  END IF;

  EXECUTE format(
    'SELECT count(*)::bigint FROM (SELECT 1 FROM public.bookings b WHERE %s LIMIT %s) z',
    v_where, c_cap + 1) INTO v_total;

  v_page := v_where;
  IF p_cursor_ts IS NOT NULL AND p_cursor_id IS NOT NULL THEN
    v_page := v_page || format(
      ' AND (b.created_at < (%1$L)::timestamptz'
      '   OR (b.created_at = (%1$L)::timestamptz AND b.barcode < %2$L))',
      p_cursor_ts, p_cursor_id);
  END IF;

  EXECUTE format($q$
    WITH page AS (
      SELECT b.* FROM public.bookings b
      WHERE %1$s
      ORDER BY b.created_at DESC, b.barcode DESC
      LIMIT %2$s
    ), ranked AS (
      SELECT p.*, row_number() OVER (ORDER BY p.created_at DESC, p.barcode DESC) AS _rn
      FROM page p
    )
    SELECT jsonb_build_object(
      'rows', COALESCE((
        SELECT jsonb_agg(
          to_jsonb(r) - '_rn'
          || jsonb_build_object('deal', COALESCE(
               (SELECT to_jsonb(d) - 'search_vec' - 'name_norm' - 'loc_keys'
                  FROM public.deals d WHERE d.id = r.deal_id), 'null'::jsonb))
          -- v14.24 — حالة الاسترداد داخل الصفّ. بدونها تُطلق كل بطاقة طلبٍ
          -- مدفوع نداءً مستقلّاً عند الظهور: عشرون طلباً = عشرون نداءً،
          -- وثلاث صفحات = ستّون — أغلبها يعود فارغاً.
          || jsonb_build_object('refund', (
               SELECT jsonb_build_object(
                 'barcode', rf.barcode, 'status', rf.status, 'amount', rf.amount,
                 'opened_by', rf.opened_by, 'reason', rf.reason,
                 'requested_at', rf.requested_at, 'merchant_note', rf.merchant_note,
                 'decided_at', rf.decided_at, 'refunded_at', rf.refunded_at,
                 'refund_amount', rf.refund_amount, 'refund_ref', rf.refund_ref,
                 'refund_method', rf.refund_method, 'credit_note_no', rf.credit_note_no)
                 FROM public.booking_refunds rf WHERE rf.barcode = r.barcode))
          ORDER BY r._rn)
        FROM ranked r WHERE r._rn <= %3$s), '[]'::jsonb),
      'has_more', (SELECT count(*) FROM page) > %3$s,
      'next_ts',  (SELECT r.created_at FROM ranked r WHERE r._rn = %3$s),
      'next_id',  (SELECT r.barcode    FROM ranked r WHERE r._rn = %3$s))
  $q$, v_page, v_lim + 1, v_lim) INTO v_out;

  RETURN COALESCE(v_out, jsonb_build_object('rows','[]'::jsonb,'has_more',false))
       || jsonb_build_object('total', LEAST(v_total, c_cap), 'total_capped', v_total > c_cap);
END $_$;


--
-- Name: browse_deal_ratings(text, timestamp with time zone, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browse_deal_ratings(p_deal_id text, p_cursor_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_lim  int := GREATEST(1, LEAST(50, COALESCE(p_limit, 20)));
  v_rows jsonb;
  v_more boolean := false;
BEGIN
  IF p_deal_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'DEAL_REQUIRED');
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC, r.id DESC), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT rt.*
    FROM public.ratings rt
    WHERE rt.deal_id = p_deal_id
      AND rt.deleted_at IS NULL
      AND (
        p_cursor_at IS NULL
        OR rt.created_at < p_cursor_at
        OR (rt.created_at = p_cursor_at AND rt.id < p_cursor_id)
      )
    ORDER BY rt.created_at DESC, rt.id DESC
    LIMIT v_lim + 1
  ) r;

  IF jsonb_array_length(v_rows) > v_lim THEN
    v_more := true;
    v_rows := (SELECT jsonb_agg(e) FROM (
                 SELECT e FROM jsonb_array_elements(v_rows) e LIMIT v_lim) s);
  END IF;

  RETURN jsonb_build_object('ok', true, 'rows', COALESCE(v_rows, '[]'::jsonb), 'has_more', v_more);
END $$;


--
-- Name: browse_deals(text, text, text, text, text, text, text, text, text, text, boolean, boolean, double precision, text, integer, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browse_deals(p_query text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_gender text DEFAULT NULL::text, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_mall text DEFAULT NULL::text, p_store_id text DEFAULT NULL::text, p_season_id text DEFAULT NULL::text, p_sort text DEFAULT 'new'::text, p_mode text DEFAULT 'live'::text, p_open_now boolean DEFAULT false, p_verified boolean DEFAULT false, p_cursor_key double precision DEFAULT NULL::double precision, p_cursor_id text DEFAULT NULL::text, p_limit integer DEFAULT 30, p_blocked text[] DEFAULT NULL::text[], p_exclude_ids text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_now bigint := (EXTRACT(epoch FROM now()) * 1000)::bigint;
  v_lim integer := LEAST(GREATEST(COALESCE(p_limit, 30), 1), 60);
  v_q text := public.taki_norm(p_query);
  v_ts tsquery; v_long boolean := false;
  v_sort text := lower(COALESCE(p_sort, 'new'));
  v_expr text; v_cast text; v_desc boolean; v_dir text; v_cmp text;
  v_where text; v_page_w text; v_closed text[]; v_out jsonb; v_total bigint;
  c_cap constant integer := 5000;
BEGIN
  IF v_q IS NOT NULL THEN
    SELECT to_tsquery('simple', string_agg(quote_literal(t) || ':*', ' & ')) INTO v_ts
      FROM unnest(string_to_array(v_q, ' ')) AS t WHERE t <> '';
    v_long := length(v_q) >= 3;
  END IF;

  IF v_ts IS NOT NULL AND v_sort IN ('best', 'relevance') THEN
    v_expr := format('(ts_rank_cd(d.search_vec, %L::tsquery) * 8 + word_similarity(%L, d.name_norm) * 4'
                     ' + CASE WHEN d.name_norm LIKE %L THEN 3 ELSE 0 END'
                     ' + CASE WHEN d.name_norm LIKE %L THEN 2 ELSE 0 END)',
                     v_ts::text, v_q, v_q || '%', '%' || v_q || '%');
    v_cast := 'double precision'; v_desc := true;
  ELSIF v_sort = 'price' THEN
    v_expr := 'd.discounted_price'; v_cast := 'numeric'; v_desc := false;
  ELSIF v_sort = 'discount' THEN
    v_expr := 'd.discount_percentage'; v_cast := 'integer'; v_desc := true;
  ELSIF v_sort = 'reliability' THEN
    v_expr := 'd.reliability_score'; v_cast := 'integer'; v_desc := true;
  ELSIF v_sort = 'soon' THEN
    v_expr := 'COALESCE(d.starts_at, 0)'; v_cast := 'bigint'; v_desc := false;
  ELSE
    v_expr := 'd.created_at'; v_cast := 'bigint'; v_desc := true;
  END IF;
  v_dir := CASE WHEN v_desc THEN 'DESC' ELSE 'ASC' END;
  v_cmp := CASE WHEN v_desc THEN '<' ELSE '>' END;

  v_where := 'd.status = ''active'''
          || ' AND (d.is_unlimited OR COALESCE(d.quantity,0) > 0 OR COALESCE(d.initial_quantity,0) <= 0)';
  -- v14.32 — عروض متجرٍ موقوف لا تُعرض. كان الإيقاف يُخفي صفحة المتجر من
  -- الدليل وحدها، بينما عروضه تبقى في الرئيسية وفي «القريب مني» ويفتحها
  -- المشترون ويحجزون — أي أن «إيقاف التاجر» لم يكن يوقف بيعه.
  -- الفلترة هنا لا في صفوف العروض: فكّ الإيقاف يُعيدها كما كانت بلا أي إصلاح.
  v_where := v_where || ' AND NOT EXISTS (SELECT 1 FROM public.users su'
                     || ' WHERE su.id = d.store_id AND (su.is_suspended OR su.deleted_at IS NOT NULL))';


  IF lower(COALESCE(p_mode,'live')) = 'coming_soon' THEN
    v_where := v_where || format(' AND d.starts_at IS NOT NULL AND d.starts_at > %s AND d.starts_at <= %s', v_now, v_now + 604800000);
  ELSE
    v_where := v_where || format(' AND COALESCE(d.starts_at, 0) <= %s'
      ' AND %s <= (GREATEST(COALESCE(d.starts_at,0), d.created_at)::bigint'
      '            + (CASE WHEN COALESCE(d.expires_in_minutes,0) = 0 THEN 120 ELSE d.expires_in_minutes END)::bigint * 60000)', v_now, v_now);
  END IF;

  IF NULLIF(p_category,'') IS NOT NULL AND p_category <> 'all' THEN
    v_where := v_where || format(' AND (d.category = %L OR d.category = ''all'')', p_category); END IF;
  IF NULLIF(p_gender,'') IS NOT NULL AND p_gender <> 'all' THEN
    v_where := v_where || format(' AND (d.gender = %L OR d.gender = ''all'')', p_gender); END IF;
  IF NULLIF(p_store_id,'') IS NOT NULL THEN
    v_where := v_where || format(' AND d.store_id = %L', p_store_id); END IF;
  IF NULLIF(p_season_id,'') IS NOT NULL THEN
    v_where := v_where || format(' AND d.season_id = %L', p_season_id); END IF;

  IF NULLIF(p_mall,'') IS NOT NULL THEN
    v_where := v_where || format(' AND d.loc_keys @> ARRAY[%L]::text[]', 'm:' || p_mall);
  ELSIF NULLIF(p_city,'') IS NOT NULL THEN
    v_where := v_where || format(' AND d.loc_keys @> ARRAY[%L]::text[]', 'c:' || p_city);
  ELSIF NULLIF(p_region,'') IS NOT NULL THEN
    v_where := v_where || format(' AND d.loc_keys @> ARRAY[%L]::text[]', 'r:' || p_region);
  END IF;

  -- v13.25 — الحظر والاستثناء (كانا ترشيحاً محلياً على النافذة المُحمّلة)
  IF p_blocked IS NOT NULL AND COALESCE(array_length(p_blocked,1),0) > 0 THEN
    v_where := v_where || format(' AND NOT (d.store_id = ANY(%L::text[]))', p_blocked);
  END IF;
  IF p_exclude_ids IS NOT NULL AND COALESCE(array_length(p_exclude_ids,1),0) > 0 THEN
    v_where := v_where || format(' AND NOT (d.id = ANY(%L::text[]))', p_exclude_ids);
  END IF;

  IF COALESCE(p_open_now,false) THEN
    v_closed := taki_internal.closed_store_ids();
    IF COALESCE(array_length(v_closed,1),0) > 0 THEN
      v_where := v_where || format(' AND NOT (d.store_id = ANY(%L::text[]))', v_closed);
    END IF;
  END IF;

  IF COALESCE(p_verified,false) THEN
    v_where := v_where || ' AND (d.auth_real_count + d.auth_fake_count) > 0 AND d.auth_real_count >= d.auth_fake_count';
  END IF;

  IF v_ts IS NOT NULL THEN
    IF v_long THEN
      v_where := v_where || format(' AND (d.search_vec @@ %L::tsquery OR d.name_norm LIKE %L OR %L <%% d.name_norm)', v_ts::text, '%' || v_q || '%', v_q);
    ELSE
      v_where := v_where || format(' AND d.search_vec @@ %L::tsquery', v_ts::text);
    END IF;
  END IF;

  EXECUTE format('SELECT count(*)::bigint FROM (SELECT 1 FROM public.deals d WHERE %s LIMIT %s) z', v_where, c_cap + 1) INTO v_total;

  v_page_w := v_where;
  IF p_cursor_id IS NOT NULL AND p_cursor_key IS NOT NULL THEN
    v_page_w := v_page_w || format(' AND ((%1$s) %2$s (%3$L)::%4$s OR ((%1$s) = (%3$L)::%4$s AND d.id %2$s %5$L))',
                                   v_expr, v_cmp, p_cursor_key::text, v_cast, p_cursor_id);
  END IF;

  EXECUTE format($q$
    WITH page AS (
      SELECT d.*, (%1$s)::double precision AS _k FROM public.deals d
      WHERE %2$s ORDER BY %1$s %3$s, d.id %3$s LIMIT %4$s
    ), ranked AS (
      SELECT p.*, row_number() OVER (ORDER BY p._k %3$s, p.id %3$s) AS _rn FROM page p
    )
    SELECT jsonb_build_object(
      'rows', COALESCE((SELECT jsonb_agg(to_jsonb(r) - '_k' - '_rn' - 'search_vec' - 'name_norm' - 'loc_keys' ORDER BY r._rn)
                        FROM ranked r WHERE r._rn <= %5$s), '[]'::jsonb),
      'has_more', (SELECT count(*) FROM page) > %5$s,
      'next_key', (SELECT r._k FROM ranked r WHERE r._rn = %5$s),
      'next_id',  (SELECT r.id FROM ranked r WHERE r._rn = %5$s))
  $q$, v_expr, v_page_w, v_dir, v_lim + 1, v_lim) INTO v_out;

  RETURN COALESCE(v_out, jsonb_build_object('rows','[]'::jsonb,'has_more',false))
       || jsonb_build_object('total', LEAST(v_total, c_cap), 'total_capped', v_total > c_cap,
                             'limit', v_lim, 'sort', v_sort);
END $_$;


--
-- Name: browse_nearby(double precision, double precision, double precision, text, text, text, text, text, text, boolean, text[], integer, double precision, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browse_nearby(p_lat double precision, p_lng double precision, p_radius_km double precision DEFAULT 0, p_query text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_location_id text DEFAULT NULL::text, p_loc_type text DEFAULT NULL::text, p_open_now boolean DEFAULT false, p_blocked text[] DEFAULT NULL::text[], p_limit integer DEFAULT 30, p_cursor_dist double precision DEFAULT NULL::double precision, p_cursor_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_now   bigint  := (EXTRACT(epoch FROM now()) * 1000)::bigint;
  v_lim   integer := LEAST(GREATEST(COALESCE(p_limit, 30), 1), 60);
  v_q     text    := public.taki_norm(p_query);
  v_ts    tsquery;
  v_long  boolean := false;
  v_where text;
  v_page  text;
  v_dlat  double precision;
  v_dlng  double precision;
  v_closed text[];
  v_out   jsonb;
  v_total bigint;
  c_cap   constant integer := 5000;
BEGIN
  IF p_lat IS NULL OR p_lng IS NULL THEN
    RETURN jsonb_build_object('rows','[]'::jsonb,'has_more',false,'total',0,'total_capped',false);
  END IF;

  IF v_q IS NOT NULL THEN
    SELECT to_tsquery('simple', string_agg(quote_literal(t) || ':*', ' & ')) INTO v_ts
      FROM unnest(string_to_array(v_q, ' ')) AS t WHERE t <> '';
    v_long := length(v_q) >= 3;
  END IF;

  -- دورة حياة العرض — نفس قواعد بقية المنصة
  v_where := 'd.status = ''active'''
          || ' AND (d.is_unlimited OR COALESCE(b.quantity, d.quantity, 0) > 0 OR COALESCE(d.initial_quantity,0) <= 0)'
          || format(' AND COALESCE(d.starts_at, 0) <= %s', v_now)
          || format(' AND %s <= (GREATEST(COALESCE(d.starts_at,0), d.created_at)::bigint'
                    ' + (CASE WHEN COALESCE(d.expires_in_minutes,0) = 0 THEN 120'
                    '         ELSE d.expires_in_minutes END)::bigint * 60000)', v_now)
          || ' AND b.lat IS NOT NULL AND b.lng IS NOT NULL';
  -- v14.32 — عروض متجرٍ موقوف لا تُعرض. كان الإيقاف يُخفي صفحة المتجر من
  -- الدليل وحدها، بينما عروضه تبقى في الرئيسية وفي «القريب مني» ويفتحها
  -- المشترون ويحجزون — أي أن «إيقاف التاجر» لم يكن يوقف بيعه.
  -- الفلترة هنا لا في صفوف العروض: فكّ الإيقاف يُعيدها كما كانت بلا أي إصلاح.
  v_where := v_where || ' AND NOT EXISTS (SELECT 1 FROM public.users su'
                     || ' WHERE su.id = d.store_id AND (su.is_suspended OR su.deleted_at IS NOT NULL))';


  -- المرشّح الصندوقي: ضربة فهرس قبل أي حساب مثلثات
  IF COALESCE(p_radius_km, 0) > 0 THEN
    v_dlat := p_radius_km / 111.045;
    v_dlng := p_radius_km / (111.045 * GREATEST(cos(radians(p_lat)), 0.01));
    v_where := v_where || format(
      ' AND b.lat BETWEEN %s AND %s AND b.lng BETWEEN %s AND %s',
      p_lat - v_dlat, p_lat + v_dlat, p_lng - v_dlng, p_lng + v_dlng);
    v_where := v_where || format(
      ' AND public.taki_haversine_km(%s, %s, b.lat, b.lng) <= %s', p_lat, p_lng, p_radius_km);
  END IF;

  IF NULLIF(p_category,'') IS NOT NULL AND p_category <> 'all' THEN
    v_where := v_where || format(' AND (d.category = %L OR d.category = ''all'')', p_category); END IF;
  IF NULLIF(p_region,'') IS NOT NULL THEN
    v_where := v_where || format(' AND b.region = %L', p_region); END IF;
  IF NULLIF(p_city,'') IS NOT NULL THEN
    v_where := v_where || format(' AND b.city = %L', p_city); END IF;
  IF NULLIF(p_location_id,'') IS NOT NULL THEN
    v_where := v_where || format(' AND b.location_id = %L', p_location_id); END IF;
  IF NULLIF(p_loc_type,'') IS NOT NULL THEN
    v_where := v_where || format(
      ' AND EXISTS (SELECT 1 FROM public.locations lt WHERE lt.id = b.location_id AND lt.type = %L)', p_loc_type); END IF;
  IF p_blocked IS NOT NULL AND COALESCE(array_length(p_blocked,1),0) > 0 THEN
    v_where := v_where || format(' AND NOT (d.store_id = ANY(%L::text[]))', p_blocked); END IF;

  IF COALESCE(p_open_now,false) THEN
    v_closed := taki_internal.closed_store_ids();
    IF COALESCE(array_length(v_closed,1),0) > 0 THEN
      v_where := v_where || format(' AND NOT (d.store_id = ANY(%L::text[]))', v_closed);
    END IF;
  END IF;

  -- البحث: نفس الطبقات الثلاث + اسم الفرع (يبحث المستخدم باسم المول أيضاً)
  IF v_ts IS NOT NULL THEN
    IF v_long THEN
      v_where := v_where || format(
        ' AND (d.search_vec @@ %L::tsquery OR d.name_norm LIKE %L OR %L <%% d.name_norm'
        '      OR public.taki_norm(b.branch_name) LIKE %L)',
        v_ts::text, '%' || v_q || '%', v_q, '%' || v_q || '%');
    ELSE
      v_where := v_where || format(
        ' AND (d.search_vec @@ %L::tsquery OR public.taki_norm(b.branch_name) LIKE %L)',
        v_ts::text, '%' || v_q || '%');
    END IF;
  END IF;

  EXECUTE format(
    'SELECT count(*)::bigint FROM (SELECT 1 FROM public.deal_branches b'
    ' JOIN public.deals d ON d.id = b.deal_id WHERE %s LIMIT %s) z', v_where, c_cap + 1) INTO v_total;

  v_page := v_where;
  IF p_cursor_dist IS NOT NULL AND p_cursor_key IS NOT NULL THEN
    v_page := v_page || format(
      ' AND ((public.taki_haversine_km(%1$s, %2$s, b.lat, b.lng) > (%3$L)::double precision)'
      '   OR (public.taki_haversine_km(%1$s, %2$s, b.lat, b.lng) = (%3$L)::double precision'
      '       AND (b.deal_id || ''__'' || b.branch_id) > %4$L))',
      p_lat, p_lng, p_cursor_dist::text, p_cursor_key);
  END IF;

  EXECUTE format($q$
    WITH page AS (
      SELECT d, b, public.taki_haversine_km(%1$s, %2$s, b.lat, b.lng) AS _dist,
             (b.deal_id || '__' || b.branch_id) AS _key
      FROM public.deal_branches b
      JOIN public.deals d ON d.id = b.deal_id
      WHERE %3$s
      ORDER BY _dist ASC, _key ASC
      LIMIT %4$s
    ), ranked AS (
      SELECT p.*, row_number() OVER (ORDER BY p._dist ASC, p._key ASC) AS _rn FROM page p
    )
    SELECT jsonb_build_object(
      'rows', COALESCE((
        SELECT jsonb_agg(
          (to_jsonb(r.d) - 'search_vec' - 'name_norm' - 'loc_keys')
          || jsonb_build_object(
               'distance', r._dist,
               'lat',      (r.b).lat,
               'lng',      (r.b).lng,
               '_key',     r._key,
               '_bId',     (r.b).branch_id,
               '_bLocId',  (r.b).location_id,
               '_bName',   (r.b).branch_name,
               '_bRegion', (r.b).region,
               '_bCity',   (r.b).city)
          || CASE WHEN (r.b).quantity IS NOT NULL
                  THEN jsonb_build_object('quantity', (r.b).quantity)
                  ELSE '{}'::jsonb END
          ORDER BY r._rn)
        FROM ranked r WHERE r._rn <= %5$s), '[]'::jsonb),
      'has_more',  (SELECT count(*) FROM page) > %5$s,
      'next_dist', (SELECT r._dist FROM ranked r WHERE r._rn = %5$s),
      'next_key',  (SELECT r._key  FROM ranked r WHERE r._rn = %5$s))
  $q$, p_lat, p_lng, v_page, v_lim + 1, v_lim) INTO v_out;

  RETURN COALESCE(v_out, jsonb_build_object('rows','[]'::jsonb,'has_more',false))
       || jsonb_build_object('total', LEAST(v_total, c_cap), 'total_capped', v_total > c_cap);
END $_$;


--
-- Name: browse_notifications(timestamp with time zone, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browse_notifications(p_cursor_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id text DEFAULT NULL::text, p_limit integer DEFAULT 40) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid  text := auth.uid()::text;
  v_lim  int  := GREATEST(1, LEAST(100, COALESCE(p_limit, 40)));
  v_rows jsonb;
  v_more boolean := false;
  v_unread int;
  v_total  int;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED');
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC, r.id DESC), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT n.*
    FROM public.notifications n
    WHERE n.user_id = v_uid
      AND (
        p_cursor_at IS NULL
        OR n.created_at < p_cursor_at
        OR (n.created_at = p_cursor_at AND n.id < p_cursor_id)
      )
    ORDER BY n.created_at DESC, n.id DESC
    LIMIT v_lim + 1               -- صفٌّ زائد: به نعرف «هل بعدها المزيد» بلا عدٍّ ثانٍ
  ) r;

  IF jsonb_array_length(v_rows) > v_lim THEN
    v_more := true;
    v_rows := (SELECT jsonb_agg(e) FROM (
                 SELECT e FROM jsonb_array_elements(v_rows) e LIMIT v_lim) s);
  END IF;

  -- العدّان من الجدول كلّه لا من الصفحة — وهذا بيت القصيد.
  SELECT count(*) FILTER (WHERE NOT is_read), count(*)
    INTO v_unread, v_total
  FROM public.notifications WHERE user_id = v_uid;

  RETURN jsonb_build_object(
    'ok', true, 'rows', COALESCE(v_rows, '[]'::jsonb), 'has_more', v_more,
    'unread_total', v_unread, 'total', v_total);
END $$;


--
-- Name: browse_store_ratings(text, timestamp with time zone, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browse_store_ratings(p_store_id text, p_cursor_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id text DEFAULT NULL::text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_lim int := GREATEST(1, LEAST(50, COALESCE(p_limit, 10)));
  v_rows jsonb; v_more boolean := false; v_total int;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'STORE_REQUIRED');
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC, r.id DESC), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT rt.*, d.item_name
    FROM public.ratings rt
    JOIN public.deals d ON d.id = rt.deal_id
    WHERE d.store_id = p_store_id
      AND rt.deleted_at IS NULL
      AND (p_cursor_at IS NULL
           OR rt.created_at < p_cursor_at
           OR (rt.created_at = p_cursor_at AND rt.id < p_cursor_id))
    ORDER BY rt.created_at DESC, rt.id DESC
    LIMIT v_lim + 1
  ) r;

  IF jsonb_array_length(v_rows) > v_lim THEN
    v_more := true;
    v_rows := (SELECT jsonb_agg(e) FROM (SELECT e FROM jsonb_array_elements(v_rows) e LIMIT v_lim) s);
  END IF;

  SELECT count(*) INTO v_total
  FROM public.ratings rt JOIN public.deals d ON d.id = rt.deal_id
  WHERE d.store_id = p_store_id AND rt.deleted_at IS NULL;

  RETURN jsonb_build_object('ok', true, 'rows', COALESCE(v_rows,'[]'::jsonb),
                            'has_more', v_more, 'total', v_total);
END $$;


--
-- Name: buyer_confirm_receipt(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.buyer_confirm_receipt(p_barcode text) RETURNS public.bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid  text := auth.uid()::text;
  v_b    public.bookings%ROWTYPE;
  v_trk  text;
  v_out  public.bookings;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND OR v_b.user_id IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'لم يتم العثور على الطلب' USING ERRCODE = 'P0002';
  END IF;
  IF COALESCE(v_b.fulfillment,'pickup') <> 'delivery' THEN
    RAISE EXCEPTION 'هذا الزرّ لطلبات التوصيل فقط' USING ERRCODE = 'P0001';
  END IF;
  IF v_b.status NOT IN ('pending','acknowledged') THEN
    RAISE EXCEPTION 'الطلب مغلق بالفعل' USING ERRCODE = 'P0001';
  END IF;

  SELECT status INTO v_trk FROM public.delivery_tracks WHERE barcode = v_b.barcode;
  IF COALESCE(v_trk,'') NOT IN ('on_the_way','arrived','delivered') THEN
    RAISE EXCEPTION 'لم يبدأ التاجر التوصيل بعد' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.bookings
     SET status = 'completed', completed_by = 'buyer'
   WHERE barcode = v_b.barcode
     AND status IN ('pending','acknowledged')
  RETURNING * INTO v_out;

  IF v_out.barcode IS NULL THEN
    RAISE EXCEPTION 'الطلب مغلق بالفعل' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
  VALUES (v_out.store_id,
          '✅ أكّد المشتري الاستلام', '✅ Buyer confirmed receipt',
          'أكّد المشتري استلام الطلب ' || v_out.barcode,
          'The buyer confirmed receiving order ' || v_out.barcode,
          'booking',
          jsonb_build_object('audience','seller','event','buyer_confirmed',
                             'barcode', v_out.barcode, 'dealId', v_out.deal_id),
          NOW());

  RETURN v_out;
END;
$$;


--
-- Name: cancel_booking(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_booking(p_barcode text) RETURNS public.bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    caller  text := (SELECT auth.uid()::text);
    updated public.bookings;
    v_b     public.bookings%ROWTYPE;
BEGIN
    IF caller IS NULL THEN
        RAISE EXCEPTION 'يجب تسجيل الدخول' USING ERRCODE = '28000';
    END IF;

    -- v14.18 — الطلب المدفوع إلكترونياً لا يُلغى بضغطة واحدة. مالٌ خرج من حساب
    -- المشتري ووصل حساب التاجر مباشرة (تاكي لا تمرّ بها الأموال أصلاً)، فإلغاءٌ
    -- صامت يُعيد الكمّية للتاجر ويترك المشتري بلا بضاعة ولا مال ولا أثر مكتوب.
    -- المسار الصحيح: طلب إلغاء واسترداد يُسجَّل ويُبلَّغ ويُثبَّت بمرجع ومبلغ.
    SELECT * INTO v_b FROM public.bookings WHERE barcode = p_barcode;
    IF FOUND AND v_b.paid_at IS NOT NULL
       AND (caller = v_b.store_id OR caller = v_b.user_id) THEN
        RAISE EXCEPTION 'TAKI_PAID_NEEDS_REFUND' USING ERRCODE = 'P0014';
    END IF;

    UPDATE public.bookings
    SET status = 'cancelled',
        cancelled_by = CASE WHEN caller = store_id THEN 'seller' ELSE 'buyer' END
    WHERE barcode = p_barcode
      AND status IN ('pending', 'acknowledged')
      AND (caller = store_id OR caller = user_id)
    RETURNING * INTO updated;

    IF updated.barcode IS NULL THEN
        IF EXISTS (
            SELECT 1 FROM public.bookings
            WHERE barcode = p_barcode
              AND (caller = store_id OR caller = user_id)
        ) THEN
            RAISE EXCEPTION 'الحجز مغلق ولا يمكن إلغاؤه' USING ERRCODE = 'P0001';
        ELSE
            RAISE EXCEPTION 'لم يتم العثور على الحجز' USING ERRCODE = 'P0002';
        END IF;
    END IF;

    RETURN updated;
END;
$$;


--
-- Name: merchant_subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.merchant_subscriptions (
    id text DEFAULT (('sub_'::text || (EXTRACT(epoch FROM now()))::text) || substr(md5((random())::text), 1, 6)) NOT NULL,
    merchant_id text NOT NULL,
    plan_id text,
    status text DEFAULT 'trial'::text NOT NULL,
    trial_starts_at timestamp with time zone,
    trial_ends_at timestamp with time zone,
    current_period_start timestamp with time zone,
    current_period_end timestamp with time zone,
    discount_percent numeric DEFAULT 0,
    granted_by_admin text,
    grant_reason text,
    grant_expires_at timestamp with time zone,
    branches_count integer DEFAULT 1 NOT NULL,
    last_renewed_at timestamp with time zone,
    last_warning_sent_at timestamp with time zone,
    cancel_at_period_end boolean DEFAULT false,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT merchant_subscriptions_discount_percent_check CHECK (((discount_percent >= (0)::numeric) AND (discount_percent <= (100)::numeric))),
    CONSTRAINT merchant_subscriptions_status_check CHECK ((status = ANY (ARRAY['trial'::text, 'active'::text, 'past_due'::text, 'frozen'::text, 'cancelled'::text, 'gifted'::text])))
);

ALTER TABLE ONLY public.merchant_subscriptions REPLICA IDENTITY FULL;


--
-- Name: cancel_subscription(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_subscription(p_immediate boolean DEFAULT false) RETURNS public.merchant_subscriptions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller TEXT := auth.uid()::text;
    v_row merchant_subscriptions;
BEGIN
    IF v_caller IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT * INTO v_row
    FROM merchant_subscriptions
    WHERE merchant_id = v_caller
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No subscription found for merchant %', v_caller;
    END IF;

    IF v_row.status = 'cancelled' THEN
        RETURN v_row; -- idempotent
    END IF;

    IF p_immediate THEN
        UPDATE merchant_subscriptions
        SET status = 'cancelled',
            cancel_at_period_end = FALSE,
            current_period_end = NOW(),
            updated_at = NOW()
        WHERE merchant_id = v_caller
        RETURNING * INTO v_row;
    ELSE
        UPDATE merchant_subscriptions
        SET cancel_at_period_end = TRUE,
            updated_at = NOW()
        WHERE merchant_id = v_caller
        RETURNING * INTO v_row;
    END IF;

    RETURN v_row;
END;
$$;


--
-- Name: cancel_unverified_signup(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_unverified_signup(target_email text, target_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_ip text;
BEGIN
  IF target_id IS NULL OR target_email IS NULL OR btrim(target_email) = '' THEN
    RAISE EXCEPTION 'target_email and target_id are both required';
  END IF;

  v_ip := public._taki_client_ip();
  IF v_ip IS NOT NULL THEN
    PERFORM public.taki_rate_check('cus1h:' || v_ip, 20, 3600,
      '⏳ محاولات كثيرة — أعد المحاولة بعد قليل.');
  END IF;

  DELETE FROM auth.users
   WHERE id = target_id
     AND email = target_email
     AND email_confirmed_at IS NULL
     AND created_at < NOW() - INTERVAL '10 minutes';
END;
$$;


--
-- Name: cast_authenticity_vote(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cast_authenticity_vote(p_deal_id text, p_is_real boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text; v_store text;
BEGIN
    v_uid := auth.uid()::text;
    IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
    SELECT store_id INTO v_store FROM deals WHERE id = p_deal_id;
    IF v_store IS NULL THEN RAISE EXCEPTION 'deal not found'; END IF;
    IF NOT EXISTS (SELECT 1 FROM bookings WHERE deal_id = p_deal_id AND user_id = v_uid AND status = 'completed') THEN
        RAISE EXCEPTION 'purchase required';
    END IF;
    -- v12.29: the vote is editable — a re-vote UPDATES the previous one
    -- (merchants can no longer rely on a buyer's first vote being frozen).
    INSERT INTO deal_authenticity_votes (deal_id, store_id, user_id, is_real)
    VALUES (p_deal_id, v_store, v_uid, p_is_real)
    ON CONFLICT (deal_id, user_id) DO UPDATE SET is_real = EXCLUDED.is_real;
END;
$$;


--
-- Name: cleanup_old_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_activity() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    DELETE FROM activity_log WHERE created_at < NOW() - INTERVAL '90 days';
    -- v14.23 — كانت ٧ أيام والخصوصية تقول ٣٠ تحت «المدد المطبَّقة فعلياً».
    DELETE FROM user_sessions WHERE last_seen_at < NOW() - INTERVAL '30 days';
    -- وجلسات المصادقة نفسها لم يكن يحذفها شيء إطلاقاً.
    BEGIN
      DELETE FROM auth.sessions       WHERE COALESCE(updated_at, created_at) < NOW() - INTERVAL '30 days';
      DELETE FROM auth.refresh_tokens WHERE COALESCE(updated_at, created_at) < NOW() - INTERVAL '30 days';
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'auth session prune skipped: %', SQLERRM;
    END;
END
$$;


--
-- Name: complete_booking(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_booking(p_barcode text) RETURNS public.bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    caller text := auth.uid()::text;
    updated public.bookings;
BEGIN
    IF caller IS NULL THEN
        RAISE EXCEPTION 'يجب تسجيل الدخول لإتمام الحجز' USING ERRCODE = '28000';
    END IF;

    UPDATE public.bookings
    SET status = 'completed'
    WHERE barcode = p_barcode
      AND status IN ('pending', 'acknowledged')
      AND (caller = store_id OR caller = user_id)
    RETURNING * INTO updated;

    IF updated.barcode IS NULL THEN
        -- Distinguish "not yours / not found" from "already completed"
        IF EXISTS (
            SELECT 1 FROM public.bookings
            WHERE barcode = p_barcode
              AND (caller = store_id OR caller = user_id)
        ) THEN
            RAISE EXCEPTION 'الحجز مغلق بالفعل أو ملغى' USING ERRCODE = 'P0001';
        ELSE
            RAISE EXCEPTION 'لم يتم العثور على الحجز أو ليست لديك صلاحية' USING ERRCODE = 'P0002';
        END IF;
    END IF;

    RETURN updated;
END;
$$;


--
-- Name: compute_subscription_price(text, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_subscription_price(p_plan_id text, p_branches integer, p_discount_percent numeric DEFAULT 0) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    v_plan RECORD;
    v_extra_branches INTEGER;
    v_total NUMERIC;
BEGIN
    SELECT * INTO v_plan FROM subscription_plans WHERE id = p_plan_id LIMIT 1;
    IF v_plan IS NULL THEN
        RETURN 0;
    END IF;

    v_extra_branches := GREATEST(0, COALESCE(p_branches, 1) - COALESCE(v_plan.included_branches, 3));
    v_total := COALESCE(v_plan.price_monthly, 0) + (v_extra_branches * COALESCE(v_plan.extra_branch_fee, 0));

    IF p_discount_percent IS NOT NULL AND p_discount_percent > 0 THEN
        v_total := v_total * (1 - p_discount_percent / 100.0);
    END IF;

    RETURN ROUND(v_total::numeric, 2);
END;
$$;


--
-- Name: confirm_subscription_payment(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_subscription_payment(p_payment_id text, p_gateway_reference text) RETURNS public.merchant_subscriptions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_payment subscription_payments;
    v_sub merchant_subscriptions;
    v_caller_role TEXT;
BEGIN
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Only admins can confirm payments';
    END IF;

    SELECT * INTO v_payment FROM subscription_payments WHERE id = p_payment_id;
    IF v_payment IS NULL THEN
        RAISE EXCEPTION 'Payment not found';
    END IF;

    UPDATE subscription_payments
    SET status = 'paid', gateway_reference = p_gateway_reference, paid_at = NOW()
    WHERE id = p_payment_id;

    UPDATE merchant_subscriptions
    SET status = 'active',
        current_period_start = COALESCE(v_payment.period_start, NOW()),
        current_period_end = COALESCE(v_payment.period_end, NOW() + interval '30 days'),
        last_renewed_at = NOW(),
        updated_at = NOW()
    WHERE id = v_payment.subscription_id
    RETURNING * INTO v_sub;

    INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type)
    VALUES (v_payment.merchant_id,
        '✅ تم تجديد اشتراكك', '✅ Subscription renewed',
        'استلمنا دفعتك بنجاح. اشتراكك ساري حتى ' ||
            to_char(COALESCE(v_payment.period_end, NOW() + interval '30 days'), 'YYYY-MM-DD'),
        'We received your payment. Your subscription is active until ' ||
            to_char(COALESCE(v_payment.period_end, NOW() + interval '30 days'), 'YYYY-MM-DD'),
        'system');

    RETURN v_sub;
END;
$$;


--
-- Name: contest_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contest_counts(p_contest_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'total',     count(*),
    'qualified', count(*) filter (where qualified)
  ) from contest_entries where contest_id = p_contest_id;
$$;


--
-- Name: contest_public_results(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contest_public_results(p_contest_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare c record; v jsonb;
begin
  select * into c from contests where id = p_contest_id;
  if not found or c.status <> 'drawn' then return '[]'::jsonb; end if;
  select jsonb_agg(jsonb_build_object(
    'name',  case when c.reveal_name then name else 'فائز' end,
    'phone', case c.reveal_phone
               when 'full'   then phone
               when 'hidden' then null
               else '*** ' || right(regexp_replace(phone, '\D', '', 'g'), 4)
             end
  )) into v from contest_entries where contest_id = p_contest_id and is_winner = true;
  return coalesce(v, '[]'::jsonb);
end; $$;


--
-- Name: deal_payment_mode(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_payment_mode(p_store_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN NOT public.direct_pay_on() THEN 'cod'
    WHEN g.merchant_id IS NULL THEN 'cod'
    WHEN NOT public.pay_provider_on(g.provider) THEN 'cod'
    WHEN NOT g.is_enabled OR g.disabled_by_admin OR g.verified_at IS NULL OR g.fail_count >= 5 THEN 'cod'
    ELSE g.payment_modes
  END
  FROM (SELECT 1) x
  LEFT JOIN public.merchant_gateways g ON g.merchant_id = p_store_id;
$$;


--
-- Name: default_maps_link_from_location(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.default_maps_link_from_location() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF (NEW.google_maps_link IS NULL OR NEW.google_maps_link = '') AND NEW.location_id IS NOT NULL THEN
    SELECT google_maps_link INTO NEW.google_maps_link FROM public.locations WHERE id = NEW.location_id;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: delete_rating(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_rating(p_rating_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_uid text := (auth.uid())::text;
    v_owner text;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'auth required';
    END IF;
    SELECT user_id INTO v_owner FROM public.ratings WHERE id = p_rating_id;
    IF v_owner IS NULL THEN
        RAISE EXCEPTION 'rating not found';
    END IF;
    IF v_owner <> v_uid AND NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = v_uid AND u.user_type='admin') THEN
        RAISE EXCEPTION 'forbidden';
    END IF;
    UPDATE public.ratings SET deleted_at = now(), updated_at = now() WHERE id = p_rating_id;
END $$;


--
-- Name: delete_user_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_user_account() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text := (auth.uid())::text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  -- v14.20 — كانت تمسح صفّ المصادقة فيتسلسل الحذف إلى الطلبات والفواتير.
  -- اليوم تُحوّل إلى المسار المعتمد: تعطيلٌ فوري ثم تجهيلٌ بعد ثلاثين يوماً
  -- مع إمكانية التراجع — وهو ما تَعِد به الشروط حرفياً.
  UPDATE public.users
     SET deleted_at = now(), purge_after = now() + interval '30 days'
   WHERE id = v_uid;
  UPDATE public.deals SET status = 'paused' WHERE store_id = v_uid AND status = 'active';
END
$$;


--
-- Name: delivery_quote(text, double precision, double precision, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delivery_quote(p_store_id text, p_lat double precision, p_lng double precision, p_location_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  sp   public.store_profiles%ROWTYPE;
  z    public.store_delivery_zones%ROWTYPE;
  -- عرضٌ بلا فرع محدّد = الموقع الأساسي للمتجر. بدون هذه المساواة يسقط كل عرضٍ
  -- ذي موقع واحد (location_id فارغ) خارج نطاقاته المرسومة على 'primary' فلا
  -- يظهر له توصيل أبداً — وهي الحالة الأشيع: متجرٌ بفروع، وعرضٌ في المحل الرئيس.
  v_loc text := coalesce(nullif(btrim(coalesce(p_location_id, '')), ''), 'primary');
  v_zone_count int;
BEGIN
  SELECT * INTO sp FROM public.store_profiles WHERE store_id = p_store_id;
  IF NOT FOUND OR NOT coalesce(sp.delivery_enabled, false) THEN
    RETURN jsonb_build_object('enabled', false, 'available', false, 'reason', 'disabled');
  END IF;

  -- النطاقات التي تحكم هذا الحجز: نطاقات الفرع المختار + النطاقات العامة
  -- (branch_id IS NULL) التي رُسمت قبل ربط النطاق بالفرع أو لمتجر بموقع واحد.
  SELECT count(*) INTO v_zone_count
    FROM public.store_delivery_zones dz
   WHERE dz.store_id = p_store_id AND dz.is_active
     AND (dz.branch_id IS NULL OR (v_loc IS NOT NULL AND dz.branch_id = v_loc));

  IF v_zone_count = 0 THEN
    RETURN jsonb_build_object('enabled', true, 'available', false, 'reason', 'no_zones',
      'payment', sp.delivery_payment, 'min_order', sp.delivery_min_order,
      'eta_min', sp.delivery_eta_min, 'note', sp.delivery_note);
  END IF;
  IF p_lat IS NULL OR p_lng IS NULL THEN
    RETURN jsonb_build_object('enabled', true, 'available', false, 'reason', 'no_location',
      'payment', sp.delivery_payment, 'min_order', sp.delivery_min_order,
      'eta_min', sp.delivery_eta_min, 'note', sp.delivery_note);
  END IF;

  SELECT * INTO z FROM public.store_delivery_zones dz
   WHERE dz.store_id = p_store_id AND dz.is_active
     AND (dz.branch_id IS NULL OR (v_loc IS NOT NULL AND dz.branch_id = v_loc))
     AND public._taki_zone_contains(dz, p_lat, p_lng)
   ORDER BY coalesce(dz.fee, sp.delivery_fee) ASC, dz.created_at ASC
   LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('enabled', true, 'available', false, 'reason', 'out_of_zone',
      'payment', sp.delivery_payment, 'min_order', sp.delivery_min_order,
      'eta_min', sp.delivery_eta_min, 'note', sp.delivery_note);
  END IF;

  RETURN jsonb_build_object(
    'enabled',   true,
    'available', true,
    'zone_id',   z.id,
    'zone_name', z.name,
    'branch_id', z.branch_id,
    'fee',       round(coalesce(z.fee, sp.delivery_fee), 2),
    'min_order', sp.delivery_min_order,
    'payment',   sp.delivery_payment,
    'eta_min',   sp.delivery_eta_min,
    'note',      sp.delivery_note);
END
$$;


--
-- Name: delivery_track_get(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delivery_track_get(p_barcode text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid  text := auth.uid()::text;
  v_b    public.bookings%ROWTYPE;
  v_t    public.delivery_tracks%ROWTYPE;
  v_is_seller boolean;
  v_is_buyer  boolean;
  v_fresh boolean;
  v_store_lat double precision;
  v_store_lng double precision;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'auth'); END IF;
  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;

  v_is_seller := v_b.store_id IS NOT DISTINCT FROM v_uid;
  v_is_buyer  := v_b.user_id  IS NOT DISTINCT FROM v_uid;
  IF NOT (v_is_seller OR v_is_buyer OR public.is_admin()) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'forbidden');
  END IF;
  IF coalesce(v_b.fulfillment,'pickup') <> 'delivery' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_delivery');
  END IF;

  SELECT * INTO v_t FROM public.delivery_tracks WHERE barcode = v_b.barcode;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'status', 'preparing', 'live', false,
      'destination', jsonb_build_object('lat', nullif(v_b.delivery_address->>'lat','')::double precision,
                                        'lng', nullif(v_b.delivery_address->>'lng','')::double precision));
  END IF;

  -- «حيّ» = نبضة خلال دقيقتين. أقدم من ذلك يُعرَض كآخر موقع معروف بوقته، ولا
  -- يُقدَّم كأنه الآن — إشارة متجمّدة تُعرض كحيّة تُفقد الثقة بالميزة كلها.
  v_fresh := v_t.lat IS NOT NULL AND v_t.updated_at > now() - interval '2 minutes'
             AND v_t.status IN ('on_the_way','arrived');

  SELECT u.lat, u.lng INTO v_store_lat, v_store_lng FROM public.users u WHERE u.id = v_b.store_id;

  RETURN jsonb_build_object(
    'ok', true,
    'role', CASE WHEN v_is_seller THEN 'seller' ELSE 'buyer' END,
    'status', v_t.status,
    'live', v_fresh,
    -- الإحداثيات لا تخرج إلا وهي حيّة وأثناء التوصيل: صفٌّ منتهٍ لا موقع فيه أصلاً.
    'lat', CASE WHEN v_fresh THEN v_t.lat ELSE NULL END,
    'lng', CASE WHEN v_fresh THEN v_t.lng ELSE NULL END,
    'heading', CASE WHEN v_fresh THEN v_t.heading ELSE NULL END,
    'accuracy_m', CASE WHEN v_fresh THEN v_t.accuracy_m ELSE NULL END,
    'remaining_km', CASE WHEN v_fresh THEN v_t.remaining_km ELSE NULL END,
    'eta_min', CASE WHEN v_fresh THEN v_t.eta_min ELSE NULL END,
    'updated_at', v_t.updated_at,
    'started_at', v_t.started_at,
    'ended_at', v_t.ended_at,
    'age_sec', GREATEST(0, EXTRACT(EPOCH FROM (now() - v_t.updated_at)))::int,
    'destination', jsonb_build_object(
        'lat', nullif(v_b.delivery_address->>'lat','')::double precision,
        'lng', nullif(v_b.delivery_address->>'lng','')::double precision,
        'label', v_b.delivery_address->>'label',
        -- تفاصيل العنوان للتاجر (هو من يصل)، والمشتري يعرف عنوانه أصلاً.
        'details', CASE WHEN v_is_seller THEN v_b.delivery_address->>'details' ELSE NULL END,
        'phone',   CASE WHEN v_is_seller THEN v_b.delivery_address->>'phone'   ELSE NULL END),
    'store', jsonb_build_object('lat', v_store_lat, 'lng', v_store_lng,
                                'name', (SELECT coalesce(nullif(u.shop,''), u.name) FROM public.users u WHERE u.id = v_b.store_id)),
    'booking_status', v_b.status
  );
END
$$;


--
-- Name: delivery_track_ping(text, double precision, double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delivery_track_ping(p_barcode text, p_lat double precision, p_lng double precision, p_accuracy double precision DEFAULT NULL::double precision, p_heading double precision DEFAULT NULL::double precision, p_speed_kmh double precision DEFAULT NULL::double precision) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid   text := auth.uid()::text;
  v_b     public.bookings%ROWTYPE;
  v_prev  public.delivery_tracks%ROWTYPE;
  v_dlat  double precision;
  v_dlng  double precision;
  v_km    numeric;
  v_eta   integer;
  v_speed double precision;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_lat IS NULL OR p_lng IS NULL
     OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180 THEN
    RAISE EXCEPTION 'BAD_POINT';
  END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_b.store_id IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF coalesce(v_b.fulfillment,'pickup') <> 'delivery' THEN RAISE EXCEPTION 'NOT_DELIVERY'; END IF;
  IF v_b.status IN ('completed','cancelled') THEN RAISE EXCEPTION 'BOOKING_CLOSED'; END IF;

  SELECT * INTO v_prev FROM public.delivery_tracks WHERE barcode = v_b.barcode;
  -- لا بثّ قبل ضغطة «بدء التوصيل»: نبضةٌ بلا حالة سائرة تُرفض، فلا يتسرّب موقع
  -- تاجرٍ لم يبدأ توصيلاً بعد.
  IF v_prev.barcode IS NULL OR v_prev.status NOT IN ('on_the_way','arrived') THEN
    RAISE EXCEPTION 'NOT_STARTED';
  END IF;
  -- حدّ النبض: نبضة كل ٤ ثوانٍ على الأكثر (الواجهة ترسل كل ~١٠). يمنع إغراق
  -- الجدول وإرهاق الريل‑تايم من عميل معطوب أو خبيث.
  -- ⚠️ **إلا النبضة الأولى**: `delivery_track_set_status` تضع `updated_at = now()`،
  -- فكان الحدّ يبتلع أوّل موقع بعد ضغطة «بدء التوصيل» مباشرة — وهي أهمّ نبضة
  -- («خرج الآن من المتجر»)، فيبقى المشتري يرى «غير متصل» بلا سبب. الشرط الآن
  -- على وجود موقعٍ سابق فعلاً لا على وقت آخر تعديل. (كشفه اختبار T5/T6/T7.)
  IF v_prev.lat IS NOT NULL AND v_prev.updated_at > now() - interval '4 seconds' THEN
    RETURN jsonb_build_object('ok', true, 'throttled', true);
  END IF;

  v_dlat := nullif(v_b.delivery_address->>'lat','')::double precision;
  v_dlng := nullif(v_b.delivery_address->>'lng','')::double precision;
  IF v_dlat IS NOT NULL AND v_dlng IS NOT NULL THEN
    v_km := round(public._taki_km(p_lat, p_lng, v_dlat, v_dlng)::numeric, 2);
    -- السرعة الفعلية إن أرسلها الجهاز ومعقولة (١–١٢٠)، وإلا ٢٥ كم/س داخل المدينة.
    v_speed := CASE WHEN p_speed_kmh IS NOT NULL AND p_speed_kmh BETWEEN 1 AND 120
                    THEN p_speed_kmh ELSE 25 END;
    -- +١.٣ معامل التواء الطرق عن الخطّ المستقيم، ودقيقة واحدة حدّ أدنى.
    v_eta := GREATEST(1, CEIL((v_km * 1.3 / v_speed) * 60))::int;
  END IF;

  UPDATE public.delivery_tracks SET
    lat = p_lat, lng = p_lng,
    accuracy_m = p_accuracy, heading = p_heading, speed_kmh = p_speed_kmh,
    remaining_km = v_km, eta_min = v_eta,
    updated_at = now()
  WHERE barcode = v_b.barcode;

  RETURN jsonb_build_object('ok', true, 'remaining_km', v_km, 'eta_min', v_eta, 'status', v_prev.status);
END
$$;


--
-- Name: delivery_track_set_status(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delivery_track_set_status(p_barcode text, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid text := auth.uid()::text;
  v_b   public.bookings%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_status IS NULL OR p_status NOT IN ('preparing','on_the_way','arrived','delivered','cancelled') THEN
    RAISE EXCEPTION 'BAD_STATUS';
  END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_b.store_id IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF coalesce(v_b.fulfillment,'pickup') <> 'delivery' THEN RAISE EXCEPTION 'NOT_DELIVERY'; END IF;
  IF v_b.status IN ('cancelled') THEN RAISE EXCEPTION 'BOOKING_CLOSED'; END IF;
  -- الانطلاق يستلزم تأكيد الاستلام أولاً. الإيقاف والإنهاء لا يستلزمانه
  -- (لا يُحبس تاجرٌ عن إيقاف بثٍّ بدأه).
  IF p_status IN ('on_the_way','arrived') AND v_b.status = 'pending' THEN
    RAISE EXCEPTION 'NOT_ACKNOWLEDGED';
  END IF;

  INSERT INTO public.delivery_tracks (barcode, store_id, user_id, status, started_at)
  VALUES (v_b.barcode, v_b.store_id, v_b.user_id, p_status,
          CASE WHEN p_status = 'on_the_way' THEN now() ELSE NULL END)
  ON CONFLICT (barcode) DO UPDATE SET
    status     = EXCLUDED.status,
    started_at = CASE WHEN EXCLUDED.status = 'on_the_way'
                      THEN coalesce(public.delivery_tracks.started_at, now())
                      ELSE public.delivery_tracks.started_at END,
    ended_at   = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN now() ELSE NULL END,
    lat        = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.lat END,
    lng        = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.lng END,
    accuracy_m = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.accuracy_m END,
    heading    = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.heading END,
    speed_kmh  = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.speed_kmh END,
    remaining_km = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.remaining_km END,
    eta_min    = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.eta_min END,
    updated_at = now();

  RETURN jsonb_build_object('ok', true, 'status', p_status, 'barcode', v_b.barcode);
END
$$;


--
-- Name: direct_pay_on(); Type: FUNCTION; Schema: public; Owner: -
