$$;


--
-- Name: draw_contest_winners(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.draw_contest_winners(p_contest_id uuid, p_count integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v jsonb;
begin
  if not public.is_admin() then raise exception 'forbidden: admin only'; end if;
  -- Never reset existing winners; draw only from not-yet-winners.
  with picked as (
    select id from contest_entries
    where contest_id = p_contest_id and qualified = true and is_winner = false
    order by random() limit greatest(1, coalesce(p_count, 1))
  ), upd as (
    update contest_entries e set is_winner = true
    from picked where e.id = picked.id
    returning e.name, e.phone, e.created_at
  )
  select jsonb_agg(jsonb_build_object('name', name, 'phone', phone) order by created_at) into v from upd;
  update contests set status = 'drawn', updated_at = now() where id = p_contest_id;
  return coalesce(v, '[]'::jsonb);
end; $$;


--
-- Name: enforce_branch_location_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_branch_location_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role TEXT; v_max INT; v_new_key TEXT; v_old_key TEXT; v_distinct INT; v_exists BOOLEAN;
BEGIN
    IF NEW.is_active IS DISTINCT FROM true THEN RETURN NEW; END IF;
    SELECT user_type INTO v_role FROM users WHERE id = NEW.merchant_id;
    SELECT max_branches INTO v_max FROM store_profiles WHERE store_id = NEW.merchant_id;
    IF v_role = 'admin' AND v_max IS NULL THEN RETURN NEW; END IF;
    v_max := COALESCE(v_max, 3);

    IF NEW.location_id IS NOT NULL AND NEW.location_id <> 'other' AND NEW.location_id NOT LIKE 'custom\_%' ESCAPE '\'
    THEN v_new_key := 'loc:' || NEW.location_id;
    ELSE v_new_key := 'geo:' || ROUND(COALESCE(NEW.map_lat,0)::numeric,3)::text || ',' || ROUND(COALESCE(NEW.map_lng,0)::numeric,3)::text;
    END IF;

    -- Editing a branch without moving its location → always allowed (rename, etc.)
    IF TG_OP = 'UPDATE' THEN
        IF OLD.location_id IS NOT NULL AND OLD.location_id <> 'other' AND OLD.location_id NOT LIKE 'custom\_%' ESCAPE '\'
        THEN v_old_key := 'loc:' || OLD.location_id;
        ELSE v_old_key := 'geo:' || ROUND(COALESCE(OLD.map_lat,0)::numeric,3)::text || ',' || ROUND(COALESCE(OLD.map_lng,0)::numeric,3)::text;
        END IF;
        IF v_old_key = v_new_key THEN RETURN NEW; END IF;
    END IF;

    SELECT
        COUNT(*) FILTER (WHERE k <> v_new_key),
        bool_or(k = v_new_key)
      INTO v_distinct, v_exists
    FROM (
        SELECT DISTINCT k FROM (
            -- v13.16: مفاتيح العروض النشطة تشمل فروع النشر المتعدد
            SELECT k FROM deals d
              CROSS JOIN LATERAL public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k
             WHERE d.store_id = NEW.merchant_id AND d.status='active'
            UNION ALL
            SELECT CASE WHEN b.location_id IS NOT NULL AND b.location_id <> 'other' AND b.location_id NOT LIKE 'custom\_%' ESCAPE '\'
                THEN 'loc:' || b.location_id
                ELSE 'geo:' || ROUND(COALESCE(b.map_lat,0)::numeric,3)::text || ',' || ROUND(COALESCE(b.map_lng,0)::numeric,3)::text END
            FROM store_branches b WHERE b.merchant_id = NEW.merchant_id AND b.is_active = true AND b.id <> NEW.id
        ) t
    ) keys;

    IF COALESCE(v_exists,false) THEN RETURN NEW; END IF;   -- location already used → not new
    IF COALESCE(v_distinct,0) >= v_max THEN
        RAISE EXCEPTION 'LOCATION_LIMIT_EXCEEDED: Plan allows % locations.', v_max USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END; $$;


--
-- Name: enforce_seller_location_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_seller_location_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role TEXT; v_max INT; v_new_keys TEXT[]; v_other_keys TEXT[]; v_union INT; v_self INT;
BEGIN
    IF NEW.status IS DISTINCT FROM 'active' THEN RETURN NEW; END IF;
    SELECT user_type INTO v_role FROM users WHERE id = NEW.store_id;
    SELECT max_branches INTO v_max FROM store_profiles WHERE store_id = NEW.store_id;
    IF v_role = 'admin' AND v_max IS NULL THEN RETURN NEW; END IF;
    v_max := COALESCE(v_max, 3);

    -- v13.16: كل مفاتيح هذا العرض (الأساسي + فروع «انشر في عدة مواقع»)
    SELECT COALESCE(array_agg(DISTINCT k), ARRAY[]::text[]) INTO v_new_keys
      FROM public._taki_deal_loc_keys(NEW.location_id, NEW.map_lat, NEW.map_lng, NEW.locations) k;
    v_self := array_length(v_new_keys, 1);

    -- العرض وحده يتجاوز الباقة (الحالة التي أبلغ عنها ناصر: باقة ١ وعرض بـ٣ فروع)
    IF COALESCE(v_self,0) > v_max THEN
        RAISE EXCEPTION
          'LOCATION_LIMIT_EXCEEDED: Plan allows % distinct locations; this deal needs %.',
          v_max, v_self USING ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(array_agg(DISTINCT k), ARRAY[]::text[]) INTO v_other_keys
      FROM deals d
      CROSS JOIN LATERAL public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k
     WHERE d.store_id = NEW.store_id AND d.status = 'active' AND d.id <> NEW.id;

    SELECT count(DISTINCT k) INTO v_union FROM unnest(v_new_keys || v_other_keys) k;

    IF v_union > v_max THEN
        RAISE EXCEPTION
          'LOCATION_LIMIT_EXCEEDED: Plan allows % distinct locations; this deal needs %.',
          v_max, v_union USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END; $$;


--
-- Name: ensure_active_subscription(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_active_subscription(p_merchant_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_enabled  boolean;
    v_role     text;
    v_status   text;
    v_pe       timestamptz;
    v_te       timestamptz;
    v_plan     text;
    v_exp      timestamptz;
BEGIN
    -- Free mode: gateway disabled or unset -> everyone is "active".
    SELECT (value = 'true'::jsonb) INTO v_enabled
      FROM platform_settings WHERE key = 'payment_gateway_enabled';
    IF v_enabled IS NOT TRUE THEN
        RETURN TRUE;
    END IF;

    -- Admins always pass.
    SELECT user_type INTO v_role FROM users WHERE id = p_merchant_id;
    IF v_role = 'admin' THEN
        RETURN TRUE;
    END IF;

    -- Source A: the billing lifecycle table.
    SELECT status, current_period_end, trial_ends_at
      INTO v_status, v_pe, v_te
      FROM merchant_subscriptions WHERE merchant_id = p_merchant_id;
    IF v_status = 'trial' AND v_te IS NOT NULL AND v_te > NOW() THEN
        RETURN TRUE;
    END IF;
    IF v_status IN ('active','gifted') AND (v_pe IS NULL OR v_pe > NOW()) THEN
        RETURN TRUE;
    END IF;

    -- Source B: the store_profiles mirror (admin RPC + self-serve write here).
    SELECT subscription_plan, subscription_expires_at
      INTO v_plan, v_exp
      FROM store_profiles WHERE store_id = p_merchant_id;
    IF v_plan IS NOT NULL AND lower(v_plan) <> 'free'
       AND (v_exp IS NULL OR v_exp > NOW()) THEN
        RETURN TRUE;
    END IF;

    RETURN FALSE;
END;
$$;


--
-- Name: expire_due_bookings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_due_bookings() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now     bigint  := (EXTRACT(EPOCH FROM NOW())*1000)::bigint;
  v_grace   bigint  := (public.taki_booking_grace_hours() * 3600000)::bigint;
  v_count   int;
BEGIN
  WITH upd AS (
    UPDATE public.bookings b
       SET status = 'cancelled', cancelled_by = 'system'
     WHERE b.status IN ('pending','acknowledged')
       AND b.expiry_time IS NOT NULL
       AND b.expiry_time < v_now
       -- (أ) طلبٌ دفع صاحبه بالبطاقة لا يُلغى تلقائياً أبداً. إلغاؤه يخلق
       --     مطالبة استرداد كاذبة، ولا أحد يراجعها.
       AND b.paid_at IS NULL
       -- (ب) طلب توصيل انطلق مندوبه: العدّاد متوقّف — حتى شبكة الأمان.
       AND NOT (
             EXISTS (SELECT 1 FROM public.delivery_tracks t
                      WHERE t.barcode = b.barcode
                        AND t.status IN ('preparing','on_the_way','arrived','delivered'))
             AND b.booked_at + v_grace > v_now
           )
    RETURNING 1
  ) SELECT count(*) INTO v_count FROM upd;
  RETURN COALESCE(v_count,0);
END;
$$;


--
-- Name: expire_trials(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_trials() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    WITH expired AS (
        UPDATE merchant_subscriptions
        SET status = 'frozen', updated_at = NOW()
        WHERE status = 'trial' AND trial_ends_at < NOW()
        RETURNING merchant_id
    )
    INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type)
    SELECT merchant_id,
        '⏰ انتهت فترتك التجريبية', '⏰ Your free trial ended',
        'انتهت الـ 14 يوماً المجانية. اشترك الآن لاستئناف نشر العروض الجديدة. عروضك الحالية تبقى مرئية للزبائن.',
        'Your 14-day free trial ended. Subscribe now to resume publishing new deals. Your existing deals remain visible.',
        'system'
    FROM expired
    RETURNING 1
    INTO v_count;
    RETURN COALESCE(v_count, 0);
END;
$$;


--
-- Name: find_email_by_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_email_by_phone(input_phone text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    digits_only TEXT;
    bare        TEXT;
    intl        TEXT;
    country     TEXT;
    found_email TEXT;
    v_ip        TEXT;
BEGIN
    v_ip := public._taki_client_ip();
    IF v_ip IS NOT NULL THEN
      PERFORM public.taki_rate_check('fep1m:' || v_ip, 10, 60,
        '⏳ محاولات كثيرة خلال وقت قصير — انتظر دقيقة ثم أعد المحاولة.');
      PERFORM public.taki_rate_check('fep1h:' || v_ip, 60, 3600,
        '⏳ محاولات كثيرة — أعد المحاولة بعد قليل.');
    END IF;

    digits_only := regexp_replace(COALESCE(input_phone, ''), '\D', '', 'g');

    IF length(digits_only) >= 13 AND left(digits_only, 5) = '00966' THEN
        digits_only := '0' || substring(digits_only from 6);
    ELSIF length(digits_only) >= 12 AND left(digits_only, 3) = '966' THEN
        digits_only := '0' || substring(digits_only from 4);
    END IF;

    IF length(digits_only) < 9 THEN
        RETURN NULL;
    END IF;

    IF left(digits_only, 1) = '0' THEN
        bare := substring(digits_only from 2);
    ELSE
        bare := digits_only;
    END IF;
    intl    := '+966' || bare;
    country := '966'  || bare;

    -- v12.39: admin accounts are excluded — their emails must never be
    -- resolvable from a phone number (admins log in with email).
    SELECT email INTO found_email
      FROM public.users
     WHERE (phone         IN (digits_only, '0' || bare, bare, intl, country)
        OR contact_phone IN (digits_only, '0' || bare, bare, intl, country))
       AND user_type IS DISTINCT FROM 'admin'
     LIMIT 1;

    IF found_email IS NOT NULL THEN
        RETURN found_email;
    END IF;

    SELECT COALESCE(au.email, au.raw_user_meta_data->>'email') INTO found_email
      FROM auth.users au
     WHERE (au.phone                          IN (digits_only, '0' || bare, bare, intl, country)
        OR au.raw_user_meta_data->>'phone'         IN (digits_only, '0' || bare, bare, intl, country)
        OR au.raw_user_meta_data->>'contact_phone' IN (digits_only, '0' || bare, bare, intl, country))
       AND NOT EXISTS (
         SELECT 1 FROM public.users pu
         WHERE pu.id = au.id::text AND pu.user_type = 'admin'
       )
     LIMIT 1;

    RETURN found_email;
END;
$$;


--
-- Name: sa_cities_geo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sa_cities_geo (
    city_id text NOT NULL,
    region_id text NOT NULL,
    lat double precision NOT NULL,
    lng double precision NOT NULL
);


--
-- Name: find_nearest_sa_city(double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_nearest_sa_city(p_lat double precision, p_lng double precision) RETURNS public.sa_cities_geo
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
    SELECT g.*
    FROM public.sa_cities_geo g
    ORDER BY (
        2 * 6371 * asin(sqrt(
            sin(radians((g.lat - p_lat) / 2))^2
            + cos(radians(p_lat)) * cos(radians(g.lat))
              * sin(radians((g.lng - p_lng) / 2))^2
        ))
    ) ASC
    LIMIT 1
$$;


--
-- Name: freeze_deals_on_downgrade(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_deals_on_downgrade() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max INT;
  r RECORD;
  v_keys TEXT[] := ARRAY[]::TEXT[];
  v_deal_keys TEXT[];
BEGIN
  BEGIN
    IF NEW.max_branches IS NULL OR OLD.max_branches IS NULL
       OR NEW.max_branches >= OLD.max_branches THEN
      RETURN NEW;   -- ترقية أو بلا تغيير → لا شيء
    END IF;
    v_max := GREATEST(1, NEW.max_branches);

    -- (١) العروض التي تتجاوز السقف بذاتها
    UPDATE deals d
       SET status = 'paused', subscription_frozen = TRUE
     WHERE d.store_id = NEW.store_id
       AND d.status = 'active'
       AND (SELECT count(DISTINCT k)
              FROM public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k) > v_max;

    -- (٢) اتحاد الباقي: نُبقي الأقدم ونوقف ما يدفع الاتحاد فوق السقف
    FOR r IN
      SELECT d.id,
             ARRAY(SELECT DISTINCT k
                     FROM public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k) AS keys
        FROM deals d
       WHERE d.store_id = NEW.store_id AND d.status = 'active'
       ORDER BY d.created_at ASC NULLS FIRST, d.id ASC
    LOOP
      v_deal_keys := (SELECT array_agg(DISTINCT k) FROM unnest(v_keys || r.keys) k);
      IF COALESCE(array_length(v_deal_keys, 1), 0) > v_max THEN
        UPDATE deals SET status = 'paused', subscription_frozen = TRUE WHERE id = r.id;
      ELSE
        v_keys := v_deal_keys;   -- هذا العرض يسع داخل الباقة
      END IF;
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- الحماية لا تُفشل عملية الاشتراك نفسها أبداً
  END;
  RETURN NEW;
END $$;


--
-- Name: generate_telegram_link_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_telegram_link_code() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_otp text;
BEGIN
  v_otp := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
  UPDATE users
  SET telegram_link_otp = v_otp,
      telegram_link_otp_expires_at = NOW() + INTERVAL '15 minutes'
  WHERE id = auth.uid()::text;
  RETURN v_otp;
END;
$$;


--
-- Name: get_booking_card(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_booking_card(p_barcode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b          bookings%ROWTYPE;
  v_d          deals%ROWTYPE;
  v_uid        text := auth.uid()::text;
  v_is_admin   boolean := false;
  v_seller     text;
  v_buyer      text;
  v_deal_found boolean := false;
BEGIN
  IF p_barcode IS NULL OR length(btrim(p_barcode)) = 0 THEN
    RETURN jsonb_build_object('error','bad_request');
  END IF;

  SELECT * INTO v_b FROM bookings WHERE barcode = upper(btrim(p_barcode)) LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','not_found');
  END IF;

  IF v_uid IS NOT NULL THEN
    SELECT (user_type = 'admin')
      INTO v_is_admin FROM users WHERE id = v_uid;
  END IF;
  v_is_admin := coalesce(v_is_admin,false);

  IF v_uid IS NULL
     OR (v_uid <> coalesce(v_b.user_id,'~') AND v_uid <> coalesce(v_b.store_id,'~') AND NOT v_is_admin) THEN
    RETURN jsonb_build_object('error','forbidden');
  END IF;

  SELECT * INTO v_d FROM deals WHERE id = v_b.deal_id LIMIT 1;
  v_deal_found := FOUND;

  SELECT coalesce(nullif(shop,''), name) INTO v_seller FROM users WHERE id = v_b.store_id;
  v_buyer := coalesce(nullif(v_b.user_name,''), (SELECT name FROM users WHERE id = v_b.user_id));

  RETURN jsonb_build_object(
    'barcode',             v_b.barcode,
    'backup_code',         v_b.backup_code,
    'status',              v_b.status,
    'booked_quantity',     v_b.booked_quantity,
    'booked_at',           v_b.booked_at,
    'expiry_time',         v_b.expiry_time,
    'completed_at',        v_b.completed_at,
    'prep_time',           coalesce(v_b.prep_time, v_d.prep_time),
    'notes',               v_b.notes,
    'merchant_note',       v_b.merchant_note,
    'deal_id',             v_b.deal_id,
    'deal_exists',         v_deal_found,
    'item_name',           v_d.item_name,
    'shop_name',           coalesce(v_d.shop_name, v_seller),
    'category',            v_d.category,
    'image',               (v_d.images)[1],
    'original_price',      v_d.original_price,
    'discounted_price',    v_d.discounted_price,
    'discount_percentage', v_d.discount_percentage,
    'city',                v_d.city,
    'region',              v_d.region,
    'buyer_name',          v_buyer,
    'buyer_phone',         v_b.user_phone,
    'store_id',            v_b.store_id,
    'user_id',             v_b.user_id,
    'payment_method',      v_b.payment_method,
    'paid_at',             v_b.paid_at,
    'paid_amount',         v_b.paid_amount,
    'fulfillment',         coalesce(v_b.fulfillment, 'pickup'),
    'delivery_address',    v_b.delivery_address,
    'delivery_fee',        v_b.delivery_fee,
    'viewer_is_buyer',     (v_uid = v_b.user_id),
    'viewer_is_seller',    (v_uid = v_b.store_id),
    'viewer_is_admin',     v_is_admin
  );
END;
$$;


--
-- Name: get_booking_refund(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_booking_refund(p_barcode text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_me text := (SELECT auth.uid()::text); v_r public.booking_refunds%ROWTYPE;
BEGIN
  IF v_me IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_r FROM public.booking_refunds WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_me <> v_r.buyer_id AND v_me <> v_r.store_id AND NOT public.is_admin() THEN RETURN NULL; END IF;
  RETURN jsonb_build_object(
    'barcode', v_r.barcode, 'status', v_r.status, 'amount', v_r.amount,
    'opened_by', v_r.opened_by, 'reason', v_r.reason, 'requested_at', v_r.requested_at,
    'merchant_note', v_r.merchant_note, 'decided_at', v_r.decided_at,
    'refunded_at', v_r.refunded_at, 'refund_amount', v_r.refund_amount,
    'refund_ref', v_r.refund_ref, 'refund_method', v_r.refund_method,
    'credit_note_no', v_r.credit_note_no);
END
$$;


--
-- Name: get_bookings_timeline(timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bookings_timeline(p_from timestamp with time zone DEFAULT (now() - '24:00:00'::interval), p_to timestamp with time zone DEFAULT now(), p_bucket text DEFAULT 'hour'::text) RETURNS TABLE(bucket timestamp with time zone, count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_caller_role TEXT;
    v_interval TEXT;
BEGIN
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    v_interval := CASE p_bucket
        WHEN 'minute' THEN 'minute'
        WHEN 'day'    THEN 'day'
        ELSE 'hour'
    END;

    RETURN QUERY EXECUTE format($f$
        SELECT date_trunc(%L, created_at) AS bucket, COUNT(*)::INT
        FROM bookings
        WHERE created_at BETWEEN $1 AND $2
        GROUP BY 1 ORDER BY 1
    $f$, v_interval) USING p_from, p_to;
END $_$;


--
-- Name: get_deal_funnel(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_deal_funnel(p_deal_id text, p_start timestamp with time zone DEFAULT (now() - '30 days'::interval), p_end timestamp with time zone DEFAULT now()) RETURNS TABLE(views bigint, clicks bigint, booking_started bigint, booking_abandoned bigint, booking_completed bigint, favorites bigint, shares bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_store_id TEXT;
    v_caller_role TEXT;
BEGIN
    SELECT store_id INTO v_store_id FROM deals WHERE id = p_deal_id;
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF auth.uid()::text <> v_store_id AND v_caller_role <> 'admin' THEN
        RAISE EXCEPTION 'Forbidden';
    END IF;

    RETURN QUERY
    WITH ev AS (
        SELECT * FROM store_analytics_events
         WHERE deal_id = p_deal_id
           AND created_at BETWEEN p_start AND p_end
    )
    SELECT
        (SELECT COUNT(*) FROM ev WHERE event_type = 'deal_view')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'deal_click')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'booking_started')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'booking_abandoned')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'booking_completed')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'click_favorite')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'click_share')::bigint;
END;
$$;


--
-- Name: get_live_stats(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_live_stats(p_minutes integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_role TEXT;
    v_threshold TIMESTAMPTZ;
    result JSONB;
BEGIN
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    v_threshold := NOW() - (p_minutes || ' minutes')::INTERVAL;

    SELECT jsonb_build_object(
        'active_users',   (SELECT COUNT(DISTINCT user_id)::INT FROM user_sessions WHERE last_seen_at > v_threshold),
        'active_buyers',  (SELECT COUNT(DISTINCT user_id)::INT FROM user_sessions WHERE user_type = 'buyer'  AND last_seen_at > v_threshold),
        'active_sellers', (SELECT COUNT(DISTINCT user_id)::INT FROM user_sessions WHERE user_type = 'seller' AND last_seen_at > v_threshold),
        'bookings_today', (SELECT COUNT(*)::INT FROM bookings WHERE created_at >= NOW()::DATE),
        'bookings_hour',  (SELECT COUNT(*)::INT FROM bookings WHERE created_at > NOW() - INTERVAL '1 hour'),
        'bookings_5min',  (SELECT COUNT(*)::INT FROM bookings WHERE created_at > NOW() - INTERVAL '5 minutes'),
        'new_users_today',(SELECT COUNT(*)::INT FROM users    WHERE created_at >= NOW()::DATE),
        -- v14.33 — كانت تعدّ المحذوفين، بينما «إدارة المشترين» تستبعدهم.
        -- فالزرّ في الرئيسية يقول عدداً والقائمة التي يفتحها تعرض أقلّ منه.
        'total_users',    (SELECT COUNT(*)::INT FROM users WHERE deleted_at IS NULL),
        'total_buyers',   (SELECT COUNT(*)::INT FROM users WHERE user_type = 'buyer'  AND deleted_at IS NULL),
        'total_sellers',  (SELECT COUNT(*)::INT FROM users WHERE user_type = 'seller' AND deleted_at IS NULL),
        -- «النشطة» كانت تشمل `paused` لأن الشرط نفيٌ لحالتين فقط، ومجال
        -- الحالات أربع. الإثبات أوضح من النفي.
        'active_deals',   (SELECT COUNT(*)::INT FROM deals  WHERE status = 'active'),
        'paying_sellers', (SELECT COUNT(*)::INT FROM store_profiles WHERE subscription_plan = 'premium' AND (subscription_expires_at IS NULL OR subscription_expires_at > NOW())),
        'mrr',            (SELECT COALESCE(SUM(subscription_amount), 0)::NUMERIC FROM store_profiles WHERE subscription_plan = 'premium' AND (subscription_expires_at IS NULL OR subscription_expires_at > NOW())),
        'as_of',          NOW()
    ) INTO result;

    RETURN result;
END $$;


--
-- Name: get_my_account_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_account_status() RETURNS TABLE(deleted_at timestamp with time zone, purge_after timestamp with time zone, days_left integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_uid text := (auth.uid())::text;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'auth required';
    END IF;
    RETURN QUERY
        SELECT u.deleted_at,
               u.purge_after,
               GREATEST(0, EXTRACT(day FROM (u.purge_after - now()))::integer) AS days_left
        FROM public.users u
        WHERE u.id = v_uid;
END $$;


