--
-- Name: get_my_referral_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_referral_code() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid text := auth.uid()::text;
  v_code text;
  v_type text;
  v_try text;
  i integer := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  SELECT u.referral_code, u.user_type INTO v_code, v_type
    FROM users u WHERE u.id = v_uid AND u.deleted_at IS NULL;
  IF NOT FOUND OR v_type NOT IN ('seller', 'admin') THEN RAISE EXCEPTION 'sellers only'; END IF;
  IF v_code IS NOT NULL THEN RETURN v_code; END IF;
  LOOP
    i := i + 1;
    v_try := upper(substr(md5(v_uid || clock_timestamp()::text || i::text), 1, 6));
    BEGIN
      UPDATE users SET referral_code = v_try, updated_at = now()
       WHERE id = v_uid AND referral_code IS NULL;
      EXIT;
    EXCEPTION WHEN unique_violation THEN
      IF i > 25 THEN RAISE; END IF;
    END;
  END LOOP;
  SELECT u.referral_code INTO v_code FROM users u WHERE u.id = v_uid;
  RETURN v_code;
END $$;


--
-- Name: get_order_invoice(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_order_invoice(p_barcode text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me  text := (SELECT auth.uid()::text);
  v_row public.order_invoices%ROWTYPE;
BEGIN
  IF v_me IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_row FROM public.order_invoices WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_me <> COALESCE(v_row.buyer_id, '') AND v_me <> v_row.store_id AND NOT public.is_admin() THEN
