  RETURN jsonb_build_object(
    'barcode',    v_row.barcode,
    'invoice_no', v_row.invoice_no,
    'issued_at',  v_row.issued_at,
    'currency',   v_row.currency,
    'total',      v_row.total,
    'vat_rate',   v_row.vat_rate,
    'vat_base',   v_row.vat_base,
    'vat_amount', v_row.vat_amount,
    'seller',     v_row.seller);
END
$$;


--
-- Name: get_pinned_store_ids(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pinned_store_ids(p_city text DEFAULT NULL::text, p_mall text DEFAULT NULL::text) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
    SELECT COALESCE(ARRAY_AGG(store_id ORDER BY rank ASC), ARRAY[]::TEXT[])
      FROM pinned_stores
     WHERE is_active = TRUE
       AND (target_city IS NULL OR target_city = p_city OR p_city IS NULL)
       AND (target_mall IS NULL OR target_mall = p_mall OR p_mall IS NULL)
       AND (ends_at IS NULL OR ends_at > NOW());
$$;


--
-- Name: get_recent_activity(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recent_activity(p_limit integer DEFAULT 50) RETURNS TABLE(id bigint, user_id text, user_name text, user_type text, action text, entity_type text, entity_id text, metadata jsonb, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_role TEXT;
BEGIN
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    RETURN QUERY
    SELECT a.id, a.user_id, u.name, a.user_type, a.action,
           a.entity_type, a.entity_id, a.metadata, a.created_at
    FROM activity_log a
    LEFT JOIN users u ON u.id = a.user_id
    ORDER BY a.created_at DESC
    LIMIT p_limit;
END $$;


