--
-- Name: get_store_daily(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_store_daily(p_store_id text, p_days integer DEFAULT 14) RETURNS TABLE(day date, views bigint, clicks bigint, bookings bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_role TEXT;
BEGIN
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF auth.uid()::text <> p_store_id AND v_caller_role <> 'admin' THEN
        RAISE EXCEPTION 'Forbidden';
    END IF;

    RETURN QUERY
    SELECT (created_at AT TIME ZONE 'Asia/Riyadh')::date AS day,
           SUM(CASE WHEN event_type IN ('deal_view','page_view') THEN 1 ELSE 0 END)::bigint,
           SUM(CASE WHEN event_type = 'deal_click' THEN 1 ELSE 0 END)::bigint,
           SUM(CASE WHEN event_type = 'booking_completed' THEN 1 ELSE 0 END)::bigint
      FROM store_analytics_events
     WHERE store_id = p_store_id
       AND created_at >= NOW() - (p_days || ' days')::interval
     GROUP BY 1
     ORDER BY 1 DESC;
END;
$$;


--
-- Name: get_store_funnel(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_store_funnel(p_store_id text, p_start timestamp with time zone DEFAULT (now() - '30 days'::interval), p_end timestamp with time zone DEFAULT now()) RETURNS TABLE(views bigint, clicks bigint, booking_started bigint, booking_abandoned bigint, booking_completed bigint, abandoned_rate numeric, conversion_rate numeric, unique_sessions bigint, avg_time_ms numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_role TEXT;
BEGIN
    -- The owning seller and admins can run this.
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF auth.uid()::text <> p_store_id AND v_caller_role <> 'admin' THEN
        RAISE EXCEPTION 'Forbidden';
    END IF;

    RETURN QUERY
    WITH ev AS (
        SELECT * FROM store_analytics_events
         WHERE store_id = p_store_id
           AND created_at BETWEEN p_start AND p_end
    ),
    cnt_v   AS (SELECT COUNT(*)::bigint AS n FROM ev WHERE event_type IN ('deal_view','page_view')),
    cnt_c   AS (SELECT COUNT(*)::bigint AS n FROM ev WHERE event_type = 'deal_click'),
    cnt_bs  AS (SELECT COUNT(*)::bigint AS n FROM ev WHERE event_type = 'booking_started'),
    cnt_ba  AS (SELECT COUNT(*)::bigint AS n FROM ev WHERE event_type = 'booking_abandoned'),
    cnt_bc  AS (SELECT COUNT(*)::bigint AS n FROM ev WHERE event_type = 'booking_completed'),
    cnt_s   AS (SELECT COUNT(DISTINCT session_id)::bigint AS n FROM ev WHERE session_id IS NOT NULL),
    cnt_t   AS (SELECT COALESCE(AVG(duration_ms)::numeric,0) AS n FROM ev WHERE event_type = 'time_on_page')
    SELECT
        cnt_v.n, cnt_c.n, cnt_bs.n, cnt_ba.n, cnt_bc.n,
        CASE WHEN cnt_bs.n = 0 THEN 0 ELSE ROUND((cnt_ba.n::numeric / cnt_bs.n::numeric) * 100, 1) END,
        CASE WHEN cnt_c.n  = 0 THEN 0 ELSE ROUND((cnt_bc.n::numeric / cnt_c.n::numeric) * 100, 1) END,
        cnt_s.n, cnt_t.n
    FROM cnt_v, cnt_c, cnt_bs, cnt_ba, cnt_bc, cnt_s, cnt_t;
END;
$$;


--
-- Name: grant_subscription_bulk(text[], text, integer, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_subscription_bulk(p_merchant_ids text[], p_grant_type text, p_duration_days integer, p_discount_percent numeric DEFAULT 0, p_reason text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_role TEXT;
    v_basic_plan_id TEXT;
    v_count INTEGER := 0;
    v_merchant TEXT;
    v_status TEXT;
    v_now TIMESTAMPTZ := NOW();
    v_period_end TIMESTAMPTZ;
BEGIN
  PERFORM public._admin_require_ctx();
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Only admins can grant subscriptions';
    END IF;

    IF p_grant_type NOT IN ('free','discount') THEN
        RAISE EXCEPTION 'Invalid grant type: %', p_grant_type;
    END IF;

    IF p_duration_days IS NULL OR p_duration_days <= 0 THEN
        RAISE EXCEPTION 'Duration must be > 0 days';
    END IF;

    SELECT id INTO v_basic_plan_id FROM subscription_plans WHERE code = 'basic' LIMIT 1;
    v_period_end := v_now + (p_duration_days || ' days')::interval;
    v_status := CASE WHEN p_grant_type = 'free' THEN 'gifted' ELSE 'active' END;

    FOREACH v_merchant IN ARRAY p_merchant_ids LOOP
        -- Ensure a row exists, then update it.
        INSERT INTO merchant_subscriptions (merchant_id, plan_id, status, branches_count)
        VALUES (v_merchant, v_basic_plan_id, v_status, 1)
        ON CONFLICT (merchant_id) DO NOTHING;

        UPDATE merchant_subscriptions
        SET status = v_status,
            plan_id = COALESCE(plan_id, v_basic_plan_id),
            current_period_start = v_now,
            current_period_end = v_period_end,
            grant_expires_at = v_period_end,
            granted_by_admin = auth.uid()::text,
            grant_reason = p_reason,
            discount_percent = CASE WHEN p_grant_type = 'discount' THEN p_discount_percent ELSE 0 END,
            last_renewed_at = v_now,
            updated_at = v_now
        WHERE merchant_id = v_merchant;

        -- Ledger entry: 0 SAR for free, discounted price for discount.
        INSERT INTO subscription_payments (
            subscription_id, merchant_id, plan_id, amount, currency,
            status, payment_method, gateway_provider,
            period_start, period_end, branches_count, discount_percent, metadata
        )
        SELECT s.id, v_merchant, s.plan_id,
               CASE WHEN p_grant_type = 'free' THEN 0
                    ELSE compute_subscription_price(s.plan_id, s.branches_count, p_discount_percent) END,
               'SAR',
               CASE WHEN p_grant_type = 'free' THEN 'gifted' ELSE 'paid' END,
               'admin_grant', 'admin_grant',
               v_now, v_period_end, s.branches_count,
               COALESCE(p_discount_percent, 0),
               jsonb_build_object('reason', p_reason, 'granted_by', auth.uid()::text)
          FROM merchant_subscriptions s WHERE s.merchant_id = v_merchant;

        -- Notification to the merchant.
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
        VALUES (v_merchant,
            CASE WHEN p_grant_type = 'free' THEN '🎁 تم تفعيل اشتراك مجاني!'
                 ELSE '🎉 تم تفعيل خصم خاص على اشتراكك!' END,
            CASE WHEN p_grant_type = 'free' THEN '🎁 Free subscription activated!'
                 ELSE '🎉 Special discount activated on your subscription!' END,
            CASE WHEN p_grant_type = 'free'
                 THEN 'منحتك إدارة TAKI اشتراكاً مجانياً لمدة ' || p_duration_days || ' يوماً. ابدأ بنشر عروضك الآن! 💚'
                 ELSE 'حصلت على خصم ' || p_discount_percent || '% على الاشتراك لمدة ' || p_duration_days || ' يوماً.' END,
            CASE WHEN p_grant_type = 'free'
                 THEN 'TAKI granted you a free subscription for ' || p_duration_days || ' days. Start posting your deals now! 💚'
                 ELSE 'You received a ' || p_discount_percent || '% discount on the subscription for ' || p_duration_days || ' days.' END,
            'system',
            jsonb_build_object('grant_type', p_grant_type, 'duration_days', p_duration_days,
                               'discount_percent', p_discount_percent, 'reason', p_reason));

        v_count := v_count + 1;
    END LOOP;

    RETURN v_count;
END;
$$;


--
-- Name: guard_booking_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_booking_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    old_rank INT;
    new_rank INT;
BEGIN
    old_rank := CASE OLD.status
        WHEN 'pending' THEN 0
        WHEN 'acknowledged' THEN 1
        WHEN 'completed' THEN 2
        WHEN 'cancelled' THEN 2
        ELSE 0
    END;
    new_rank := CASE NEW.status
        WHEN 'pending' THEN 0
        WHEN 'acknowledged' THEN 1
        WHEN 'completed' THEN 2
        WHEN 'cancelled' THEN 2
        ELSE 0
    END;

    -- Block any backward transition. Cancelled is terminal in the
    -- same rank as completed but they are NOT interchangeable.
    IF new_rank < old_rank THEN
        NEW.status := OLD.status;
    ELSIF OLD.status IN ('completed', 'cancelled') AND NEW.status <> OLD.status THEN
        NEW.status := OLD.status;
    END IF;

    -- Stamp completed_at the first time we transition INTO completed
    IF NEW.status = 'completed' AND OLD.status <> 'completed' THEN
        NEW.completed_at := NOW();
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: guard_deal_publish(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_deal_publish() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller TEXT;
    v_role TEXT;
    v_active BOOLEAN;
BEGIN
    v_caller := auth.uid()::text;
    SELECT user_type INTO v_role FROM users WHERE id = v_caller;

    -- Admins bypass for support purposes.
    IF v_role = 'admin' THEN
        RETURN NEW;
    END IF;

    -- Existing rows being updated to a *non-active* status are always allowed.
    -- (Pause / expire / delete must work even after trial expiry.)
    IF TG_OP = 'UPDATE' AND NEW.status IN ('expired','deleted','paused') THEN
        RETURN NEW;
    END IF;

    -- Only block INSERTs and re-activations from frozen sellers.
    IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.status <> 'active' AND NEW.status = 'active') THEN
        v_active := ensure_active_subscription(NEW.store_id);
        IF NOT v_active THEN
            RAISE EXCEPTION 'SUBSCRIPTION_REQUIRED: Merchant subscription is not active. Renew to publish new deals.'
                USING ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: guard_report_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_report_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_reporter_type TEXT;
    v_reported_type TEXT;
BEGIN
    IF NEW.reporter_id = NEW.reported_id THEN
        RAISE EXCEPTION 'SELF_REPORT_NOT_ALLOWED' USING ERRCODE = 'P0001';
    END IF;

    SELECT user_type INTO v_reporter_type FROM public.users WHERE id = NEW.reporter_id;
    SELECT user_type INTO v_reported_type FROM public.users WHERE id = NEW.reported_id;

    IF v_reporter_type IS NULL OR v_reported_type IS NULL THEN
        RAISE EXCEPTION 'INVALID_REPORT_PARTIES' USING ERRCODE = 'P0001';
    END IF;
    IF v_reporter_type NOT IN ('buyer','seller')
       OR v_reported_type NOT IN ('buyer','seller') THEN
        RAISE EXCEPTION 'REPORT_ROLE_NOT_ALLOWED' USING ERRCODE = 'P0001';
    END IF;
    IF v_reporter_type = v_reported_type THEN
        RAISE EXCEPTION 'SAME_ROLE_REPORT_BLOCKED' USING ERRCODE = 'P0001';
    END IF;

    -- Trust the DB, not the client: stamp the real roles.
    NEW.reporter_role := v_reporter_type;
    NEW.reported_role := v_reported_type;
    IF NEW.status IS NULL THEN NEW.status := 'open'; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: handle_auth_user_updated(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_auth_user_updated() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NEW.email IS DISTINCT FROM OLD.email
       AND NEW.email IS NOT NULL
       AND NEW.email_confirmed_at IS NOT NULL THEN
        UPDATE public.users SET email = NEW.email WHERE id = NEW.id::text;
    END IF;

    IF NEW.phone IS DISTINCT FROM OLD.phone
       AND NEW.phone IS NOT NULL
       AND NEW.phone_confirmed_at IS NOT NULL THEN
        BEGIN
            UPDATE public.users SET phone = NEW.phone WHERE id = NEW.id::text;
        EXCEPTION WHEN unique_violation THEN NULL;
        END;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: handle_booking_message_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_booking_message_notification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    booking_row public.bookings;
    recipient text;
    item_name text;
    sender_name text;
    preview text;
BEGIN
    SELECT * INTO booking_row FROM public.bookings WHERE barcode = NEW.barcode;
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    IF NEW.sender_role = 'buyer' THEN
        recipient := booking_row.store_id;
    ELSE
        recipient := booking_row.user_id;
    END IF;

    SELECT d.item_name INTO item_name FROM public.deals d WHERE d.id = booking_row.deal_id;
    item_name := COALESCE(item_name, 'العرض');

    SELECT COALESCE(NULLIF(u.name, ''), NULLIF(u.shop, ''), CASE NEW.sender_role WHEN 'buyer' THEN 'المشتري' ELSE 'التاجر' END)
    INTO sender_name FROM public.users u WHERE u.id = NEW.sender_id;

    preview := CASE WHEN length(NEW.body) > 80 THEN substring(NEW.body, 1, 77) || '…' ELSE NEW.body END;

    INSERT INTO public.notifications
        (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
    VALUES
        (recipient,
         CASE WHEN NEW.sender_role = 'buyer'
              THEN '💬 رسالة جديدة من المشتري'
              ELSE '💬 رسالة جديدة من التاجر' END,
         CASE WHEN NEW.sender_role = 'buyer'
              THEN '💬 New message from buyer'
              ELSE '💬 New message from seller' END,
         sender_name || ' — ' || item_name || ': ' || preview,
         sender_name || ' — ' || item_name || ': ' || preview,
         'booking',
         jsonb_build_object(
             'audience',  CASE WHEN NEW.sender_role = 'buyer' THEN 'seller' ELSE 'buyer' END,
             'barcode',   NEW.barcode,
             'dealId',    booking_row.deal_id,
             'messageId', NEW.id,
             'isMessage', true
         ),
         NOW());

    RETURN NEW;
END;
$$;


--
-- Name: handle_booking_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_booking_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    item_name   TEXT;
    buyer_name  TEXT;
    seller_name TEXT;
    admin_id    TEXT;
    v_expired   boolean;
    v_now       bigint := (EXTRACT(EPOCH FROM NOW())*1000)::bigint;
BEGIN
    SELECT d.item_name INTO item_name FROM public.deals d WHERE d.id = NEW.deal_id;
    item_name := COALESCE(item_name, 'العرض');
    SELECT COALESCE(u.name, u.shop, '') INTO buyer_name FROM public.users u WHERE u.id = NEW.user_id;
    buyer_name := COALESCE(NULLIF(buyer_name, ''), 'مشتري');
    SELECT COALESCE(u.shop, u.name, '') INTO seller_name FROM public.users u WHERE u.id = NEW.store_id;
    seller_name := COALESCE(NULLIF(seller_name, ''), 'التاجر');

    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (NEW.store_id, '📦 طلب حجز جديد!', '📦 New Booking Request!',
            'طلب جديد من ' || buyer_name || ' لـ ' || item_name || ' (' || NEW.booked_quantity || ' قطعة).'
                || CASE WHEN NEW.prep_time IS NOT NULL AND NEW.prep_time <> '' THEN
                       ' 🕒 الوقت: ' || CASE WHEN NEW.prep_time = 'arrival' THEN 'عند الوصول' ELSE replace(NEW.prep_time,'min','') || ' دقيقة' END ELSE '' END
                || CASE WHEN NEW.notes IS NOT NULL AND NEW.notes <> '' THEN ' 📝 ' || NEW.notes ELSE '' END,
            'New order from ' || buyer_name || ' for ' || item_name || ' (' || NEW.booked_quantity || ' pcs).'
                || CASE WHEN NEW.prep_time IS NOT NULL AND NEW.prep_time <> '' THEN
                       ' 🕒 ETA: ' || CASE WHEN NEW.prep_time = 'arrival' THEN 'On arrival' ELSE replace(NEW.prep_time,'min','') || ' min' END ELSE '' END
                || CASE WHEN NEW.notes IS NOT NULL AND NEW.notes <> '' THEN ' 📝 ' || NEW.notes ELSE '' END,
            'booking',
            jsonb_build_object('audience','seller','event','new','barcode',NEW.barcode,'dealId',NEW.deal_id,'quantity',NEW.booked_quantity,'prepTime',NEW.prep_time,'notes',NEW.notes), NOW());

        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (NEW.user_id, '✅ تم الحجز بنجاح!', '✅ Booking Confirmed!',
            'تم حجز ' || item_name || ' — الرمز: ' || NEW.barcode || '. سيستلم التاجر طلبك قريباً.',
            item_name || ' booked — Code: ' || NEW.barcode || '. The seller will receive your order shortly.',
            'booking', jsonb_build_object('audience','buyer','event','new','barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());

        FOR admin_id IN SELECT id FROM public.users WHERE user_type = 'admin' AND COALESCE(deleted_at::text,'') = '' LOOP
            INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (admin_id, '🛒 حجز جديد على المنصة', '🛒 New booking on platform',
                buyer_name || ' حجز ' || item_name || ' من ' || seller_name || ' (' || NEW.booked_quantity || ' قطعة).',
                buyer_name || ' booked ' || item_name || ' from ' || seller_name || ' (' || NEW.booked_quantity || ' pcs).',
                'booking', jsonb_build_object('audience','admin','event','new','admin',true,'barcode',NEW.barcode,'dealId',NEW.deal_id,'storeId',NEW.store_id,'buyerId',NEW.user_id), NOW());
        END LOOP;
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
        IF NEW.status = 'acknowledged' THEN
            INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (NEW.user_id, '📦 التاجر استلم طلبك!', '📦 Seller received your order!',
                'استلم ' || seller_name || ' طلبك لـ ' || item_name || ' وهو قيد التجهيز الآن.',
                seller_name || ' received your order for ' || item_name || ' and is preparing it now.',
                'booking', jsonb_build_object('audience','buyer','event','acknowledged','barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());

        ELSIF NEW.status = 'completed' THEN
            INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (NEW.user_id, '🎉 تم تسليم طلبك!', '🎉 Order Delivered!',
                'تم تأكيد استلام ' || item_name || ' من ' || seller_name || '. شكراً لاستخدامك تاكي 💚',
                item_name || ' delivery confirmed by ' || seller_name || '. Thanks for using Taki 💚',
                'booking', jsonb_build_object('audience','buyer','event','completed','barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());
            INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (NEW.store_id, '🎉 تم الاستلام بنجاح!', '🎉 Order Delivered!',
                'استلم ' || buyer_name || ' طلب ' || item_name || ' — تم إغلاق الحجز.',
                buyer_name || ' received the order for ' || item_name || ' — booking closed.',
                'booking', jsonb_build_object('audience','seller','event','completed','barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());
            FOR admin_id IN SELECT id FROM public.users WHERE user_type = 'admin' AND COALESCE(deleted_at::text,'') = '' LOOP
                INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
                VALUES (admin_id, '💰 إتمام بيع جديد', '💰 Sale completed',
                    seller_name || ' أكمل بيع ' || item_name || ' لـ ' || buyer_name || '.',
                    seller_name || ' completed a sale of ' || item_name || ' to ' || buyer_name || '.',
                    'booking', jsonb_build_object('audience','admin','event','completed','admin',true,'barcode',NEW.barcode,'dealId',NEW.deal_id,'storeId',NEW.store_id,'buyerId',NEW.user_id), NOW());
            END LOOP;

        ELSIF NEW.status = 'cancelled' THEN
            -- v14.21 — إلغاءُ استردادٍ له رسائله الخاصّة من `resolve_booking_refund`
            -- (المبلغ والمرجع والإشعار الدائن). وهذا الفرع يحسب «انتهت المهلة» من
            -- `expiry_time`، والدفع لا يمسحه — فكان المشتري الذي رُدّ ماله يتلقّى
            -- فوق إشعار الردّ «⏰ انتهت مدة حجزك فأُلغي تلقائياً»، وهي كذبة، ويتلقّى
            -- التاجر «أُلغي دون استلام»، والإدارة «انتهاء حجز تلقائي».
            IF COALESCE(NEW.cancelled_by, '') = 'refund' THEN
                RETURN NEW;
            END IF;
            v_expired := (NEW.expiry_time IS NOT NULL AND NEW.expiry_time < v_now);
            INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (NEW.user_id,
                CASE WHEN v_expired THEN '⏰ انتهت مدة الحجز' ELSE '⚠️ تم إلغاء الحجز' END,
                CASE WHEN v_expired THEN '⏰ Booking expired' ELSE '⚠️ Booking Cancelled' END,
                CASE WHEN v_expired THEN 'انتهت مدة حجز ' || item_name || ' (ساعتان) فأُلغي تلقائياً وأُتيح العرض للآخرين.'
                     ELSE 'تم إلغاء حجز ' || item_name || '.' END,
                CASE WHEN v_expired THEN 'Your booking for ' || item_name || ' expired (2h window) and was auto-cancelled.'
                     ELSE 'Booking for ' || item_name || ' has been cancelled.' END,
                'booking', jsonb_build_object('audience','buyer','event', CASE WHEN v_expired THEN 'expired' ELSE 'cancelled' END,'barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());
            INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (NEW.store_id,
                CASE WHEN v_expired THEN '⏰ انتهى حجز دون استلام' ELSE '⚠️ تم إلغاء حجز' END,
                CASE WHEN v_expired THEN '⏰ Booking expired' ELSE '⚠️ Booking Cancelled' END,
                CASE WHEN v_expired THEN 'انتهت مدة حجز ' || item_name || ' من ' || buyer_name || ' دون استلام، وأُلغي تلقائياً.'
                     ELSE 'تم إلغاء حجز ' || item_name || ' من قِبل ' || buyer_name || '.' END,
                CASE WHEN v_expired THEN 'Booking for ' || item_name || ' by ' || buyer_name || ' expired without pickup and was auto-cancelled.'
                     ELSE buyer_name || ' cancelled the booking for ' || item_name || '.' END,
                'booking', jsonb_build_object('audience','seller','event', CASE WHEN v_expired THEN 'expired' ELSE 'cancelled' END,'barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());
            FOR admin_id IN SELECT id FROM public.users WHERE user_type = 'admin' AND COALESCE(deleted_at::text,'') = '' LOOP
                INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
                VALUES (admin_id,
                    CASE WHEN v_expired THEN '⏰ انتهاء حجز تلقائي' ELSE '↩️ إلغاء حجز' END, '↩️ Booking cancelled',
                    CASE WHEN v_expired THEN 'انتهت مدة حجز ' || item_name || ' بين ' || buyer_name || ' و' || seller_name || ' تلقائياً.'
                         ELSE 'إلغاء حجز ' || item_name || ' بين ' || buyer_name || ' و' || seller_name || '.' END,
                    'Booking ' || item_name || ' between ' || buyer_name || ' and ' || seller_name || (CASE WHEN v_expired THEN ' expired.' ELSE ' was cancelled.' END),
                    'booking', jsonb_build_object('audience','admin','event', CASE WHEN v_expired THEN 'expired' ELSE 'cancelled' END,'admin',true,'barcode',NEW.barcode,'dealId',NEW.deal_id,'storeId',NEW.store_id,'buyerId',NEW.user_id), NOW());
            END LOOP;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: handle_deal_smart_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_deal_smart_notifications() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    deal_region_id  TEXT;
    deal_city_id    TEXT;
    deal_lat        DOUBLE PRECISION;
    deal_lng        DOUBLE PRECISION;
    nearest_row     public.sa_cities_geo;
    rec             RECORD;
    now_ms          BIGINT;
    window_cutoff   BIGINT;
BEGIN
    IF NEW.status <> 'active' THEN
        RETURN NEW;
    END IF;

    now_ms        := (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT;
    window_cutoff := now_ms + (7 * 24 * 60 * 60 * 1000);  -- 7 days

    -- v11.21 — Hidden phase: deal scheduled further than 7 days out. Only
    -- the merchant who owns it knows about it; no buyer-side fan-out yet.
    -- The pg_cron job `taki_dispatch_coming_soon_window` will pick the
    -- row up as soon as starts_at crosses into the visibility window.
    IF NEW.starts_at IS NOT NULL AND NEW.starts_at > window_cutoff THEN
        RETURN NEW;
    END IF;

    deal_region_id := NEW.region;
    deal_city_id   := NEW.city;
    deal_lat       := NEW.map_lat;
    deal_lng       := NEW.map_lng;

    IF deal_region_id IS NULL OR deal_city_id IS NULL THEN
        SELECT l.city_id, c.region_id,
               COALESCE(deal_lat, l.lat),
               COALESCE(deal_lng, l.lng)
        INTO deal_city_id, deal_region_id, deal_lat, deal_lng
        FROM public.locations l
        LEFT JOIN public.cities c ON c.id = l.city_id
        WHERE l.id = NEW.location_id;
    END IF;

    IF (deal_region_id IS NULL OR deal_city_id IS NULL)
       AND deal_lat IS NOT NULL AND deal_lng IS NOT NULL
    THEN
        SELECT * INTO nearest_row FROM public.find_nearest_sa_city(deal_lat, deal_lng);
        IF nearest_row.city_id IS NOT NULL THEN
            deal_region_id := COALESCE(deal_region_id, nearest_row.region_id);
            deal_city_id   := COALESCE(deal_city_id,   nearest_row.city_id);
        END IF;
    END IF;

    FOR rec IN
        SELECT id, smart_alerts, followed_merchants
        FROM public.users
        WHERE id <> NEW.store_id
          AND deleted_at IS NULL
          -- v13.31 — لا تمرّ على كل مستخدمي المنصة: من لا تنبيهات لديه ولا
          -- يتابع هذا المتجر يخرج من taki_dispatch_smart_alert بـRETURN FALSE
          -- حتماً، فتمريره كان يُنفّذ taki_norm على نص العرض مرة لكل مستخدم
          -- (قِيس: ١٠.٦ ثانية عند ١٠٠ ألف مستخدم — التاجر ينتظرها عند كل إضافة).
          AND ( COALESCE(jsonb_array_length(smart_alerts), 0) > 0
             OR NEW.store_id = ANY(COALESCE(followed_merchants, ARRAY[]::text[])) )
    LOOP
        PERFORM public.taki_dispatch_smart_alert(
            rec.id,
            rec.followed_merchants,
            rec.smart_alerts,
            NEW,
            deal_region_id, deal_city_id,
            deal_lat, deal_lng,
            FALSE
        );
    END LOOP;

    -- Mark notified so the cron dispatcher never re-fires on this row.
    -- We update directly via UPDATE (not by editing NEW) because AFTER
    -- INSERT triggers can't mutate NEW back to the row.
    UPDATE public.deals SET coming_soon_notified_at = now_ms WHERE id = NEW.id;

    RETURN NEW;
END;
$$;


--
-- Name: handle_deleted_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_deleted_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM public.users WHERE id = OLD.id::text;
  RETURN OLD;
END;
$$;


--
-- Name: handle_follow_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_follow_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    added_merchant_id TEXT;
    buyer_name TEXT;
BEGIN
    SELECT elem INTO added_merchant_id
    FROM unnest(NEW.followed_merchants) AS elem
    WHERE elem NOT IN (SELECT unnest(COALESCE(OLD.followed_merchants, ARRAY[]::TEXT[])));

    IF added_merchant_id IS NOT NULL THEN
        -- Idempotency guard: one follow notification per
        -- (merchant, follower) per hour — kills the double-write race
        -- and quick unfollow/refollow spam without suppressing a
        -- genuine re-follow much later.
        IF EXISTS (
            SELECT 1 FROM public.notifications
            WHERE user_id = added_merchant_id
              AND type = 'follow'
              AND meta_data->>'followerId' = NEW.id
              AND created_at > NOW() - INTERVAL '1 hour'
        ) THEN
            RETURN NEW;
        END IF;

        buyer_name := COALESCE(NEW.name, 'مستخدم جديد');

        INSERT INTO public.notifications (
            user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at
        ) VALUES (
            added_merchant_id,
            '👥 متابع جديد!',
            '👥 New Follower!',
            'بدأ ' || buyer_name || ' بمتابعة محلك لمشاهدة أحدث عروضك.',
            buyer_name || ' started following your shop to see your latest deals.',
            'follow',
            jsonb_build_object('followerId', NEW.id),
            NOW()
        );
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: handle_new_complaint(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_complaint() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE a RECORD; v_from text; v_body text;
BEGIN
  SELECT COALESCE(NULLIF(name,''), NULLIF(email,''), 'مستخدم') INTO v_from
  FROM public.users WHERE id = NEW.user_id;
  v_body := COALESCE(v_from, 'مستخدم') || ': ' || left(COALESCE(NEW.message, NEW.subject, ''), 160);

  FOR a IN SELECT id FROM public.users
           WHERE user_type = 'admin' AND deleted_at IS NULL
  LOOP
    INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (a.id, '📮 شكوى جديدة', '📮 New complaint', v_body, v_body, 'system',
            jsonb_build_object('audience','admin', 'complaintId', NEW.id,
                               'actionUrl', '/admin?tab=reports',
                               'action_url', '/admin?tab=reports'));
    -- البريد هو القناة الوحيدة التي تصل ناصر وهو خارج التطبيق وبلا إشعارات مثبَّتة.
    BEGIN
      PERFORM public.taki_queue_email(a.id, 'admin_complaint',
        '📮 شكوى جديدة على تاكي',
        '<div dir="rtl" style="font-family:system-ui"><h2>📮 شكوى جديدة</h2><p>'
        || coalesce(v_body,'') || '</p><p><a href="https://www.takisa.net/admin?tab=reports">فتح لوحة البلاغات</a></p></div>');
    EXCEPTION WHEN others THEN NULL;  -- تعذّر البريد لا يمنع الشكوى من الوصول
    END;
  END LOOP;
  RETURN NEW;
END $$;


--
-- Name: handle_new_seller_trial(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_seller_trial() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_trial_days INT;
    v_amount NUMERIC;
    v_max INT := NULL;
    v_pkg jsonb := NULL;
    v_existing_plan TEXT;
BEGIN
    IF NEW.user_type IS DISTINCT FROM 'seller' THEN
        RETURN NEW;
    END IF;

    BEGIN
        SELECT (value::text)::int INTO v_trial_days
        FROM platform_settings WHERE key = 'trial_days';
    EXCEPTION WHEN OTHERS THEN v_trial_days := NULL;
    END;
    v_trial_days := COALESCE(NULLIF(v_trial_days, 0), 14);

    -- Unified source (v12.35): the default package in the الباقات catalogue.
    BEGIN
        SELECT p INTO v_pkg
        FROM platform_settings ps, jsonb_array_elements(ps.value) p
        WHERE ps.key = 'location_packages'
          AND (p->>'id')::int = (SELECT (value::text)::int FROM platform_settings WHERE key = 'default_package_id')
          AND COALESCE((p->>'active')::boolean, true)
        LIMIT 1;
    EXCEPTION WHEN OTHERS THEN v_pkg := NULL;
    END;

    IF v_pkg IS NOT NULL THEN
        v_amount := round(COALESCE((v_pkg->>'price')::numeric, 0)
                          * (1 - COALESCE((v_pkg->>'discount')::numeric, 0) / 100), 2);
        v_max := (v_pkg->>'max')::int;
    ELSE
        -- Legacy fallback if the catalogue/setting is missing.
        BEGIN
            SELECT (value::text)::numeric INTO v_amount
            FROM platform_settings WHERE key = 'basic_plan_price_sar';
        EXCEPTION WHEN OTHERS THEN v_amount := NULL;
        END;
        v_amount := COALESCE(v_amount, 199);
    END IF;

    SELECT subscription_plan INTO v_existing_plan
    FROM store_profiles WHERE store_id = NEW.id;

    IF v_existing_plan IN ('premium', 'trial') THEN
        RETURN NEW;
    END IF;

    INSERT INTO store_profiles (
        store_id,
        subscription_plan,
        subscription_amount,
        subscription_started_at,
        subscription_expires_at,
        discount_percentage,
        max_branches
    )
    VALUES (
        NEW.id,
        'trial',
        v_amount,
        NOW(),
        NOW() + (v_trial_days || ' days')::INTERVAL,
        0,
        COALESCE(v_max, 3)
    )
    ON CONFLICT (store_id) DO UPDATE SET
        subscription_plan = 'trial',
        subscription_amount = EXCLUDED.subscription_amount,
        subscription_started_at = EXCLUDED.subscription_started_at,
        subscription_expires_at = EXCLUDED.subscription_expires_at,
        discount_percentage = 0,
        max_branches = COALESCE(v_max, store_profiles.max_branches);

    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION handle_new_seller_trial(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handle_new_seller_trial() IS 'Auto-grants every new seller a free trial sized by platform_settings.trial_days and pre-populated with platform_settings.basic_plan_price_sar so the post-trial billing amount matches the current platform price. Skips sellers who already have a premium or trial plan (admin overrides win).';


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_src text;
  v_detail text;
  v_code text;
  v_ref_store text;
  v_requested text;
  v_type text;
  v_lang text;
BEGIN
  v_src    := NULLIF(btrim(coalesce(new.raw_user_meta_data->>'referral_source', '')), '');
  v_detail := NULLIF(btrim(coalesce(new.raw_user_meta_data->>'referral_source_detail', '')), '');
  v_code   := NULLIF(btrim(coalesce(new.raw_user_meta_data->>'referred_by_code', '')), '');
  IF v_code IS NOT NULL THEN
    SELECT u.id INTO v_ref_store FROM public.users u
     WHERE u.referral_code IS NOT NULL AND upper(u.referral_code) = upper(v_code)
     LIMIT 1;
    IF v_ref_store IS NOT NULL THEN v_src := 'store'; END IF;
  END IF;

  -- v13.42: whitelist. Never let signup metadata name a privileged role.
  v_requested := lower(btrim(coalesce(new.raw_user_meta_data->>'user_type', '')));
  v_type := CASE WHEN v_requested IN ('buyer', 'seller') THEN v_requested ELSE 'buyer' END;

  -- v13.92: لغة الواجهة وقت التسجيل. أي قيمة غير 'en' تُعامَل عربية.
  v_lang := CASE WHEN lower(btrim(coalesce(new.raw_user_meta_data->>'lang', ''))) = 'en'
                 THEN 'en' ELSE 'ar' END;

  INSERT INTO public.users (id, email, phone, name, user_type, shop,
                            referral_source, referral_source_detail, referred_by_store,
                            preferred_lang)
  VALUES (
    new.id::text,
    new.email,
    new.raw_user_meta_data->>'phone',
    COALESCE(new.raw_user_meta_data->>'name', 'مستخدم'),
    v_type,
    new.raw_user_meta_data->>'shop',
    v_src, v_detail, v_ref_store,
    v_lang
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN new;
END;
$$;


--
-- Name: handle_new_user_admin_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user_admin_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    admin_id    TEXT;
    label_ar    TEXT;
    label_en    TEXT;
    display     TEXT;
BEGIN
    label_ar := CASE NEW.user_type
        WHEN 'seller' THEN 'بائع جديد انضم'
        WHEN 'admin'  THEN 'مدير جديد أُضيف'
        ELSE 'مشترٍ جديد سجّل'
    END;
    label_en := CASE NEW.user_type
        WHEN 'seller' THEN 'New seller joined'
        WHEN 'admin'  THEN 'New admin added'
        ELSE 'New buyer signed up'
    END;
    display := COALESCE(NULLIF(NEW.shop, ''), NULLIF(NEW.name, ''), NULLIF(NEW.phone, ''), 'مستخدم');

    FOR admin_id IN SELECT id FROM public.users WHERE user_type = 'admin' AND id <> NEW.id LOOP
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (
            admin_id,
            '👤 ' || label_ar,
            '👤 ' || label_en,
            display || ' انضم للمنصة الآن.',
            display || ' just joined the platform.',
            'system',
            jsonb_build_object('userId', NEW.id, 'userType', NEW.user_type, 'admin', true),
            NOW()
        );
    END LOOP;
    RETURN NEW;
END;
$$;


--
-- Name: handle_notification_push(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_notification_push() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_url    text;
  v_secret text;
BEGIN
  BEGIN
    SELECT value INTO v_url    FROM public.app_secrets WHERE key = 'push_url';
    SELECT value INTO v_secret FROM public.app_secrets WHERE key = 'push_shared_secret';
  EXCEPTION WHEN OTHERS THEN
    RETURN NEW;   -- الخزنة غير متاحة: لا نُسقط الإشعار نفسه أبداً
  END;
  IF coalesce(v_url, '') = '' OR coalesce(v_secret, '') = '' THEN
    RETURN NEW;
  END IF;

  -- لا مشترك = لا نداء. يوفّر نداءً لكل إشعار لمستخدم بلا جهاز مسجَّل،
  -- وهي الحالة الغالبة اليوم (١١٧٧ إشعاراً مقابل صفر اشتراك).
  IF NOT EXISTS (SELECT 1 FROM public.push_subscriptions WHERE user_id = NEW.user_id) THEN
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url := v_url,
      body := jsonb_build_object(
        'userId',  NEW.user_id,
        'titleAr', NEW.title_ar,
        'titleEn', NEW.title_en,
        'bodyAr',  NEW.body_ar,
        'bodyEn',  NEW.body_en,
        'type',    NEW.type,
        'data',    NEW.meta_data,
        'notifId', NEW.id
      ),
      headers := jsonb_build_object(
        'Content-Type',  'application/json',
        'x-push-secret', v_secret
      ),
      timeout_milliseconds := 5000
    );
  EXCEPTION WHEN OTHERS THEN
    -- إشعارٌ في القاعدة أهمّ من دفعةٍ فشلت: لا تُجهض الإدراج أبداً.
    NULL;
  END;
  RETURN NEW;
END;
$$;


--
-- Name: handle_rating_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_rating_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_store_id  TEXT;
    v_item_name TEXT;
    v_buyer     TEXT;
BEGIN
    SELECT d.store_id, d.item_name INTO v_store_id, v_item_name
    FROM public.deals d WHERE d.id = NEW.deal_id;

    v_item_name := COALESCE(NULLIF(v_item_name, ''), 'منتجك');
    v_buyer     := COALESCE(NULLIF(NEW.user_name, ''), 'عميل');

    IF v_store_id IS NOT NULL THEN
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (
            v_store_id,
            '⭐ تقييم جديد لمتجرك!',
            '⭐ New rating for your store!',
            'قام ' || v_buyer || ' بتقييم ' || v_item_name || ' بـ ' || NEW.score || ' من 5'
                || CASE WHEN NEW.comment IS NOT NULL AND NEW.comment <> '' THEN ' — «' || NEW.comment || '»' ELSE '' END,
            v_buyer || ' rated ' || v_item_name || ' ' || NEW.score || '/5'
                || CASE WHEN NEW.comment IS NOT NULL AND NEW.comment <> '' THEN ' — "' || NEW.comment || '"' ELSE '' END,
            'rating',
            jsonb_build_object('audience', 'seller', 'dealId', NEW.deal_id, 'ratingId', NEW.id, 'score', NEW.score),
            NOW()
        );
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: handle_report_threshold(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_report_threshold() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_distinct      INT;
    v_under_review  BOOLEAN;
    v_admin_id      TEXT;
    v_reported_name TEXT;
BEGIN
    SELECT COUNT(DISTINCT reporter_id) INTO v_distinct
    FROM public.reports
    WHERE reported_id = NEW.reported_id
      AND status <> 'dismissed'
      AND created_at > NOW() - INTERVAL '14 days';

    SELECT COALESCE(under_review, false) INTO v_under_review
    FROM public.users WHERE id = NEW.reported_id;

    IF v_distinct >= 3 AND COALESCE(v_under_review, false) = false THEN
        UPDATE public.users
        SET under_review = true, under_review_at = NOW()
        WHERE id = NEW.reported_id;

        SELECT COALESCE(NULLIF(name,''), shop, 'حساب') INTO v_reported_name
        FROM public.users WHERE id = NEW.reported_id;

        FOR v_admin_id IN
            SELECT id FROM public.users
            WHERE user_type = 'admin' AND COALESCE(deleted_at::text,'') = ''
        LOOP
            INSERT INTO public.notifications
                (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (
                v_admin_id,
                '🚩 حساب تحت المراجعة — بلاغات متعددة',
                '🚩 Account under review — multiple reports',
                'تلقّى «' || COALESCE(v_reported_name,'حساب') || '» ' || v_distinct
                    || ' بلاغات من أشخاص مختلفين خلال 14 يوماً. راجِع مركز البلاغات في لوحة الأدمن.',
                'Account "' || COALESCE(v_reported_name,'account') || '" received ' || v_distinct
                    || ' reports from distinct users within 14 days. Review the admin Reports center.',
                'report',
                jsonb_build_object(
                    'audience','admin','admin',true,
                    'reportedId',NEW.reported_id,'reportedRole',NEW.reported_role,
                    'distinctReporters',v_distinct
                ),
                NOW()
            );
        END LOOP;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: handle_smart_alerts_backfill(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_smart_alerts_backfill() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    deal_rec        public.deals;
    deal_region_id  TEXT;
    deal_city_id    TEXT;
    deal_lat        DOUBLE PRECISION;
    deal_lng        DOUBLE PRECISION;
    nearest_row     public.sa_cities_geo;
    has_new_rules   BOOLEAN;
    cutoff_ms       BIGINT;
BEGIN
    IF NEW.smart_alerts IS NULL
       OR jsonb_typeof(NEW.smart_alerts) <> 'array'
       OR jsonb_array_length(NEW.smart_alerts) = 0
    THEN
        RETURN NEW;
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM jsonb_array_elements(NEW.smart_alerts) AS new_rule
        WHERE NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(COALESCE(OLD.smart_alerts, '[]'::jsonb)) AS old_rule
            WHERE old_rule = new_rule
        )
    ) INTO has_new_rules;
    IF NOT has_new_rules THEN
        RETURN NEW;
    END IF;

    cutoff_ms := (EXTRACT(EPOCH FROM (NOW() - INTERVAL '7 days')) * 1000)::BIGINT;

    FOR deal_rec IN
        SELECT * FROM public.deals
        WHERE status = 'active'
          AND created_at > cutoff_ms
          AND store_id <> NEW.id
          AND NOT (store_id = ANY(COALESCE(NEW.blocked_merchants, ARRAY[]::TEXT[])))
        ORDER BY created_at DESC
        LIMIT 200
    LOOP
        deal_region_id := deal_rec.region;
        deal_city_id   := deal_rec.city;
        deal_lat       := deal_rec.map_lat;
        deal_lng       := deal_rec.map_lng;

        IF deal_region_id IS NULL OR deal_city_id IS NULL THEN
            SELECT l.city_id, c.region_id,
                   COALESCE(deal_lat, l.lat),
                   COALESCE(deal_lng, l.lng)
            INTO deal_city_id, deal_region_id, deal_lat, deal_lng
            FROM public.locations l
            LEFT JOIN public.cities c ON c.id = l.city_id
            WHERE l.id = deal_rec.location_id;
        END IF;
        IF (deal_region_id IS NULL OR deal_city_id IS NULL)
           AND deal_lat IS NOT NULL AND deal_lng IS NOT NULL
        THEN
            SELECT * INTO nearest_row FROM public.find_nearest_sa_city(deal_lat, deal_lng);
            IF nearest_row.city_id IS NOT NULL THEN
                deal_region_id := COALESCE(deal_region_id, nearest_row.region_id);
                deal_city_id   := COALESCE(deal_city_id,   nearest_row.city_id);
            END IF;
        END IF;

        PERFORM public.taki_dispatch_smart_alert(
            NEW.id,
            NEW.followed_merchants,
            NEW.smart_alerts,
            deal_rec,
            deal_region_id, deal_city_id,
            deal_lat, deal_lng,
            TRUE
        );
    END LOOP;

    RETURN NEW;
END;
$$;


--
-- Name: has_admin_permission(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_admin_permission(perm text, uid text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  target_uid TEXT;
  is_super BOOLEAN;
  perms TEXT[];
BEGIN
  target_uid := COALESCE(uid, auth.uid()::text);
  IF target_uid IS NULL OR perm IS NULL OR perm = '' THEN RETURN FALSE; END IF;
  SELECT u.is_super_admin, u.admin_permissions
    INTO is_super, perms
  FROM public.users u
  WHERE u.id = target_uid AND u.user_type = 'admin';
  IF NOT FOUND THEN RETURN FALSE; END IF;
  IF COALESCE(is_super, FALSE) THEN RETURN TRUE; END IF;
  RETURN perm = ANY(COALESCE(perms, '{}'::TEXT[]));
END;
$$;


--
-- Name: increment_deal_click(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_deal_click(target_deal_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_store text;
BEGIN
    UPDATE public.deals
       SET clicks = COALESCE(clicks, 0) + 1
     WHERE id = target_deal_id
    RETURNING store_id INTO v_store;
    IF v_store IS NOT NULL THEN
        INSERT INTO public.analytics_events (kind, user_id, store_id, deal_id)
        VALUES ('deal_click', auth.uid()::text, v_store, target_deal_id);
    END IF;
END;
$$;


--
-- Name: increment_deal_view(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_deal_view(target_deal_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_store text;
BEGIN
    UPDATE public.deals
       SET views = COALESCE(views, 0) + 1
     WHERE id = target_deal_id
    RETURNING store_id INTO v_store;
    IF v_store IS NOT NULL THEN
        INSERT INTO public.analytics_events (kind, user_id, store_id, deal_id)
        VALUES ('deal_view', auth.uid()::text, v_store, target_deal_id);
    END IF;
END;
$$;


--
-- Name: increment_sponsorship_metric(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_sponsorship_metric(p_id text, p_metric text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF p_metric = 'impression' THEN
        UPDATE sponsorships SET impressions = impressions + 1 WHERE id = p_id;
    ELSIF p_metric = 'click' THEN
        UPDATE sponsorships SET clicks = clicks + 1 WHERE id = p_id;
    ELSE
        RAISE EXCEPTION 'Invalid metric: %', p_metric;
    END IF;
END;
$$;


--
-- Name: invoice_customer_details(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_customer_details(p_merchant_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_me text := auth.uid()::text; v_out jsonb;
begin
  if v_me is null then return null; end if;
  if v_me <> p_merchant_id and not public.is_admin() then return null; end if;

  select jsonb_build_object(
    'name',    coalesce(nullif(u.shop,''), u.name),
    'vat',     nullif(sp.vat_number,''),
    'cr',      nullif(sp.cr_number,''),
    'address', coalesce(nullif(sp.address,''), nullif(u.address,'')),
    'email',   coalesce(nullif(sp.email,''), nullif(u.email,'')),
    'phone',   coalesce(nullif(sp.phone,''), nullif(u.contact_phone,''), nullif(u.phone,''))
  ) into v_out
  from users u left join store_profiles sp on sp.store_id = u.id
  where u.id = p_merchant_id;

  return v_out;
end $$;


--
-- Name: is_admin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin(uid text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    target_uid TEXT;
    found      BOOLEAN;
    v_ctx      TEXT;
    v_perm     TEXT;
    v_super    BOOLEAN;
    v_perms    TEXT[];
BEGIN
    target_uid := COALESCE(uid, auth.uid()::text);
    IF target_uid IS NULL THEN
        RETURN FALSE;
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM public.users
        WHERE id = target_uid AND user_type = 'admin'
    ) INTO found;
    IF NOT found THEN
        RETURN FALSE;
    END IF;

    -- v13.46: which admin_* RPC are we gating for, if any?
    GET DIAGNOSTICS v_ctx = PG_CONTEXT;

    SELECT r.required_perm INTO v_perm
      FROM public.admin_rpc_permissions r
     WHERE v_ctx ~ ('function ' || r.rpc_name || '\(')
     LIMIT 1;

    -- No admin_* frame on the stack (an RLS policy, a trigger, a plain call):
    -- behave exactly as before.
    IF v_perm IS NULL THEN
        RETURN TRUE;
    END IF;

    SELECT u.is_super_admin, u.admin_permissions
      INTO v_super, v_perms
      FROM public.users u
     WHERE u.id = target_uid;

    IF COALESCE(v_super, FALSE) THEN
        RETURN TRUE;
    END IF;

    RETURN v_perm = ANY(COALESCE(v_perms, '{}'::TEXT[]));
END;
$$;


--
-- Name: is_super_admin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_super_admin(uid text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  target_uid TEXT;
  found BOOLEAN;
BEGIN
  target_uid := COALESCE(uid, auth.uid()::text);
  IF target_uid IS NULL THEN RETURN FALSE; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = target_uid AND u.user_type = 'admin' AND u.is_super_admin = TRUE
  ) INTO found;
  RETURN found;
END;
$$;


--
-- Name: log_activity(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_activity(p_action text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id TEXT;
    v_user_type TEXT;
BEGIN
    v_user_id := auth.uid()::text;
    SELECT user_type INTO v_user_type FROM users WHERE id = v_user_id;

    INSERT INTO activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
    VALUES (v_user_id, v_user_type, p_action, p_entity_type, p_entity_id, p_metadata);
END $$;


--
-- Name: log_moderation_flag(text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_moderation_flag(p_source text, p_content text, p_matched text[] DEFAULT NULL::text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid text := auth.uid()::text;
  v_type text; v_shop text; v_name text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF p_source NOT IN ('upload','chat','rating','deal') THEN RAISE EXCEPTION 'bad source'; END IF;
  SELECT u.user_type, u.shop, u.name INTO v_type, v_shop, v_name FROM users u WHERE u.id = v_uid;
  INSERT INTO moderation_flags (kind, source, store_id, offender_id, offender_name, content, matched)
  VALUES ('image', p_source,
          CASE WHEN v_type IN ('seller','admin') AND v_shop IS NOT NULL THEN v_uid ELSE NULL END,
          v_uid, coalesce(v_shop, v_name), left(coalesce(p_content,''), 500), p_matched);
END $$;


--
-- Name: lookup_booking_by_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_booking_by_code(p_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid  text := auth.uid()::text;
  v_code text := upper(btrim(COALESCE(p_code, '')));
  v_b    public.bookings%ROWTYPE;
  v_role text;
BEGIN
  -- جوابٌ واحد لكل حالات الفشل: لا يفرّق المستمع بين «غير موجود» و«ليس لك».
  IF v_uid IS NULL OR v_code = '' OR length(v_code) > 32 THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT * INTO v_b FROM public.bookings
  WHERE upper(barcode) = v_code OR upper(backup_code) = v_code
  LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;

  IF    v_uid = v_b.store_id THEN v_role := 'seller';
  ELSIF v_uid = v_b.user_id  THEN v_role := 'buyer';
  ELSIF public.is_admin()    THEN v_role := 'admin';
  ELSE  RETURN jsonb_build_object('found', false);
  END IF;

  RETURN jsonb_build_object('found', true,
                            'booking', public._booking_card(v_b.barcode, v_role));
END $$;


--
-- Name: mark_booking_messages_read(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_booking_messages_read(p_barcode text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    caller text := auth.uid()::text;
    booking_row public.bookings;
    role text;
    updated_count int;
BEGIN
    IF caller IS NULL THEN
        RAISE EXCEPTION 'يجب تسجيل الدخول' USING ERRCODE = '28000';
    END IF;
    SELECT * INTO booking_row FROM public.bookings WHERE barcode = p_barcode;
    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    IF caller = booking_row.user_id THEN
        role := 'buyer';
    ELSIF caller = booking_row.store_id THEN
        role := 'seller';
    ELSE
        RETURN 0;
    END IF;

    UPDATE public.booking_messages
    SET read_at = NOW()
    WHERE barcode = p_barcode
      AND sender_role <> role
      AND read_at IS NULL;
    GET DIAGNOSTICS updated_count = ROW_COUNT;
    RETURN updated_count;
END;
$$;


--
-- Name: merchant_accept_gateway_agreement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_accept_gateway_agreement() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text := auth.uid()::text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  UPDATE public.merchant_gateways
  SET agreement_accepted_at = COALESCE(agreement_accepted_at, now()), updated_at = now()
  WHERE merchant_id = v_uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'NO_GATEWAY'; END IF;
  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'seller', 'gateway_agreement_accepted', 'merchant_gateway', v_uid, '{}'::jsonb);
  RETURN public.get_my_gateway();
END $$;


--
-- Name: merchant_request_store_name(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_request_store_name(p_name text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid  text := auth.uid()::text;
  v_name text := btrim(COALESCE(p_name, ''));
  v_cur  text; v_type text; v_id text;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT COALESCE(shop, name), user_type INTO v_cur, v_type FROM public.users WHERE id = v_uid;
  IF v_type NOT IN ('seller','admin') THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_A_MERCHANT'); END IF;
  IF length(v_name) < 2 OR length(v_name) > 60 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_NAME');
  END IF;
  IF v_name = COALESCE(v_cur, '') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SAME_NAME');
  END IF;
  -- انتحال علامة قائمة: يُرفض قبل أن يصل الطابور أصلاً.
  IF EXISTS (SELECT 1 FROM public.users u
             WHERE u.id <> v_uid AND u.deleted_at IS NULL
               AND public.taki_norm(COALESCE(u.shop,'')) = public.taki_norm(v_name)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NAME_TAKEN');
  END IF;
  IF EXISTS (SELECT 1 FROM public.store_name_requests
             WHERE store_id = v_uid AND status = 'requested') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ALREADY_PENDING');
  END IF;

  INSERT INTO public.store_name_requests (store_id, current_name, wanted_name, reason)
  VALUES (v_uid, v_cur, v_name, NULLIF(btrim(COALESCE(p_reason,'')), ''))
  RETURNING id INTO v_id;

  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  SELECT a.id, '🏷 طلب تغيير اسم متجر', '🏷 Store rename request',
         COALESCE(v_cur,'—') || ' ← ' || v_name, COALESCE(v_cur,'—') || ' → ' || v_name,
         'system', jsonb_build_object('audience','admin','actionUrl','/admin?tab=sellers',
                                      'action_url','/admin?tab=sellers','nameRequestId', v_id)
  FROM public.users a WHERE a.user_type = 'admin' AND a.deleted_at IS NULL;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'status', 'requested');
END $$;


--
-- Name: merchant_set_delivery(boolean, text, numeric, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_set_delivery(p_enabled boolean, p_payment text, p_fee numeric, p_min_order numeric, p_eta_min integer, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_uid text := auth.uid()::text; v_type text; v_shop text; v_mode text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT user_type, shop INTO v_type, v_shop FROM public.users WHERE id = v_uid AND deleted_at IS NULL;
  IF v_type IS NULL OR (v_type NOT IN ('seller','admin') AND nullif(btrim(coalesce(v_shop,'')),'') IS NULL) THEN
    RAISE EXCEPTION 'SELLER_ONLY';
  END IF;
  IF p_payment IS NULL OR p_payment NOT IN ('cod','card','both') THEN RAISE EXCEPTION 'BAD_MODE'; END IF;
  IF coalesce(p_fee, 0) < 0 OR coalesce(p_fee, 0) > 1000 THEN RAISE EXCEPTION 'BAD_FEE'; END IF;
  IF coalesce(p_min_order, 0) < 0 OR coalesce(p_min_order, 0) > 100000 THEN RAISE EXCEPTION 'BAD_MIN'; END IF;
  IF p_eta_min IS NOT NULL AND p_eta_min NOT BETWEEN 0 AND 1440 THEN RAISE EXCEPTION 'BAD_ETA'; END IF;
  IF coalesce(p_enabled, false) AND p_payment IN ('card','both') THEN
    v_mode := public.deal_payment_mode(v_uid);
    IF v_mode NOT IN ('online','both') THEN RAISE EXCEPTION 'GATEWAY_REQUIRED'; END IF;
  END IF;

  INSERT INTO public.store_profiles (store_id, delivery_enabled, delivery_payment, delivery_fee, delivery_min_order, delivery_eta_min, delivery_note)
  VALUES (v_uid, coalesce(p_enabled,false), p_payment, round(coalesce(p_fee,0),2), round(coalesce(p_min_order,0),2), p_eta_min, nullif(left(btrim(coalesce(p_note,'')),300),''))
  ON CONFLICT (store_id) DO UPDATE SET
    delivery_enabled   = EXCLUDED.delivery_enabled,
    delivery_payment   = EXCLUDED.delivery_payment,
    delivery_fee       = EXCLUDED.delivery_fee,
    delivery_min_order = EXCLUDED.delivery_min_order,
    delivery_eta_min   = EXCLUDED.delivery_eta_min,
    delivery_note      = EXCLUDED.delivery_note,
    updated_at         = now();

  RETURN (SELECT jsonb_build_object(
    'delivery_enabled', sp.delivery_enabled, 'delivery_payment', sp.delivery_payment,
    'delivery_fee', sp.delivery_fee, 'delivery_min_order', sp.delivery_min_order,
    'delivery_eta_min', sp.delivery_eta_min, 'delivery_note', sp.delivery_note,
    'zones', (SELECT count(*) FROM public.store_delivery_zones z WHERE z.store_id = v_uid AND z.is_active))
    FROM public.store_profiles sp WHERE sp.store_id = v_uid);
END
$$;


--
-- Name: merchant_set_gateway(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_set_gateway(p_provider text, p_publishable_key text DEFAULT NULL::text, p_secret_key text DEFAULT NULL::text, p_webhook_secret text DEFAULT NULL::text, p_extra jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text := auth.uid()::text; v_utype text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT u.user_type INTO v_utype FROM public.users u WHERE u.id = v_uid;
  IF v_utype IS NULL OR v_utype NOT IN ('seller','admin') THEN RAISE EXCEPTION 'SELLER_ONLY'; END IF;
  RETURN public._gateway_write(v_uid, p_provider, p_publishable_key, p_secret_key, p_webhook_secret, p_extra, v_uid, v_utype);
END $$;


--
-- Name: merchant_set_payment_declaration(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_set_payment_declaration(p_accepts_cod boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_uid text := auth.uid()::text; v_type text; v_shop text; v_mode text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT user_type, shop INTO v_type, v_shop FROM public.users WHERE id = v_uid AND deleted_at IS NULL;
  IF v_type IS NULL OR (v_type NOT IN ('seller','admin') AND nullif(btrim(coalesce(v_shop,'')),'') IS NULL) THEN
    RAISE EXCEPTION 'SELLER_ONLY';
  END IF;
  v_mode := public.deal_payment_mode(v_uid);
  -- رفض النقد بلا بوابة يعني متجراً لا يستطيع تحصيل ريال واحد — نمنعه بدل أن
  -- نتركه يكتشف ذلك من مشترٍ لا يستطيع الحجز.
  IF NOT coalesce(p_accepts_cod, true) AND v_mode NOT IN ('online','both') THEN
    RAISE EXCEPTION 'NEED_GATEWAY_OR_COD';
  END IF;

  INSERT INTO public.store_profiles (store_id, accepts_cod, payment_declared_at)
  VALUES (v_uid, coalesce(p_accepts_cod, true), now())
  ON CONFLICT (store_id) DO UPDATE SET
    accepts_cod = EXCLUDED.accepts_cod,
    payment_declared_at = now(),
    updated_at = now();

  RETURN public.store_can_sell(v_uid);
END
$$;


--
-- Name: merchant_set_payment_modes(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_set_payment_modes(p_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text := auth.uid()::text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_mode IS NULL OR p_mode NOT IN ('cod','online','both') THEN RAISE EXCEPTION 'BAD_MODE'; END IF;
  UPDATE public.merchant_gateways SET payment_modes = p_mode, updated_at = now() WHERE merchant_id = v_uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'NO_GATEWAY'; END IF;
  RETURN public.get_my_gateway();
END $$;


--
-- Name: merchant_set_policies(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_set_policies(p_refund_policy text, p_store_terms text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me text := (SELECT auth.uid()::text);
  v_r  text;
  v_t  text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  v_r := NULLIF(left(btrim(COALESCE(p_refund_policy, '')), 1500), '');
  v_t := NULLIF(left(btrim(COALESCE(p_store_terms,   '')), 1500), '');

  INSERT INTO public.store_profiles (store_id, refund_policy, store_terms)
  VALUES (v_me, v_r, v_t)
  ON CONFLICT (store_id) DO UPDATE
    SET refund_policy = EXCLUDED.refund_policy,
        store_terms   = EXCLUDED.store_terms,
        updated_at    = now();

  RETURN jsonb_build_object('ok', true, 'refund_policy', v_r, 'store_terms', v_t);
END
$$;


--
-- Name: merchant_set_subscription_renew(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_set_subscription_renew(p_on boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller text := auth.uid()::text;
    v_row    store_profiles;
BEGIN
    IF v_caller IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    UPDATE store_profiles
    SET auto_renew = p_on,
        subscription_canceled_at = CASE WHEN p_on THEN NULL ELSE NOW() END,
        updated_at = NOW()
    WHERE store_id = v_caller
    RETURNING * INTO v_row;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No store profile for %', v_caller;
    END IF;

    -- v12.32: لا استعادة تلقائية للعروض المجمّدة — التاجر يفعّلها بنفسه.

    RETURN jsonb_build_object(
        'success', true,
        'auto_renew', v_row.auto_renew,
        'canceled_at', v_row.subscription_canceled_at,
        'expires_at', v_row.subscription_expires_at
    );
END;
$$;


--
-- Name: merchant_toggle_gateway(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_toggle_gateway(p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text := auth.uid()::text; v_row public.merchant_gateways%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT * INTO v_row FROM public.merchant_gateways WHERE merchant_id = v_uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'NO_GATEWAY'; END IF;
  IF p_enabled THEN
    IF v_row.agreement_accepted_at IS NULL THEN RAISE EXCEPTION 'AGREEMENT_REQUIRED'; END IF;
    IF v_row.secret_key_id IS NULL THEN RAISE EXCEPTION 'KEYS_REQUIRED'; END IF;
    IF v_row.verified_at IS NULL THEN RAISE EXCEPTION 'VERIFY_REQUIRED'; END IF;
  END IF;
  UPDATE public.merchant_gateways
  SET is_enabled = p_enabled, fail_count = CASE WHEN p_enabled THEN 0 ELSE fail_count END, updated_at = now()
  WHERE merchant_id = v_uid;
  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'seller', CASE WHEN p_enabled THEN 'gateway_enabled' ELSE 'gateway_disabled' END,
          'merchant_gateway', v_uid, '{}'::jsonb);
  RETURN public.get_my_gateway();
END $$;


--
-- Name: my_contest_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_contest_entry(p_contest_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_uid text := auth.uid()::text; v_phone text; r record;
begin
  if v_uid is null then return jsonb_build_object('entered', false); end if;
  select nullif(btrim(phone), '') into v_phone from users where id = v_uid;
  if v_phone is null then return jsonb_build_object('entered', false); end if;
  select score, max_score, qualified into r
    from contest_entries where contest_id = p_contest_id and phone = v_phone;
  if not found then return jsonb_build_object('entered', false); end if;
  return jsonb_build_object('entered', true, 'qualified', r.qualified, 'score', r.score, 'max_score', r.max_score);
end; $$;


--
-- Name: my_referral_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_referral_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid text := auth.uid()::text;
  v_total integer; v_last30 integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  SELECT count(*),
         count(*) FILTER (WHERE u.created_at >= now() - interval '30 days')
    INTO v_total, v_last30
    FROM users u
   WHERE u.referred_by_store = v_uid AND u.deleted_at IS NULL;
  RETURN jsonb_build_object('total', coalesce(v_total, 0), 'last30', coalesce(v_last30, 0));
END $$;


--
-- Name: notify_shops_closing_soon(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_shops_closing_soon() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now  bigint := (EXTRACT(EPOCH FROM NOW())*1000)::bigint;
  v_count int := 0; r record; v_wh jsonb; v_os jsonb; v_mins int; v_item text; v_shop text;
BEGIN
  FOR r IN SELECT b.* FROM public.bookings b
           WHERE b.status IN ('pending','acknowledged')
             AND COALESCE(b.closing_warned,false) = false
             AND b.expiry_time > v_now
  LOOP
    SELECT working_hours INTO v_wh FROM public.users WHERE id = r.store_id;
    IF v_wh IS NULL THEN CONTINUE; END IF;
    v_os := public.store_is_open(v_wh);
    IF COALESCE((v_os->>'configured')::boolean,false)
       AND COALESCE((v_os->>'open')::boolean,false)
       AND (v_os->>'closes_in_min') IS NOT NULL THEN
      v_mins := (v_os->>'closes_in_min')::int;
      IF v_mins > 0 AND v_mins <= 60 THEN
        SELECT item_name, shop_name INTO v_item, v_shop FROM public.deals WHERE id = r.deal_id;
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (r.user_id,
          '🔔 محل ' || COALESCE(v_shop,'التاجر') || ' على وشك الإغلاق',
          '🔔 ' || COALESCE(v_shop,'The shop') || ' is about to close',
          'محل ' || COALESCE(v_shop,'التاجر') || ' سيغلق بعد ' || v_mins || ' دقيقة — يُرجى استلام طلب ' || COALESCE(v_item,'حجزك') || ' قبل الإغلاق.',
          COALESCE(v_shop,'The shop') || ' closes in ' || v_mins || ' minutes — please collect your order for ' || COALESCE(v_item,'your booking') || ' before it closes.',
          'booking', jsonb_build_object('audience','buyer','event','closing_soon','barcode',r.barcode,'dealId',r.deal_id), NOW());
        UPDATE public.bookings SET closing_warned = true WHERE barcode = r.barcode;
        v_count := v_count + 1;
      END IF;
    END IF;
  END LOOP;
  RETURN v_count;
END; $$;


--
-- Name: notify_subscription_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_subscription_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s jsonb; v_tax jsonb; v_name text;
  v_vat_on boolean; v_rate numeric; v_incl boolean;
  v_gross numeric; v_vat numeric; v_net numeric; v_total numeric;
  v_entity text; v_period text; v_title text; v_body text; v_html text;
  vars jsonb;
BEGIN
  IF NEW.merchant_id IS NOT NULL AND (
       (TG_OP = 'INSERT' AND NEW.status = 'paid')
    OR (TG_OP = 'UPDATE' AND NEW.status = 'paid' AND OLD.status IS DISTINCT FROM 'paid')
  ) THEN
    s := public.taki_msg_setting('sub_new');
    IF NOT COALESCE((s->>'enabled')::boolean, true)
       OR NOT COALESCE((s->'channels'->>'email')::boolean, false) THEN
      RETURN NEW;   -- in-app activation notice comes from the store_profiles trigger
    END IF;

    SELECT u.name INTO v_name FROM users u WHERE u.id = NEW.merchant_id;
    vars := jsonb_build_object(
      'store',   COALESCE(v_name,''),
      'plan',    COALESCE(NEW.plan_id, CASE WHEN COALESCE(NEW.branches_count,0) > 0
                       THEN 'باقة حتى ' || NEW.branches_count || ' مواقع' ELSE 'اشتراك تاكي' END),
      'price',   trim(to_char(COALESCE(NEW.amount,0), 'FM999999990.00')),
      'expires', COALESCE(to_char(NEW.period_end, 'YYYY-MM-DD'), '—'));
    v_title := public.taki_render_template(s->>'title_ar', vars);
    v_body  := public.taki_render_template(s->>'body_ar',  vars);

    IF COALESCE((s->>'email_invoice')::boolean, true) THEN
      v_tax    := COALESCE((SELECT value FROM platform_settings WHERE key = 'tax_settings'), '{}'::jsonb);
      v_vat_on := COALESCE((v_tax->>'vat_enabled')::boolean, false);
      v_rate   := COALESCE(NULLIF(v_tax->>'vat_rate','')::numeric, 15);
      v_incl   := COALESCE((v_tax->>'prices_include_vat')::boolean, true);
      v_entity := COALESCE(NULLIF(v_tax->>'entity_name',''), 'TAKI — تاكي');
      v_gross  := COALESCE(NEW.amount, 0);
      v_vat    := CASE WHEN v_vat_on THEN
                    CASE WHEN v_incl THEN round(v_gross * v_rate / (100 + v_rate), 2)
                         ELSE round(v_gross * v_rate / 100, 2) END
                  ELSE 0 END;
      v_net    := CASE WHEN v_incl THEN v_gross - v_vat ELSE v_gross END;
      v_total  := CASE WHEN v_incl THEN v_gross ELSE v_gross + v_vat END;
      v_period := CASE WHEN NEW.period_start IS NOT NULL AND NEW.period_end IS NOT NULL
                    THEN to_char(NEW.period_start,'YYYY-MM-DD') || ' ← ' || to_char(NEW.period_end,'YYYY-MM-DD')
                    ELSE '—' END;
      v_html := '<p>' || replace(v_body, E'\n', '<br>') || '</p>'
        || '<div style="border:1px solid #e5e7eb;border-radius:12px;padding:16px;margin-top:14px;background:#fafafa;">'
        || '<div style="font-weight:800;font-size:15px;margin-bottom:8px;">🧾 '
        || CASE WHEN v_vat_on AND COALESCE(v_tax->>'vat_number','') <> '' THEN 'فاتورة ضريبية' ELSE 'فاتورة' END /* v13.37 */
        || '</div>'
        || '<div style="font-size:12px;color:#6b7280;margin-bottom:10px;">' || v_entity
        || CASE WHEN COALESCE(v_tax->>'cr_number','') <> '' THEN ' — سجل/وثيقة: ' || (v_tax->>'cr_number') ELSE '' END
        || CASE WHEN v_vat_on AND COALESCE(v_tax->>'vat_number','') <> '' THEN ' — الرقم الضريبي: ' || (v_tax->>'vat_number') ELSE '' END
        || '</div>'
        || '<table style="width:100%;border-collapse:collapse;font-size:13px;">'
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">رقم الفاتورة</td><td style="border:1px solid #e5e5e5;padding:7px 10px;font-weight:700;">INV-' || NEW.id || '</td></tr>'
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">التاريخ</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">' || to_char(COALESCE(NEW.paid_at, NEW.created_at) AT TIME ZONE 'Asia/Riyadh', 'YYYY-MM-DD HH24:MI') || '</td></tr>'
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">العميل (التاجر)</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">' || COALESCE(v_name,'—') || '</td></tr>'
        || CASE WHEN COALESCE((SELECT vat_number FROM store_profiles WHERE store_id = NEW.merchant_id), '') <> ''
             THEN '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">الرقم الضريبي للعميل</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">' || (SELECT vat_number FROM store_profiles WHERE store_id = NEW.merchant_id) || '</td></tr>'
             ELSE '' END
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">البيان</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">اشتراك باقة مواقع'
        || CASE WHEN COALESCE(NEW.branches_count,0) > 0 THEN ' (' || NEW.branches_count || ' مواقع)' ELSE '' END
        || ' — الفترة: ' || v_period || '</td></tr>'
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">الصافي</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">' || trim(to_char(v_net,'FM999999990.00')) || ' ر.س</td></tr>'
        || CASE WHEN v_vat_on THEN '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">ضريبة القيمة المضافة (' || trim(to_char(v_rate,'FM990.00')) || '%)</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">' || trim(to_char(v_vat,'FM999999990.00')) || ' ر.س</td></tr>' ELSE '' END
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;background:#fffbe6;font-weight:800;">الإجمالي</td><td style="border:1px solid #e5e5e5;padding:7px 10px;background:#fffbe6;font-weight:800;">' || trim(to_char(v_total,'FM999999990.00')) || ' ر.س</td></tr>'
        || '</table>'
        || '<div style="font-size:11px;color:#9ca3af;margin-top:8px;">للنسخة الرسمية القابلة للطباعة (مع رمز QR): صفحة الاشتراك ← «🧾 فواتيري».</div>'
        || '</div>';
      PERFORM public.taki_queue_email(NEW.merchant_id, 'sub_new', v_title, public.taki_email_wrap(v_title, v_html));
    ELSE
      PERFORM public.taki_queue_email(NEW.merchant_id, 'sub_new', v_title,
          public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
    END IF;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'notify_subscription_invoice: %', SQLERRM;
  RETURN NEW;
END $$;


--
-- Name: pay_provider_on(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_provider_on(p_provider text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT (value ->> p_provider)::boolean FROM public.platform_settings WHERE key = 'enabled_pay_providers'),
    false);
$$;


--
-- Name: pending_rating_prompts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_rating_prompts() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'barcode',      t.barcode,
           'deal_id',      t.deal_id,
           'store_id',     t.store_id,
           'shop_name',    t.shop_name,
           'completed_at', t.completed_at,
           'has_rating',   t.has_rating,
           'has_vote',     t.has_vote) ORDER BY t.completed_at DESC), '[]'::jsonb)
  FROM (
    SELECT b.barcode, b.deal_id, b.store_id, b.completed_at,
           coalesce(d.shop_name, nullif(u.shop,''), u.name) AS shop_name,
           EXISTS (SELECT 1 FROM public.ratings r
                    WHERE r.user_id = b.user_id AND r.store_id = b.store_id AND r.deleted_at IS NULL) AS has_rating,
           EXISTS (SELECT 1 FROM public.deal_authenticity_votes v
                    WHERE v.user_id = b.user_id AND v.deal_id = b.deal_id) AS has_vote
      FROM public.bookings b
      LEFT JOIN public.deals d ON d.id = b.deal_id
      LEFT JOIN public.users u ON u.id = b.store_id
     WHERE b.user_id = auth.uid()::text
       AND b.status = 'completed'
       AND b.completed_at >= now() - interval '7 days'
       AND d.id IS NOT NULL
     ORDER BY b.completed_at DESC
     LIMIT 20
  ) t
  WHERE NOT (t.has_rating AND t.has_vote);
$$;


--
-- Name: prune_analytics_events(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_analytics_events(p_keep_days integer DEFAULT 180) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_count BIGINT;
BEGIN
    DELETE FROM store_analytics_events
     WHERE created_at < NOW() - (p_keep_days || ' days')::interval;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


--
-- Name: prune_push_subscriptions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_push_subscriptions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n integer;
BEGIN
  DELETE FROM public.push_subscriptions
   WHERE coalesce(last_used_at, created_at) < now() - interval '90 days';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END
$$;


--
-- Name: purge_expired_accounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_accounts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n integer := 0; r record; v_mask text;
BEGIN
  FOR r IN
    SELECT id FROM public.users
     WHERE purge_after IS NOT NULL AND purge_after < now()
       AND COALESCE(is_anonymized, false) = false
  LOOP
    v_mask := 'deleted+' || substr(md5(r.id), 1, 12) || '@takisa.invalid';

    -- (أ) الصفّ العامّ
    UPDATE public.users
       SET name = 'مستخدم محذوف',
           shop = NULL, bio = NULL, address = NULL, avatar_url = NULL,
           phone = NULL, contact_phone = NULL,
           email = v_mask,
           lat = NULL, lng = NULL,
           delivery_address = NULL,
           notif_keywords = NULL, smart_alerts = NULL, followed_merchants = NULL,
           telegram_id = NULL, telegram_chat_id = NULL, whatsapp_chat_id = NULL,
           telegram_link_otp = NULL, telegram_link_otp_expires_at = NULL,
           consent_ip = NULL, consent_user_agent = NULL,
           is_anonymized = true, anonymized_at = now(),
           purge_after = NULL
     WHERE id = r.id;

    -- (ب) صفّ المصادقة **وهويّاته**. 🪤 v14.22 نظّفت `auth.users` وحدها، و
    --     `auth.identities.identity_data` تحمل البريد والاسم والجوال والعنوان.
    BEGIN
      UPDATE auth.users
         SET email = v_mask, phone = NULL, encrypted_password = '',
             raw_user_meta_data = '{}'::jsonb,
             email_change = NULL, phone_change = NULL
       WHERE id::text = r.id;
      UPDATE auth.identities
         SET identity_data = jsonb_build_object('sub', r.id, 'email', v_mask)
       WHERE user_id::text = r.id;
      DELETE FROM auth.refresh_tokens WHERE user_id = r.id;
      DELETE FROM auth.sessions WHERE user_id::text = r.id;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'auth scrub skipped for %: %', r.id, SQLERRM;
    END;

    -- (ج) ما يحمل هويّته خارج صفّه
    DELETE FROM public.user_addresses     WHERE user_id = r.id;
    DELETE FROM public.push_subscriptions WHERE user_id = r.id;
    DELETE FROM public.delivery_tracks    WHERE user_id = r.id;
    DELETE FROM public.email_outbox       WHERE user_id = r.id;
    DELETE FROM public.notifications      WHERE user_id = r.id;
    UPDATE public.ratings SET user_name = 'مستخدم محذوف' WHERE user_id = r.id;

    -- (د) الطلبات تبقى سجلّاً للتاجر، بلا اسم ولا جوال ولا ما يقود لبيته
    UPDATE public.bookings
       SET user_name = NULL, user_phone = NULL,
           delivery_address = CASE
             WHEN delivery_address IS NULL THEN NULL
             ELSE delivery_address - 'phone' - 'details' - 'lat' - 'lng' END
     WHERE user_id = r.id;

    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END
$$;


--
-- Name: record_analytics_events(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_analytics_events(p_events jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_count INTEGER := 0;
  v_uid   TEXT := auth.uid()::text;
BEGIN
  IF p_events IS NULL OR jsonb_typeof(p_events) <> 'array' OR jsonb_array_length(p_events) = 0 THEN
    RETURN 0;
  END IF;
  IF jsonb_array_length(p_events) > 50 THEN
    RAISE EXCEPTION 'batch too large';
  END IF;

  INSERT INTO public.store_analytics_events (
    store_id, deal_id, user_id, session_id, event_type, duration_ms, metadata, created_at
  )
  SELECT
    ev->>'store_id',
    NULLIF(ev->>'deal_id',''),
    v_uid,                                    -- تختمه القاعدة، ولا يُصدَّق ما يرسله العميل
    NULLIF(ev->>'session_id',''),
    ev->>'event_type',
    NULLIF(ev->>'duration_ms','')::int,
    COALESCE(ev->'metadata','{}'::jsonb),
    -- لا نثق بطابع العميل مطلقاً: نقبله فقط داخل نافذة ±١٠ دقائق من الآن،
    -- وإلا نستخدم وقت الخادم — فلا يستطيع أحد حقن أحداث بتواريخ ماضية/مستقبلية.
    CASE
      WHEN (ev->>'created_at')::timestamptz BETWEEN now() - interval '10 minutes'
                                                AND now() + interval '10 minutes'
      THEN (ev->>'created_at')::timestamptz
      ELSE now()
    END
  FROM jsonb_array_elements(p_events) AS ev
  WHERE NULLIF(ev->>'store_id','') IS NOT NULL
    AND ev->>'event_type' IN ('deal_view','deal_click','click_favorite','click_share',
                              'booking_started','booking_completed','booking_abandoned','time_on_page');

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END
$$;


--
-- Name: record_subscription_payment(numeric, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_subscription_payment(p_amount numeric, p_days integer, p_max integer, p_plan_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text := auth.uid()::text; v_id text; v_plan_id text;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
  IF p_amount IS NULL OR p_amount < 0 THEN RETURN jsonb_build_object('success', false, 'error', 'bad_amount'); END IF;
  SELECT id INTO v_plan_id FROM subscription_plans
   WHERE id = p_plan_label OR code = p_plan_label OR name_ar = p_plan_label OR name_en = p_plan_label
   LIMIT 1;
  INSERT INTO subscription_payments (merchant_id, plan_id, amount, currency, status, payment_method, gateway_provider, branches_count, period_start, period_end, paid_at, metadata)
  VALUES (v_uid, v_plan_id, round(p_amount, 2), 'SAR', 'paid', 'web', 'simulated', p_max,
          NOW(), NOW() + (greatest(coalesce(p_days,30),1)::text || ' days')::interval, NOW(),
          jsonb_build_object('source','web','plan_label',p_plan_label))
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('success', true, 'payment_id', v_id);
END $$;


--
-- Name: record_user_consent(text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_user_consent(p_terms_version text, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_kind text DEFAULT 'terms'::text, p_min_age integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me   text := (SELECT auth.uid()::text);
  v_ip   text;
  v_prev text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('changed', false, 'error', 'AUTH_REQUIRED'); END IF;

  -- العنوان من الترويسة لا من العميل: ما يُمرّره المتصفّح عن نفسه ليس دليلاً.
  BEGIN
    v_ip := NULLIF(split_part(COALESCE(
      current_setting('request.headers', true)::json->>'x-forwarded-for',
      current_setting('request.headers', true)::json->>'x-real-ip', ''), ',', 1), '');
  EXCEPTION WHEN OTHERS THEN v_ip := NULL; END;
  v_ip := COALESCE(btrim(v_ip), NULLIF(btrim(COALESCE(p_ip, '')), ''));

  IF p_kind = 'gateway' THEN
    UPDATE public.users
       SET gateway_agreement_version = p_terms_version,
           gateway_agreement_at = now()
     WHERE id = v_me;
    RETURN jsonb_build_object('changed', true, 'kind', 'gateway');
  END IF;

  SELECT consent_terms_version INTO v_prev FROM public.users WHERE id = v_me;
  IF v_prev IS NOT DISTINCT FROM p_terms_version AND p_min_age IS NULL THEN
    RETURN jsonb_build_object('changed', false);
  END IF;

  UPDATE public.users
     SET consent_terms_at      = now(),
         consent_privacy_at    = now(),
         consent_refund_at     = now(),
         consent_terms_version = p_terms_version,
         consent_ip            = COALESCE(v_ip, consent_ip),
         consent_user_agent    = COALESCE(NULLIF(btrim(COALESCE(p_user_agent, '')), ''), consent_user_agent),
         consent_age_confirmed = CASE WHEN p_min_age IS NOT NULL THEN true ELSE consent_age_confirmed END,
         consent_min_age       = COALESCE(p_min_age, consent_min_age)
   WHERE id = v_me;

  RETURN jsonb_build_object('changed', true, 'kind', 'terms', 'ip_recorded', v_ip IS NOT NULL);
END
$$;


--
-- Name: request_booking_refund(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_booking_refund(p_barcode text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me   text := (SELECT auth.uid()::text);
  v_b    public.bookings%ROWTYPE;
  v_amt  numeric;
  v_cur  public.booking_refunds%ROWTYPE;
  v_shop text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;
  IF v_me <> v_b.user_id THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_BUYER'); END IF;
  IF v_b.paid_at IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_PAID'); END IF;

  SELECT * INTO v_cur FROM public.booking_refunds WHERE barcode = v_b.barcode;
  IF FOUND AND v_cur.status IN ('requested','approved','refunded') THEN
    RETURN jsonb_build_object('ok', true, 'already', true, 'status', v_cur.status);
  END IF;

  v_amt := round(COALESCE(NULLIF(v_b.paid_amount, 0), v_b.total_amount, 0), 2);

  INSERT INTO public.booking_refunds (barcode, store_id, buyer_id, status, opened_by, amount, reason)
  VALUES (v_b.barcode, v_b.store_id, v_b.user_id, 'requested', 'buyer', v_amt,
          NULLIF(left(btrim(COALESCE(p_reason, '')), 600), ''))
  ON CONFLICT (barcode) DO UPDATE
    SET status = 'requested', opened_by = 'buyer', amount = EXCLUDED.amount,
        reason = EXCLUDED.reason, requested_at = now(),
        decided_at = NULL, decided_by = NULL, merchant_note = NULL, updated_at = now();

  SELECT COALESCE(NULLIF(u.shop,''), u.name) INTO v_shop FROM public.users u WHERE u.id = v_b.store_id;

  PERFORM public._refund_notify(v_b.store_id,
    '↩️ طلب إلغاء واسترداد', 'Refund request',
    'طلب المشتري إلغاء الطلب ' || v_b.barcode || ' واسترداد ' || trim(to_char(v_amt,'FM999999990.09')) || ' ر.س. القرار لك وفق سياستك المعلنة — من لوحتك.',
    'The buyer asked to cancel order ' || v_b.barcode || ' and be refunded ' || trim(to_char(v_amt,'FM999999990.09')) || ' SAR. The decision is yours under your published policy.',
    v_b.barcode, 'seller', 'refund_requested');

  PERFORM public._refund_notify(v_b.user_id,
    '↩️ وصل طلبك للتاجر', 'Your request was sent',
    'أرسلنا طلب الإلغاء والاسترداد للطلب ' || v_b.barcode || ' إلى «' || COALESCE(v_shop,'المتجر') || '». القرار والتنفيذ عليه وفق سياسته المعلنة — تاكي وسيط لا تحتفظ بالمال ولا تبتّ فيه.',
    'Your cancellation and refund request for order ' || v_b.barcode || ' was sent to "' || COALESCE(v_shop,'the store') || '". The decision and the payment are theirs under their published policy — TAKI is an intermediary and never holds the money.',
    v_b.barcode, 'buyer', 'refund_requested');

  RETURN jsonb_build_object('ok', true, 'status', 'requested', 'amount', v_amt);
END
$$;


--
-- Name: resolve_booking_refund(text, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_booking_refund(p_barcode text, p_action text, p_note text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric, p_ref text DEFAULT NULL::text, p_method text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me        text := (SELECT auth.uid()::text);
  v_b         public.bookings%ROWTYPE;
  v_r         public.booking_refunds%ROWTYPE;
  v_admin     boolean;
  v_amt       numeric;
  v_seq       integer;
  v_cn        text;
  v_shop      text;
  v_money     text;
  v_cancelled boolean := false;
  v_rows      integer;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  v_admin := public.is_admin();

  -- v14.21 — قفل صفّ الحجز. بدونه يسبق «استلمتُ طلبي» تأكيدَ الردّ فيقرأ هذا
  -- النداء حالةً قديمة، فيُصدر إشعاراً دائناً ويقول «أُلغي الطلب» ولا إلغاء وقع.
  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode)) FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;
  IF v_me <> v_b.store_id AND NOT v_admin THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_MERCHANT');
  END IF;
  IF v_b.paid_at IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_PAID'); END IF;

  SELECT COALESCE(NULLIF(u.shop,''), u.name) INTO v_shop FROM public.users u WHERE u.id = v_b.store_id;

  -- v14.21 — الحارس **قبل** كل فرع. كان بعد فرع `open`، فيُعاد فتح استرداد
  -- مُغلق ثم يُصدَر له إشعار دائن ثانٍ ويُهدر رقم من سلسلة التاجر.
  SELECT * INTO v_r FROM public.booking_refunds WHERE barcode = v_b.barcode FOR UPDATE;
  IF FOUND AND v_r.status = 'refunded' THEN
    RETURN jsonb_build_object('ok', true, 'already', true, 'status', 'refunded',
                              'credit_note_no', v_r.credit_note_no);
  END IF;

  -- ── التاجر يفتحها بنفسه: يُسجَّل الدَّين ثم يُثبته لاحقاً بمرجع ──────────
  IF p_action = 'open' THEN
    v_amt := round(COALESCE(NULLIF(v_b.paid_amount, 0), v_b.total_amount, 0), 2);
    INSERT INTO public.booking_refunds (barcode, store_id, buyer_id, status, opened_by, amount, merchant_note)
    VALUES (v_b.barcode, v_b.store_id, v_b.user_id, 'approved',
            CASE WHEN v_admin AND v_me <> v_b.store_id THEN 'admin' ELSE 'seller' END,
            v_amt, NULLIF(left(btrim(COALESCE(p_note,'')), 600), ''))
    ON CONFLICT (barcode) DO UPDATE
      SET status = 'approved', merchant_note = EXCLUDED.merchant_note,
          decided_at = now(), decided_by = v_me, updated_at = now();

    -- v14.21 — الصياغة تطابق الشاشة: الطلب **ما زال قائماً** حتى يؤكّد التاجر
    -- التحويل. كانت تقول «ألغى التاجر طلبك» بينما الرمز ما زال قابلاً للمسح.
    PERFORM public._refund_notify(v_b.user_id,
      '↩️ أقرّ التاجر إلغاء طلبك واستردادك', 'The merchant approved cancelling your order and refunding you',
      'أقرّ «' || COALESCE(v_shop,'المتجر') || '» إلغاء الطلب ' || v_b.barcode
        || COALESCE(' (' || NULLIF(btrim(COALESCE(p_note,'')), '') || ')', '')
        || '، والمبلغ ' || trim(to_char(v_amt,'FM999999990.09')) || ' ر.س مستحقّ لك منه. '
        || 'يبقى الطلب في «حجوزاتي» حتى يؤكّد التاجر التحويل، وعندها يُغلق ويصلك إشعار بالمرجع.',
      '"' || COALESCE(v_shop,'The store') || '" approved cancelling order ' || v_b.barcode
        || '. A refund of ' || trim(to_char(v_amt,'FM999999990.09')) || ' SAR is due to you from the merchant. '
        || 'The order stays in «My Bookings» until they confirm the transfer.',
      v_b.barcode, 'buyer', 'refund_approved');

    RETURN jsonb_build_object('ok', true, 'status', 'approved', 'amount', v_amt);
  END IF;

  IF NOT FOUND OR v_r.barcode IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'NO_REQUEST'); END IF;

  -- ── رفض ──────────────────────────────────────────────────────────────────
  IF p_action = 'decline' THEN
    UPDATE public.booking_refunds
       SET status = 'declined', decided_at = now(), decided_by = v_me,
           merchant_note = NULLIF(left(btrim(COALESCE(p_note,'')), 600), ''), updated_at = now()
     WHERE barcode = v_b.barcode;

    PERFORM public._refund_notify(v_b.user_id,
      '↩️ ردّ التاجر على طلب الاسترداد', 'The merchant responded to your refund request',
      'اعتذر «' || COALESCE(v_shop,'المتجر') || '» عن الاسترداد للطلب ' || v_b.barcode || ' وفق سياسته المعلنة.'
        || COALESCE(' السبب: ' || NULLIF(btrim(COALESCE(p_note,'')), ''), '')
        || ' طلبك ما زال قائماً. وإن رأيت في ذلك مخالفة لسياسته المعلنة فارفع شكوى من «📣 الشكاوى» — تاكي تُيسّر التواصل ولا تبتّ في السياسات.',
      '"' || COALESCE(v_shop,'The store') || '" declined the refund for order ' || v_b.barcode || ' under its published policy. Your order still stands.',
      v_b.barcode, 'buyer', 'refund_declined');

    RETURN jsonb_build_object('ok', true, 'status', 'declined');
  END IF;

  -- ── تثبيت ردّ المال ──────────────────────────────────────────────────────
  IF p_action <> 'refund' THEN RETURN jsonb_build_object('ok', false, 'error', 'BAD_ACTION'); END IF;

  v_amt := round(COALESCE(p_amount, v_r.amount, 0), 2);
  IF NOT (v_amt > 0) THEN RETURN jsonb_build_object('ok', false, 'error', 'ZERO_AMOUNT'); END IF;

  INSERT INTO public.store_invoice_counters (store_id, last_credit_seq)
  VALUES (v_b.store_id, 1)
  ON CONFLICT (store_id) DO UPDATE
    SET last_credit_seq = public.store_invoice_counters.last_credit_seq + 1, updated_at = now()
  RETURNING last_credit_seq INTO v_seq;
  v_cn := 'CN-' || lpad(v_seq::text, 6, '0');

  UPDATE public.booking_refunds
     SET status = 'refunded', decided_at = COALESCE(decided_at, now()), decided_by = v_me,
         merchant_note = COALESCE(NULLIF(left(btrim(COALESCE(p_note,'')), 600), ''), merchant_note),
         refunded_at = now(), refund_amount = v_amt,
         refund_ref = NULLIF(left(btrim(COALESCE(p_ref,'')), 120), ''),
         refund_method = NULLIF(left(btrim(COALESCE(p_method,'')), 40), ''),
         credit_note_no = v_cn, updated_at = now()
   WHERE barcode = v_b.barcode;

  -- الإلغاء وإعادة الكمّية لطلبٍ لم يُستلم بعد. أمّا طلبٌ اكتمل فالبضاعة خرجت
  -- فعلاً: يبقى مكتملاً ولا تعود كمّيته، والرسالة أدناه تقول ذلك بصدق.
  IF v_b.status IN ('pending','acknowledged') THEN
    UPDATE public.bookings SET status = 'cancelled', cancelled_by = 'refund' WHERE barcode = v_b.barcode;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_cancelled := v_rows > 0;
  END IF;

  v_money := trim(to_char(v_amt, 'FM999999990.09'));

  PERFORM public._refund_notify(v_b.user_id,
    '✅ أكّد التاجر ردّ المبلغ', 'The merchant confirmed your refund',
    'أكّد «' || COALESCE(v_shop,'المتجر') || '» ردّ ' || v_money || ' ر.س عن الطلب ' || v_b.barcode
      || COALESCE(' — المرجع: ' || NULLIF(btrim(COALESCE(p_ref,'')), ''), '')
      || '. إشعار دائن رقم ' || v_cn || ' على فاتورتك. مدّة وصول المبلغ لحسابك تحدّدها جهة الدفع لا تاكي.',
    '"' || COALESCE(v_shop,'The store') || '" confirmed a refund of ' || v_money || ' SAR for order ' || v_b.barcode
      || COALESCE(' — reference: ' || NULLIF(btrim(COALESCE(p_ref,'')), ''), '')
      || '. Credit note ' || v_cn || ' is on your invoice.',
    v_b.barcode, 'buyer', 'refund_done');

  PERFORM public._refund_notify(v_b.store_id,
    '✅ سُجِّل ردّ المبلغ', 'Refund recorded',
    'سُجِّل ردّ ' || v_money || ' ر.س عن الطلب ' || v_b.barcode || ' بإشعار دائن ' || v_cn || '. '
      || CASE WHEN v_cancelled
              THEN 'وأُلغي الطلب وعادت الكمّية للبيع.'
              ELSE 'والطلب ' || CASE WHEN v_b.status = 'completed' THEN 'مكتملٌ' ELSE 'مُغلق' END
                   || ' فلم تعد كمّيته للبيع — البضاعة خرجت فعلاً.' END,
    'A refund of ' || v_money || ' SAR for order ' || v_b.barcode || ' was recorded as credit note ' || v_cn || '. '
      || CASE WHEN v_cancelled THEN 'The order was cancelled and the stock returned.'
              ELSE 'The order was already closed, so the stock did not return.' END,
    v_b.barcode, 'seller', 'refund_done');

  RETURN jsonb_build_object('ok', true, 'status', 'refunded', 'amount', v_amt,
                            'credit_note_no', v_cn, 'order_cancelled', v_cancelled);
END
$$;


--
-- Name: restore_my_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_my_account() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_uid text := (auth.uid())::text;
    v_purge timestamptz;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'auth required';
    END IF;
    SELECT purge_after INTO v_purge FROM public.users WHERE id = v_uid;
    IF v_purge IS NULL OR v_purge < now() THEN
        RETURN false;
    END IF;
    UPDATE public.users SET deleted_at = NULL, purge_after = NULL WHERE id = v_uid;
    RETURN true;
END $$;


--
-- Name: resume_subscription(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resume_subscription() RETURNS public.merchant_subscriptions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller TEXT := auth.uid()::text;
    v_row merchant_subscriptions;
BEGIN
    IF v_caller IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT * INTO v_row
    FROM merchant_subscriptions
    WHERE merchant_id = v_caller
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No subscription found for merchant %', v_caller;
    END IF;

    IF v_row.status = 'cancelled' THEN
        RAISE EXCEPTION 'Subscription already terminated; please subscribe again';
    END IF;

    UPDATE merchant_subscriptions
    SET cancel_at_period_end = FALSE,
        updated_at = NOW()
    WHERE merchant_id = v_caller
    RETURNING * INTO v_row;

    RETURN v_row;
END;
$$;


--
-- Name: revoke_subscription(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_subscription(p_merchant_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_role TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Only admins can revoke subscriptions';
    END IF;

    UPDATE merchant_subscriptions
    SET status = 'frozen',
        current_period_end = NOW(),
        grant_expires_at = NOW(),
        updated_at = NOW()
    WHERE merchant_id = p_merchant_id;

    INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type)
    VALUES (p_merchant_id,
        '⚠️ تم تعليق اشتراكك', '⚠️ Your subscription was suspended',
        'تم تعليق اشتراكك من قِبل الإدارة. تواصل معنا لتفعيله مجدداً.',
        'Your subscription was suspended by admin. Contact us to reactivate.',
        'system');
END;
$$;


--
-- Name: seller_order_stats(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seller_order_stats(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_me   text := auth.uid()::text;
  v_days integer := LEAST(GREATEST(COALESCE(p_days, 30), 1), 365);
  v_from timestamptz := ((now() AT TIME ZONE 'Asia/Riyadh')::date - (v_days - 1))::timestamptz;
  v_out  jsonb;
BEGIN
  IF v_me IS NULL THEN RETURN '{}'::jsonb; END IF;

  SELECT jsonb_build_object(
    'lifetime', (
      SELECT jsonb_build_object(
        'orders',       count(*) FILTER (WHERE b.status <> 'cancelled'),
        'all_orders',   count(*),
        'completed',    count(*) FILTER (WHERE b.status = 'completed'),
        'cancelled',    count(*) FILTER (WHERE b.status = 'cancelled'),
        'pending',      count(*) FILTER (WHERE b.status = 'pending'),
        'acknowledged', count(*) FILTER (WHERE b.status = 'acknowledged'),
        'revenue', COALESCE(SUM(COALESCE(d.discounted_price,0) * COALESCE(b.booked_quantity,1))
                            FILTER (WHERE b.status <> 'cancelled'), 0),
        'revenue_completed', COALESCE(SUM(COALESCE(d.discounted_price,0) * COALESCE(b.booked_quantity,1))
                            FILTER (WHERE b.status = 'completed'), 0),
        'savings', COALESCE(SUM(GREATEST(COALESCE(d.original_price,0) - COALESCE(d.discounted_price,0), 0)
                                * COALESCE(b.booked_quantity,1))
                            FILTER (WHERE b.status <> 'cancelled'), 0))
      FROM public.bookings b LEFT JOIN public.deals d ON d.id = b.deal_id AND d.store_id = v_me /* v13.31 */
      WHERE b.store_id = v_me),

    'deals', (
      SELECT jsonb_build_object(
        'total',  count(*), 'active', count(*) FILTER (WHERE d.status = 'active'),
        'views',  COALESCE(SUM(d.views), 0), 'clicks', COALESCE(SUM(d.clicks), 0))
      FROM public.deals d WHERE d.store_id = v_me AND d.status <> 'deleted'),

    'trend', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('d', dd, 'orders', n, 'revenue', rev) ORDER BY dd)
      FROM (SELECT (b.created_at AT TIME ZONE 'Asia/Riyadh')::date AS dd, count(*) AS n,
                   COALESCE(SUM(COALESCE(d.discounted_price,0) * COALESCE(b.booked_quantity,1)), 0) AS rev
            FROM public.bookings b LEFT JOIN public.deals d ON d.id = b.deal_id AND d.store_id = v_me /* v13.31 */
            WHERE b.store_id = v_me AND b.created_at >= v_from AND b.status <> 'cancelled'
            GROUP BY 1) t), '[]'::jsonb),

    'hours', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('h', hh, 'n', n) ORDER BY hh)
      FROM (SELECT EXTRACT(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int AS hh, count(*) AS n
            FROM public.bookings b
            WHERE b.store_id = v_me AND b.status <> 'cancelled'
            GROUP BY 1) t), '[]'::jsonb),

    'top_deals', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', id, 'name', item_name, 'image', img,
                                          'views', views, 'orders', orders, 'revenue', revenue)
             ORDER BY orders DESC, views DESC)
      FROM (SELECT d.id, d.item_name, (d.images)[1] AS img, COALESCE(d.views,0) AS views,
                   count(b.barcode) FILTER (WHERE b.status <> 'cancelled') AS orders,
                   COALESCE(SUM(COALESCE(d.discounted_price,0) * COALESCE(b.booked_quantity,1))
                            FILTER (WHERE b.status <> 'cancelled'), 0) AS revenue
            FROM public.deals d LEFT JOIN public.bookings b ON b.deal_id = d.id
            WHERE d.store_id = v_me AND d.status <> 'deleted'
            GROUP BY d.id, d.item_name, d.images, d.views
            ORDER BY orders DESC, views DESC LIMIT 8) t), '[]'::jsonb),

    'categories', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('cat', cat, 'orders', n) ORDER BY n DESC)
      FROM (SELECT d.category AS cat, count(b.barcode) FILTER (WHERE b.status <> 'cancelled') AS n
            FROM public.deals d LEFT JOIN public.bookings b ON b.deal_id = d.id
            WHERE d.store_id = v_me AND d.status <> 'deleted'
            GROUP BY d.category HAVING count(b.barcode) FILTER (WHERE b.status <> 'cancelled') > 0
            ORDER BY n DESC LIMIT 8) t), '[]'::jsonb),

    -- شرائح الخصم: أي مدى خصمٍ يجلب طلبات أكثر
    'disc_bands', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('band', band, 'n', n) ORDER BY ord)
      FROM (SELECT CASE WHEN d.discount_percentage BETWEEN 1 AND 20  THEN '1-20'
                        WHEN d.discount_percentage BETWEEN 21 AND 40 THEN '21-40'
                        WHEN d.discount_percentage BETWEEN 41 AND 60 THEN '41-60'
                        WHEN d.discount_percentage >= 61             THEN '61+'
                   END AS band,
                   CASE WHEN d.discount_percentage BETWEEN 1 AND 20  THEN 1
                        WHEN d.discount_percentage BETWEEN 21 AND 40 THEN 2
                        WHEN d.discount_percentage BETWEEN 41 AND 60 THEN 3 ELSE 4 END AS ord,
                   count(*) AS n
            FROM public.bookings b JOIN public.deals d ON d.id = b.deal_id AND d.store_id = v_me /* v13.31 */
            WHERE b.store_id = v_me AND b.status <> 'cancelled' AND d.discount_percentage >= 1
            GROUP BY 1, 2) t), '[]'::jsonb),

    'days', v_days
  ) INTO v_out;

  RETURN v_out;
END $$;


--
-- Name: booking_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.booking_messages (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    barcode text NOT NULL,
    sender_id text NOT NULL,
    sender_role text NOT NULL,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    read_at timestamp with time zone,
    recipient_id text,
    attachment_path text,
    CONSTRAINT booking_messages_body_check CHECK (((length(body) > 0) AND (length(body) <= 500))),
    CONSTRAINT booking_messages_sender_role_check CHECK ((sender_role = ANY (ARRAY['buyer'::text, 'seller'::text])))
);


--
-- Name: COLUMN booking_messages.attachment_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.booking_messages.attachment_path IS 'اسم الكائن داخل مستودع chat الخاص (<barcode>/<uuid>.<ext>) — لا عنوان عام. يُقرأ برابط موقّع مؤقّت.';


--
-- Name: send_booking_message(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_booking_message(p_barcode text, p_body text, p_attachment_path text DEFAULT NULL::text) RETURNS public.booking_messages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  caller      text := auth.uid()::text;
  booking_row public.bookings;
  v_role      text;
  sent_count  int;
  inserted    public.booking_messages;
  clean_body  text;
  v_att       text := NULLIF(btrim(COALESCE(p_attachment_path, '')), '');
BEGIN
  IF caller IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول لإرسال الرسالة' USING ERRCODE = '28000';
  END IF;

  clean_body := btrim(p_body);
  -- رسالةٌ بمرفقٍ بلا نصّ مشروعة (صورة تكفي)، لكن الجدول يمنع النصّ الفارغ.
  IF clean_body = '' AND v_att IS NOT NULL THEN clean_body := '📎'; END IF;
  IF clean_body = '' OR length(clean_body) > 500 THEN
    RAISE EXCEPTION 'الرسالة يجب أن تكون بين ١ و ٥٠٠ حرف' USING ERRCODE = 'P0003';
  END IF;

  SELECT * INTO booking_row FROM public.bookings WHERE barcode = p_barcode;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'لم يتم العثور على الحجز' USING ERRCODE = 'P0002';
  END IF;

  IF caller = booking_row.user_id THEN v_role := 'buyer';
  ELSIF caller = booking_row.store_id THEN v_role := 'seller';
  ELSE RAISE EXCEPTION 'ليست لديك صلاحية للكتابة على هذا الحجز' USING ERRCODE = '42501';
  END IF;

  IF booking_row.status IN ('cancelled') THEN
    RAISE EXCEPTION 'الحجز ملغى — لا يمكن إرسال رسائل' USING ERRCODE = 'P0001';
  END IF;

  -- المرفق يُصدَّق على ثلاثة: أنه رُفع فعلاً، وأنه تحت هذا الباركود، وأن
  -- المرسِل هو من رفعه. بلا ذلك يستطيع طرفٌ أن يُشير إلى مرفق محادثةٍ أخرى.
  IF v_att IS NOT NULL THEN
    IF split_part(v_att, '/', 1) <> p_barcode THEN
      RAISE EXCEPTION 'المرفق لا يخصّ هذا الطلب' USING ERRCODE = 'P0017';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM storage.objects o
      WHERE o.bucket_id = 'chat' AND o.name = v_att AND o.owner = auth.uid()
    ) THEN
      RAISE EXCEPTION 'المرفق غير موجود أو ليس لك' USING ERRCODE = 'P0017';
    END IF;
  END IF;

  SELECT COUNT(*) INTO sent_count
  FROM public.booking_messages
  WHERE barcode = p_barcode AND sender_role = v_role;

  IF sent_count >= 3 THEN
    RAISE EXCEPTION 'وصلت الحد الأقصى (٣ رسائل). اتصل بالطرف الآخر مباشرة.' USING ERRCODE = 'P0004';
  END IF;

  INSERT INTO public.booking_messages (barcode, sender_id, sender_role, body, attachment_path)
  VALUES (p_barcode, caller, v_role, clean_body, v_att)
  RETURNING * INTO inserted;

  RETURN inserted;
END $$;


--
-- Name: send_trial_ending_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_trial_ending_notifications() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    seller RECORD;
    deal_stats RECORD;
    notif_id TEXT;
    notif_body_ar TEXT;
    notif_body_en TEXT;
BEGIN
    FOR seller IN 
        SELECT u.id, u.name, sp.subscription_expires_at 
        FROM users u
        JOIN store_profiles sp ON u.id = sp.store_id
        WHERE u.user_type = 'seller'
          AND sp.subscription_plan = 'trial'
          AND sp.subscription_expires_at IS NOT NULL
          AND sp.subscription_expires_at BETWEEN NOW() AND (NOW() + INTERVAL '3 days')
          -- Prevent duplicate warnings by checking if we already sent a trial_warning
          AND NOT EXISTS (
              SELECT 1 FROM notifications n 
              WHERE n.user_id = u.id 
                AND n.type = 'marketing' 
                AND n.meta_data->>'trial_warning' = 'true'
          )
    LOOP
        -- Calculate stats for this seller
        -- 'initial_quantity - quantity' represents bookings if we assume quantity drops on booking.
        -- We will also count total views if available, but for now we aggregate bookings (or simulated views/bookings).
        SELECT 
            COUNT(*) as deals_count,
            -- If initial_quantity exists, calculate bookings. Otherwise use a fallback stat.
            COALESCE(SUM(GREATEST(0, COALESCE(initial_quantity, quantity) - quantity)), 0) as total_bookings
        INTO deal_stats
        FROM deals 
        WHERE store_id = seller.id;

        notif_id := 'n' || extract(epoch from now())::text || substr(md5(random()::text), 1, 5);

        -- Construct personalized smart message
        notif_body_ar := 'لقد حققت عروضك (' || deal_stats.total_bookings || ') عملية حجز خلال الفترة المجانية، لا تدع الأرقام تتوقف! اشترك الآن واستمر في تنمية أعمالك 🚀.';
        notif_body_en := 'Your deals achieved (' || deal_stats.total_bookings || ') bookings during the free trial, don''t let the numbers stop! Subscribe now to continue growing 🚀.';

        INSERT INTO notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
        VALUES (
            notif_id,
            seller.id,
            '⏳ فترتك التجريبية توشك على الانتهاء!',
            '⏳ Your trial is ending soon!',
            notif_body_ar,
            notif_body_en,
            'marketing',
            '{"trial_warning": "true", "actionUrl": "/subscription"}'::jsonb
        );
    END LOOP;
END;
$$;


--
-- Name: send_trial_warnings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_trial_warnings() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_warning_days INTEGER;
    v_count INTEGER := 0;
    rec RECORD;
    v_views INTEGER;
    v_bookings INTEGER;
BEGIN
    v_warning_days := COALESCE((get_setting('trial_warning_days_before', '3'::jsonb))::int, 3);

    FOR rec IN
        SELECT s.merchant_id, s.id AS sub_id, s.trial_ends_at
          FROM merchant_subscriptions s
         WHERE s.status = 'trial'
           AND s.trial_ends_at IS NOT NULL
           AND s.trial_ends_at > NOW()
           AND s.trial_ends_at <= NOW() + (v_warning_days || ' days')::interval
           AND s.last_warning_sent_at IS NULL
    LOOP
        -- Personalised stats for the warning notification.
        SELECT
            COALESCE((SELECT COUNT(*) FROM store_analytics_events
                       WHERE store_id = rec.merchant_id
                         AND event_type IN ('deal_view','page_view')
                         AND created_at >= (SELECT trial_starts_at FROM merchant_subscriptions WHERE id = rec.sub_id)
                     ),0),
            COALESCE((SELECT COUNT(*) FROM bookings
                       WHERE store_id = rec.merchant_id
                         AND created_at >= (SELECT trial_starts_at FROM merchant_subscriptions WHERE id = rec.sub_id)
                     ),0)
        INTO v_views, v_bookings;

        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
        VALUES (rec.merchant_id,
            '🔥 لا تخسر زخم متجرك!', '🔥 Don''t lose your store''s momentum!',
            'حقّقت عروضك ' || v_views || ' مشاهدة و ' || v_bookings ||
              ' عملية حجز خلال الفترة المجانية. تنتهي تجربتك خلال أيام — اشترك الآن لتستمر بالنمو 🚀',
            'Your deals scored ' || v_views || ' views and ' || v_bookings ||
              ' bookings during the trial. It ends in a few days — subscribe now to keep growing 🚀',
            'marketing',
            jsonb_build_object('cta_url','/seller?tab=subscription','views',v_views,'bookings',v_bookings));

        UPDATE merchant_subscriptions SET last_warning_sent_at = NOW() WHERE id = rec.sub_id;
        v_count := v_count + 1;
    END LOOP;

    RETURN v_count;
END;
$$;


--
-- Name: session_heartbeat(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.session_heartbeat(p_page text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_device_type text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id TEXT;
    v_user_type TEXT;
BEGIN
    v_user_id := auth.uid()::text;
    IF v_user_id IS NULL THEN RETURN; END IF;

    SELECT user_type INTO v_user_type FROM users WHERE id = v_user_id;

    INSERT INTO user_sessions (user_id, user_type, current_page, user_agent, device_type, last_seen_at)
    VALUES (v_user_id, v_user_type, p_page, p_user_agent, p_device_type, NOW())
    ON CONFLICT (user_id) DO UPDATE SET
        last_seen_at = NOW(),
        current_page = COALESCE(EXCLUDED.current_page, user_sessions.current_page),
        device_type  = COALESCE(EXCLUDED.device_type, user_sessions.device_type);

    UPDATE users SET last_active_at = NOW() WHERE id = v_user_id;
END $$;


--
-- Name: set_rating_reply(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_rating_reply(p_rating_id text, p_reply text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_uid text := (auth.uid())::text;
    v_store_id text;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'auth required';
    END IF;
    -- Only the seller who owns the deal (or an admin) can reply
    SELECT d.store_id INTO v_store_id FROM public.ratings r
        JOIN public.deals d ON d.id = r.deal_id
        WHERE r.id = p_rating_id AND r.deleted_at IS NULL;
    IF v_store_id IS NULL THEN
        RAISE EXCEPTION 'rating not found';
    END IF;
    IF v_store_id <> v_uid AND NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = v_uid AND u.user_type='admin') THEN
        RAISE EXCEPTION 'forbidden';
    END IF;
    UPDATE public.ratings
        SET reply = NULLIF(trim(p_reply), ''),
            replied_at = CASE WHEN NULLIF(trim(p_reply),'') IS NULL THEN NULL ELSE now() END,
            replied_by = CASE WHEN NULLIF(trim(p_reply),'') IS NULL THEN NULL ELSE v_uid END,
            updated_at = now()
        WHERE id = p_rating_id;
END $$;


--
-- Name: set_rating_store_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_rating_store_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    NEW.store_id := (SELECT store_id FROM deals WHERE id = NEW.deal_id);
    RETURN NEW;
END;
$$;


--
-- Name: soft_delete_my_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.soft_delete_my_account() RETURNS TABLE(deleted_at timestamp with time zone, purge_after timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_uid text := (auth.uid())::text;
    v_now timestamptz := now();
    v_purge timestamptz := now() + interval '30 days';
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'auth required';
    END IF;
    UPDATE public.users
        SET deleted_at = v_now,
            purge_after = v_purge
        WHERE id = v_uid;
    -- Hide all of this user's deals from the public feed during the grace
    -- period. We mark them "paused" so a recovered account can resume them
    -- without losing the data; a real purge later will hard-delete.
    UPDATE public.deals SET status = 'paused' WHERE store_id = v_uid AND status = 'active';
    RETURN QUERY SELECT v_now, v_purge;
END $$;


--
-- Name: start_trial_for_merchant(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_trial_for_merchant(p_merchant_id text) RETURNS public.merchant_subscriptions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_trial_days INTEGER;
    v_basic_plan_id TEXT;
    v_existing merchant_subscriptions;
    v_new merchant_subscriptions;
BEGIN
    -- v12.75: an authenticated caller may only start a trial for HIMSELF
    -- (admins and internal definer/cron chains that carry no other uid pass).
    IF auth.uid() IS NOT NULL AND auth.uid()::text <> p_merchant_id AND NOT is_admin() THEN
        RAISE EXCEPTION 'forbidden';
    END IF;

    SELECT * INTO v_existing FROM merchant_subscriptions WHERE merchant_id = p_merchant_id;
    IF FOUND THEN
        RETURN v_existing;
    END IF;

    v_trial_days := COALESCE((get_setting('trial_days', '14'::jsonb))::int, 14);
    SELECT id INTO v_basic_plan_id FROM subscription_plans WHERE code = 'basic' LIMIT 1;

    INSERT INTO merchant_subscriptions (
        merchant_id, plan_id, status,
        trial_starts_at, trial_ends_at, branches_count
    )
    VALUES (
        p_merchant_id, v_basic_plan_id, 'trial',
        NOW(), NOW() + (v_trial_days || ' days')::interval, 1
    )
    RETURNING * INTO v_new;

    RETURN v_new;
END;
$$;


--
-- Name: store_can_sell(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_can_sell(p_store_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE sp public.store_profiles%ROWTYPE; v_mode text; v_online boolean;
BEGIN
  SELECT * INTO sp FROM public.store_profiles WHERE store_id = p_store_id;
  v_mode := public.deal_payment_mode(p_store_id);
  v_online := v_mode IN ('online','both');
  IF sp.store_id IS NULL OR sp.payment_declared_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_declared',
      'accepts_cod', coalesce(sp.accepts_cod, true), 'online', v_online);
  END IF;
  -- أقرّ ألا نقد ولا بوابة ⇒ لا وسيلة لتحصيل الثمن أصلاً.
  IF NOT coalesce(sp.accepts_cod, true) AND NOT v_online THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_method', 'accepts_cod', false, 'online', false);
  END IF;
  RETURN jsonb_build_object('ok', true, 'accepts_cod', coalesce(sp.accepts_cod, true), 'online', v_online);
END
$$;


