$$;


--
-- Name: store_is_open(jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_is_open(wh jsonb, at_ts timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  loc        timestamp;
  dow        int;
  cur_min    int;
  shifts     jsonb;
  sh         jsonb;
  o_min      int;
  c_min      int;
  open_now   boolean := false;
  closes_in  int := NULL;
  next_min   int := NULL;
  off        int;
  delta      int;
BEGIN
  IF wh IS NULL OR COALESCE((wh->>'enabled')::boolean, false) = false THEN
    RETURN jsonb_build_object('configured', false, 'open', true);
  END IF;
  loc     := at_ts AT TIME ZONE 'Asia/Riyadh';
  dow     := EXTRACT(dow FROM loc)::int;                          -- 0=Sun..6=Sat
  cur_min := EXTRACT(hour FROM loc)::int * 60 + EXTRACT(minute FROM loc)::int;

  -- open right now?
  shifts := wh->'days'->(dow::text);
  IF shifts IS NOT NULL AND jsonb_typeof(shifts) = 'array' THEN
    FOR sh IN SELECT * FROM jsonb_array_elements(shifts) LOOP
      o_min := split_part(sh->>0, ':', 1)::int * 60 + split_part(sh->>0, ':', 2)::int;
      c_min := split_part(sh->>1, ':', 1)::int * 60 + split_part(sh->>1, ':', 2)::int;
      IF cur_min >= o_min AND cur_min < c_min THEN
        open_now := true;
        closes_in := LEAST(COALESCE(closes_in, 2147483647), c_min - cur_min);
      END IF;
    END LOOP;
  END IF;

  IF open_now THEN
    RETURN jsonb_build_object('configured', true, 'open', true, 'closes_in_min', closes_in);
  END IF;

  -- closed now → soonest future opening within the next 8 days
  FOR off IN 0..7 LOOP
    shifts := wh->'days'->(((dow + off) % 7)::text);
    IF shifts IS NOT NULL AND jsonb_typeof(shifts) = 'array' THEN
      FOR sh IN SELECT * FROM jsonb_array_elements(shifts) LOOP
        o_min := split_part(sh->>0, ':', 1)::int * 60 + split_part(sh->>0, ':', 2)::int;
        delta := off * 1440 + o_min - cur_min;
        IF delta > 0 AND (next_min IS NULL OR delta < next_min) THEN
          next_min := delta;
        END IF;
      END LOOP;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('configured', true, 'open', false, 'opens_in_min', next_min);
END $$;


