-- Name: store_policies(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_policies(p_store_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'refund_policy', NULLIF(btrim(COALESCE(sp.refund_policy, '')), ''),
    'store_terms',   NULLIF(btrim(COALESCE(sp.store_terms,   '')), '')))
