$$;


--
-- Name: submit_contest_entry(uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_contest_entry(p_contest_id uuid, p_name text, p_phone text, p_answers jsonb, p_social jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  c record; q jsonb; v_score int := 0; v_max int := 0; v_qual boolean;
  ans text; pts int;
  correct_set jsonb; n_correct int;
  v_uid text := auth.uid()::text;
  v_name text; v_phone text; v_role text;
begin
  if v_uid is null then
    raise exception 'يجب تسجيل الدخول للمشاركة في المسابقة';
  end if;
  -- identity (+ role) from THEIR account; client values are ignored
  select coalesce(nullif(btrim(name), ''), 'مشارك'), nullif(btrim(phone), ''), user_type
    into v_name, v_phone, v_role
  from users where id = v_uid;
  if v_phone is null then
    raise exception 'أكمل رقم جوالك في حسابك أولاً ثم شارك';
  end if;

  select * into c from contests where id = p_contest_id;
  if not found then raise exception 'المسابقة غير موجودة'; end if;
  if c.status <> 'active' then raise exception 'المسابقة غير مفعّلة حالياً'; end if;
  if c.starts_at is not null and now() < c.starts_at then raise exception 'المسابقة لم تبدأ بعد'; end if;
  if c.ends_at  is not null and now() > c.ends_at  then raise exception 'انتهت مدة المسابقة'; end if;

  -- audience gate (admins bypass so the owner can test any audience)
  if v_role is distinct from 'admin' then
    if c.audience = 'sellers' and v_role is distinct from 'seller' then
      raise exception 'هذه المسابقة مخصّصة للتجار فقط';
    end if;
    if c.audience = 'buyers' and v_role = 'seller' then
      raise exception 'هذه المسابقة مخصّصة للمشترين فقط';
    end if;
  end if;

  -- ONE entry per user — no re-submission / no overwrite
  if exists (select 1 from contest_entries e where e.contest_id = p_contest_id and e.phone = v_phone) then
    raise exception 'لقد شاركت في هذه المسابقة من قبل — لكل مشارك محاولة واحدة فقط';
  end if;

  for q in select * from jsonb_array_elements(c.questions) loop
    -- v12.37: multi-correct — correctAnswers[] first, legacy correctAnswer fallback
    correct_set := q->'correctAnswers';
    if correct_set is null or jsonb_typeof(correct_set) <> 'array' then
      correct_set := '[]'::jsonb;
    end if;
    if jsonb_array_length(correct_set) = 0
       and coalesce(btrim(q->>'correctAnswer'), '') <> '' then
      correct_set := jsonb_build_array(q->>'correctAnswer');
    end if;
    select count(*) into n_correct
      from jsonb_array_elements_text(correct_set) v where btrim(v) <> '';
    if n_correct > 0 then
      pts := coalesce(nullif(q->>'points','')::int, 1);
      v_max := v_max + pts;
      ans := p_answers->>(q->>'id');
      if ans is not null and exists (
        select 1 from jsonb_array_elements_text(correct_set) ca
        where btrim(ca) <> '' and lower(btrim(ca)) = lower(btrim(ans))
      ) then
        v_score := v_score + pts;
      end if;
    end if;
  end loop;

  v_qual := case c.pass_mode
    when 'collect' then true
    when 'any'     then (v_score > 0 or v_max = 0)
    else (v_score >= v_max)
  end;

  insert into contest_entries(contest_id, name, phone, answers, social_answers, score, max_score, qualified)
  values (p_contest_id, v_name, v_phone, coalesce(p_answers,'{}'::jsonb), coalesce(p_social,'{}'::jsonb), v_score, v_max, v_qual);

  return jsonb_build_object('qualified', v_qual, 'score', v_score, 'max_score', v_max, 'name', v_name);
end; $$;


--
-- Name: subscribe_self_to_package(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscribe_self_to_package(p_package_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid   text := auth.uid()::text;
  v_role  text;
  v_pkg   jsonb;
  v_price numeric;
  v_disc  numeric;
  v_days  integer;
  v_max   integer;
  v_net   numeric;
  v_now   timestamptz := now();
  v_end   timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  SELECT user_type INTO v_role FROM public.users WHERE id = v_uid;
  IF v_role NOT IN ('seller', 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_a_merchant');
  END IF;

  -- The catalogue is the authority, never the caller.
  SELECT pkg INTO v_pkg
    FROM public.platform_settings ps,
         LATERAL jsonb_array_elements(ps.value) AS pkg
   WHERE ps.key = 'location_packages'
     AND (pkg->>'id')::int = p_package_id
   LIMIT 1;

  IF v_pkg IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown_package');
  END IF;
  IF coalesce((v_pkg->>'active')::boolean, false) IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'package_inactive');
  END IF;

  v_price := coalesce((v_pkg->>'price')::numeric, 0);
  v_disc  := coalesce((v_pkg->>'discount')::numeric, 0);
  v_days  := coalesce((v_pkg->>'durationDays')::int, 30);
  v_max   := coalesce((v_pkg->>'max')::int, 1);
  v_net   := round(v_price * (1 - (v_disc / 100.0)), 2);
  v_end   := v_now + make_interval(days => v_days);

  INSERT INTO public.store_profiles (
    store_id, subscription_plan, subscription_started_at, subscription_expires_at,
    subscription_amount, max_branches, subscription_package_id,
    auto_renew, subscription_canceled_at, updated_at)
  VALUES (
    v_uid, 'premium', v_now, v_end,
    v_net, v_max, p_package_id,
    true, NULL, v_now)
  ON CONFLICT (store_id) DO UPDATE SET
    subscription_plan        = EXCLUDED.subscription_plan,
    subscription_started_at  = EXCLUDED.subscription_started_at,
    subscription_expires_at  = EXCLUDED.subscription_expires_at,
    subscription_amount      = EXCLUDED.subscription_amount,
    max_branches             = EXCLUDED.max_branches,
    subscription_package_id  = EXCLUDED.subscription_package_id,
    auto_renew               = true,
    subscription_canceled_at = NULL,
    updated_at               = EXCLUDED.updated_at;

  RETURN jsonb_build_object(
    'success', true,
    'plan', 'premium',
    'amount', v_net,
    'days', v_days,
    'max_branches', v_max,
    'expires_at', v_end,
    'package_ar', v_pkg->>'ar');
END;
$$;


--
-- Name: sync_auth_lang(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_auth_lang() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_lang text;
BEGIN
  v_lang := CASE WHEN lower(btrim(coalesce(new.preferred_lang, ''))) = 'en'
                 THEN 'en' ELSE 'ar' END;

  UPDATE auth.users au
     SET raw_user_meta_data =
           jsonb_set(coalesce(au.raw_user_meta_data, '{}'::jsonb),
                     '{lang}', to_jsonb(v_lang), true)
   WHERE au.id::text = new.id
     AND coalesce(au.raw_user_meta_data->>'lang', '') IS DISTINCT FROM v_lang;

  RETURN new;
END;
$$;


--
-- Name: sync_branch_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_branch_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_merchant TEXT;
    v_count INTEGER;
BEGIN
    v_merchant := COALESCE(NEW.merchant_id, OLD.merchant_id);
    SELECT COUNT(*) INTO v_count FROM store_branches
     WHERE merchant_id = v_merchant AND is_active = TRUE;
    UPDATE merchant_subscriptions
       SET branches_count = GREATEST(1, v_count), updated_at = NOW()
     WHERE merchant_id = v_merchant;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: taki_booking_amount(text, integer, jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_booking_amount(p_deal_id text, p_quantity integer, p_selected jsonb, p_delivery_fee numeric) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_price   numeric;
  v_opts    jsonb;
  v_vars    jsonb;
  v_sel     jsonb := CASE WHEN jsonb_typeof(COALESCE(p_selected, 'null'::jsonb)) = 'array'
                          THEN p_selected ELSE '[]'::jsonb END;
  v_row     jsonb;
  v_node    jsonb;
  v_base    numeric := 0;
  v_addons  numeric := 0;
  v_variant boolean := false;
  v_dlv     numeric := round(GREATEST(COALESCE(p_delivery_fee, 0), 0), 2);
BEGIN
  SELECT d.discounted_price, d.options, d.variants
    INTO v_price, v_opts, v_vars
    FROM public.deals d WHERE d.id = p_deal_id;

  -- الأساس: مجموع النسخ المختارة (لكلٍّ سعرها)، وإلا سعر العرض × الكمية.
  IF jsonb_typeof(COALESCE(v_vars, 'null'::jsonb)) = 'array' THEN
    FOR v_row IN SELECT * FROM jsonb_array_elements(v_sel) LOOP
      CONTINUE WHEN v_row->>'g' IS DISTINCT FROM '__variant__';
      SELECT e INTO v_node FROM jsonb_array_elements(v_vars) e
        WHERE e->>'id' = v_row->>'c' LIMIT 1;
      CONTINUE WHEN v_node IS NULL;
      v_variant := true;
      v_base := v_base + COALESCE(NULLIF(v_node->>'price','')::numeric, 0)
                       * GREATEST(COALESCE(NULLIF(v_row->>'qty','')::int, 1), 1);
    END LOOP;
  END IF;
  IF NOT v_variant THEN
    v_base := COALESCE(v_price, 0) * GREATEST(COALESCE(p_quantity, 1), 1);
  END IF;

  -- الإضافات: سعر كل خيار × عدد القطع التي اختارته (جبنة +٣ على برغرين = +٦).
  IF jsonb_typeof(COALESCE(v_opts, 'null'::jsonb)) = 'array' THEN
    FOR v_row IN SELECT * FROM jsonb_array_elements(v_sel) LOOP
      CONTINUE WHEN v_row->>'g' = '__variant__';
      SELECT c INTO v_node
        FROM jsonb_array_elements(v_opts) g,
             jsonb_array_elements(CASE WHEN jsonb_typeof(COALESCE(g->'choices','null'::jsonb)) = 'array'
                                       THEN g->'choices' ELSE '[]'::jsonb END) c
       WHERE g->>'id' = v_row->>'g' AND c->>'id' = v_row->>'c' LIMIT 1;
      CONTINUE WHEN v_node IS NULL;
      v_addons := v_addons + COALESCE(NULLIF(v_node->>'price','')::numeric, 0)
                           * GREATEST(COALESCE(NULLIF(v_row->>'qty','')::int, 1), 1);
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'base',     round(v_base, 2),
    'addons',   round(v_addons, 2),
    'goods',    round(v_base + v_addons, 2),
    'delivery', v_dlv,
    'total',    round(v_base + v_addons + v_dlv, 2));
END
$$;


--
-- Name: taki_booking_grace_hours(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_booking_grace_hours() RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT GREATEST(1, LEAST(8760, COALESCE(
    (SELECT (value->>'in_progress_hours')::numeric
       FROM public.platform_settings WHERE key = 'booking_holds' LIMIT 1), 72)));
$$;


--
-- Name: taki_booking_hold_hours(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_booking_hold_hours(p_fulfillment text) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT GREATEST(
    0.25,                                   -- لا تسمح بمهلة أقصر من ١٥ دقيقة مهما ضُبط
    LEAST(
      8760,                                 -- ولا أطول من سنة
      COALESCE(
        (SELECT CASE WHEN COALESCE(p_fulfillment,'pickup') = 'delivery'
                     THEN (value->>'delivery_hours')::numeric
                     ELSE (value->>'pickup_hours')::numeric END
           FROM public.platform_settings WHERE key = 'booking_holds' LIMIT 1),
        CASE WHEN COALESCE(p_fulfillment,'pickup') = 'delivery' THEN 6 ELSE 2 END
      )
    )
  );
$$;


--
-- Name: taki_cancel_abuse_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_cancel_abuse_scan() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s jsonb; v_cats text[]; v_window int; v_thresh int;
  v_cb boolean; v_ct boolean; v_gap int; v_before int; v_action text; v_ban_days int;
  r record; v_warn_count int; v_last timestamptz; v_wid uuid; v_msg text; v_delay int;
BEGIN
  SELECT value INTO s FROM platform_settings WHERE key = 'cancel_abuse_settings';
  IF s IS NULL OR COALESCE((s->>'enabled')::boolean, false) IS NOT TRUE THEN RETURN; END IF;
  v_cats     := COALESCE(ARRAY(SELECT jsonb_array_elements_text(s->'categories')), '{}');
  v_window   := GREATEST(COALESCE((s->>'window_days')::int, 30), 1);
  v_thresh   := GREATEST(COALESCE((s->>'cancel_threshold')::int, 3), 1);
  v_cb       := COALESCE((s->>'count_buyer_cancel')::boolean, true);
  v_ct       := COALESCE((s->>'count_timeout')::boolean, true);
  v_gap      := GREATEST(COALESCE((s->>'warn_gap_hours')::int, 72), 1);
  v_before   := GREATEST(COALESCE((s->>'warnings_before_action')::int, 3), 1);
  v_action   := COALESCE(s->>'action', 'booking_ban');
  v_ban_days := GREATEST(COALESCE((s->>'ban_days')::int, 7), 1);
  v_delay    := COALESCE((SELECT (value->>'warn_delay_minutes')::int FROM platform_settings WHERE key = 'moderation_settings'), 0);

  FOR r IN
    SELECT b.user_id, u.name, count(*) AS n
    FROM bookings b
    JOIN deals d ON d.id = b.deal_id
    JOIN users u ON u.id = b.user_id
    WHERE b.status = 'cancelled'
      AND ((v_cb AND b.cancelled_by = 'buyer') OR (v_ct AND b.cancelled_by = 'timeout'))
      AND b.created_at >= now() - make_interval(days => v_window)
      AND (cardinality(v_cats) = 0 OR d.category = ANY(v_cats))
      AND u.user_type <> 'admin'
      AND COALESCE(u.is_suspended, false) = false
      AND (u.booking_banned_until IS NULL OR u.booking_banned_until < now())
      -- 🔴 v14.32 — العقوبة كانت تُجدّد نفسها إلى ما لا نهاية.
      -- السبب: فحص المهلة وعدّاد الإنذارات يبحثان عن صفوفٍ نصّها يبدأ بـ
      -- «⚠️ إلغاءات متكررة»، بينما صفّ **العقوبة** نصّه يبدأ بـ«⏸️ تم تعليق
      -- الحجز» أو «⛔ تم إيقاف حسابك». فالماسح لا يرى عقوبته السابقة إطلاقاً.
      -- والنتيجة: مشترٍ عوقب ٧ أيام على ثلاثة إلغاءات، يُعاقَب ٧ أيام أخرى
      -- فور انقضائها على **نفس** الإلغاءات، ويتكرّر حتى تخرج من نافذة الثلاثين
      -- يوماً — أي حظرٌ شبه دائم على مخالفةٍ واحدة.
      -- العلاج: لا يُحسب إلا ما وقع **بعد** آخر إجراء. فالعقوبة مرّة لكل مجموعة.
      AND b.created_at > COALESCE((
            SELECT max(w.created_at) FROM user_warnings w
             WHERE w.user_id = b.user_id
               AND (w.reason LIKE '⏸️ تم تعليق الحجز%'
                 OR w.reason LIKE '⛔ تم إيقاف حسابك بسبب تكرار%')
          ), '-infinity'::timestamptz)
    GROUP BY b.user_id, u.name
    HAVING count(*) >= v_thresh
  LOOP
    -- المهلة بين إنذار وإنذار — يحددها المالك
    -- المهلة تُقاس من آخر **أي** إجراء (إنذاراً كان أو عقوبة) لا من آخر إنذار
    -- وحده — وإلا أنذر الماسحُ من عاقبه قبل ساعة.
    SELECT max(created_at) INTO v_last FROM user_warnings
     WHERE user_id = r.user_id
       AND (reason LIKE '⚠️ إلغاءات متكررة%'
         OR reason LIKE '⏸️ تم تعليق الحجز%'
         OR reason LIKE '⛔ تم إيقاف حسابك بسبب تكرار%');
    IF v_last IS NOT NULL AND v_last > now() - make_interval(hours => v_gap) THEN CONTINUE; END IF;

    SELECT count(*) INTO v_warn_count FROM user_warnings
     WHERE user_id = r.user_id AND reason LIKE '⚠️ إلغاءات متكررة%';

    IF v_warn_count < v_before THEN
      v_msg := format('⚠️ إلغاءات متكررة: رصدنا %s حجوزات ملغاة أو غير مستلمة خلال آخر %s يوماً. تكرار ذلك سيؤدي لتعليق الحجز أو إيقاف الحساب. (إنذار %s من %s)', r.n, v_window, v_warn_count + 1, v_before);
      INSERT INTO user_warnings (user_id, user_role, reason, admin_id)
      VALUES (r.user_id, 'buyer', v_msg, NULL) RETURNING id INTO v_wid;
      IF v_delay <= 0 THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
        VALUES (r.user_id, '⚠️ تنبيه من إدارة تاكي', '⚠️ Warning from TAKI', v_msg, v_msg, 'system',
                jsonb_build_object('audience', 'user', 'admin_warning', TRUE));
      ELSE
        INSERT INTO pending_warnings (warning_id, user_id, message, deliver_at)
        VALUES (v_wid, r.user_id, v_msg, now() + make_interval(mins => v_delay));
      END IF;
    ELSE
      IF v_action = 'suspend' THEN
        UPDATE users SET is_suspended = true WHERE id = r.user_id;
        v_msg := '⛔ تم إيقاف حسابك بسبب تكرار إلغاء الحجوزات بعد عدة إنذارات — تواصل مع إدارة تاكي.';
      ELSE
        UPDATE users SET booking_banned_until = now() + make_interval(days => v_ban_days),
                         booking_ban_reason = 'إلغاءات متكررة (آلي)'
         WHERE id = r.user_id;
        v_msg := format('⏸️ تم تعليق الحجز على حسابك لمدة %s أيام بسبب تكرار الإلغاء/عدم الاستلام بعد عدة إنذارات.', v_ban_days);
      END IF;
      INSERT INTO user_warnings (user_id, user_role, reason, admin_id)
      VALUES (r.user_id, 'buyer', v_msg, NULL);
      INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      VALUES (r.user_id, '⛔ إجراء من إدارة تاكي', '⛔ TAKI enforcement', v_msg, v_msg, 'system',
              jsonb_build_object('audience', 'user', 'admin_warning', TRUE));
      INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      SELECT id, '🚫 عقوبة إلغاءات متكررة', '🚫 Cancel-abuse action',
             format('طُبقت عقوبة تلقائية على «%s»: %s', COALESCE(r.name, r.user_id), v_msg),
             'Automatic cancel-abuse action applied', 'system',
             jsonb_build_object('audience', 'admin')
      FROM users WHERE user_type = 'admin';
    END IF;
  END LOOP;
END $$;


