--
-- Name: taki_chat_member(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_chat_member(p_object_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid text := auth.uid()::text;
  v_bc  text;
BEGIN
  IF v_uid IS NULL OR p_object_name IS NULL THEN RETURN false; END IF;
  v_bc := split_part(p_object_name, '/', 1);
  IF v_bc = '' OR v_bc = p_object_name THEN RETURN false; END IF;   -- لا مجلّد ⇒ مرفوض
  RETURN EXISTS (
    SELECT 1 FROM public.bookings b
    WHERE b.barcode = v_bc AND (b.user_id = v_uid OR b.store_id = v_uid)
  );
END $$;


--
-- Name: taki_deliver_warnings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_deliver_warnings() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT * FROM pending_warnings WHERE sent_at IS NULL AND deliver_at <= now() ORDER BY deliver_at LIMIT 50
  LOOP
    INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (r.user_id, '⚠️ تنبيه من إدارة تاكي', '⚠️ Warning from TAKI', r.message, r.message, 'system',
            jsonb_build_object('audience', 'user', 'admin_warning', TRUE));
    UPDATE pending_warnings SET sent_at = now() WHERE id = r.id;
  END LOOP;
END $$;


--
-- Name: taki_dispatch_coming_soon_window(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_dispatch_coming_soon_window() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    deal_rec        public.deals;
    deal_region_id  TEXT;
    deal_city_id    TEXT;
    deal_lat        DOUBLE PRECISION;
    deal_lng        DOUBLE PRECISION;
    nearest_row     public.sa_cities_geo;
    rec             RECORD;
    now_ms          BIGINT;
    window_cutoff   BIGINT;
    processed       INTEGER := 0;
BEGIN
    now_ms        := (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT;
    window_cutoff := now_ms + (7 * 24 * 60 * 60 * 1000);

    -- Cap at 50 per tick. With a 5-minute interval that's 600 deals/hour —
    -- well above any realistic burst. Cap exists so a sudden spike (e.g.
    -- a backfill migration that resets coming_soon_notified_at on
    -- hundreds of rows) can't fan out into thousands of notifications in
    -- a single tick and choke the trigger budget.
    FOR deal_rec IN
        SELECT * FROM public.deals
        WHERE status = 'active'
          AND starts_at IS NOT NULL
          AND coming_soon_notified_at IS NULL
          AND starts_at > now_ms                  -- still in the future
          AND starts_at <= window_cutoff          -- inside the 7-day window
        ORDER BY starts_at ASC
        LIMIT 50
    LOOP
        deal_region_id := deal_rec.region;
        deal_city_id   := deal_rec.city;
        deal_lat       := deal_rec.map_lat;
        deal_lng       := deal_rec.map_lng;

        IF deal_region_id IS NULL OR deal_city_id IS NULL THEN
            SELECT l.city_id, c.region_id,
                   COALESCE(deal_lat, l.lat),
                   COALESCE(deal_lng, l.lng)
            INTO deal_city_id, deal_region_id, deal_lat, deal_lng
            FROM public.locations l
            LEFT JOIN public.cities c ON c.id = l.city_id
            WHERE l.id = deal_rec.location_id;
        END IF;

        IF (deal_region_id IS NULL OR deal_city_id IS NULL)
           AND deal_lat IS NOT NULL AND deal_lng IS NOT NULL
        THEN
            SELECT * INTO nearest_row FROM public.find_nearest_sa_city(deal_lat, deal_lng);
            IF nearest_row.city_id IS NOT NULL THEN
                deal_region_id := COALESCE(deal_region_id, nearest_row.region_id);
                deal_city_id   := COALESCE(deal_city_id,   nearest_row.city_id);
            END IF;
        END IF;

        FOR rec IN
            SELECT id, smart_alerts, followed_merchants
            FROM public.users
            WHERE id <> deal_rec.store_id
              AND deleted_at IS NULL
              -- v13.31 — نفس إصلاح ترغر الإضافة: المعنيّون فقط
              AND ( COALESCE(jsonb_array_length(smart_alerts), 0) > 0
                 OR deal_rec.store_id = ANY(COALESCE(followed_merchants, ARRAY[]::text[])) )
        LOOP
            PERFORM public.taki_dispatch_smart_alert(
                rec.id,
                rec.followed_merchants,
                rec.smart_alerts,
                deal_rec,
                deal_region_id, deal_city_id,
                deal_lat, deal_lng,
                TRUE  -- dedupe: skip if a notification for this (user, deal) already exists
            );
        END LOOP;

        UPDATE public.deals
        SET coming_soon_notified_at = now_ms
        WHERE id = deal_rec.id;

        processed := processed + 1;
    END LOOP;

    RETURN processed;
END;
$$;


--
-- Name: taki_loc_keys(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_loc_keys(p_region text, p_city text, p_location_id text, p_locations jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT COALESCE(
    CASE
      -- عرض متعدد المواقع: مفاتيح كل فرع (نفس قاعدة dealResolvedLocations)
      WHEN jsonb_typeof(p_locations) = 'array' AND jsonb_array_length(p_locations) > 1 THEN
        ARRAY(
          SELECT DISTINCT k
          FROM jsonb_array_elements(p_locations) e
          CROSS JOIN LATERAL (VALUES
            ('r:' || COALESCE(NULLIF(e->>'region',''), '~')),
            ('c:' || COALESCE(NULLIF(e->>'city',''), '~')),
            ('m:' || COALESCE(NULLIF(e->>'locationId',''), '~'))
          ) v(k)
          WHERE k NOT LIKE '%:~'
        )
      ELSE
        ARRAY(
          SELECT DISTINCT k
          FROM (VALUES
            ('r:' || COALESCE(NULLIF(p_region,''), '~')),
            ('c:' || COALESCE(NULLIF(p_city,''), '~')),
            ('m:' || COALESCE(NULLIF(p_location_id,''), '~'))
          ) v(k)
          WHERE k NOT LIKE '%:~'
        )
    END, ARRAY[]::text[]);
$$;


--
-- Name: deals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.deals (
    id text NOT NULL,
    store_id text NOT NULL,
    shop_name text NOT NULL,
    item_name text NOT NULL,
    category text NOT NULL,
    gender text DEFAULT 'all'::text,
    size text,
    original_price numeric NOT NULL,
    discounted_price numeric NOT NULL,
    discount_percentage integer DEFAULT 0 NOT NULL,
    images text[] DEFAULT '{}'::text[],
    description text,
    location_id text,
    custom_location_name text,
    google_maps_link text,
    map_lat double precision,
    map_lng double precision,
    reliability_score integer DEFAULT 100 NOT NULL,
    expires_in_minutes integer DEFAULT 120,
    quantity integer,
    is_unlimited boolean DEFAULT false,
    initial_quantity integer,
    prep_time text,
    status text DEFAULT 'active'::text,
    created_at bigint NOT NULL,
    expiry_hijri text,
    expiry_gregorian text,
    updated_at timestamp with time zone DEFAULT now(),
    city text,
    region text,
    expiry_type text,
    expiry_date text,
    views integer DEFAULT 0,
    clicks integer DEFAULT 0,
    starts_at bigint,
    coming_soon_notified_at bigint,
    subscription_frozen boolean DEFAULT false NOT NULL,
    source text DEFAULT 'web'::text NOT NULL,
    max_per_booking integer,
    max_bookings_per_buyer integer,
    rebook_cooldown_minutes integer,
    season_id text,
    options jsonb,
    variants jsonb,
    pos_sku text,
    locations jsonb,
    loc_qty_mode text,
    name_norm text GENERATED ALWAYS AS (public.taki_norm(((COALESCE(item_name, ''::text) || ' '::text) || COALESCE(shop_name, ''::text)))) STORED,
    search_vec tsvector GENERATED ALWAYS AS ((((setweight(to_tsvector('simple'::regconfig, COALESCE(public.taki_norm(item_name), ''::text)), 'A'::"char") || setweight(to_tsvector('simple'::regconfig, COALESCE(public.taki_norm(shop_name), ''::text)), 'B'::"char")) || setweight(to_tsvector('simple'::regconfig, COALESCE(public.taki_norm(((((COALESCE(category, ''::text) || ' '::text) || COALESCE(size, ''::text)) || ' '::text) || COALESCE(pos_sku, ''::text))), ''::text)), 'C'::"char")) || setweight(to_tsvector('simple'::regconfig, COALESCE(public.taki_norm(description), ''::text)), 'D'::"char"))) STORED,
    auth_real_count integer DEFAULT 0 NOT NULL,
    auth_fake_count integer DEFAULT 0 NOT NULL,
    loc_keys text[] GENERATED ALWAYS AS (public.taki_loc_keys(region, city, location_id, locations)) STORED,
    rating_avg numeric(3,2) DEFAULT 0 NOT NULL,
    rating_count integer DEFAULT 0 NOT NULL,
    bookings_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT deals_expiry_type_check CHECK (((expiry_type IS NULL) OR (expiry_type = ANY (ARRAY['hours'::text, 'duration'::text, 'date'::text, 'stock'::text])))),
    CONSTRAINT deals_source_chk CHECK ((source = ANY (ARRAY['web'::text, 'telegram'::text, 'whatsapp'::text]))),
    CONSTRAINT deals_status_check CHECK ((status = ANY (ARRAY['active'::text, 'expired'::text, 'deleted'::text, 'paused'::text])))
);

ALTER TABLE ONLY public.deals REPLICA IDENTITY FULL;


--
-- Name: COLUMN deals.starts_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deals.starts_at IS 'Scheduled launch (epoch ms). NULL = launches immediately on insert. When set in the future the deal is Coming Soon: surfaced on Home but locked from booking until the timestamp passes.';


--
-- Name: COLUMN deals.coming_soon_notified_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deals.coming_soon_notified_at IS 'Epoch ms when the Coming-Soon window-entry notification was dispatched. NULL = not yet dispatched. Set by tr_coming_soon_window_dispatch. Once set the dispatcher never reconsiders this row, even if starts_at is edited backward — that prevents duplicate buyer-side pings.';


--
-- Name: COLUMN deals.pos_sku; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deals.pos_sku IS 'v12.88 merchant POS SKU/barcode for the base product (printed as scannable barcode on the order receipt)';


--
-- Name: COLUMN deals.locations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deals.locations IS 'v12.91 multi-location list [{id,locationId,name,lat,lng,region,city,quantity,initialQuantity}]; null=single location';


--
-- Name: COLUMN deals.loc_qty_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deals.loc_qty_mode IS 'v12.91 shared=one pool (deals.quantity), per_location=each branch its own quantity';


--
-- Name: COLUMN deals.name_norm; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deals.name_norm IS 'v13.24 — اسم المنتج+المتجر مُطبَّعاً؛ فهرس trgm للبحث الضبابي وبالبادئة.';


--
-- Name: COLUMN deals.search_vec; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deals.search_vec IS 'v13.24 — متجه البحث النصّي الموزون (A اسم/B متجر/C تصنيف/D وصف).';


--
-- Name: COLUMN deals.loc_keys; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deals.loc_keys IS 'v13.24 — مفاتيح r:<منطقة> / c:<مدينة> / m:<مول> لكل فروع العرض؛ تُفلتر بضربة فهرس GIN واحدة.';


--
-- Name: taki_dispatch_smart_alert(text, text[], jsonb, public.deals, text, text, double precision, double precision, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_dispatch_smart_alert(p_user_id text, p_followed_merchants text[], p_smart_alerts jsonb, p_deal public.deals, p_deal_region text, p_deal_city text, p_deal_lat double precision, p_deal_lng double precision, p_skip_existing boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    is_follower         BOOLEAN;
    rule_matched        BOOLEAN := FALSE;
    deal_text           TEXT;
    rule                JSONB;
    rule_idx            INT;
    ok                  BOOLEAN;
    has_any_condition   BOOLEAN;
    this_range          DOUBLE PRECISION;
    this_kw             TEXT;
    kw_ok               BOOLEAN;
    i                   INT;
    kw                  TEXT;
    has_range           BOOLEAN := FALSE;
    range_km_min        DOUBLE PRECISION;
    has_mall            BOOLEAN := FALSE;
    has_city            BOOLEAN := FALSE;
    has_category        BOOLEAN := FALSE;
    cat_first           TEXT;
    has_keyword         BOOLEAN := FALSE;
    kw_first            TEXT;
    has_region          BOOLEAN := FALSE;
    chips_ar            TEXT[] := ARRAY[]::TEXT[];
    chips_en            TEXT[] := ARRAY[]::TEXT[];
    title_ar            TEXT;
    title_en            TEXT;
    body_ar             TEXT;
    body_en             TEXT;
    nkind               TEXT;
    city_name           TEXT;
    mall_name           TEXT;
    chip_count          INT;
    shown_ar            TEXT[];
    shown_en            TEXT[];
    more_n              INT;
    line1_ar            TEXT;
    line1_en            TEXT;
    line2_ar            TEXT;
    line2_en            TEXT;
    line3_ar            TEXT;
    line3_en            TEXT;
    range_num_text      TEXT;
    range_chip_ar       TEXT;
    range_chip_en       TEXT;
    range_title_ar      TEXT;
    range_title_en      TEXT;
    is_coming_soon      BOOLEAN := FALSE;
    now_ms              BIGINT;
    starts_in_days      INT;
    starts_eta_ar       TEXT;
    starts_eta_en       TEXT;
BEGIN
    is_follower := p_followed_merchants IS NOT NULL
                   AND p_deal.store_id = ANY(p_followed_merchants);

    now_ms := (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT;
    IF p_deal.starts_at IS NOT NULL AND p_deal.starts_at > now_ms THEN
        is_coming_soon := TRUE;
        starts_in_days := GREATEST(1, CEIL((p_deal.starts_at - now_ms)::numeric / 86400000.0)::INT);
        IF starts_in_days = 1 THEN
            starts_eta_ar := 'خلال يوم';
            starts_eta_en := 'in 1 day';
        ELSIF starts_in_days = 2 THEN
            starts_eta_ar := 'بعد يومين';
            starts_eta_en := 'in 2 days';
        ELSE
            starts_eta_ar := 'خلال ' || starts_in_days::TEXT || ' أيام';
            starts_eta_en := 'in ' || starts_in_days::TEXT || ' days';
        END IF;
    END IF;

    deal_text := COALESCE(public.taki_norm(
        COALESCE(p_deal.item_name, '')   || ' ' ||
        COALESCE(p_deal.shop_name, '')   || ' ' ||
        COALESCE(p_deal.category, '')    || ' ' ||
        COALESCE(p_deal.description, '')
    ), '');

    IF p_smart_alerts IS NOT NULL
       AND jsonb_typeof(p_smart_alerts) = 'array'
       AND jsonb_array_length(p_smart_alerts) > 0
    THEN
        FOR rule_idx IN 0 .. (jsonb_array_length(p_smart_alerts) - 1) LOOP
            rule              := p_smart_alerts -> rule_idx;
            ok                := TRUE;
            this_range        := NULL;
            this_kw           := NULL;
            has_any_condition := FALSE;

            IF rule ? 'regions' AND jsonb_array_length(rule->'regions') > 0 THEN
                has_any_condition := TRUE;
                IF p_deal_region IS NULL OR NOT (rule->'regions' ? p_deal_region) THEN
                    ok := FALSE;
                END IF;
            END IF;
            IF ok AND rule ? 'cities' AND jsonb_array_length(rule->'cities') > 0 THEN
                has_any_condition := TRUE;
                IF p_deal_city IS NULL OR NOT (rule->'cities' ? p_deal_city) THEN
                    ok := FALSE;
                END IF;
            END IF;
            IF ok AND rule ? 'malls' AND jsonb_array_length(rule->'malls') > 0 THEN
                has_any_condition := TRUE;
                IF p_deal.location_id IS NULL OR NOT (rule->'malls' ? p_deal.location_id) THEN
                    ok := FALSE;
                END IF;
            END IF;
            IF ok AND rule ? 'categories' AND jsonb_array_length(rule->'categories') > 0 THEN
                has_any_condition := TRUE;
                IF p_deal.category IS NULL OR NOT (rule->'categories' ? p_deal.category) THEN
                    ok := FALSE;
                END IF;
            END IF;
            IF ok AND rule ? 'keywords' AND jsonb_array_length(rule->'keywords') > 0 THEN
                has_any_condition := TRUE;
                kw_ok := FALSE;
                FOR i IN 0 .. (jsonb_array_length(rule->'keywords') - 1) LOOP
                    kw := public.taki_norm(rule->'keywords'->>i);
                    IF kw IS NOT NULL AND deal_text LIKE '%' || kw || '%' THEN
                        kw_ok := TRUE;
                        this_kw := rule->'keywords'->>i;
                        EXIT;
                    END IF;
                END LOOP;
                IF NOT kw_ok THEN ok := FALSE; END IF;
            END IF;
            IF ok
               AND rule ? 'coords'
               AND rule->'coords' ? 'lat'
               AND rule->'coords' ? 'lng'
               AND rule ? 'radiusKm'
            THEN
                has_any_condition := TRUE;
                this_range := public.taki_haversine_km(
                    (rule->'coords'->>'lat')::DOUBLE PRECISION,
                    (rule->'coords'->>'lng')::DOUBLE PRECISION,
                    p_deal_lat, p_deal_lng
                );
                IF this_range IS NULL
                   OR this_range > (rule->>'radiusKm')::DOUBLE PRECISION
                THEN
                    ok := FALSE;
                END IF;
            END IF;

            IF NOT has_any_condition THEN
                ok := FALSE;
            END IF;

            IF ok THEN
                rule_matched := TRUE;
                IF rule ? 'regions' AND jsonb_array_length(rule->'regions') > 0 THEN
                    has_region := TRUE;
                END IF;
                IF rule ? 'cities' AND jsonb_array_length(rule->'cities') > 0 THEN
                    has_city := TRUE;
                END IF;
                IF rule ? 'malls' AND jsonb_array_length(rule->'malls') > 0 THEN
                    has_mall := TRUE;
                END IF;
                IF rule ? 'categories' AND jsonb_array_length(rule->'categories') > 0 THEN
                    has_category := TRUE;
                    IF cat_first IS NULL THEN cat_first := p_deal.category; END IF;
                END IF;
                IF rule ? 'keywords' AND jsonb_array_length(rule->'keywords') > 0 THEN
                    has_keyword := TRUE;
                    IF kw_first IS NULL THEN kw_first := this_kw; END IF;
                END IF;
                IF rule ? 'coords' AND rule ? 'radiusKm' THEN
                    has_range := TRUE;
                    IF this_range IS NOT NULL
                       AND (range_km_min IS NULL OR this_range < range_km_min)
                    THEN
                        range_km_min := this_range;
                    END IF;
                END IF;
            END IF;
        END LOOP;
    END IF;

    IF NOT is_follower AND NOT rule_matched THEN
        RETURN FALSE;
    END IF;

    IF p_skip_existing THEN
        IF EXISTS (
            SELECT 1 FROM public.notifications
            WHERE user_id = p_user_id
              AND (meta_data->>'dealId') = p_deal.id::TEXT
              AND type IN ('deal','marketing')
        ) THEN
            RETURN FALSE;
        END IF;
    END IF;

    IF has_city AND p_deal_city IS NOT NULL THEN
        SELECT name INTO city_name FROM public.cities WHERE id = p_deal_city LIMIT 1;
    END IF;
    IF has_mall AND p_deal.location_id IS NOT NULL THEN
        SELECT name INTO mall_name FROM public.locations WHERE id = p_deal.location_id LIMIT 1;
    END IF;

    IF has_range AND range_km_min IS NOT NULL THEN
        IF range_km_min < 0.1 THEN
            range_chip_ar  := '📍 بجانبك تماماً';
            range_chip_en  := '📍 Right next to you';
            range_title_ar := '📍 عرض بجانبك تماماً';
            range_title_en := '📍 A deal right next to you';
        ELSIF range_km_min < 1 THEN
            range_chip_ar  := '📍 أقل من 1 كم منك';
            range_chip_en  := '📍 Under 1 km away';
            range_title_ar := '📍 عرض على بُعد أقل من 1 كم منك';
            range_title_en := '📍 Deal under 1 km from you';
        ELSE
            range_num_text := TRIM(TRAILING '.' FROM
                                   TRIM(TRAILING '0' FROM ROUND(range_km_min::numeric, 1)::TEXT));
            IF range_num_text = '' OR range_num_text IS NULL THEN
                range_num_text := '1';
            END IF;
            range_chip_ar  := '📍 ' || range_num_text || ' كم منك';
            range_chip_en  := '📍 ' || range_num_text || ' km away';
            range_title_ar := '📍 عرض على بُعد ' || range_num_text || ' كم منك';
            range_title_en := '📍 Deal ' || range_num_text || ' km from you';
        END IF;
    END IF;

    IF is_follower THEN
        chips_ar := chips_ar || '🔥 متجر تتابعه'::TEXT;
        chips_en := chips_en || '🔥 Followed store'::TEXT;
    END IF;
    IF has_range THEN
        chips_ar := chips_ar || range_chip_ar;
        chips_en := chips_en || range_chip_en;
    END IF;
    IF has_mall THEN
        chips_ar := chips_ar || ('🏬 ' || COALESCE(mall_name, 'مولك'))::TEXT;
        chips_en := chips_en || ('🏬 ' || COALESCE(mall_name, 'Your mall'))::TEXT;
    END IF;
    IF has_city THEN
        chips_ar := chips_ar || ('🌆 ' || COALESCE(city_name, 'مدينتك'))::TEXT;
        chips_en := chips_en || ('🌆 ' || COALESCE(city_name, 'Your city'))::TEXT;
    END IF;
    IF has_category THEN
        chips_ar := chips_ar || public.taki_category_label_ar(cat_first);
        chips_en := chips_en || public.taki_category_label_en(cat_first);
    END IF;
    IF has_keyword THEN
        chips_ar := chips_ar || ('🔍 «' || kw_first || '»')::TEXT;
        chips_en := chips_en || ('🔍 "' || kw_first || '"')::TEXT;
    END IF;
    IF has_region THEN
        chips_ar := chips_ar || '🌍 منطقتك'::TEXT;
        chips_en := chips_en || '🌍 Your region'::TEXT;
    END IF;
    IF is_coming_soon THEN
        chips_ar := chips_ar || ('⏳ يبدأ ' || starts_eta_ar)::TEXT;
        chips_en := chips_en || ('⏳ Starts ' || starts_eta_en)::TEXT;
    END IF;

    IF is_coming_soon THEN
        title_ar := '⏳ عرض قادم — ' || COALESCE(p_deal.shop_name, 'متجر') || ' يبدأ ' || starts_eta_ar;
        title_en := '⏳ Coming soon — ' || COALESCE(p_deal.shop_name, 'a store') || ' starts ' || starts_eta_en;
    ELSIF is_follower AND rule_matched THEN
        title_ar := '🔥 ' || COALESCE(p_deal.shop_name, 'متجر تتابعه') || ' نزّل عرضاً يطابق تنبيهك';
        title_en := '🔥 ' || COALESCE(p_deal.shop_name, 'A store you follow') || ' posted a matching deal';
    ELSIF is_follower THEN
        title_ar := '🔥 ' || COALESCE(p_deal.shop_name, 'متجرك المفضل') || ' نزّل عرضاً جديداً';
        title_en := '🔥 New deal from ' || COALESCE(p_deal.shop_name, 'your favorite store');
    ELSIF has_range THEN
        title_ar := range_title_ar;
        title_en := range_title_en;
    ELSIF has_mall THEN
        title_ar := '🏬 عرض جديد في ' || COALESCE(mall_name, 'مولك');
        title_en := '🏬 New deal at ' || COALESCE(mall_name, 'your mall');
    ELSIF has_city THEN
        title_ar := '🌆 عرض جديد في ' || COALESCE(city_name, 'مدينتك');
        title_en := '🌆 New deal in ' || COALESCE(city_name, 'your city');
    ELSIF has_keyword THEN
        title_ar := '🔍 عرض يطابق كلمتك «' || kw_first || '»';
        title_en := '🔍 Deal matching "' || kw_first || '"';
    ELSIF has_category THEN
        title_ar := '🎯 ' || public.taki_category_label_ar(cat_first) || ' — عرض جديد';
        title_en := '🎯 ' || public.taki_category_label_en(cat_first) || ' — new deal';
    ELSIF has_region THEN
        title_ar := '🌍 عرض جديد في منطقتك';
        title_en := '🌍 New deal in your region';
    ELSE
        title_ar := '🎯 يطابق تنبيهك الذكي';
        title_en := '🎯 Matches your smart alert';
    END IF;

    line1_ar := COALESCE(p_deal.item_name, 'عرض جديد')
                || '  —  خصم ' || COALESCE(p_deal.discount_percentage::TEXT, '؟') || '٪';
    line1_en := COALESCE(p_deal.item_name, 'New deal')
                || '  —  ' || COALESCE(p_deal.discount_percentage::TEXT, '?') || '% off';
    line2_ar := '🏪 ' || COALESCE(p_deal.shop_name, 'متجر');
    line2_en := '🏪 ' || COALESCE(p_deal.shop_name, 'Store');

    chip_count := COALESCE(array_length(chips_ar, 1), 0);
    IF chip_count <= 3 THEN
        shown_ar := chips_ar;
        shown_en := chips_en;
        more_n   := 0;
    ELSE
        shown_ar := chips_ar[1:3];
        shown_en := chips_en[1:3];
        more_n   := chip_count - 3;
    END IF;

    IF chip_count > 0 THEN
        line3_ar := array_to_string(shown_ar, '  •  ');
        line3_en := array_to_string(shown_en, '  •  ');
        IF more_n > 0 THEN
            line3_ar := line3_ar || '  •  +' || more_n::TEXT;
            line3_en := line3_en || '  •  +' || more_n::TEXT;
        END IF;
        body_ar := line1_ar || E'\n' || line2_ar || E'\n' || line3_ar;
        body_en := line1_en || E'\n' || line2_en || E'\n' || line3_en;
    ELSE
        body_ar := line1_ar || E'\n' || line2_ar;
        body_en := line1_en || E'\n' || line2_en;
    END IF;

    IF is_coming_soon THEN
        nkind := 'coming_soon';
    ELSIF is_follower THEN
        nkind := 'follow';
    ELSIF has_range THEN
        nkind := 'range';
    ELSIF has_mall THEN
        nkind := 'mall';
    ELSIF has_city THEN
        nkind := 'city';
    ELSIF has_keyword THEN
        nkind := 'keyword';
    ELSIF has_category THEN
        nkind := 'category';
    ELSIF has_region THEN
        nkind := 'region';
    ELSE
        nkind := 'other';
    END IF;

    INSERT INTO public.notifications
        (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
    VALUES (
        p_user_id, title_ar, title_en, body_ar, body_en,
        CASE WHEN is_follower THEN 'deal' ELSE 'marketing' END,
        jsonb_build_object(
            'dealId',         p_deal.id::TEXT,
            'reasons_ar',     to_jsonb(chips_ar),
            'reasons_en',     to_jsonb(chips_en),
            'follower',       is_follower,
            'primary_kind',   nkind,
            'audience',       CASE WHEN is_follower THEN 'follower' ELSE 'alert' END,
            'coming_soon',    is_coming_soon,
            'starts_at',      p_deal.starts_at,
            'bot_message_ar', title_ar || E'\n\n' || body_ar,
            'bot_message_en', title_en || E'\n\n' || body_en
        ),
        NOW()
    );

    RETURN TRUE;
END;
$$;


--
-- Name: taki_email_wrap(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_email_wrap(p_title text, p_body_html text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
SELECT '<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8"></head>'
    || '<body style="margin:0;padding:0;background:#f4f7f6;font-family:-apple-system,''Segoe UI'',Tahoma,Arial,sans-serif;">'
    || '<div style="max-width:600px;margin:0 auto;padding:24px 16px;">'
    || '<div style="background:linear-gradient(135deg,#10b981,#0d9488);border-radius:16px 16px 0 0;padding:22px 24px;text-align:center;">'
    || '<div style="font-size:26px;font-weight:900;color:#ffffff;letter-spacing:1px;">TAKI — تاكي</div>'
    || '<div style="font-size:12px;color:#d1fae5;margin-top:4px;">منصة حجز التخفيضات في السعودية</div></div>'
    || '<div style="background:#ffffff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 16px 16px;padding:26px 24px;">'
    || '<h1 style="font-size:19px;margin:0 0 14px;color:#111827;text-align:right;">' || COALESCE(p_title,'') || '</h1>'
    || '<div style="font-size:14px;line-height:2;color:#374151;text-align:right;">' || COALESCE(p_body_html,'') || '</div>'
    || '<div style="margin-top:22px;text-align:center;">'
    || '<a href="https://taki-test-eight.vercel.app" style="display:inline-block;background:#10b981;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:11px 28px;border-radius:12px;">فتح تاكي</a></div></div>'
    || '<div style="text-align:center;font-size:11px;color:#9ca3af;padding:14px 6px;">وصلتك هذه الرسالة لأنك مشترك في منصة تاكي. يمكنك التحكم بالإشعارات من صفحة حسابك.</div>'
    || '</div></body></html>';
$$;


--
-- Name: taki_enforce_booking_ban(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_enforce_booking_ban() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_until timestamptz; v_susp boolean;
BEGIN
  SELECT booking_banned_until, COALESCE(is_suspended, false) INTO v_until, v_susp
    FROM users WHERE id = NEW.user_id;
  IF v_susp THEN
    RAISE EXCEPTION 'حسابك موقوف — تواصل مع إدارة تاكي';
  END IF;
  IF v_until IS NOT NULL AND v_until > now() THEN
    RAISE EXCEPTION 'تم تعليق الحجز على حسابك حتى % بسبب إلغاءات متكررة', to_char(v_until AT TIME ZONE 'Asia/Riyadh', 'YYYY-MM-DD HH24:MI');
  END IF;
  RETURN NEW;
END $$;


--
-- Name: taki_enforce_booking_rules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_enforce_booking_rules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal deals%ROWTYPE; v_cnt int; v_last timestamptz; v_wait int;
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = NEW.deal_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  -- (a) units per single booking
  IF COALESCE(v_deal.max_per_booking, 0) > 0
     AND COALESCE(NEW.booked_quantity, 1) > v_deal.max_per_booking THEN
    RAISE EXCEPTION 'TAKI_MAX_QTY:%', v_deal.max_per_booking;
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- (b) bookings per buyer (active + completed count; cancelled/expired don't)
    IF COALESCE(v_deal.max_bookings_per_buyer, 0) > 0 THEN
      SELECT count(*) INTO v_cnt FROM bookings
       WHERE deal_id = NEW.deal_id AND user_id = NEW.user_id
         AND status IN ('pending','acknowledged','completed');
      IF v_cnt >= v_deal.max_bookings_per_buyer THEN
        RAISE EXCEPTION 'TAKI_REBOOK_LIMIT:%', v_deal.max_bookings_per_buyer;
      END IF;
    END IF;
    -- (c) cooldown after the buyer's last COMPLETED pickup
    IF COALESCE(v_deal.rebook_cooldown_minutes, 0) > 0 THEN
      SELECT max(completed_at) INTO v_last FROM bookings
       WHERE deal_id = NEW.deal_id AND user_id = NEW.user_id AND status = 'completed';
      IF v_last IS NOT NULL
         AND v_last + (v_deal.rebook_cooldown_minutes || ' minutes')::interval > now() THEN
        v_wait := CEIL(EXTRACT(EPOCH FROM (v_last + (v_deal.rebook_cooldown_minutes || ' minutes')::interval - now())) / 60)::int;
        RAISE EXCEPTION 'TAKI_REBOOK_WAIT:%', GREATEST(v_wait, 1);
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: taki_enforce_branch_display_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_enforce_branch_display_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cap integer; v_shown integer;
begin
  if coalesce(new.show_on_store_page, false) = false then return new; end if;
  if tg_op = 'UPDATE' and coalesce(old.show_on_store_page, false) = true then return new; end if;

  select coalesce(sp.max_branches, 1) into v_cap
    from public.store_profiles sp where sp.store_id = new.merchant_id;
  v_cap := coalesce(v_cap, 1);

  select count(*) into v_shown
    from public.store_branches b
   where b.merchant_id = new.merchant_id
     and b.show_on_store_page = true
     and b.id is distinct from new.id;

  if v_shown + 1 > v_cap then
    raise exception 'BRANCH_DISPLAY_CAP:%', v_cap
      using hint = 'باقتك تسمح بعرض ' || v_cap || ' موقع فقط على صفحتك. أخفِ موقعاً أو رقِّ باقتك.';
  end if;
  return new;
end $$;


--
-- Name: taki_expire_delivery_tracks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_expire_delivery_tracks() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_wiped integer; v_deleted integer;
BEGIN
  -- (أ) بثٌّ توقّف ساعةً: يُغلق المسار ويُمحى الموقع.
  UPDATE public.delivery_tracks
     SET status = 'cancelled', lat = NULL, lng = NULL, accuracy_m = NULL,
         heading = NULL, speed_kmh = NULL, remaining_km = NULL, eta_min = NULL,
         ended_at = now(), updated_at = now()
   WHERE status IN ('on_the_way','arrived')
     AND updated_at < now() - interval '1 hour';
  GET DIAGNOSTICS v_wiped = ROW_COUNT;

  -- (ب) ثم يُحذف الصفّ بعد ساعة من إغلاق **الطلب** لا من إغلاق المسار.
  -- 🪤 v14.19 كانت تحذفه بعد ساعة من `ended_at` بلا شرطٍ على الطلب. والتاجر
  -- يضغط «تم التسليم» فيُغلق المسار **والطلب يبقى مفتوحاً** بانتظار تأكيد
  -- المشتري — فكان الحذف يُخفي زرّ «✅ استلمت طلبي»، ويُسقط الحمايةَ التي
  -- تمنع الإلغاء التلقائي لطلبٍ انطلق مندوبه، فيُلغى طلبٌ وصل صاحبه فعلاً.
  DELETE FROM public.delivery_tracks t
   WHERE COALESCE(t.ended_at, t.updated_at) < now() - interval '1 hour'
     AND t.status IN ('delivered','cancelled')
     AND EXISTS (SELECT 1 FROM public.bookings b
                  WHERE b.barcode = t.barcode
                    AND b.status IN ('completed','cancelled')
                    AND COALESCE(b.completed_at, b.created_at) < now() - interval '1 hour');
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN v_wiped + v_deleted;
END
$$;


--
-- Name: taki_guard_banned_signup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_guard_banned_signup() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_hit text;
BEGIN
  SELECT id INTO v_hit FROM public.users
  WHERE is_suspended = true
    AND id <> NEW.id
    AND (   (NULLIF(btrim(lower(NEW.email)), '') IS NOT NULL
             AND lower(email) = btrim(lower(NEW.email)))
         OR (NULLIF(btrim(NEW.phone), '') IS NOT NULL
             AND regexp_replace(COALESCE(phone,''), '[^0-9]', '', 'g')
               = regexp_replace(NEW.phone, '[^0-9]', '', 'g')) )
  LIMIT 1;
  IF v_hit IS NOT NULL THEN
    RAISE EXCEPTION 'هذا البريد أو الجوال مرتبط بحساب موقوف. تواصل مع إدارة تاكي.'
      USING ERRCODE = 'P0019';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: taki_guard_publish_needs_declaration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_guard_publish_needs_declaration() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_sell jsonb; v_msg text;
BEGIN
  IF NEW.status <> 'active' THEN RETURN NEW; END IF;
  -- لا نُزعج عرضاً نشطاً يُحدَّث لسببٍ آخر وهو مقرٌّ أصلاً.
  IF TG_OP = 'UPDATE' AND OLD.status = 'active' THEN RETURN NEW; END IF;

  v_sell := public.store_can_sell(NEW.store_id);
  IF COALESCE((v_sell->>'ok')::boolean, false) THEN RETURN NEW; END IF;

  NEW.status := 'paused';

  v_msg := CASE v_sell->>'reason'
    WHEN 'no_method' THEN
      '📝 عرضك «' || COALESCE(NEW.item_name,'') || '» حُفظ مسوّدة. أقررتَ ألّا تقبل الدفع عند الاستلام ولا الدفع الإلكتروني — فلا وسيلة لتحصيل ثمنه. عدّل إقرار طريقة الحساب في لوحة التاجر ثم انشره.'
    ELSE
      '📝 عرضك «' || COALESCE(NEW.item_name,'') || '» حُفظ مسوّدة ولم يُنشر: لم تُقرّ بعد بطريقة حساب متجرك. أكمل «إقرار طريقة الحساب» في لوحة التاجر ثم انشره بضغطة.'
  END;

  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (NEW.store_id, '📝 عرضك محفوظ مسوّدة', '📝 Your deal is saved as a draft',
          v_msg, v_msg, 'system',
          jsonb_build_object('audience','seller','dealId', NEW.id,
                             'actionUrl','/seller','action_url','/seller'));
  RETURN NEW;
END $$;


--
-- Name: taki_guard_store_rename(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_guard_store_rename() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.shop IS DISTINCT FROM OLD.shop
     AND NOT COALESCE(public.is_admin(), false)
     -- الدوال المالكة (طابور الموافقة) تعمل بلا `auth.uid()` أو بهوية الأدمن،
     -- وهذا الشرط يسمح لها ويمنع التاجر من الكتابة المباشرة من المتصفّح.
     AND auth.uid()::text = NEW.id THEN
    RAISE EXCEPTION 'تغيير اسم المتجر يمرّ بموافقة إدارة تاكي — أرسل طلباً من لوحة التاجر.'
      USING ERRCODE = 'P0020';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: taki_guard_suspended_publish(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_guard_suspended_publish() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_blocked boolean;
BEGIN
  SELECT (is_suspended OR deleted_at IS NOT NULL) INTO v_blocked
  FROM public.users WHERE id = NEW.store_id;
  IF COALESCE(v_blocked, false) THEN
    RAISE EXCEPTION 'حسابك موقوف — لا يمكنك نشر عروض. تواصل مع إدارة تاكي.'
      USING ERRCODE = 'P0018';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: taki_haversine_km(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_haversine_km(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    p CONSTANT DOUBLE PRECISION := 0.017453292519943295;
    a DOUBLE PRECISION;
BEGIN
    IF lat1 IS NULL OR lng1 IS NULL OR lat2 IS NULL OR lng2 IS NULL THEN
        RETURN NULL;
    END IF;
    a := 0.5
       - cos((lat2 - lat1) * p) / 2
       + cos(lat1 * p) * cos(lat2 * p) * (1 - cos((lng2 - lng1) * p)) / 2;
    RETURN 2 * 6371.0 * asin(sqrt(a));
END;
$$;


--
-- Name: taki_is_saudi_vat(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_is_saudi_vat(p_vat text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT COALESCE(btrim(p_vat), '') ~ '^3[0-9]{13}3$';
$_$;


--
-- Name: taki_issue_order_invoice(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_issue_order_invoice(p_barcode text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_store text;
  v_no    text;
  v_seq   integer;
BEGIN
  SELECT store_id, invoice_no INTO v_store, v_no
    FROM public.order_invoices WHERE barcode = p_barcode FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_no IS NOT NULL THEN RETURN v_no; END IF;   -- أُصدرت من قبل: لا تُصدر مرّتين

  -- عدّاد التاجر. `ON CONFLICT DO UPDATE` يقفل الصفّ فيتسلسل تاجران معاً بلا
  -- تصادم، وتراجُع المعاملة يُعيد الرقم فلا تنشأ فجوة.
  INSERT INTO public.store_invoice_counters (store_id, last_seq)
  VALUES (v_store, 1)
  ON CONFLICT (store_id) DO UPDATE
    SET last_seq = public.store_invoice_counters.last_seq + 1,
        updated_at = now()
  RETURNING last_seq INTO v_seq;

  v_no := 'TK-' || lpad(v_seq::text, 6, '0');

  UPDATE public.order_invoices
     SET seq = v_seq, invoice_no = v_no, issued_at = now()
   WHERE barcode = p_barcode;

  RETURN v_no;
END
$$;


--
-- Name: taki_match_terms(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_match_terms(p_text text) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(array_agg(mt.term), '{}'::text[])
    FROM moderation_terms mt
   WHERE p_text IS NOT NULL AND btrim(p_text) <> ''
     AND (
          (mt.match_mode = 'substr' AND p_text ILIKE '%' || mt.term || '%')
       OR (mt.match_mode = 'word'   AND p_text ~* ('\m' || mt.term || '\M'))
     );
$$;


--
-- Name: taki_merchant_vat_rate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_merchant_vat_rate() RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT GREATEST(0, LEAST(100, COALESCE(
    (SELECT NULLIF(value->>'rate','')::numeric FROM public.platform_settings WHERE key = 'merchant_vat'),
    15)));
$$;


--
-- Name: taki_moderation_escalate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_moderation_escalate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cnt int; v_susp boolean; v_role text; v_name text;
  v_delay int; v_wid uuid; v_msg text;
BEGIN
  BEGIN
    IF NEW.offender_id IS NULL THEN RETURN NEW; END IF;
    SELECT count(*) INTO v_cnt FROM moderation_flags WHERE offender_id = NEW.offender_id;
    SELECT is_suspended, user_type, coalesce(shop, name) INTO v_susp, v_role, v_name
      FROM users WHERE id = NEW.offender_id;

    IF v_cnt = 2 THEN
      -- إنذار آلي (مرة واحدة عند المخالفة الثانية) — السجل فوري، والإشعار
      -- يحترم moderation_settings.warn_delay_minutes (إيحاء المراجعة البشرية)
      v_msg := 'رصدت إدارة تاكي محتوى مخالفاً متكرراً من حسابك (ألفاظ أو محتوى محظور). هذا إنذار رسمي — تكرار المخالفة مرة أخرى يؤدي إلى تعليق حسابك.';
      INSERT INTO user_warnings (user_id, user_role, reason, context_message, admin_id)
      VALUES (NEW.offender_id, v_role, '⚠️ إنذار آلي: مخالفة محتوى متكررة (المخالفة الثانية)', left(coalesce(NEW.content,''), 300), NULL)
      RETURNING id INTO v_wid;
      v_delay := COALESCE((SELECT (value->>'warn_delay_minutes')::int FROM platform_settings WHERE key='moderation_settings'), 0);
      IF v_delay <= 0 THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
        VALUES (NEW.offender_id, '⚠️ تنبيه من إدارة تاكي', '⚠️ Warning from TAKI', v_msg, v_msg, 'system',
                jsonb_build_object('audience','user','admin_warning', TRUE));
      ELSE
        INSERT INTO pending_warnings (warning_id, user_id, message, deliver_at)
        VALUES (v_wid, NEW.offender_id, v_msg, now() + make_interval(mins => v_delay));
      END IF;
      -- «تحت المجهر» — إبلاغ الأدمن
      INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      SELECT u.id, '🔎 حساب تحت المجهر', '🔎 Account under watch',
             'المستخدم «' || coalesce(v_name,'?') || '» سجّل مخالفتي محتوى — أُرسل له إنذار آلي. المخالفة الثالثة تعلق حسابه تلقائياً.',
             'Two content violations — auto-warning sent.', 'system',
             jsonb_build_object('audience','admin')
      FROM users u WHERE u.deleted_at IS NULL AND u.user_type = 'admin';

    ELSIF v_cnt >= 3 AND NOT COALESCE(v_susp, false) THEN
      UPDATE users SET is_suspended = true WHERE id = NEW.offender_id;
      INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      VALUES (NEW.offender_id, '⛔ تم تعليق حسابك', '⛔ Account suspended',
              'عُلّق حسابك لتكرار مخالفات المحتوى بعد إنذار رسمي. للاعتراض تواصل مع الإدارة من «الشكاوى / تواصل الإدارة».',
              'Your account was suspended for repeated content violations.', 'system',
              jsonb_build_object('audience','user'));
      INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      SELECT u.id, '⛔ تعليق تلقائي لحساب', '⛔ Auto-suspension',
             'عُلّق حساب «' || coalesce(v_name,'?') || '» تلقائياً بعد ٣ مخالفات محتوى. راجعه من «الحسابات المعلقة» في البلاغات.',
             'Account auto-suspended after 3 violations.', 'system',
             jsonb_build_object('audience','admin')
      FROM users u WHERE u.deleted_at IS NULL AND u.user_type = 'admin';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL; -- التصعيد لا يكسر تسجيل المخالفة أبداً
  END;
  RETURN NEW;
END $$;


