CREATE FUNCTION public.taki_propagate_store_name() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.shop IS DISTINCT FROM OLD.shop THEN
    UPDATE public.deals
       SET shop_name = COALESCE(NULLIF(btrim(NEW.shop), ''), NULLIF(btrim(NEW.name), ''), 'متجر')
     WHERE store_id = NEW.id;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: taki_prune_analytics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_prune_analytics() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- أحداث القِمع التفصيلية — ٩٠ يوماً تكفي كل لوحات التاجر والاتجاهات
  DELETE FROM public.store_analytics_events WHERE created_at < now() - interval '90 days';
  -- أحداث فتح التطبيق (جمهور المدن) — ١٨٠ يوماً لمقارنات الموسم بالموسم
  DELETE FROM public.analytics_events       WHERE created_at < now() - interval '180 days';
  -- سجل الحضور اللحظي — لا معنى له بعد ٣٠ يوماً
  DELETE FROM public.user_sessions          WHERE last_seen_at < now() - interval '30 days';
END
$$;


--
-- Name: taki_queue_email(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_queue_email(p_user_id text, p_event text, p_subject text, p_html text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_email text;
BEGIN
  SELECT email INTO v_email FROM users WHERE id = p_user_id;
  IF v_email IS NULL
     OR v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
     OR v_email ILIKE '%telegram%' OR v_email ILIKE '%whatsapp%' OR v_email ILIKE '%.local'
  THEN
    RETURN false;
  END IF;
  INSERT INTO email_outbox (user_id, to_email, subject, html, event)
  VALUES (p_user_id, v_email, COALESCE(p_subject,'TAKI'), COALESCE(p_html,''), p_event);
  RETURN true;
END $_$;


--
-- Name: taki_rate_check(text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_rate_check(p_key text, p_max integer, p_window_secs integer, p_msg text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_win  timestamptz;
  v_hits int;
BEGIN
  v_win := to_timestamp(floor(extract(epoch FROM now()) / p_window_secs) * p_window_secs);
  INSERT INTO rate_limit_counters (bucket_key, window_start, hits)
  VALUES (p_key, v_win, 1)
  ON CONFLICT (bucket_key, window_start)
  DO UPDATE SET hits = rate_limit_counters.hits + 1
  RETURNING hits INTO v_hits;
  IF v_hits > p_max THEN
    RAISE EXCEPTION '%', p_msg USING ERRCODE = 'P0011';
  END IF;
END;
$$;


--
-- Name: taki_reconcile_all_branch_display(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_reconcile_all_branch_display() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n integer := 0;
begin
  for r in select distinct merchant_id from public.store_branches loop
    perform public.taki_reconcile_branch_display(r.merchant_id);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: taki_reconcile_branch_display(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_reconcile_branch_display(p_store_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cap integer;
BEGIN
    SELECT max_branches INTO v_cap FROM public.store_profiles WHERE store_id = p_store_id;
    IF v_cap IS NULL OR v_cap <= 0 THEN RETURN; END IF;

    UPDATE public.store_branches b
       SET show_on_store_page = false, updated_at = NOW()
     WHERE b.merchant_id = p_store_id
       AND b.show_on_store_page
       AND b.id NOT IN (
            SELECT x.id FROM public.store_branches x
             WHERE x.merchant_id = p_store_id
               AND x.show_on_store_page
               AND COALESCE(x.is_active, true)
             ORDER BY x.is_primary DESC NULLS LAST, x.created_at ASC
             LIMIT v_cap);
END;
$$;


--
-- Name: taki_reconcile_location_caps(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_reconcile_location_caps() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s RECORD; r RECORD;
  v_max INT; v_keys TEXT[]; v_union TEXT[];
  v_paused INT := 0; v_n INT;
BEGIN
  FOR s IN
    SELECT sp.store_id, GREATEST(1, sp.max_branches) AS max_b
      FROM store_profiles sp
      JOIN users u ON u.id = sp.store_id
     WHERE sp.max_branches IS NOT NULL
  LOOP
    v_max := s.max_b;

    -- (١) العروض المتجاوزة بذاتها
    UPDATE deals d
       SET status = 'paused', subscription_frozen = TRUE
     WHERE d.store_id = s.store_id
       AND d.status = 'active'
       AND (SELECT count(DISTINCT k)
              FROM public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k) > v_max;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_paused := v_paused + COALESCE(v_n, 0);

    -- (٢) اتحاد الباقي — نُبقي الأقدم فالأقدم
    v_keys := ARRAY[]::TEXT[];
    FOR r IN
      SELECT d.id,
             ARRAY(SELECT DISTINCT k
                     FROM public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k) AS keys
        FROM deals d
       WHERE d.store_id = s.store_id AND d.status = 'active'
       ORDER BY d.created_at ASC NULLS FIRST, d.id ASC
    LOOP
      v_union := (SELECT array_agg(DISTINCT k) FROM unnest(v_keys || r.keys) k);
      IF COALESCE(array_length(v_union, 1), 0) > v_max THEN
        UPDATE deals SET status = 'paused', subscription_frozen = TRUE WHERE id = r.id;
        v_paused := v_paused + 1;
      ELSE
        v_keys := v_union;
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'deals_paused', v_paused);
END $$;


--
-- Name: taki_recur_campaigns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_recur_campaigns() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_riyadh timestamp := (NOW() AT TIME ZONE 'Asia/Riyadh');
  v_today  date := v_riyadh::date;
  c record; v_last date; v_due boolean; v_sent int := 0; v_reached int := 0;
BEGIN
  FOR c IN SELECT * FROM promotional_campaigns
           WHERE is_active = true
             AND recurrence <> 'none'
             AND starts_at <= NOW()
             AND (ends_at IS NULL OR ends_at > NOW())
  LOOP
    IF extract(hour FROM v_riyadh)::int <> COALESCE(c.recurrence_hour, 10) THEN CONTINUE; END IF;
    v_last := (c.last_broadcast_at AT TIME ZONE 'Asia/Riyadh')::date;
    v_due := CASE c.recurrence
      WHEN 'daily'        THEN v_last IS NULL OR v_last < v_today
      WHEN 'every_3_days' THEN v_last IS NULL OR (v_today - v_last) >= 3
      WHEN 'weekend'      THEN extract(isodow FROM v_today)::int = 5 AND (v_last IS NULL OR v_last < v_today)
      WHEN 'weekly'       THEN v_last IS NULL OR (v_today - v_last) >= 7
      WHEN 'monthly'      THEN v_last IS NULL OR (v_today - v_last) >= 30
      ELSE false END;
    IF v_due THEN
      v_reached := v_reached + public._broadcast_campaign_core(c.id, true);
      v_sent := v_sent + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('campaigns', v_sent, 'notifications', v_reached);
END;
$$;


--
-- Name: taki_render_template(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_render_template(p_tpl text, p_vars jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_out text := COALESCE(p_tpl, ''); v_k text; v_v text;
BEGIN
  FOR v_k, v_v IN SELECT key, value FROM jsonb_each_text(COALESCE(p_vars, '{}'::jsonb)) LOOP
    v_out := replace(v_out, '{' || v_k || '}', COALESCE(v_v, ''));
  END LOOP;
  RETURN v_out;
END $$;


--
-- Name: taki_scan_text_tr(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_scan_text_tr() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_content text;
  v_source text;
  v_store text;
  v_offender text;
  v_matched text[];
BEGIN
  BEGIN
    IF TG_TABLE_NAME = 'booking_messages' THEN
      v_content := NEW.body;
      v_source := 'chat';
      v_offender := NEW.sender_id;
      SELECT b.store_id INTO v_store FROM bookings b WHERE b.barcode = NEW.barcode LIMIT 1;
    ELSIF TG_TABLE_NAME = 'ratings' THEN
      IF TG_OP = 'UPDATE' AND NEW.comment IS NOT DISTINCT FROM OLD.comment THEN RETURN NEW; END IF;
      v_content := NEW.comment;
      v_source := 'rating';
      v_offender := NEW.user_id;
      v_store := NEW.store_id;
    ELSE -- deals
      IF TG_OP = 'UPDATE'
         AND NEW.item_name IS NOT DISTINCT FROM OLD.item_name
         AND NEW.description IS NOT DISTINCT FROM OLD.description THEN RETURN NEW; END IF;
      v_content := coalesce(NEW.item_name,'') || ' — ' || coalesce(NEW.description,'');
      v_source := 'deal';
      v_offender := NEW.store_id;
      v_store := NEW.store_id;
    END IF;

    v_matched := public.taki_match_terms(v_content);
    IF array_length(v_matched, 1) IS NULL THEN RETURN NEW; END IF;

    INSERT INTO moderation_flags (kind, source, store_id, offender_id, offender_name, content, matched)
    VALUES ('text', v_source, v_store, v_offender,
            (SELECT coalesce(u.shop, u.name) FROM users u WHERE u.id = v_offender),
            left(v_content, 500), v_matched);
  EXCEPTION WHEN OTHERS THEN
    NULL;   -- moderation must never break chat/rating/deal writes
  END;
  RETURN NEW;
END $$;


--
-- Name: taki_season_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_season_reminders() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_cfg      jsonb;
    v_dates    jsonb;
    v_notified jsonb;
    v_today    date := (now() AT TIME ZONE 'Asia/Riyadh')::date;
    r          RECORD;
    v_days     int;
    v_marker   text;
    v_name     text;
BEGIN
    SELECT value INTO v_cfg FROM platform_settings WHERE key = 'season_event_dates';
    IF v_cfg IS NULL THEN RETURN; END IF;
    v_dates    := COALESCE(v_cfg->'dates', '{}'::jsonb);
    v_notified := COALESCE(v_cfg->'notified', '[]'::jsonb);

    FOR r IN SELECT key AS season_id, value #>> '{}' AS event_date FROM jsonb_each(v_dates)
    LOOP
        CONTINUE WHEN r.event_date IS NULL OR r.event_date = '';
        v_days := (r.event_date::date - v_today);
        -- نافذتا تذكير: شهر قبلها وأسبوع قبلها (تلتقط اليوم التالي لو تعطّل الكرون يوماً)
        IF v_days BETWEEN 28 AND 30 THEN v_marker := r.season_id || ':' || r.event_date || ':30';
        ELSIF v_days BETWEEN 5 AND 7 THEN v_marker := r.season_id || ':' || r.event_date || ':7';
        ELSE CONTINUE;
        END IF;
        CONTINUE WHEN v_notified ? v_marker;

        v_name := CASE r.season_id
            WHEN 'ramadan' THEN 'رمضان' WHEN 'eid' THEN 'العيد'
            WHEN 'founding' THEN 'يوم التأسيس' WHEN 'national' THEN 'اليوم الوطني'
            WHEN 'school' THEN 'العودة للمدارس' WHEN 'white_friday' THEN 'الجمعة البيضاء'
            WHEN 'summer' THEN 'إجازة الصيف' ELSE r.season_id END;

        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        SELECT u.id,
               '⏰ باقي ' || v_days || ' يوماً على ' || v_name,
               '⏰ ' || v_days || ' days until ' || v_name,
               'جهّز حملة الموسم من أدوات الإدارة → هوية المواسم: افتح باب التجار لإضافة منتجاتهم، وحدّد فترة ظهور صفحة العروض للعامة.',
               'Set up the season campaign from Admin Tools → Seasonal identity.',
               'system',
               jsonb_build_object('audience', 'admin', 'season_id', r.season_id, 'event_date', r.event_date),
               NOW()
        FROM users u
        WHERE u.deleted_at IS NULL AND u.user_type = 'admin';

        v_notified := v_notified || to_jsonb(v_marker);
    END LOOP;

    UPDATE platform_settings
       SET value = jsonb_build_object('dates', v_dates, 'notified', v_notified),
           updated_at = NOW()
     WHERE key = 'season_event_dates';
END $$;


--
-- Name: taki_season_sync_theme(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_season_sync_theme() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  eff text;
  cur text;
BEGIN
  eff := public.taki_season_theme_effective();
  SELECT COALESCE(value #>> '{}', '') INTO cur
    FROM platform_settings WHERE key = 'seasonal_theme';
  IF cur IS DISTINCT FROM eff THEN
    INSERT INTO platform_settings (key, value, description, updated_at)
    VALUES ('seasonal_theme', to_jsonb(eff),
            'Auto-derived from season_campaign public window (v12.57)', now())
    ON CONFLICT (key) DO UPDATE
      SET value = EXCLUDED.value,
          description = EXCLUDED.description,
          updated_at = EXCLUDED.updated_at;
  END IF;
END;
$$;


--
-- Name: taki_season_theme_effective(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_season_theme_effective() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((
    SELECT CASE
      WHEN COALESCE(value->>'season_id','') <> ''
       AND COALESCE(value->>'public_from','') <> ''
       AND COALESCE(value->>'public_to','') <> ''
       AND (now() AT TIME ZONE 'Asia/Riyadh')::date
           BETWEEN (value->>'public_from')::date AND (value->>'public_to')::date
      THEN value->>'season_id'
      ELSE ''
    END
    FROM platform_settings WHERE key = 'season_campaign'
  ), '');
$$;


--
-- Name: taki_store_profiles_subscription_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_store_profiles_subscription_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s jsonb; vars jsonb; v_new boolean := false; v_cancel boolean := false;
  v_name text; v_plan text; v_title text; v_body text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_new := lower(COALESCE(NEW.subscription_plan,'free')) <> 'free'
             AND NEW.subscription_expires_at IS NOT NULL;
  ELSE
    v_new := lower(COALESCE(NEW.subscription_plan,'free')) <> 'free' AND (
         lower(COALESCE(OLD.subscription_plan,'free')) = 'free'
      OR (NEW.subscription_started_at IS DISTINCT FROM OLD.subscription_started_at
          AND NEW.subscription_started_at IS NOT NULL)
      OR (NEW.subscription_expires_at IS DISTINCT FROM OLD.subscription_expires_at
          AND NEW.subscription_expires_at > COALESCE(OLD.subscription_expires_at, NOW()))
    );
    v_cancel := COALESCE(OLD.auto_renew, true) AND NEW.auto_renew IS FALSE;
  END IF;

  IF NOT v_new AND NOT v_cancel THEN RETURN NEW; END IF;
  SELECT u.name INTO v_name FROM users u WHERE u.id = NEW.store_id;

  IF v_new THEN
    s := public.taki_msg_setting('sub_new');
    IF COALESCE((s->>'enabled')::boolean, true) THEN
      v_plan := CASE
        WHEN lower(COALESCE(NEW.subscription_plan,'')) = 'premium' AND COALESCE(NEW.max_branches,0) > 0
          THEN 'باقة حتى ' || NEW.max_branches || ' مواقع'
        ELSE COALESCE(NEW.subscription_plan,'') END;
      vars := jsonb_build_object(
        'store',   COALESCE(v_name,''),
        'plan',    v_plan,
        'price',   trim(to_char(COALESCE(NEW.subscription_amount,0), 'FM999999990.00')),
        'expires', to_char(NEW.subscription_expires_at, 'YYYY-MM-DD'));
      IF COALESCE((s->'channels'->>'inapp')::boolean, true) THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (NEW.store_id,
                public.taki_render_template(s->>'title_ar', vars),
                public.taki_render_template(s->>'title_en', vars),
                public.taki_render_template(s->>'body_ar', vars),
                public.taki_render_template(s->>'body_en', vars),
                'subscription', jsonb_build_object('audience','seller','event','sub_new'), NOW());
      END IF;
      -- email for sub_new is queued by the payment trigger (real invoice data);
      -- admin-granted subscriptions have no payment, hence in-app only.
    END IF;
  END IF;

  IF v_cancel THEN
    s := public.taki_msg_setting('sub_cancelled');
    IF COALESCE((s->>'enabled')::boolean, true) THEN
      vars := jsonb_build_object(
        'store',   COALESCE(v_name,''),
        'expires', COALESCE(to_char(NEW.subscription_expires_at, 'YYYY-MM-DD'), '—'));
      v_title := public.taki_render_template(s->>'title_ar', vars);
      v_body  := public.taki_render_template(s->>'body_ar',  vars);
      IF COALESCE((s->'channels'->>'inapp')::boolean, true) THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (NEW.store_id, v_title,
                public.taki_render_template(s->>'title_en', vars),
                v_body,
                public.taki_render_template(s->>'body_en', vars),
                'subscription', jsonb_build_object('audience','seller','event','sub_cancelled'), NOW());
      END IF;
      IF COALESCE((s->'channels'->>'email')::boolean, false) THEN
        PERFORM public.taki_queue_email(NEW.store_id, 'sub_cancelled', v_title,
            public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
      END IF;
    END IF;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- notifications are best-effort: NEVER block a subscription write
  RAISE WARNING 'taki_store_profiles_subscription_notify: %', SQLERRM;
  RETURN NEW;
END $$;


--
-- Name: taki_subscription_maintenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_subscription_maintenance() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_enabled boolean;
    s_warn jsonb; s_exp jsonb; s_renew jsonb;
    v_days int;
    v_warned  int := 0; v_expired int := 0; v_frozen int := 0; v_banners int := 0;
    v_renewed int := 0;
    r record; vars jsonb; v_title text; v_body text; v_body_en text;
BEGIN
    SELECT (value = 'true'::jsonb) INTO v_enabled
      FROM platform_settings WHERE key = 'payment_gateway_enabled';
    IF v_enabled IS NOT TRUE THEN
        RETURN jsonb_build_object('mode','free','warned',0,'renewed',0,'expired',0,'frozen',0,'banners_hidden',0);
    END IF;

    s_warn  := public.taki_msg_setting('sub_warning');
    s_exp   := public.taki_msg_setting('sub_expired');
    s_renew := public.taki_msg_setting('sub_renewed');
    v_days := LEAST(GREATEST(COALESCE((s_warn->>'days_before')::int, 3), 1), 60);

    IF COALESCE((s_warn->>'enabled')::boolean, true) THEN
        FOR r IN
            UPDATE store_profiles sp
            SET last_expiry_warning_at = NOW()
            WHERE sp.subscription_expires_at IS NOT NULL
              AND lower(COALESCE(sp.subscription_plan,'free')) IN ('premium','trial')
              AND sp.subscription_expires_at > NOW()
              AND sp.subscription_expires_at <= NOW() + (v_days || ' days')::interval
              -- v13.97 (طلب ناصر): لا تحذير لمن سيتجدّد اشتراكه تلقائياً — لا شيء
              -- مطلوبٌ منه، وإنذار «جدّد الآن» لمن لن ينقطع اشتراكه يُدرّب المستخدم
              -- على تجاهل إشعارات المنصة. التجارب تبقى تُحذَّر لأنها تنتهي فعلاً.
              AND NOT (lower(COALESCE(sp.subscription_plan,'')) = 'premium'
                       AND sp.auto_renew IS NOT FALSE
                       AND sp.subscription_canceled_at IS NULL)
              AND (sp.last_expiry_warning_at IS NULL
                   OR sp.last_expiry_warning_at < sp.subscription_expires_at - (v_days || ' days')::interval)
            RETURNING sp.store_id, sp.subscription_expires_at, sp.subscription_plan,
                      sp.auto_renew, sp.subscription_canceled_at, sp.subscription_amount
        LOOP
            vars := jsonb_build_object(
                'store',   COALESCE((SELECT u.name FROM users u WHERE u.id = r.store_id), ''),
                'days',    v_days::text,
                'expires', to_char(r.subscription_expires_at, 'YYYY-MM-DD'));
            v_title   := public.taki_render_template(s_warn->>'title_ar', vars);
            v_body    := public.taki_render_template(s_warn->>'body_ar',  vars);
            v_body_en := public.taki_render_template(s_warn->>'body_en',  vars);
            IF COALESCE((s_warn->'channels'->>'inapp')::boolean, true) THEN
                INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
                VALUES (r.store_id, v_title,
                        public.taki_render_template(s_warn->>'title_en', vars),
                        v_body,
                        v_body_en,
                        'system', jsonb_build_object('audience','seller','event','sub_warning'), NOW());
            END IF;
            IF COALESCE((s_warn->'channels'->>'email')::boolean, false) THEN
                PERFORM public.taki_queue_email(r.store_id, 'sub_warning', v_title,
                    public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
            END IF;
            v_warned := v_warned + 1;
        END LOOP;
    END IF;

    -- (a2) v12.67 auto-renew; v12.68 notification gated by sub_renewed setting
    FOR r IN
        UPDATE store_profiles sp
        SET subscription_started_at = NOW(),
            subscription_expires_at = NOW() + (
                GREATEST(1, LEAST(730, COALESCE(
                    ROUND(EXTRACT(EPOCH FROM (sp.subscription_expires_at - sp.subscription_started_at)) / 86400.0)::int,
                    30)))::text || ' days')::interval,
            updated_at = NOW()
        WHERE sp.subscription_expires_at IS NOT NULL
          AND sp.subscription_expires_at <= NOW()
          AND lower(COALESCE(sp.subscription_plan,'free')) = 'premium'
          AND sp.auto_renew IS NOT FALSE
          AND sp.subscription_canceled_at IS NULL
          AND sp.subscription_started_at IS NOT NULL
        RETURNING sp.store_id, sp.subscription_started_at AS new_start,
                  sp.subscription_expires_at AS new_end,
                  sp.subscription_amount, sp.max_branches
    LOOP
        v_renewed := v_renewed + 1;
        INSERT INTO subscription_payments (merchant_id, plan_id, amount, currency, status, payment_method,
                                           gateway_provider, branches_count, period_start, period_end, paid_at, metadata)
        VALUES (r.store_id, NULL, round(COALESCE(r.subscription_amount,0), 2), 'SAR', 'paid', 'auto',
                'simulated', r.max_branches, r.new_start, r.new_end, NOW(),
                jsonb_build_object('source','auto_renew','plan_label','تجديد تلقائي'));
        UPDATE merchant_subscriptions ms
        SET current_period_start = r.new_start, current_period_end = r.new_end,
            last_renewed_at = NOW(), updated_at = NOW()
        WHERE ms.merchant_id = r.store_id AND ms.status = 'active';
        IF COALESCE((s_renew->>'enabled')::boolean, true) THEN
            vars := jsonb_build_object(
                'store',   COALESCE((SELECT u.name FROM users u WHERE u.id = r.store_id), ''),
                'price',   round(COALESCE(r.subscription_amount,0),2)::text,
                'expires', to_char(r.new_end, 'YYYY-MM-DD'));
            v_title := public.taki_render_template(s_renew->>'title_ar', vars);
            v_body  := public.taki_render_template(s_renew->>'body_ar',  vars);
            IF COALESCE((s_renew->'channels'->>'inapp')::boolean, true) THEN
                INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
                VALUES (r.store_id, v_title,
                        public.taki_render_template(s_renew->>'title_en', vars),
                        v_body,
                        public.taki_render_template(s_renew->>'body_en', vars),
                        'system', jsonb_build_object('audience','seller','event','sub_renewed'), NOW());
            END IF;
            IF COALESCE((s_renew->'channels'->>'email')::boolean, false) THEN
                PERFORM public.taki_queue_email(r.store_id, 'sub_renewed', v_title,
                    public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
            END IF;
        END IF;
    END LOOP;

    -- (b) freeze deals of just-expired merchants (unchanged business rule)
    WITH froze AS (
        UPDATE deals d
        SET status = 'paused', subscription_frozen = TRUE
        WHERE d.status = 'active'
          AND d.store_id IN (
              SELECT store_id FROM store_profiles
              WHERE subscription_expires_at IS NOT NULL
                AND subscription_expires_at <= NOW()
                AND lower(COALESCE(subscription_plan,'free')) <> 'free'
          )
        RETURNING d.id
    )
    SELECT COUNT(*) INTO v_frozen FROM froze;

    -- (b2) v12.31 — hide the expired merchant's BANNERS too.
    WITH bfroze AS (
        UPDATE banners b
        SET is_active = FALSE, frozen_reason = 'subscription_expired'
        WHERE b.is_active
          AND b.store_id IS NOT NULL
          AND b.store_id IN (
              SELECT store_id FROM store_profiles
              WHERE subscription_expires_at IS NOT NULL
                AND subscription_expires_at <= NOW()
                AND lower(COALESCE(subscription_plan,'free')) <> 'free'
          )
        RETURNING b.id
    )
    SELECT COUNT(*) INTO v_banners FROM bfroze;

    -- (c) flip expired profiles to free + configurable notice
    FOR r IN
        UPDATE store_profiles
        SET subscription_plan = 'free', updated_at = NOW()
        WHERE subscription_expires_at IS NOT NULL
          AND subscription_expires_at <= NOW()
          AND lower(COALESCE(subscription_plan,'free')) <> 'free'
        RETURNING store_id, subscription_expires_at
    LOOP
        v_expired := v_expired + 1;
        IF COALESCE((s_exp->>'enabled')::boolean, true) THEN
            vars := jsonb_build_object(
                'store',   COALESCE((SELECT u.name FROM users u WHERE u.id = r.store_id), ''),
                'expires', to_char(r.subscription_expires_at, 'YYYY-MM-DD'));
            v_title := public.taki_render_template(s_exp->>'title_ar', vars);
            v_body  := public.taki_render_template(s_exp->>'body_ar',  vars);
            IF COALESCE((s_exp->'channels'->>'inapp')::boolean, true) THEN
                INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
                VALUES (r.store_id, v_title,
                        public.taki_render_template(s_exp->>'title_en', vars),
                        v_body,
                        public.taki_render_template(s_exp->>'body_en', vars),
                        'system', jsonb_build_object('audience','seller','event','sub_expired'), NOW());
            END IF;
            IF COALESCE((s_exp->'channels'->>'email')::boolean, false) THEN
                PERFORM public.taki_queue_email(r.store_id, 'sub_expired', v_title,
                    public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
            END IF;
        END IF;
    END LOOP;

    RETURN jsonb_build_object('mode','paid','warned',v_warned,'renewed',v_renewed,'expired',v_expired,'frozen',v_frozen,'banners_hidden',v_banners,'warn_days',v_days);
END;

$$;


--
-- Name: taki_sync_deal_shop_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_sync_deal_shop_name() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_name text;
BEGIN
  SELECT COALESCE(NULLIF(btrim(u.shop), ''), NULLIF(btrim(u.name), ''), 'متجر')
    INTO v_name FROM public.users u WHERE u.id = NEW.store_id;
  NEW.shop_name := COALESCE(v_name, 'متجر');
  RETURN NEW;
END $$;


--
-- Name: taki_user_in_campaign(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_user_in_campaign(p_uid text, p_city text, p_region text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_city text := NULLIF(btrim(COALESCE(p_city, '')), '');
  v_reg  text := NULLIF(btrim(COALESCE(p_region, '')), '');
  v_lat double precision; v_lng double precision;
  v_near text; v_near_reg text;
BEGIN
  IF v_city IS NULL AND v_reg IS NULL THEN RETURN true; END IF;   -- بلا استهداف = الجميع

  -- (ب) سابقة الحجز — أرخص وأدقّ من الإحداثيات، فنبدأ بها.
  IF EXISTS (
    SELECT 1 FROM public.bookings b JOIN public.deals d ON d.id = b.deal_id
    WHERE b.user_id = p_uid
      AND (v_city IS NULL OR d.city   = v_city)
      AND (v_reg  IS NULL OR d.region = v_reg)
  ) THEN RETURN true; END IF;

  -- وللتاجر: مدينة عروضه هو.
  IF EXISTS (
    SELECT 1 FROM public.deals d
    WHERE d.store_id = p_uid
      AND (v_city IS NULL OR d.city   = v_city)
      AND (v_reg  IS NULL OR d.region = v_reg)
  ) THEN RETURN true; END IF;

  -- (أ) أقرب مدينة لإحداثياته.
  SELECT lat, lng INTO v_lat, v_lng FROM public.users WHERE id = p_uid;
  IF v_lat IS NULL OR v_lng IS NULL THEN RETURN false; END IF;
  SELECT g.city_id, g.region_id INTO v_near, v_near_reg
  FROM public.sa_cities_geo g
  ORDER BY ((g.lat - v_lat) ^ 2 + (g.lng - v_lng) ^ 2) ASC
  LIMIT 1;
  RETURN (v_city IS NULL OR v_near = v_city) AND (v_reg IS NULL OR v_near_reg = v_reg);
END $$;


--
-- Name: taki_user_spend(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taki_user_spend(p_uid text) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(SUM(b.total_amount), 0)::numeric
  FROM public.bookings b
  WHERE b.user_id = p_uid AND b.status = 'completed';
$$;


--
-- Name: tg_branch_cap_on_package_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_branch_cap_on_package_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pkg_max integer;
BEGIN
  IF NEW.subscription_package_id IS NULL THEN RETURN NEW; END IF;

  SELECT GREATEST(1, (e->>'max')::int) INTO v_pkg_max
    FROM jsonb_array_elements(
           (SELECT value FROM platform_settings WHERE key = 'location_packages')) e
   WHERE NULLIF(e->>'id','') IS NOT NULL
     AND (e->>'id')::int = NEW.subscription_package_id
   LIMIT 1;

  IF v_pkg_max IS NULL THEN RETURN NEW; END IF;

  IF NEW.max_branches IS DISTINCT FROM v_pkg_max THEN
    UPDATE public.store_profiles
       SET max_branches = v_pkg_max, updated_at = NOW()
     WHERE store_id = NEW.store_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tg_branch_display_on_plan_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_branch_display_on_plan_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    PERFORM public.taki_reconcile_branch_display(NEW.store_id);
    RETURN NEW;
END;
$$;


--
-- Name: tg_enforce_branch_display_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_enforce_branch_display_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cap integer; v_shown integer;
BEGIN
    IF NOT NEW.show_on_store_page THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND OLD.show_on_store_page THEN RETURN NEW; END IF;

    SELECT max_branches INTO v_cap FROM public.store_profiles WHERE store_id = NEW.merchant_id;
    IF v_cap IS NULL OR v_cap <= 0 THEN RETURN NEW; END IF;

    SELECT count(*) INTO v_shown FROM public.store_branches
     WHERE merchant_id = NEW.merchant_id AND show_on_store_page
       AND COALESCE(is_active, true) AND id <> NEW.id;

    IF v_shown >= v_cap THEN
        RAISE EXCEPTION 'BRANCH_DISPLAY_CAP:%', v_cap USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;


