BEGIN
    RAISE EXCEPTION
        'sellers_public هو دليل قراءة فقط — الكتابة تتم على جدول users عبر سياساته'
        USING ERRCODE = 'insufficient_privilege';
END;
$$;


--
-- Name: toggle_rating_like(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_rating_like(p_rating_id text) RETURNS TABLE(rating_id text, like_count integer, liked boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_uid text := (auth.uid())::text;
    v_already boolean;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'auth required';
    END IF;
    SELECT v_uid = ANY (r.liked_by) INTO v_already FROM public.ratings r WHERE r.id = p_rating_id;
    IF v_already IS NULL THEN
        RAISE EXCEPTION 'rating not found';
    END IF;
    IF v_already THEN
        UPDATE public.ratings
            SET liked_by = array_remove(liked_by, v_uid),
                like_count = GREATEST(like_count - 1, 0),
                updated_at = now()
            WHERE id = p_rating_id;
        RETURN QUERY SELECT p_rating_id, GREATEST((SELECT like_count FROM public.ratings WHERE id = p_rating_id), 0), false;
    ELSE
        UPDATE public.ratings
            SET liked_by = array_append(liked_by, v_uid),
                like_count = like_count + 1,
                updated_at = now()
            WHERE id = p_rating_id;
        RETURN QUERY SELECT p_rating_id, (SELECT like_count FROM public.ratings WHERE id = p_rating_id), true;
    END IF;
END $$;


--
-- Name: tr_ad_set_booking_hold(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_ad_set_booking_hold() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_booked bigint;
BEGIN
  v_booked := COALESCE(NEW.booked_at, (EXTRACT(EPOCH FROM NOW())*1000)::bigint);
  NEW.booked_at   := v_booked;
  -- ⚠️ الدرس المدفوع (v12.07): لا تُقصّ المهلة إلى نهاية العرض إطلاقاً.
  NEW.expiry_time := v_booked
    + (public.taki_booking_hold_hours(COALESCE(NEW.fulfillment,'pickup')) * 3600000)::bigint;
  RETURN NEW;
END;
$$;


--
-- Name: tr_ae_set_booking_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_ae_set_booking_total() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.total_amount := (public.taki_booking_amount(
      NEW.deal_id, NEW.booked_quantity, NEW.selected_options, NEW.delivery_fee
  )->>'total')::numeric;
  RETURN NEW;
END
$$;


--
-- Name: tr_af_order_invoice_draft(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_af_order_invoice_draft() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total  numeric;
  v_rate   numeric;
  v_base   numeric;
  v_vat    numeric;
  v_vat_no text;
  v_cr     text;
  v_addr   text;
  v_name   text;
BEGIN
  v_total := round(COALESCE(NEW.total_amount, 0), 2);

  SELECT sp.vat_number, sp.cr_number, sp.address
    INTO v_vat_no, v_cr, v_addr
    FROM public.store_profiles sp WHERE sp.store_id = NEW.store_id;

  SELECT COALESCE(NULLIF(u.shop, ''), u.name)
    INTO v_name
    FROM public.users u WHERE u.id = NEW.store_id;

  -- الضريبة تظهر **برقم التاجر وحده**. ولا خيار «فوق السعر» في التجزئة:
  -- السعر المعلن للمستهلك شامل الضريبة، فالضريبة تُستخرج منه لا تُضاف إليه.
  IF public.taki_is_saudi_vat(v_vat_no) AND v_total > 0 THEN
    v_rate := public.taki_merchant_vat_rate();
    v_base := round(v_total / (1 + v_rate / 100), 2);
    v_vat  := round(v_total - v_base, 2);
  END IF;

  INSERT INTO public.order_invoices
    (barcode, store_id, buyer_id, total, vat_rate, vat_base, vat_amount, seller)
  VALUES (
    NEW.barcode, NEW.store_id, NEW.user_id, v_total, v_rate, v_base, v_vat,
    jsonb_strip_nulls(jsonb_build_object(
      'name',       NULLIF(btrim(COALESCE(v_name, '')), ''),
      'vat_number', NULLIF(btrim(COALESCE(v_vat_no, '')), ''),
      'cr_number',  NULLIF(btrim(COALESCE(v_cr, '')), ''),
      'address',    NULLIF(btrim(COALESCE(v_addr, '')), '')
    )))
  ON CONFLICT (barcode) DO NOTHING;

  RETURN NULL;
END
$$;


