    new.invoice_no := nextval('taki_invoice_seq');
  end if;
  return new;
end $$;


--
-- Name: tr_booking_message_recipient(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_booking_message_recipient() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    SELECT CASE WHEN NEW.sender_role = 'buyer' THEN b.store_id ELSE b.user_id END
      INTO NEW.recipient_id
      FROM bookings b
     WHERE b.barcode = NEW.barcode;
    RETURN NEW;
END;
$$;


--
-- Name: tr_close_delivery_track(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_close_delivery_track() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('completed','cancelled') AND coalesce(OLD.status,'') <> NEW.status THEN
    UPDATE public.delivery_tracks
       SET status = CASE WHEN NEW.status = 'completed' THEN 'delivered' ELSE 'cancelled' END,
           lat = NULL, lng = NULL, accuracy_m = NULL, heading = NULL, speed_kmh = NULL,
           remaining_km = NULL, eta_min = NULL,
           ended_at = now(), updated_at = now()
     WHERE barcode = NEW.barcode;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: tr_guard_booking_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_booking_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.order_invoices oi
              WHERE oi.barcode = OLD.barcode AND oi.invoice_no IS NOT NULL) THEN
    RAISE EXCEPTION
      'TAKI_INVOICE_ISSUED: صدرت لهذا الطلب فاتورة ضريبية مرقَّمة، وحذفه يُسقطها ويترك فجوة في تسلسل التاجر.'
      USING ERRCODE = 'P0016';
  END IF;
  RETURN OLD;
END
$$;


--
-- Name: tr_guard_booking_delivery(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_booking_delivery() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_q     jsonb;
  v_sell  jsonb;
  v_lat   float8;
  v_lng   float8;
  v_min   numeric;
  v_est   numeric;
BEGIN
  -- v14.08 (بلاغ ناصر ٨): لا بيع قبل أن يُقرّ التاجر كيف يُحاسِب. يسري على
  -- الاستلام والتوصيل معاً — متجرٌ بلا طريقة حساب لا يُحجز منه أصلاً.
  v_sell := public.store_can_sell(NEW.store_id);
  IF NOT coalesce((v_sell->>'ok')::boolean, false) THEN
    RAISE EXCEPTION 'TAKI_STORE_NO_PAYMENT:%', coalesce(v_sell->>'reason','not_declared')
      USING ERRCODE = 'P0013';
  END IF;
  -- ونقدٌ لا يقبله التاجر لا يُفرض عليه.
  IF coalesce(NEW.payment_method,'cod') = 'cod' AND NOT coalesce((v_sell->>'accepts_cod')::boolean, true) THEN
    RAISE EXCEPTION 'TAKI_STORE_CARD_ONLY' USING ERRCODE = 'P0013';
  END IF;

  IF coalesce(NEW.fulfillment, 'pickup') <> 'delivery' THEN
    NEW.fulfillment := 'pickup';
    NEW.delivery_address := NULL;
    NEW.delivery_fee := NULL;
    RETURN NEW;
  END IF;

  IF NEW.delivery_address IS NULL OR jsonb_typeof(NEW.delivery_address) <> 'object' THEN
    RAISE EXCEPTION 'TAKI_DELIVERY_NO_ADDRESS' USING ERRCODE = 'P0013';
  END IF;
  v_lat := nullif(NEW.delivery_address->>'lat', '')::float8;
  v_lng := nullif(NEW.delivery_address->>'lng', '')::float8;
  IF v_lat IS NULL OR v_lng IS NULL THEN
    RAISE EXCEPTION 'TAKI_DELIVERY_NO_ADDRESS' USING ERRCODE = 'P0013';
  END IF;

  -- ⚠️ v14.08 (بلاغ ناصر ١): النطاق يُقاس بفرع **هذا الحجز** لا بالمتجر كله،
  -- فلا يوصّل فرعُ الباحة إلى عنوانٍ داخل نطاق فرع الخبر.
  v_q := public.delivery_quote(NEW.store_id, v_lat, v_lng, NEW.location_id);
  IF NOT coalesce((v_q->>'enabled')::boolean, false) THEN
    RAISE EXCEPTION 'TAKI_DELIVERY_OFF' USING ERRCODE = 'P0013';
  END IF;
  IF NOT coalesce((v_q->>'available')::boolean, false) THEN
    RAISE EXCEPTION 'TAKI_DELIVERY_OUT_OF_ZONE' USING ERRCODE = 'P0013';
  END IF;

  IF v_q->>'payment' = 'card' THEN
    IF coalesce(NEW.payment_method, 'cod') <> 'online' THEN
      RAISE EXCEPTION 'TAKI_DELIVERY_CARD_ONLY' USING ERRCODE = 'P0013';
    END IF;
  ELSIF v_q->>'payment' = 'cod' THEN
    NEW.payment_method := 'cod';
  END IF;

  -- v14.11 — قيمة البضاعة من الصيغة الواحدة (بضاعة + إضافات، بلا رسوم).
  v_min := coalesce((v_q->>'min_order')::numeric, 0);
  IF v_min > 0 THEN
    v_est := (public.taki_booking_amount(NEW.deal_id, NEW.booked_quantity, NEW.selected_options, 0)->>'goods')::numeric;
    IF coalesce(v_est, 0) < v_min THEN
      RAISE EXCEPTION 'TAKI_DELIVERY_MIN_ORDER:%', v_min USING ERRCODE = 'P0013';
    END IF;
  END IF;

  NEW.delivery_fee := coalesce((v_q->>'fee')::numeric, 0);
  NEW.delivery_address := jsonb_strip_nulls(jsonb_build_object(
    'label',   left(coalesce(NEW.delivery_address->>'label', ''), 60),
    'details', left(coalesce(NEW.delivery_address->>'details', ''), 300),
    'city',    left(coalesce(NEW.delivery_address->>'city', ''), 60),
    'phone',   left(coalesce(NEW.delivery_address->>'phone', ''), 20),
    'lat',     v_lat,
    'lng',     v_lng,
    'zone_id', v_q->>'zone_id'));
  RETURN NEW;
END
$$;


--
-- Name: tr_guard_booking_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_booking_integrity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- The lifecycle RPCs, pg_cron and the payment function all run as the owner.
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;
  IF public.is_admin() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF coalesce(NEW.status, 'pending') <> 'pending' THEN
      RAISE EXCEPTION 'forbidden: a new booking must start as pending'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.paid_at          IS NOT NULL
    OR NEW.paid_amount      IS NOT NULL
    OR NEW.payment_provider IS NOT NULL
    OR NEW.payment_ref      IS NOT NULL
    OR NEW.payment_expected IS NOT NULL
    OR NEW.total_amount     IS NOT NULL
    OR NEW.completed_at     IS NOT NULL
    OR NEW.completed_by     IS NOT NULL
    OR NEW.cancelled_by     IS NOT NULL
    OR NEW.merchant_note    IS NOT NULL THEN
      RAISE EXCEPTION 'forbidden: payment and lifecycle fields are set by the server'
        USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE from a client session: identity, money, stock and lifecycle frozen.
  IF NEW.barcode          IS DISTINCT FROM OLD.barcode
  OR NEW.backup_code      IS DISTINCT FROM OLD.backup_code
  OR NEW.deal_id          IS DISTINCT FROM OLD.deal_id
  OR NEW.user_id          IS DISTINCT FROM OLD.user_id
  OR NEW.store_id         IS DISTINCT FROM OLD.store_id
  OR NEW.booked_quantity  IS DISTINCT FROM OLD.booked_quantity
  OR NEW.booked_at        IS DISTINCT FROM OLD.booked_at
  OR NEW.expiry_time      IS DISTINCT FROM OLD.expiry_time
  OR NEW.status           IS DISTINCT FROM OLD.status
  OR NEW.completed_at     IS DISTINCT FROM OLD.completed_at
  OR NEW.completed_by     IS DISTINCT FROM OLD.completed_by
  OR NEW.paid_at          IS DISTINCT FROM OLD.paid_at
  OR NEW.paid_amount      IS DISTINCT FROM OLD.paid_amount
  OR NEW.payment_provider IS DISTINCT FROM OLD.payment_provider
  OR NEW.payment_ref      IS DISTINCT FROM OLD.payment_ref
  OR NEW.payment_expected IS DISTINCT FROM OLD.payment_expected
  OR NEW.total_amount     IS DISTINCT FROM OLD.total_amount
  OR NEW.payment_method   IS DISTINCT FROM OLD.payment_method
  OR NEW.selected_options IS DISTINCT FROM OLD.selected_options
  OR NEW.cancelled_by     IS DISTINCT FROM OLD.cancelled_by
  OR NEW.merchant_note    IS DISTINCT FROM OLD.merchant_note
  OR NEW.location_id      IS DISTINCT FROM OLD.location_id
  OR NEW.fulfillment      IS DISTINCT FROM OLD.fulfillment
  OR NEW.delivery_address IS DISTINCT FROM OLD.delivery_address
  OR NEW.delivery_fee     IS DISTINCT FROM OLD.delivery_fee THEN
    RAISE EXCEPTION 'forbidden: booking payment and lifecycle fields are server-managed'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tr_guard_delivery_zone(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_delivery_zone() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_n int;
  v_pt jsonb;
  v_cnt int;
BEGIN
  IF NEW.store_id IS NULL THEN
    RAISE EXCEPTION 'TAKI_ZONE_BAD:store' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = NEW.store_id AND u.user_type IN ('seller','admin')) THEN
    RAISE EXCEPTION 'TAKI_ZONE_BAD:not_store' USING ERRCODE = '42501';
  END IF;

  NEW.name := nullif(left(btrim(coalesce(NEW.name, '')), 60), '');
  NEW.branch_id := nullif(btrim(coalesce(NEW.branch_id, '')), '');
  -- v14.08 — الفرع إمّا 'primary' (موقع المتجر) أو فرعٌ يملكه هذا المتجر.
  IF NEW.branch_id IS NOT NULL AND NEW.branch_id <> 'primary'
     AND NOT EXISTS (SELECT 1 FROM public.store_branches b
                      WHERE b.id = NEW.branch_id AND b.merchant_id = NEW.store_id) THEN
    RAISE EXCEPTION 'TAKI_ZONE_BAD:branch' USING ERRCODE = '23514';
  END IF;

  IF NEW.fee IS NOT NULL AND (NEW.fee < 0 OR NEW.fee > 1000) THEN
    RAISE EXCEPTION 'TAKI_ZONE_BAD:fee' USING ERRCODE = '23514';
  END IF;

  IF NEW.kind = 'circle' THEN
    IF NEW.center_lat IS NULL OR NEW.center_lng IS NULL OR NEW.radius_km IS NULL
       OR NEW.center_lat NOT BETWEEN -90 AND 90 OR NEW.center_lng NOT BETWEEN -180 AND 180
       OR NEW.radius_km < 0.2 OR NEW.radius_km > 200 THEN
      RAISE EXCEPTION 'TAKI_ZONE_BAD:circle' USING ERRCODE = '23514';
    END IF;
    NEW.points := NULL;
  ELSE
    IF NEW.points IS NULL OR jsonb_typeof(NEW.points) <> 'array' THEN
      RAISE EXCEPTION 'TAKI_ZONE_BAD:points' USING ERRCODE = '23514';
    END IF;
    v_n := jsonb_array_length(NEW.points);
    IF (NEW.kind = 'rect' AND v_n <> 2) OR (NEW.kind = 'polygon' AND (v_n < 3 OR v_n > 80)) THEN
      RAISE EXCEPTION 'TAKI_ZONE_BAD:points_count' USING ERRCODE = '23514';
    END IF;
    FOR v_pt IN SELECT * FROM jsonb_array_elements(NEW.points) LOOP
      IF jsonb_typeof(v_pt) <> 'array' OR jsonb_array_length(v_pt) <> 2
         OR jsonb_typeof(v_pt->0) <> 'number' OR jsonb_typeof(v_pt->1) <> 'number'
         OR (v_pt->>0)::float8 NOT BETWEEN -90 AND 90 OR (v_pt->>1)::float8 NOT BETWEEN -180 AND 180 THEN
        RAISE EXCEPTION 'TAKI_ZONE_BAD:point' USING ERRCODE = '23514';
      END IF;
    END LOOP;
    NEW.center_lat := NULL; NEW.center_lng := NULL; NEW.radius_km := NULL;
  END IF;

  IF TG_OP = 'INSERT' OR (NEW.is_active AND NOT OLD.is_active) THEN
    SELECT count(*) INTO v_cnt FROM public.store_delivery_zones z
     WHERE z.store_id = NEW.store_id AND z.is_active AND z.id <> NEW.id;
    IF v_cnt >= 10 THEN
      RAISE EXCEPTION 'TAKI_ZONE_CAP:10' USING ERRCODE = '23514';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END
$$;


--
-- Name: tr_guard_rating_purchase(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_rating_purchase() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Trusted server paths: the bot RPCs, admin tooling and pg_cron all run as
  -- the owner. The bot's own flow is barcode-driven, so it is gated already.
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;
  IF public.is_admin() THEN
    RETURN NEW;
  END IF;

  -- Belt and braces next to the RLS policy: never review as somebody else.
  IF NEW.user_id IS DISTINCT FROM auth.uid()::text THEN
    RAISE EXCEPTION 'forbidden: cannot review on behalf of another user'
      USING ERRCODE = '42501';
  END IF;

  -- The actual gate: a completed booking with this store.
  IF NOT EXISTS (
    SELECT 1 FROM public.bookings b
     WHERE b.user_id  = NEW.user_id
       AND b.store_id = NEW.store_id
       AND b.status   = 'completed'
  ) THEN
    RAISE EXCEPTION 'forbidden: only a completed purchase from this store allows a review'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tr_guard_store_billing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_store_billing() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_touches boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_touches :=
         NEW.subscription_plan       IS NOT NULL
      OR NEW.subscription_expires_at IS NOT NULL
      OR NEW.subscription_started_at IS NOT NULL
      OR NEW.subscription_amount     IS NOT NULL
      OR NEW.subscription_package_id IS NOT NULL
      OR NEW.max_branches            IS NOT NULL
      OR coalesce(NEW.discount_percentage, 0) <> 0
      OR coalesce(NEW.is_pinned, false)
      OR coalesce(NEW.is_suspended, false)
      OR NEW.custom_features IS NOT NULL
      OR NEW.admin_notes     IS NOT NULL;
  ELSE
    v_touches :=
         NEW.subscription_plan       IS DISTINCT FROM OLD.subscription_plan
      OR NEW.subscription_expires_at IS DISTINCT FROM OLD.subscription_expires_at
      OR NEW.subscription_started_at IS DISTINCT FROM OLD.subscription_started_at
      OR NEW.subscription_amount     IS DISTINCT FROM OLD.subscription_amount
      OR NEW.subscription_package_id IS DISTINCT FROM OLD.subscription_package_id
      OR NEW.max_branches            IS DISTINCT FROM OLD.max_branches
      OR NEW.discount_percentage     IS DISTINCT FROM OLD.discount_percentage
      OR NEW.is_pinned               IS DISTINCT FROM OLD.is_pinned
      OR NEW.is_suspended            IS DISTINCT FROM OLD.is_suspended
      OR NEW.custom_features         IS DISTINCT FROM OLD.custom_features
      OR NEW.admin_notes             IS DISTINCT FROM OLD.admin_notes;
  END IF;

  IF NOT v_touches THEN
    RETURN NEW;   -- ordinary profile edits (bio, phone, VAT number…) pass through
  END IF;

  -- The activation RPC, admin RPCs, pg_cron renewals and the service role all
  -- run as the owner; the merchant's own session does not.
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;
  IF public.is_admin() THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'forbidden: subscription and limit fields are not self-editable'
    USING ERRCODE = '42501';
END;
$$;


--
-- Name: tr_guard_user_address(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_user_address() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_cnt int;
BEGIN
  IF NEW.lat IS NULL OR NEW.lng IS NULL
     OR NEW.lat NOT BETWEEN 16 AND 33 OR NEW.lng NOT BETWEEN 34 AND 56 THEN
    RAISE EXCEPTION 'TAKI_ADDR_BAD:point' USING ERRCODE = '23514';
  END IF;
  NEW.label   := nullif(left(btrim(coalesce(NEW.label, '')), 60), '');
  NEW.details := nullif(left(btrim(coalesce(NEW.details, '')), 300), '');
  NEW.city    := nullif(left(btrim(coalesce(NEW.city, '')), 60), '');
  NEW.phone   := nullif(left(btrim(coalesce(NEW.phone, '')), 20), '');
  IF TG_OP = 'INSERT' THEN
    SELECT count(*) INTO v_cnt FROM public.user_addresses WHERE user_id = NEW.user_id;
    IF v_cnt >= 10 THEN RAISE EXCEPTION 'TAKI_ADDR_CAP:10' USING ERRCODE = '23514'; END IF;
    -- أول عنوان يصير الافتراضي بلا سؤال — لا يُعقل أن يملك المشتري عنواناً واحداً
    -- ولا يكون افتراضياً، فيرى «لا عنوان محدد» وعنده عنوان.
    IF v_cnt = 0 THEN NEW.is_default := true; END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END
$$;


--
-- Name: tr_guard_user_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_user_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n bigint;
BEGIN
  SELECT count(*) INTO v_n FROM public.bookings
   WHERE user_id = OLD.id OR store_id = OLD.id;
  IF v_n > 0 THEN
    RAISE EXCEPTION
      'TAKI_USER_HAS_ORDERS: هذا الحساب طرفٌ في % طلباً. الطلبات وفواتيرها الضريبية سجلٌّ لا يُمحى بحذف حساب — استعمل حذف الحساب المعتمد (تعطيل ثم تجهيل بعد ٣٠ يوماً).', v_n
      USING ERRCODE = 'P0015';
  END IF;
  RETURN OLD;
END
$$;


--
-- Name: tr_guard_user_privileges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_user_privileges() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_touches_privilege boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_touches_privilege :=
         NEW.user_type = 'admin'
      OR coalesce(NEW.is_super_admin, false)
      OR NEW.admin_permissions IS NOT NULL;
  ELSE
    v_touches_privilege :=
         NEW.user_type         IS DISTINCT FROM OLD.user_type
      OR NEW.is_super_admin    IS DISTINCT FROM OLD.is_super_admin
      OR NEW.admin_permissions IS DISTINCT FROM OLD.admin_permissions;
  END IF;

  IF NOT v_touches_privilege THEN
    RETURN NEW;
  END IF;

  -- Trusted server-side callers: admin RPCs (SECURITY DEFINER → owner),
  -- pg_cron, and the service role.
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  -- A genuine super admin may manage roles.
  IF public.is_super_admin() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'forbidden: cannot create a privileged account'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.is_super_admin IS DISTINCT FROM OLD.is_super_admin THEN
    RAISE EXCEPTION 'forbidden: is_super_admin is not self-editable'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.admin_permissions IS DISTINCT FROM OLD.admin_permissions THEN
    RAISE EXCEPTION 'forbidden: admin_permissions is not self-editable'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.user_type IS DISTINCT FROM OLD.user_type
     AND NEW.user_type NOT IN ('buyer', 'seller') THEN
    RAISE EXCEPTION 'forbidden: cannot grant yourself the % role', NEW.user_type
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tr_notify_delivery_started(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_notify_delivery_started() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_shop text; v_item text;
BEGIN
  IF NEW.status = 'on_the_way'
     AND coalesce(OLD.status, '') <> 'on_the_way'
     AND OLD.started_at IS NULL THEN
    SELECT coalesce(nullif(u.shop,''), u.name, 'المتجر') INTO v_shop FROM public.users u WHERE u.id = NEW.store_id;
    SELECT coalesce(d.item_name, 'طلبك') INTO v_item
      FROM public.bookings b LEFT JOIN public.deals d ON d.id = b.deal_id WHERE b.barcode = NEW.barcode;
    INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
    VALUES (NEW.user_id,
      '🚚 طلبك في الطريق إليك!', '🚚 Your order is on the way!',
      'انطلق ' || v_shop || ' بطلبك (' || v_item || '). تابع موقعه على الخريطة من «حجوزاتي».',
      v_shop || ' set off with your order (' || v_item || '). Track it on the map in “My bookings”.',
      'booking',
      jsonb_build_object('audience','buyer','event','delivery_started','barcode',NEW.barcode,'track',true),
      NOW());
  END IF;
  RETURN NEW;
END
$$;


