--
-- Name: tr_single_default_address(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_single_default_address() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.is_default THEN
    UPDATE public.user_addresses SET is_default = false, updated_at = now()
     WHERE user_id = NEW.user_id AND id <> NEW.id AND is_default;
    -- `users.delivery_address` تبقى مرآةً للعنوان الافتراضي: البوتان وكل ما
    -- كُتب قبل هذه النسخة يقرؤها، فمزامنتها هنا تُبقيهما يعملان بلا تعديل.
    UPDATE public.users SET delivery_address = jsonb_strip_nulls(jsonb_build_object(
        'label', NEW.label, 'details', NEW.details, 'city', NEW.city,
        'phone', NEW.phone, 'lat', NEW.lat, 'lng', NEW.lng, 'addr_id', NEW.id))
     WHERE id = NEW.user_id;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: tr_validate_booking_options(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_validate_booking_options() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_opts jsonb; v_vars jsonb; v_grp jsonb; v_sel jsonb; v_var jsonb;
BEGIN
  SELECT d.options, d.variants INTO v_opts, v_vars FROM deals d WHERE d.id = NEW.deal_id;

  IF COALESCE(NEW.source,'web') <> 'web' THEN
    IF v_vars IS NOT NULL AND jsonb_typeof(v_vars) = 'array' AND jsonb_array_length(v_vars) > 0 THEN
      RAISE EXCEPTION 'NEEDS_OPTIONS';
    END IF;
    IF v_opts IS NOT NULL AND jsonb_typeof(v_opts) = 'array' AND jsonb_array_length(v_opts) > 0 THEN
      FOR v_grp IN SELECT * FROM jsonb_array_elements(v_opts) LOOP
        IF COALESCE((v_grp->>'required')::boolean, false)
           AND NOT EXISTS (
             SELECT 1 FROM jsonb_array_elements(COALESCE(NEW.selected_options,'[]'::jsonb)) s
             WHERE s->>'g' = v_grp->>'id')
        THEN
          RAISE EXCEPTION 'NEEDS_OPTIONS';
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- كمية النسخة المتبقية يجب أن تكفي المطلوب
  IF v_vars IS NOT NULL AND jsonb_typeof(v_vars) = 'array'
     AND NEW.selected_options IS NOT NULL AND jsonb_typeof(NEW.selected_options) = 'array' THEN
    FOR v_sel IN SELECT * FROM jsonb_array_elements(NEW.selected_options) LOOP
      CONTINUE WHEN v_sel->>'g' IS DISTINCT FROM '__variant__';
      SELECT e INTO v_var FROM jsonb_array_elements(v_vars) e WHERE e->>'id' = v_sel->>'c' LIMIT 1;
      CONTINUE WHEN v_var IS NULL OR NOT (v_var ? 'qty') OR NULLIF(v_var->>'qty','') IS NULL;
      IF (v_var->>'qty')::numeric < GREATEST(COALESCE((v_sel->>'qty')::int,1),1) THEN
        RAISE EXCEPTION 'VARIANT_STOCK:%:%', COALESCE(v_var->>'label','?'), GREATEST((v_var->>'qty')::int, 0);
      END IF;
    END LOOP;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: tr_validate_deal_season(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_validate_deal_season() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_camp  jsonb;
    v_from  date;
    v_to    date;
    v_today date := (now() AT TIME ZONE 'Asia/Riyadh')::date;
BEGIN
    IF NEW.season_id IS NULL THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND NEW.season_id IS NOT DISTINCT FROM OLD.season_id THEN
        RETURN NEW; -- وسم قائم لم يتغيّر — تعديلات الحقول الأخرى لا تُعاد محاكمتها
    END IF;
    IF public.is_admin() THEN RETURN NEW; END IF;

    SELECT value INTO v_camp FROM platform_settings WHERE key = 'season_campaign';
    IF v_camp IS NULL OR (v_camp->>'season_id') IS DISTINCT FROM NEW.season_id THEN
        RAISE EXCEPTION 'إضافة العروض لهذا الموسم غير متاحة حالياً — انتظر إعلان فتح باب المشاركة';
    END IF;
    v_from := NULLIF(v_camp->>'seller_from','')::date;
    v_to   := NULLIF(v_camp->>'seller_to','')::date;
    IF v_from IS NULL OR v_to IS NULL OR v_today < v_from OR v_today > v_to THEN
        RAISE EXCEPTION 'نافذة إضافة عروض الموسم من % إلى % — التاريخ الحالي خارجها', COALESCE(v_from::text,'؟'), COALESCE(v_to::text,'؟');
    END IF;
    RETURN NEW;
END $$;


--
-- Name: tr_zy_issue_order_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_zy_issue_order_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed')
     OR (NEW.paid_at IS NOT NULL AND OLD.paid_at IS NULL) THEN
    PERFORM public.taki_issue_order_invoice(NEW.barcode);
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: track_app_open(text, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_app_open(p_source text DEFAULT 'web'::text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text := auth.uid()::text;
        v_src text := CASE WHEN p_source IN ('web','telegram','whatsapp') THEN p_source ELSE 'web' END;
        v_lat double precision := CASE WHEN p_lat BETWEEN -90 AND 90 THEN p_lat END;
        v_lng double precision := CASE WHEN p_lng BETWEEN -180 AND 180 THEN p_lng END;
BEGIN
    -- نفس المستخدم خلال ٣٠ دقيقة = جلسة واحدة (المجهول يعتمد على كبح العميل).
    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM analytics_events
        WHERE kind='app_open' AND user_id=v_uid AND source=v_src
          AND created_at > now() - interval '30 minutes'
    ) THEN RETURN; END IF;
    INSERT INTO analytics_events (kind, user_id, source, lat, lng)
    VALUES ('app_open', v_uid, v_src, v_lat, v_lng);
END;
$$;


--
-- Name: track_search(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_search(p_query text, p_scope text DEFAULT 'home'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_q text := lower(btrim(COALESCE(p_query, '')));
        v_uid text := auth.uid()::text;
BEGIN
    IF length(v_q) < 2 OR length(v_q) > 80 THEN RETURN; END IF;
    -- نفس المستخدم + نفس الكلمة خلال ١٠ دقائق = بحث واحد (يمنع تضخيم العدّاد أثناء الكتابة)
    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM analytics_events
        WHERE kind='search' AND user_id=v_uid AND query=v_q
          AND created_at > now() - interval '10 minutes'
    ) THEN RETURN; END IF;
    INSERT INTO analytics_events (kind, user_id, query, source)
    VALUES ('search', v_uid, v_q,
            CASE WHEN p_scope IN ('home','deals','nearby') THEN p_scope ELSE 'home' END);
END;
$$;


--
-- Name: track_store_view(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_store_view(p_store_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid text := auth.uid()::text;
BEGIN
    IF p_store_id IS NULL OR btrim(p_store_id) = '' THEN RETURN; END IF;
    -- Dedupe: one event per visitor per store per 30 minutes (signed-in only;
    -- guests always count — the client also dedupes per session).
    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM analytics_events
        WHERE kind = 'store_view' AND store_id = p_store_id AND user_id = v_uid
          AND created_at > now() - interval '30 minutes'
    ) THEN RETURN; END IF;
    INSERT INTO analytics_events (kind, user_id, store_id)
    VALUES ('store_view', v_uid, p_store_id);
END;
$$;


--
-- Name: update_rating(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_rating(p_rating_id text, p_score integer, p_comment text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_uid text := (auth.uid())::text;
    v_owner text;
BEGIN
    IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
    IF p_score IS NULL OR p_score < 1 OR p_score > 5 THEN RAISE EXCEPTION 'bad score'; END IF;
    SELECT r.user_id INTO v_owner FROM public.ratings r WHERE r.id = p_rating_id AND r.deleted_at IS NULL;
    IF v_owner IS NULL THEN RAISE EXCEPTION 'rating not found'; END IF;
    IF v_owner <> v_uid AND NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = v_uid AND u.user_type = 'admin') THEN
        RAISE EXCEPTION 'forbidden';
    END IF;
    UPDATE public.ratings
       SET score = p_score,
           comment = NULLIF(btrim(COALESCE(p_comment, '')), ''),
           updated_at = now()
     WHERE id = p_rating_id;
END $$;


