--
-- Name: urlencode(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.urlencode(p_in text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_bytes bytea := convert_to(coalesce(p_in,''),'UTF8'); v_out text := ''; i int; b int; c text;
BEGIN
  FOR i IN 0..octet_length(v_bytes)-1 LOOP
    b := get_byte(v_bytes, i);
    c := chr(b);
    IF c ~ '[A-Za-z0-9_.~-]' THEN v_out := v_out || c;
    ELSE v_out := v_out || '%' || upper(lpad(to_hex(b),2,'0'));
    END IF;
  END LOOP;
  RETURN v_out;
END; $$;


