--
-- Name: app_secrets; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.app_secrets AS
 SELECT SUBSTRING(name FROM 12) AS key,
    decrypted_secret AS value
   FROM vault.decrypted_secrets s
  WHERE (name ~~ 'app\_secret:%'::text);


