    amount numeric DEFAULT 0 NOT NULL,
    reason text,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    decided_by text,
    merchant_note text,
    refunded_at timestamp with time zone,
    refund_amount numeric,
    refund_ref text,
    refund_method text,
    credit_note_no text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT booking_refunds_sane CHECK (((amount >= (0)::numeric) AND (amount <= (1000000)::numeric) AND ((refund_amount IS NULL) OR ((refund_amount >= (0)::numeric) AND (refund_amount <= (1000000)::numeric))) AND ((reason IS NULL) OR (length(reason) <= 600)) AND ((merchant_note IS NULL) OR (length(merchant_note) <= 600)) AND ((refund_ref IS NULL) OR (length(refund_ref) <= 120)) AND ((refund_method IS NULL) OR (length(refund_method) <= 40)))),
    CONSTRAINT booking_refunds_status_chk CHECK ((status = ANY (ARRAY['requested'::text, 'declined'::text, 'approved'::text, 'refunded'::text, 'withdrawn'::text])))
);


