--
-- Name: store_profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.store_profiles (
    store_id text NOT NULL,
    phone text,
    email text,
    avatar_url text,
    bio text,
    address text,
    updated_at timestamp with time zone DEFAULT now(),
    subscription_plan text DEFAULT 'trial'::text,
    subscription_expires_at timestamp with time zone,
    discount_percentage integer DEFAULT 0,
    is_pinned boolean DEFAULT false,
    max_branches integer DEFAULT 3,
    subscription_amount numeric DEFAULT 199,
    subscription_started_at timestamp with time zone,
    admin_notes text,
    is_suspended boolean DEFAULT false,
    custom_features jsonb DEFAULT '{}'::jsonb,
    auto_renew boolean DEFAULT true NOT NULL,
    subscription_canceled_at timestamp with time zone,
    last_expiry_warning_at timestamp with time zone,
    subscription_package_id integer,
    vat_number text,
    cr_number text,
    vat_status text,
    delivery_enabled boolean DEFAULT false NOT NULL,
    delivery_payment text DEFAULT 'cod'::text NOT NULL,
    delivery_fee numeric DEFAULT 0 NOT NULL,
    delivery_min_order numeric DEFAULT 0 NOT NULL,
    delivery_eta_min integer,
    delivery_note text,
    accepts_cod boolean DEFAULT true NOT NULL,
    payment_declared_at timestamp with time zone,
    refund_policy text,
    store_terms text,
    CONSTRAINT store_profiles_delivery_chk CHECK (((delivery_payment = ANY (ARRAY['cod'::text, 'card'::text, 'both'::text])) AND (delivery_fee >= (0)::numeric) AND (delivery_fee <= (1000)::numeric) AND (delivery_min_order >= (0)::numeric) AND (delivery_min_order <= (100000)::numeric) AND ((delivery_eta_min IS NULL) OR ((delivery_eta_min >= 0) AND (delivery_eta_min <= 1440))) AND ((delivery_note IS NULL) OR (length(delivery_note) <= 300)))),
    CONSTRAINT store_profiles_policies_chk CHECK ((((refund_policy IS NULL) OR (length(refund_policy) <= 1500)) AND ((store_terms IS NULL) OR (length(store_terms) <= 1500)))),
    CONSTRAINT store_profiles_vat_status_check CHECK (((vat_status IS NULL) OR (vat_status = ANY (ARRAY['registered'::text, 'not_registered'::text]))))
);


--
-- Name: COLUMN store_profiles.subscription_package_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.store_profiles.subscription_package_id IS 'v13.16 — معرّف الباقة من platform_settings.location_packages. يربط المتجر بباقته فتنتشر تعديلات الأدمن (عدد المواقع) تلقائياً.';


--
-- Name: COLUMN store_profiles.vat_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.store_profiles.vat_number IS 'الرقم الضريبي للتاجر (١٥ رقماً يبدأ وينتهي بـ3) — وجوده يحوّل سند الطلب المطبوع إلى فاتورة ضريبية مبسطة بQR حسب متطلبات الهيئة';


--
-- Name: COLUMN store_profiles.cr_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.store_profiles.cr_number IS 'السجل التجاري للتاجر — يظهر على الفاتورة القياسية (v13.37)';


--
-- Name: COLUMN store_profiles.vat_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.store_profiles.vat_status IS 'الوضع الضريبي المُعلَن من التاجر: registered / not_registered / NULL = لم يحدّد بعد (v13.38)';


--
-- Name: COLUMN store_profiles.refund_policy; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.store_profiles.refund_policy IS 'سياسة الاسترداد والاستبدال التي يكتبها التاجر ويُلزَم بها. تُعرض للمشتري قبل الحجز.';


--
-- Name: COLUMN store_profiles.store_terms; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.store_profiles.store_terms IS 'شروط إضافية يضيفها التاجر (مواعيد، ضمان، شروط الاستخدام…). تُعرض مع السياسة.';


