--
-- Name: v_top_buyers; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_top_buyers WITH (security_invoker='true') AS
 SELECT u.id,
    u.name,
    u.phone,
    (count(b.barcode))::integer AS bookings_count,
    sum((d.discounted_price * (b.booked_quantity)::numeric)) AS total_spent,
    u.last_active_at,
    u.created_at
   FROM ((public.users u
     LEFT JOIN public.bookings b ON ((b.user_id = u.id)))
     LEFT JOIN public.deals d ON ((d.id = b.deal_id)))
  WHERE (u.user_type = 'buyer'::text)
  GROUP BY u.id, u.name, u.phone, u.last_active_at, u.created_at
  ORDER BY ((count(b.barcode))::integer) DESC;


--
-- Name: v_top_sellers; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_top_sellers WITH (security_invoker='true') AS
 SELECT u.id,
    u.name,
    u.shop,
    count(DISTINCT d.id) FILTER (WHERE ((d.status IS NULL) OR (d.status <> 'deleted'::text))) AS deals_count,
    count(DISTINCT b.barcode) AS bookings_count,
    sp.subscription_plan,
    sp.subscription_amount,
    sp.subscription_expires_at,
    u.last_active_at
   FROM (((public.users u
     LEFT JOIN public.deals d ON ((d.store_id = u.id)))
     LEFT JOIN public.bookings b ON ((b.store_id = u.id)))
     LEFT JOIN public.store_profiles sp ON ((sp.store_id = u.id)))
  WHERE (u.user_type = 'seller'::text)
  GROUP BY u.id, u.name, u.shop, sp.subscription_plan, sp.subscription_amount, sp.subscription_expires_at, u.last_active_at
  ORDER BY (count(DISTINCT b.barcode)) DESC;


